from __future__ import annotations

import hashlib
import json
from pathlib import Path
import re
from typing import Any
import zipfile

from .bytecode_profile import (
    BytecodeProfileError,
    profile_class_constant_pool_references,
    profile_class_field_accesses,
    profile_class_utf8_constants,
)
from .classfile import ClassFormatError, parse_class
from .decompiler import sha256_file
from .source_digest import source_tree_digest


class SourceNormalizationError(ValueError):
    pass


_SYNTHETIC_CLASS_RE = re.compile(
    r"(?m)^(?P<indent>[ \t]*)synthetic class "
    r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)[ \t]*$"
)
_DISCARDED_STRING_RE = re.compile(
    r'^(?P<indent>[ \t]*)(?P<expr>"(?:\\.|[^"\\])*"\s*\+.+);[ \t]*$'
)
_METHOD_DECL_RE = re.compile(
    r"(?m)^(?P<indent>[ \t]*)"
    r"(?:(?:public|private|protected|static|final|synchronized|strictfp)\s+)*"
    r"(?P<return>[A-Za-z_$][A-Za-z0-9_$.<>?, \[\]]*)\s+"
    r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\s*"
    r"\((?P<params>[^()\n]*)\)\s*"
    r"(?:throws\s+[^\{\n]+\s*)?\{"
)
_FQ_PARAM_RE = re.compile(
    r"(?:^|,)\s*(?:final\s+)?"
    r"(?P<type>[A-Za-z_$][A-Za-z0-9_$]*"
    r"(?:\.[A-Za-z_$][A-Za-z0-9_$]*)+)\s+"
    r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\s*(?=,|$)"
)
_IDENTIFIER = re.compile(r"^[A-Za-z_$][A-Za-z0-9_$]*$")
_JAVA_RESERVED = {
    "abstract", "assert", "boolean", "break", "byte", "case", "catch",
    "char", "class", "const", "continue", "default", "do", "double",
    "else", "enum", "extends", "final", "finally", "float", "for",
    "goto", "if", "implements", "import", "instanceof", "int",
    "interface", "long", "native", "new", "package", "private",
    "protected", "public", "return", "short", "static", "strictfp",
    "super", "switch", "synchronized", "this", "throw", "throws",
    "transient", "try", "void", "volatile", "while", "_",
    "true", "false", "null",
}


def _stable_digest(value: Any) -> str:
    raw = json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def _source_tree_digest(root: Path) -> tuple[str, int, int]:
    digest, files, total_bytes = source_tree_digest(root)
    return digest, len(files), total_bytes


def _is_java_identifier(name: str) -> bool:
    return bool(_IDENTIFIER.fullmatch(name)) and name not in _JAVA_RESERVED


def _line_start_contexts(text: str) -> list[tuple[int, str]]:
    """Return (lexical brace depth, lexer state) at every source-line start."""
    contexts: list[tuple[int, str]] = [(0, "code")]
    depth = 0
    state = "code"
    escaped = False
    i = 0
    while i < len(text):
        ch = text[i]
        nxt = text[i + 1] if i + 1 < len(text) else ""

        if state == "line_comment":
            if ch == "\n":
                state = "code"
                contexts.append((depth, state))
        elif state == "block_comment":
            if ch == "*" and nxt == "/":
                state = "code"
                i += 1
            elif ch == "\n":
                contexts.append((depth, state))
        elif state == "string":
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                state = "code"
            elif ch == "\n":
                contexts.append((depth, state))
        elif state == "char":
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == "'":
                state = "code"
            elif ch == "\n":
                contexts.append((depth, state))
        elif state == "text_block":
            if text.startswith('"""', i):
                state = "code"
                i += 2
            elif ch == "\n":
                contexts.append((depth, state))
        else:
            if ch == "/" and nxt == "/":
                state = "line_comment"
                i += 1
            elif ch == "/" and nxt == "*":
                state = "block_comment"
                i += 1
            elif text.startswith('"""', i):
                state = "text_block"
                i += 2
            elif ch == '"':
                state = "string"
                escaped = False
            elif ch == "'":
                state = "char"
                escaped = False
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth = max(0, depth - 1)
            elif ch == "\n":
                contexts.append((depth, state))
        i += 1
    return contexts


def _normalize_synthetic_class(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> dict[str, Any] | None:
    text = path.read_text(encoding="utf-8")
    matches = list(_SYNTHETIC_CLASS_RE.finditer(text))
    if not matches:
        return None
    if len(matches) != 1:
        raise SourceNormalizationError(
            f"{path}: expected one Procyon synthetic class declaration, "
            f"found {len(matches)}"
        )

    rel = path.relative_to(source_root).as_posix()
    match = matches[0]
    name = match.group("name")
    if Path(rel).stem != name:
        raise SourceNormalizationError(
            f"{rel}: synthetic class name {name!r} does not match file stem"
        )

    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
    except KeyError as exc:
        raise SourceNormalizationError(
            f"{rel}: exact readable class entry {class_entry!r} is absent"
        ) from exc

    try:
        parsed = parse_class(class_bytes)
    except ClassFormatError as exc:
        raise SourceNormalizationError(
            f"{rel}: exact readable class could not be parsed: {exc}"
        ) from exc

    if parsed.name != class_entry[:-6]:
        raise SourceNormalizationError(
            f"{rel}: readable class identity disagrees with source path"
        )

    # Exact proven Procyon/Javac switch-map helper shape:
    # package-private ACC_SUPER | ACC_SYNTHETIC, Object superclass, no
    # interfaces, zero or more synthetic static-final int[] fields, and
    # either no methods or one ordinary static <clinit>.
    if parsed.access != 0x1020:
        raise SourceNormalizationError(
            f"{rel}: unsupported synthetic class access {parsed.access:#x}"
        )
    if parsed.super_name != "java/lang/Object" or parsed.interfaces:
        raise SourceNormalizationError(
            f"{rel}: unsupported synthetic class hierarchy"
        )
    for field in parsed.fields:
        if (
            field.get("access") != 0x1018
            or field.get("descriptor") != "[I"
            or not _is_java_identifier(str(field.get("name", "")))
        ):
            raise SourceNormalizationError(
                f"{rel}: unsupported synthetic field shape {field!r}"
            )
    if parsed.methods:
        if len(parsed.methods) != 1:
            raise SourceNormalizationError(
                f"{rel}: unsupported synthetic method count "
                f"{len(parsed.methods)}"
            )
        method = parsed.methods[0]
        if (
            method.get("name") != "<clinit>"
            or method.get("descriptor") != "()V"
            or method.get("access") != 0x0008
        ):
            raise SourceNormalizationError(
                f"{rel}: unsupported synthetic method shape {method!r}"
            )

    declared_fields: list[str] = []
    for field in parsed.fields:
        field_name = str(field["name"])
        declaration_re = re.compile(
            r"(?m)^[ \t]*(?:static\s+final|final\s+static)\s+"
            r"int\[\]\s+" + re.escape(field_name) + r"\s*;"
        )
        if declaration_re.search(text):
            declared_fields.append(field_name)
    if declared_fields and len(declared_fields) != len(parsed.fields):
        raise SourceNormalizationError(
            f"{rel}: Procyon emitted only a subset of exact synthetic fields"
        )

    replacement = match.group("indent") + "class " + name
    text = text[: match.start()] + replacement + text[match.end() :]

    inserted_fields: list[str] = []
    if parsed.fields and not declared_fields:
        declaration = re.search(
            r"(?m)^[ \t]*class\s+"
            + re.escape(name)
            + r"[ \t]*\n(?P<brace>[ \t]*\{[ \t]*)$",
            text,
        )
        if declaration is None:
            raise SourceNormalizationError(
                f"{rel}: normalized synthetic class opening brace is unsupported"
            )
        insert_at = declaration.end()
        block = "".join(
            "\n    static final int[] " + str(field["name"]) + ";"
            for field in parsed.fields
        )
        text = text[:insert_at] + block + text[insert_at:]
        inserted_fields = [str(field["name"]) for field in parsed.fields]

    path.write_text(text, encoding="utf-8")
    return {
        "kind": "synthetic_class_reconstruction",
        "source_path": rel,
        "class_entry": class_entry,
        "class_entry_sha256": hashlib.sha256(class_bytes).hexdigest(),
        "source_class_name": name,
        "inserted_fields": inserted_fields,
        "exact_field_count": len(parsed.fields),
        "exact_method_count": len(parsed.methods),
        "provenance": {
            "kind": "source_safety",
            "reason": "procyon_synthetic_class_pseudo_syntax",
            "strategy": "exact_readable_class_shape_reconstruction",
        },
    }


def _normalize_discarded_strings(
    *,
    source_root: Path,
    path: Path,
) -> list[dict[str, Any]]:
    text = path.read_text(encoding="utf-8")
    lines = text.splitlines(keepends=True)
    contexts = _line_start_contexts(text)
    changed = False
    actions: list[dict[str, Any]] = []

    for index, line in enumerate(lines):
        raw = line[:-1] if line.endswith("\n") else line
        match = _DISCARDED_STRING_RE.fullmatch(raw)
        if match is None:
            continue
        if index >= len(contexts):
            raise SourceNormalizationError(
                f"{path}: missing lexical context for source line {index + 1}"
            )
        depth, state = contexts[index]
        if state != "code" or depth < 2:
            raise SourceNormalizationError(
                f"{path}: discarded string expression at line {index + 1} "
                "is not proven to be inside executable Java code"
            )

        rel = path.relative_to(source_root).as_posix()
        expression = match.group("expr")
        original = raw.strip()
        suffix = hashlib.sha256(
            (rel + "\0" + original).encode("utf-8")
        ).hexdigest()[:12]
        local_name = "recoveredDiscardedExpression_" + suffix
        if re.search(r"\b" + re.escape(local_name) + r"\b", text):
            raise SourceNormalizationError(
                f"{rel}: deterministic discarded-expression local collides"
            )

        newline = "\n" if line.endswith("\n") else ""
        replacement = (
            match.group("indent")
            + "final String "
            + local_name
            + " = "
            + expression
            + ";"
            + newline
        )
        lines[index] = replacement
        changed = True
        actions.append(
            {
                "kind": "discarded_string_expression_capture",
                "source_path": rel,
                "source_line": index + 1,
                "original_sha256": hashlib.sha256(
                    original.encode("utf-8")
                ).hexdigest(),
                "replacement_local": local_name,
                "provenance": {
                    "kind": "source_safety",
                    "reason": "java_illegal_discarded_string_expression",
                    "strategy": "preserve_evaluation_via_unused_string_local",
                },
            }
        )

    if changed:
        path.write_text("".join(lines), encoding="utf-8")
    return actions



def _matching_brace_end(text: str, brace_start: int) -> int:
    depth = 0
    state = "code"
    escaped = False
    i = brace_start
    while i < len(text):
        ch = text[i]
        nxt = text[i + 1] if i + 1 < len(text) else ""
        if state == "line_comment":
            if ch == "\n":
                state = "code"
        elif state == "block_comment":
            if ch == "*" and nxt == "/":
                state = "code"
                i += 1
        elif state == "string":
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                state = "code"
        elif state == "char":
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == "'":
                state = "code"
        elif state == "text_block":
            if text.startswith('"""', i):
                state = "code"
                i += 2
        else:
            if ch == "/" and nxt == "/":
                state = "line_comment"
                i += 1
            elif ch == "/" and nxt == "*":
                state = "block_comment"
                i += 1
            elif text.startswith('"""', i):
                state = "text_block"
                i += 2
            elif ch == '"':
                state = "string"
                escaped = False
            elif ch == "'":
                state = "char"
                escaped = False
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    return i + 1
                if depth < 0:
                    break
        i += 1
    raise SourceNormalizationError(
        f"unbalanced Java method body starting at offset {brace_start}"
    )


def _java_code_mask(text: str) -> str:
    """Mask comments and literals while preserving source offsets."""
    chars = list(text)
    state = "code"
    escaped = False
    i = 0
    while i < len(text):
        ch = text[i]
        nxt = text[i + 1] if i + 1 < len(text) else ""

        if state == "line_comment":
            if ch == "\n":
                state = "code"
            else:
                chars[i] = " "
        elif state == "block_comment":
            chars[i] = " " if ch != "\n" else "\n"
            if ch == "*" and nxt == "/":
                chars[i + 1] = " "
                state = "code"
                i += 1
        elif state == "string":
            chars[i] = " " if ch != "\n" else "\n"
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                state = "code"
        elif state == "char":
            chars[i] = " " if ch != "\n" else "\n"
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == "'":
                state = "code"
        elif state == "text_block":
            chars[i] = " " if ch != "\n" else "\n"
            if text.startswith('"""', i):
                if i + 1 < len(chars):
                    chars[i + 1] = " "
                if i + 2 < len(chars):
                    chars[i + 2] = " "
                state = "code"
                i += 2
        else:
            if ch == "/" and nxt == "/":
                chars[i] = chars[i + 1] = " "
                state = "line_comment"
                i += 1
            elif ch == "/" and nxt == "*":
                chars[i] = chars[i + 1] = " "
                state = "block_comment"
                i += 1
            elif text.startswith('"""', i):
                chars[i] = " "
                if i + 1 < len(chars):
                    chars[i + 1] = " "
                if i + 2 < len(chars):
                    chars[i + 2] = " "
                state = "text_block"
                i += 2
            elif ch == '"':
                chars[i] = " "
                state = "string"
                escaped = False
            elif ch == "'":
                chars[i] = " "
                state = "char"
                escaped = False
        i += 1
    return "".join(chars)


def _field_access_counter(
    method: dict[str, Any],
    *,
    owner: str,
    field_names: set[str],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for access in method.get("field_accesses", []):
        if access.get("owner") != owner:
            continue
        name = str(access.get("name", ""))
        if name not in field_names:
            continue
        if access.get("operation") not in {"getstatic", "putstatic"}:
            continue
        counts[name] = counts.get(name, 0) + 1
    return counts


def _normalize_shadowed_self_static_field_owners(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Qualify exact self static-field owners hidden by a same-name parameter.

    Procyon can print a.a for a self static field in a method whose parameter
    is also named a. Java then resolves the qualifier as the parameter
    expression. Rewriting is allowed only when the source field-use multiset
    exactly equals the current-owner getstatic/putstatic multiset for one
    exact method and the bytecode has no corresponding field access through
    the shadow parameter owner.
    """
    rel = path.relative_to(source_root).as_posix()
    simple_name_from_path = Path(rel).stem
    text = path.read_text(encoding="utf-8")
    potential_shadow = False
    for method_match in _METHOD_DECL_RE.finditer(text):
        if any(
            param.group("name") == simple_name_from_path
            for param in _FQ_PARAM_RE.finditer(method_match.group("params"))
        ):
            potential_shadow = True
            break
    if not potential_shadow:
        return []

    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
    except KeyError:
        return []

    try:
        profile = profile_class_field_accesses(class_bytes)
    except BytecodeProfileError as exc:
        raise SourceNormalizationError(
            f"{rel}: exact readable class field profile failed: {exc}"
        ) from exc

    internal_name = str(profile["internal_name"])
    simple_name = internal_name.rsplit("/", 1)[-1]
    if Path(rel).stem != simple_name:
        return []

    static_fields = {
        str(field["name"])
        for field in profile.get("fields", [])
        if int(field.get("access", 0)) & 0x0008
        and _is_java_identifier(str(field.get("name", "")))
    }
    if not static_fields:
        return []

    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []
    qualified_owner = internal_name.replace("/", ".")

    for match in _METHOD_DECL_RE.finditer(text):
        shadow_params = [
            param
            for param in _FQ_PARAM_RE.finditer(match.group("params"))
            if param.group("name") == simple_name
        ]
        if len(shadow_params) != 1:
            continue
        shadow_type = shadow_params[0].group("type")
        shadow_internal = shadow_type.replace(".", "/")
        if shadow_internal == internal_name:
            continue

        shadow_entry = shadow_internal + ".class"
        try:
            shadow_bytes = readable_zip.read(shadow_entry)
        except KeyError:
            continue
        try:
            shadow_profile = profile_class_field_accesses(shadow_bytes)
        except BytecodeProfileError as exc:
            raise SourceNormalizationError(
                f"{rel}: shadow class field profile failed for "
                f"{shadow_internal}: {exc}"
            ) from exc

        shadow_private_fields = {
            str(field["name"])
            for field in shadow_profile.get("fields", [])
            if int(field.get("access", 0)) & 0x0002
        }

        brace_start = text.find("{", match.start(), match.end())
        if brace_start < 0:
            continue
        body_end = _matching_brace_end(text, brace_start)
        method_text = text[match.start():body_end]
        method_code = _java_code_mask(method_text)

        source_counts: dict[str, int] = {}
        occurrences: list[tuple[int, int, str]] = []
        for field_name in sorted(static_fields):
            token = re.compile(
                r"(?<![A-Za-z0-9_$.])"
                + re.escape(simple_name)
                + r"\."
                + re.escape(field_name)
                + r"\b(?!\s*\()"
            )
            hits = list(token.finditer(method_code))
            if not hits:
                continue
            source_counts[field_name] = len(hits)
            for hit in hits:
                occurrences.append(
                    (
                        match.start() + hit.start(),
                        match.start() + hit.end(),
                        qualified_owner + "." + field_name,
                    )
                )
        if not source_counts:
            continue
        if not set(source_counts).issubset(shadow_private_fields):
            continue

        candidates = []
        for method in profile.get("methods", []):
            if method.get("name") != match.group("name"):
                continue
            descriptor = str(method.get("descriptor", ""))
            if ("L" + shadow_internal + ";") not in descriptor:
                continue
            self_counts = _field_access_counter(
                method,
                owner=internal_name,
                field_names=static_fields,
            )
            if self_counts != source_counts:
                continue
            shadow_counts = _field_access_counter(
                method,
                owner=shadow_internal,
                field_names=set(source_counts),
            )
            if shadow_counts:
                continue
            candidates.append(method)

        if len(candidates) != 1:
            continue
        exact_method = candidates[0]

        edits.extend(occurrences)
        actions.append(
            {
                "kind": "shadowed_self_static_field_owner_qualification",
                "source_path": rel,
                "method_name": match.group("name"),
                "method_descriptor": exact_method["descriptor"],
                "shadow_parameter_name": simple_name,
                "shadow_parameter_type": shadow_internal,
                "qualified_owner": internal_name,
                "field_access_counts": dict(sorted(source_counts.items())),
                "replacement_count": sum(source_counts.values()),
                "provenance": {
                    "kind": "source_safety",
                    "reason": "procyon_shadowed_self_static_field_owner",
                    "strategy": (
                        "exact_method_field_access_multiset_qualification"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping owner-qualification edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



_PRIMITIVE_FIELD_DESCRIPTORS = {
    "Z", "B", "C", "S", "I", "J", "F", "D",
}


def _is_primitive_value_shadow_descriptor(descriptor: str) -> bool:
    """Return true for primitive scalars or arrays of primitive values."""
    if descriptor in _PRIMITIVE_FIELD_DESCRIPTORS:
        return True
    value = descriptor
    while value.startswith("["):
        value = value[1:]
    return (
        value in _PRIMITIVE_FIELD_DESCRIPTORS
        and value != descriptor
    )


def _is_reference_value_shadow_descriptor(descriptor: str) -> bool:
    """Return true for reference scalars or arrays of references."""
    value = descriptor
    while value.startswith("["):
        value = value[1:]
    return value.startswith("L") and value.endswith(";")


def _read_readable_hierarchy(
    *,
    readable_zip: zipfile.ZipFile,
    internal_name: str,
) -> list[tuple[str, Any]]:
    hierarchy: list[tuple[str, Any]] = []
    seen: set[str] = set()
    current: str | None = internal_name
    while current and current not in seen:
        seen.add(current)
        try:
            data = readable_zip.read(current + ".class")
        except KeyError:
            break
        try:
            parsed = parse_class(data)
        except ClassFormatError as exc:
            raise SourceNormalizationError(
                f"{internal_name}: hierarchy class {current} could not be "
                f"parsed: {exc}"
            ) from exc
        if parsed.name != current:
            raise SourceNormalizationError(
                f"{internal_name}: hierarchy identity mismatch for {current}"
            )
        hierarchy.append((current, parsed))
        current = parsed.super_name
    return hierarchy


def _field_visible_from(
    *,
    declaring_owner: str,
    current_owner: str,
    access: int,
) -> bool:
    if declaring_owner == current_owner:
        return True
    if access & 0x0002:  # private
        return False
    if access & (0x0001 | 0x0004):  # public or protected
        return True
    declaring_package = declaring_owner.rpartition("/")[0]
    current_package = current_owner.rpartition("/")[0]
    return declaring_package == current_package


def _same_name_value_shadow_spans(
    *,
    method_match: re.Match[str],
    method_code: str,
    simple_name: str,
) -> tuple[bool, list[tuple[int, int]]]:
    """Return whole-method parameter shadow plus conservative local scopes."""
    params = method_match.group("params")
    primitive_source_types = {
        "boolean", "byte", "char", "short", "int", "long", "float",
        "double",
    }
    param_name = re.compile(
        r"(?:^|,)\s*(?:final\s+)?"
        r"(?P<type>[A-Za-z_$][A-Za-z0-9_$.\[\]<>?, ]*?)\s+"
        + re.escape(simple_name)
        + r"\s*(?=,|$)"
    )
    for param in param_name.finditer(params):
        param_type = param.group("type").strip()
        if param_type not in primitive_source_types:
            return True, []

    brace = method_code.find("{")
    if brace < 0:
        return True, []
    body_start = brace + 1
    body = method_code[body_start:]
    local_name = re.compile(
        r"(?:^|[;{}]\s*|\(\s*|,\s*)\s*"
        r"(?:final\s+)?"
        r"(?P<type>[A-Za-z_$][A-Za-z0-9_$.\[\]<>?]*"
        r"(?:\s*<[^;{}()]*>)?)"
        r"\s+(?P<name>"
        + re.escape(simple_name)
        + r")\s*(?==|;|,|:|\))",
        re.MULTILINE,
    )
    spans: list[tuple[int, int]] = []
    for local in local_name.finditer(body):
        local_type = local.group("type").strip()
        if local_type in primitive_source_types:
            # A scalar primitive cannot be the receiver of `.field`; exact
            # bytecode proof can therefore establish class qualification
            # even while the primitive local shadows the class simple name.
            continue
        declaration = body_start + local.start("name")
        stack: list[int] = []
        for index, ch in enumerate(method_code[:declaration]):
            if ch == "{":
                stack.append(index)
            elif ch == "}" and stack:
                stack.pop()
        if not stack:
            spans.append((declaration, len(method_code)))
            continue
        spans.append(
            (declaration, _matching_brace_end(method_code, stack[-1]))
        )
    return False, spans


def _primitive_same_name_value_shadow_spans(
    *,
    method_match: re.Match[str],
    method_code: str,
    simple_name: str,
) -> tuple[bool, list[tuple[int, int]]]:
    """Return scalar-primitive parameter shadow plus primitive local scopes."""
    primitive_source_types = {
        "boolean", "byte", "char", "short", "int", "long", "float",
        "double",
    }
    params = method_match.group("params")
    param_name = re.compile(
        r"(?:^|,)\s*(?:final\s+)?"
        r"(?P<type>[A-Za-z_$][A-Za-z0-9_$.\[\]<>?, ]*?)\s+"
        + re.escape(simple_name)
        + r"\s*(?=,|$)"
    )
    primitive_parameter = any(
        param.group("type").strip() in primitive_source_types
        for param in param_name.finditer(params)
    )

    brace = method_code.find("{")
    if brace < 0:
        return primitive_parameter, []
    body_start = brace + 1
    body = method_code[body_start:]
    local_name = re.compile(
        r"(?:^|[;{}]\s*|\(\s*|,\s*)\s*"
        r"(?:final\s+)?"
        r"(?P<type>[A-Za-z_$][A-Za-z0-9_$.\[\]<>?]*"
        r"(?:\s*<[^;{}()]*>)?)"
        r"\s+(?P<name>"
        + re.escape(simple_name)
        + r")\s*(?==|;|,|:|\))",
        re.MULTILINE,
    )
    spans: list[tuple[int, int]] = []
    for local in local_name.finditer(body):
        if local.group("type").strip() not in primitive_source_types:
            continue
        declaration = body_start + local.start("name")
        stack: list[int] = []
        for index, ch in enumerate(method_code[:declaration]):
            if ch == "{":
                stack.append(index)
            elif ch == "}" and stack:
                stack.pop()
        if not stack:
            spans.append((declaration, len(method_code)))
            continue
        spans.append(
            (declaration, _matching_brace_end(method_code, stack[-1]))
        )
    return primitive_parameter, spans


def _method_has_same_name_value_binding(
    *,
    method_match: re.Match[str],
    method_code: str,
    simple_name: str,
) -> bool:
    parameter_shadow, local_spans = _same_name_value_shadow_spans(
        method_match=method_match,
        method_code=method_code,
        simple_name=simple_name,
    )
    return parameter_shadow or bool(local_spans)


def _descriptor_return_descriptor(
    descriptor: str,
) -> str | None:
    close = descriptor.find(")")
    if close < 0 or close + 1 >= len(descriptor):
        return None
    value = descriptor[close + 1:]
    if value == "V":
        return value
    if value and value[0] in "ZBCSIJFD":
        return value if len(value) == 1 else None
    if value.startswith("L") and value.endswith(";"):
        return value
    if value.startswith("["):
        return value
    return None


def _java_cast_type_from_reference_descriptor(
    descriptor: str,
) -> str | None:
    if not (
        descriptor.startswith("L")
        and descriptor.endswith(";")
    ):
        return None
    internal = descriptor[1:-1]
    if not internal or "$" in internal:
        return None
    parts = internal.split("/")
    if not all(_is_java_identifier(part) for part in parts):
        return None
    return ".".join(parts)


def _source_parameter_count(params: str) -> int:
    text = params.strip()
    if not text:
        return 0
    depth = 0
    count = 1
    for ch in text:
        if ch == "<":
            depth += 1
        elif ch == ">" and depth:
            depth -= 1
        elif ch == "," and depth == 0:
            count += 1
    return count


def _source_call_argument_count(
    code: str,
    *,
    open_paren: int,
) -> int | None:
    """Count one source invocation's arguments from its opening parenthesis.

    The input is normally a Java code mask, so comments and literals cannot
    manufacture delimiter tokens. Return None rather than guessing on an
    unbalanced expression.
    """
    if not (0 <= open_paren < len(code)) or code[open_paren] != "(":
        return None

    paren_depth = 1
    bracket_depth = 0
    brace_depth = 0
    comma_count = 0
    saw_argument_token = False
    index = open_paren + 1

    while index < len(code):
        ch = code[index]
        if ch == "(":
            paren_depth += 1
        elif ch == ")":
            paren_depth -= 1
            if paren_depth == 0:
                return (
                    0
                    if not saw_argument_token
                    else comma_count + 1
                )
            if paren_depth < 0:
                return None
        elif ch == "[":
            bracket_depth += 1
        elif ch == "]":
            if bracket_depth == 0:
                return None
            bracket_depth -= 1
        elif ch == "{":
            brace_depth += 1
        elif ch == "}":
            if brace_depth == 0:
                return None
            brace_depth -= 1
        elif (
            ch == ","
            and paren_depth == 1
            and bracket_depth == 0
            and brace_depth == 0
        ):
            comma_count += 1
        elif (
            not ch.isspace()
            and paren_depth == 1
            and bracket_depth == 0
            and brace_depth == 0
        ):
            saw_argument_token = True
        index += 1
    return None


def _exact_finally_handler_duplicate_invocations(
    method: dict[str, Any],
    *,
    owner: str,
    relevant_signatures: set[tuple[str, int]],
) -> dict[tuple[str, int], int]:
    """Prove javac-style catch-all finally call duplication.

    A qualifying duplicate must live in a catch-all handler ending in athrow
    and have one descriptor-identical normal-exit copy between the protected
    range end and the handler entry. This is deliberately narrower than
    accepting arbitrary source/bytecode multiplicity drift.
    """
    if not relevant_signatures:
        return {}

    invocations = [
        row
        for row in method.get("method_invocations", [])
        if (
            row.get("operation") == "invokestatic"
            and str(row.get("owner", "")) == owner
        )
    ]
    instructions = sorted(
        method.get("instructions", []),
        key=lambda row: int(row.get("offset", -1)),
    )
    handlers = sorted(
        method.get("exception_handlers", []),
        key=lambda row: int(row.get("handler_pc", -1)),
    )
    code_length = int(method.get("code_length") or 0)
    if not invocations or not instructions or not handlers or code_length <= 0:
        return {}

    result: dict[tuple[str, int], int] = {}
    counted_handler_offsets: set[int] = set()

    for index, handler in enumerate(handlers):
        if handler.get("catch_type") is not None:
            continue
        start_pc = int(handler.get("start_pc", -1))
        end_pc = int(handler.get("end_pc", -1))
        handler_pc = int(handler.get("handler_pc", -1))
        if not (
            0 <= start_pc <= end_pc <= handler_pc < code_length
        ):
            continue

        next_handler_pc = min(
            [
                int(other.get("handler_pc", code_length))
                for other in handlers[index + 1:]
                if int(other.get("handler_pc", -1)) > handler_pc
            ]
            or [code_length]
        )
        handler_instructions = [
            row
            for row in instructions
            if (
                handler_pc
                <= int(row.get("offset", -1))
                < next_handler_pc
            )
        ]
        if (
            not handler_instructions
            or not str(
                handler_instructions[0].get("mnemonic", "")
            ).startswith("astore")
        ):
            continue

        exception_slot = int(
            handler_instructions[0].get("local_index", -1)
        )
        athrow_indexes = [
            instruction_index
            for instruction_index, row in enumerate(handler_instructions)
            if row.get("mnemonic") == "athrow"
        ]
        if not athrow_indexes:
            continue
        athrow_index = athrow_indexes[0]
        if athrow_index < 2:
            continue
        exception_reload = handler_instructions[athrow_index - 1]
        if not (
            exception_reload.get("mnemonic") == "aload"
            and int(exception_reload.get("local_index", -1))
            == exception_slot
        ):
            continue
        handler_block = handler_instructions[: athrow_index + 1]
        if any(
            (
                str(row.get("mnemonic", "")).startswith("if")
                or row.get("mnemonic") in {
                    "goto",
                    "goto_w",
                    "tableswitch",
                    "lookupswitch",
                    "ireturn",
                    "lreturn",
                    "freturn",
                    "dreturn",
                    "areturn",
                    "return",
                }
            )
            for row in handler_block[:-1]
        ):
            continue
        athrow_offset = int(
            handler_instructions[athrow_index].get("offset", -1)
        )

        for invocation in invocations:
            offset = int(invocation.get("offset", -1))
            if not (handler_pc <= offset < athrow_offset):
                continue
            descriptor = str(invocation.get("descriptor", ""))
            arity = _descriptor_parameter_count(descriptor)
            if arity is None:
                continue
            signature = (str(invocation.get("name", "")), arity)
            if signature not in relevant_signatures:
                continue
            normal_copies = [
                row
                for row in invocations
                if (
                    str(row.get("name", "")) == signature[0]
                    and str(row.get("descriptor", "")) == descriptor
                    and end_pc
                    <= int(row.get("offset", -1))
                    < handler_pc
                )
            ]
            if len(normal_copies) != 1:
                continue
            if offset in counted_handler_offsets:
                continue
            counted_handler_offsets.add(offset)
            result[signature] = result.get(signature, 0) + 1

    return result


def _descriptor_parameter_count(descriptor: str) -> int | None:
    if not descriptor.startswith("("):
        return None
    i = 1
    count = 0
    while i < len(descriptor) and descriptor[i] != ")":
        while i < len(descriptor) and descriptor[i] == "[":
            i += 1
        if i >= len(descriptor):
            return None
        if descriptor[i] == "L":
            end = descriptor.find(";", i + 1)
            if end < 0:
                return None
            i = end + 1
        elif descriptor[i] in "ZBCSIJFD":
            i += 1
        else:
            return None
        count += 1
    if i >= len(descriptor) or descriptor[i] != ")":
        return None
    return count


def _source_parameter_shapes(
    params: str,
) -> list[tuple[int, str, str]] | None:
    text = params.strip()
    if not text:
        return []
    parts: list[str] = []
    start = 0
    depth = 0
    for index, ch in enumerate(text):
        if ch == "<":
            depth += 1
        elif ch == ">" and depth:
            depth -= 1
        elif ch == "," and depth == 0:
            parts.append(text[start:index].strip())
            start = index + 1
    parts.append(text[start:].strip())

    primitive = {
        "boolean": "Z", "byte": "B", "char": "C", "short": "S",
        "int": "I", "long": "J", "float": "F", "double": "D",
    }
    out: list[tuple[int, str, str]] = []
    for part in parts:
        value = re.sub(r"^(?:final\s+)+", "", part.strip())
        match = re.fullmatch(
            r"(?P<type>.+?)\s+"
            r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)"
            r"(?P<var_arrays>(?:\[\])*)",
            value,
        )
        if match is None:
            return None
        type_text = match.group("type").strip()
        # Erase generic arguments conservatively while preserving the raw
        # reference name around them.
        erased: list[str] = []
        generic_depth = 0
        for ch in type_text:
            if ch == "<":
                generic_depth += 1
            elif ch == ">" and generic_depth:
                generic_depth -= 1
            elif generic_depth == 0:
                erased.append(ch)
        type_text = "".join(erased).strip()
        arrays = 0
        while type_text.endswith("[]"):
            arrays += 1
            type_text = type_text[:-2].strip()
        arrays += len(match.group("var_arrays")) // 2
        if type_text in primitive:
            out.append((arrays, "primitive", primitive[type_text]))
            continue
        if not re.fullmatch(
            r"[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)*",
            type_text,
        ):
            return None
        kind = "qualified_ref" if "." in type_text else "simple_ref"
        out.append((arrays, kind, type_text))
    return out


def _descriptor_parameter_shapes(
    descriptor: str,
) -> list[tuple[int, str, str]] | None:
    if not descriptor.startswith("("):
        return None
    i = 1
    out: list[tuple[int, str, str]] = []
    while i < len(descriptor) and descriptor[i] != ")":
        arrays = 0
        while i < len(descriptor) and descriptor[i] == "[":
            arrays += 1
            i += 1
        if i >= len(descriptor):
            return None
        ch = descriptor[i]
        if ch == "L":
            end = descriptor.find(";", i + 1)
            if end < 0:
                return None
            out.append((arrays, "ref", descriptor[i + 1:end]))
            i = end + 1
        elif ch in "ZBCSIJFD":
            out.append((arrays, "primitive", ch))
            i += 1
        else:
            return None
    if i >= len(descriptor) or descriptor[i] != ")":
        return None
    return out


def _descriptor_parameter_local_slots(
    descriptor: str,
    *,
    is_static: bool,
) -> list[int] | None:
    shapes = _descriptor_parameter_shapes(descriptor)
    if shapes is None:
        return None
    slot = 0 if is_static else 1
    slots: list[int] = []
    for arrays, kind, name in shapes:
        slots.append(slot)
        width = 1
        if arrays == 0 and kind == "primitive" and name in {"J", "D"}:
            width = 2
        slot += width
    return slots


def _source_parameters_match_descriptor(
    params: str,
    descriptor: str,
    *,
    current_package: str | None = None,
) -> bool | None:
    source = _source_parameter_shapes(params)
    target = _descriptor_parameter_shapes(descriptor)
    if source is None or target is None:
        return None
    if len(source) != len(target):
        return False
    for (s_arrays, s_kind, s_name), (t_arrays, t_kind, t_name) in zip(
        source, target
    ):
        if s_arrays != t_arrays:
            return False
        if s_kind == "primitive":
            if t_kind != "primitive" or s_name != t_name:
                return False
            continue
        if t_kind != "ref":
            return False
        if s_kind == "qualified_ref":
            parts = s_name.split(".")
            candidates: set[str] = set()
            # A dotted Java source type can represent package separators,
            # nested-class separators, or (for a relative spelling such as
            # h.a) a type in the current package. Enumerate those exact JVM
            # spellings and require the descriptor owner to equal one.
            for split in range(1, len(parts) + 1):
                package = "/".join(parts[:split])
                nested = "$".join(parts[split:])
                candidates.add(package + (("$" + nested) if nested else ""))
            if current_package:
                relative = set()
                for candidate in candidates:
                    relative.add(current_package + "/" + candidate)
                candidates.update(relative)
            if t_name not in candidates:
                return False
        else:
            target_simple = t_name.rsplit("/", 1)[-1].rsplit("$", 1)[-1]
            if target_simple != s_name:
                return False
    return True


def _brace_depth_before(code: str, offset: int) -> int:
    depth = 0
    for ch in code[:offset]:
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth = max(0, depth - 1)
    return depth


def _block_has_same_name_local_declaration(
    code: str,
    *,
    simple_name: str,
) -> bool:
    local_name = re.compile(
        r"(?:^|[;{}]\s*|\(\s*|,\s*)\s*"
        r"(?:final\s+)?"
        r"[A-Za-z_$][A-Za-z0-9_$.\[\]<>?]*"
        r"(?:\s*<[^;{}()]*>)?\s+"
        + re.escape(simple_name)
        + r"\s*(?==|;|,|:|\))",
        re.MULTILINE,
    )
    return bool(local_name.search(code))

def _hierarchy_static_field_access_counts(
    method: dict[str, Any],
    *,
    hierarchy: list[tuple[str, Any]],
    targets: dict[str, str],
) -> dict[tuple[str, str], int]:
    hierarchy_index = {
        owner: index for index, (owner, _parsed) in enumerate(hierarchy)
    }
    counts: dict[tuple[str, str], int] = {}

    for access in method.get("field_accesses", []):
        if access.get("operation") not in {"getstatic", "putstatic"}:
            continue
        field_name = str(access.get("name", ""))
        expected_declaring = targets.get(field_name)
        if expected_declaring is None:
            continue
        symbolic_owner = str(access.get("owner", ""))
        start = hierarchy_index.get(symbolic_owner)
        if start is None:
            continue

        resolved_owner: str | None = None
        for owner, parsed in hierarchy[start:]:
            declarations = [
                field
                for field in parsed.fields
                if (
                    str(field.get("name", "")) == field_name
                    and int(field.get("access", 0)) & 0x0008
                )
            ]
            if declarations:
                if len(declarations) != 1:
                    resolved_owner = None
                else:
                    resolved_owner = owner
                break

        if resolved_owner != expected_declaring:
            continue
        key = (expected_declaring, field_name)
        counts[key] = counts.get(key, 0) + 1

    return counts


def _nearest_visible_instance_reference_field(
    *,
    hierarchy: list[tuple[str, Any]],
    current_owner: str,
    field_name: str,
) -> tuple[str, str] | None:
    """Resolve the nearest visible instance reference field by Java name."""
    for owner, parsed in hierarchy:
        declarations = [
            field
            for field in parsed.fields
            if (
                str(field.get("name", "")) == field_name
                and _field_visible_from(
                    declaring_owner=owner,
                    current_owner=current_owner,
                    access=int(field.get("access", 0)),
                )
            )
        ]
        if not declarations:
            continue
        if len(declarations) != 1:
            return None
        field = declarations[0]
        if int(field.get("access", 0)) & 0x0008:
            return None
        descriptor = str(field.get("descriptor", ""))
        if not (
            descriptor.startswith("L")
            and descriptor.endswith(";")
        ):
            return None
        return owner, descriptor[1:-1]
    return None


def _hierarchy_instance_field_get_count(
    method: dict[str, Any],
    *,
    hierarchy: list[tuple[str, Any]],
    field_name: str,
    declaring_owner: str,
    descriptor: str,
) -> int:
    hierarchy_index = {
        owner: index for index, (owner, _parsed) in enumerate(hierarchy)
    }
    count = 0
    for access in method.get("field_accesses", []):
        if access.get("operation") != "getfield":
            continue
        if str(access.get("name", "")) != field_name:
            continue
        if str(access.get("descriptor", "")) != descriptor:
            continue
        symbolic_owner = str(access.get("owner", ""))
        start = hierarchy_index.get(symbolic_owner)
        if start is None:
            continue

        resolved_owner: str | None = None
        for owner, parsed in hierarchy[start:]:
            declarations = [
                field
                for field in parsed.fields
                if (
                    str(field.get("name", "")) == field_name
                    and not (int(field.get("access", 0)) & 0x0008)
                    and str(field.get("descriptor", "")) == descriptor
                )
            ]
            if declarations:
                resolved_owner = owner if len(declarations) == 1 else None
                break

        if resolved_owner == declaring_owner:
            count += 1
    return count


def _normalize_hierarchy_shadowed_self_static_field_owners(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Qualify class-static fields hidden by primitive-value shadows.

    Procyon can emit h.ae inside class h while h (or a superclass) also
    declares a primitive scalar/array field named h. javac resolves h as a value
    expression and reports "int cannot be dereferenced". Rewriting is
    allowed only when hierarchy shape, source occurrence counts and one
    exact bytecode method agree.
    """
    rel = path.relative_to(source_root).as_posix()
    simple_name_from_path = Path(rel).stem
    text = path.read_text(encoding="utf-8")
    code = _java_code_mask(text)
    candidate = re.compile(
        r"(?<![A-Za-z0-9_$.])"
        + re.escape(simple_name_from_path)
        + r"\.[A-Za-z_$][A-Za-z0-9_$]*\b"
    )
    if candidate.search(code) is None:
        return []

    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
    except KeyError:
        return []

    try:
        profile = profile_class_field_accesses(class_bytes)
    except BytecodeProfileError as exc:
        raise SourceNormalizationError(
            f"{rel}: exact readable class field profile failed: {exc}"
        ) from exc

    internal_name = str(profile["internal_name"])
    simple_name = internal_name.rsplit("/", 1)[-1]
    if Path(rel).stem != simple_name:
        return []

    hierarchy = _read_readable_hierarchy(
        readable_zip=readable_zip,
        internal_name=internal_name,
    )
    if not hierarchy:
        return []

    primitive_shadow_owners = [
        owner
        for owner, parsed in hierarchy
        for field in parsed.fields
        if (
            str(field.get("name", "")) == simple_name
            and _is_primitive_value_shadow_descriptor(
                str(field.get("descriptor", ""))
            )
            and _field_visible_from(
                declaring_owner=owner,
                current_owner=internal_name,
                access=int(field.get("access", 0)),
            )
        )
    ]
    if not primitive_shadow_owners:
        return []

    static_by_name: dict[str, list[str]] = {}
    for owner, parsed in hierarchy:
        for field in parsed.fields:
            name = str(field.get("name", ""))
            if (
                int(field.get("access", 0)) & 0x0008
                and _is_java_identifier(name)
                and _field_visible_from(
                    declaring_owner=owner,
                    current_owner=internal_name,
                    access=int(field.get("access", 0)),
                )
            ):
                static_by_name.setdefault(name, []).append(owner)
    static_targets = {
        name: owners[0]
        for name, owners in static_by_name.items()
        if len(owners) == 1
    }
    if not static_targets:
        return []

    qualified_owner = internal_name.replace("/", ".")
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for match in _METHOD_DECL_RE.finditer(text):
        brace_start = text.find("{", match.start(), match.end())
        if brace_start < 0:
            continue
        body_end = _matching_brace_end(text, brace_start)
        method_text = text[match.start():body_end]
        method_code = _java_code_mask(method_text)

        parameter_shadow, local_shadow_spans = (
            _same_name_value_shadow_spans(
                method_match=match,
                method_code=method_code,
                simple_name=simple_name,
            )
        )
        if parameter_shadow:
            continue

        source_counts: dict[tuple[str, str], int] = {}
        occurrences: list[tuple[int, int, str]] = []
        for field_name, declaring_owner in sorted(static_targets.items()):
            token = re.compile(
                r"(?<![A-Za-z0-9_$.])"
                + re.escape(simple_name)
                + r"\."
                + re.escape(field_name)
                + r"\b(?!\s*\()"
            )
            hits = [
                hit
                for hit in token.finditer(method_code)
                if not any(
                    start <= hit.start() < end
                    for start, end in local_shadow_spans
                )
            ]
            if not hits:
                continue
            source_counts[(declaring_owner, field_name)] = len(hits)
            for hit in hits:
                occurrences.append(
                    (
                        match.start() + hit.start(),
                        match.start() + hit.end(),
                        qualified_owner + "." + field_name,
                    )
                )
        if not source_counts:
            continue

        candidates: list[dict[str, Any]] = []
        source_arity = _source_parameter_count(match.group("params"))
        for method in profile.get("methods", []):
            if method.get("name") != match.group("name"):
                continue
            descriptor = str(method.get("descriptor", ""))
            if _descriptor_parameter_count(descriptor) != source_arity:
                continue
            parameter_match = _source_parameters_match_descriptor(
                match.group("params"),
                descriptor,
                current_package=internal_name.rpartition("/")[0],
            )
            if parameter_match is False:
                continue
            exact_counts = _hierarchy_static_field_access_counts(
                method,
                hierarchy=hierarchy,
                targets=static_targets,
            )
            if all(
                exact_counts.get(key, 0) >= count
                for key, count in source_counts.items()
            ):
                candidates.append(method)

        if len(candidates) != 1:
            continue

        exact_method = candidates[0]
        edits.extend(occurrences)
        actions.append(
            {
                "kind": (
                    "hierarchy_shadowed_self_static_field_owner_qualification"
                ),
                "source_path": rel,
                "method_name": match.group("name"),
                "method_descriptor": exact_method["descriptor"],
                "qualified_owner": internal_name,
                "primitive_shadow_owners": sorted(
                    set(primitive_shadow_owners)
                ),
                "field_access_counts": {
                    owner + "." + name: count
                    for (owner, name), count in sorted(
                        source_counts.items()
                    )
                },
                "replacement_count": sum(source_counts.values()),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_hierarchy_primitive_value_shadowed_class_owner"
                    ),
                    "strategy": (
                        "exact_hierarchy_static_field_access_sufficiency_qualification"
                    ),
                },
            }
        )

    whole_code = _java_code_mask(text)
    static_block_re = re.compile(r"(?m)^[ \t]*static[ \t]*\{")
    exact_clinits = [
        method
        for method in profile.get("methods", [])
        if method.get("name") == "<clinit>"
        and method.get("descriptor") == "()V"
    ]
    if len(exact_clinits) == 1:
        for block_match in static_block_re.finditer(whole_code):
            brace_start = whole_code.find(
                "{", block_match.start(), block_match.end()
            )
            if (
                brace_start < 0
                or _brace_depth_before(whole_code, brace_start) != 1
            ):
                continue
            block_end = _matching_brace_end(whole_code, brace_start)
            block_code = whole_code[block_match.start():block_end]
            if _block_has_same_name_local_declaration(
                block_code, simple_name=simple_name
            ):
                continue

            block_counts: dict[tuple[str, str], int] = {}
            block_occurrences: list[tuple[int, int, str]] = []
            for field_name, declaring_owner in sorted(
                static_targets.items()
            ):
                token = re.compile(
                    r"(?<![A-Za-z0-9_$.])"
                    + re.escape(simple_name)
                    + r"\."
                    + re.escape(field_name)
                    + r"\b(?!\s*\()"
                )
                hits = list(token.finditer(block_code))
                if not hits:
                    continue
                block_counts[(declaring_owner, field_name)] = len(hits)
                for hit in hits:
                    block_occurrences.append(
                        (
                            block_match.start() + hit.start(),
                            block_match.start() + hit.end(),
                            qualified_owner + "." + field_name,
                        )
                    )
            if not block_counts:
                continue
            exact_counts = _hierarchy_static_field_access_counts(
                exact_clinits[0],
                hierarchy=hierarchy,
                targets=static_targets,
            )
            if not all(
                exact_counts.get(key, 0) >= count
                for key, count in block_counts.items()
            ):
                continue
            edits.extend(block_occurrences)
            actions.append(
                {
                    "kind": (
                        "hierarchy_shadowed_self_static_field_owner_qualification"
                    ),
                    "source_path": rel,
                    "method_name": "<clinit>",
                    "method_descriptor": "()V",
                    "qualified_owner": internal_name,
                    "primitive_shadow_owners": sorted(
                        set(primitive_shadow_owners)
                    ),
                    "field_access_counts": {
                        owner + "." + name: count
                        for (owner, name), count in sorted(
                            block_counts.items()
                        )
                    },
                    "replacement_count": sum(block_counts.values()),
                    "provenance": {
                        "kind": "source_safety",
                        "reason": (
                            "procyon_hierarchy_primitive_shadowed_class_owner"
                        ),
                        "strategy": (
                            "exact_hierarchy_static_field_access_sufficiency_qualification"
                        ),
                    },
                }
            )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping hierarchy owner-qualification edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_primitive_scope_shadowed_self_static_field_owners(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Qualify self static fields hidden by primitive parameters or locals.

    Procyon can print i.c inside class i while a scalar primitive parameter
    or local named i is in scope. javac then treats i as the primitive value
    and reports that it cannot be dereferenced. Only occurrences proven by
    one exact readable bytecode method's complete static-field access
    multiset are rewritten.
    """
    rel = path.relative_to(source_root).as_posix()
    simple_name_from_path = Path(rel).stem
    text = path.read_text(encoding="utf-8")
    code = _java_code_mask(text)
    candidate = re.compile(
        r"(?<![A-Za-z0-9_$.])"
        + re.escape(simple_name_from_path)
        + r"\.[A-Za-z_$][A-Za-z0-9_$]*\b"
    )
    if candidate.search(code) is None:
        return []

    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
    except KeyError:
        return []

    try:
        profile = profile_class_field_accesses(class_bytes)
    except BytecodeProfileError as exc:
        raise SourceNormalizationError(
            f"{rel}: exact readable class field profile failed: {exc}"
        ) from exc

    internal_name = str(profile["internal_name"])
    simple_name = internal_name.rsplit("/", 1)[-1]
    if Path(rel).stem != simple_name:
        return []

    hierarchy = _read_readable_hierarchy(
        readable_zip=readable_zip,
        internal_name=internal_name,
    )
    if not hierarchy:
        return []

    static_by_name: dict[str, list[str]] = {}
    for owner, parsed in hierarchy:
        for field in parsed.fields:
            name = str(field.get("name", ""))
            if (
                int(field.get("access", 0)) & 0x0008
                and _is_java_identifier(name)
                and _field_visible_from(
                    declaring_owner=owner,
                    current_owner=internal_name,
                    access=int(field.get("access", 0)),
                )
            ):
                static_by_name.setdefault(name, []).append(owner)
    static_targets = {
        name: owners[0]
        for name, owners in static_by_name.items()
        if len(owners) == 1
    }
    if not static_targets:
        return []

    qualified_owner = internal_name.replace("/", ".")
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for match in _METHOD_DECL_RE.finditer(text):
        brace_start = text.find("{", match.start(), match.end())
        if brace_start < 0:
            continue
        body_end = _matching_brace_end(text, brace_start)
        method_text = text[match.start():body_end]
        method_code = _java_code_mask(method_text)

        reference_parameter, reference_local_spans = (
            _same_name_value_shadow_spans(
                method_match=match,
                method_code=method_code,
                simple_name=simple_name,
            )
        )
        if reference_parameter:
            continue

        primitive_parameter, primitive_local_spans = (
            _primitive_same_name_value_shadow_spans(
                method_match=match,
                method_code=method_code,
                simple_name=simple_name,
            )
        )
        if not primitive_parameter and not primitive_local_spans:
            continue

        affected_counts: dict[tuple[str, str], int] = {}
        total_source_counts: dict[tuple[str, str], int] = {}
        occurrences: list[tuple[int, int, str]] = []

        for field_name, declaring_owner in sorted(static_targets.items()):
            simple_token = re.compile(
                r"(?<![A-Za-z0-9_$.])"
                + re.escape(simple_name)
                + r"\."
                + re.escape(field_name)
                + r"\b(?!\s*\()"
            )
            simple_hits = [
                hit
                for hit in simple_token.finditer(method_code)
                if not any(
                    start <= hit.start() < end
                    for start, end in reference_local_spans
                )
            ]
            qualified_token = re.compile(
                r"(?<![A-Za-z0-9_$.])"
                + re.escape(qualified_owner)
                + r"\."
                + re.escape(field_name)
                + r"\b(?!\s*\()"
            )
            qualified_hits = list(qualified_token.finditer(method_code))

            affected_hits = [
                hit
                for hit in simple_hits
                if (
                    primitive_parameter
                    or any(
                        start <= hit.start() < end
                        for start, end in primitive_local_spans
                    )
                )
            ]
            if not affected_hits:
                continue

            key = (declaring_owner, field_name)
            affected_counts[key] = len(affected_hits)
            total_source_counts[key] = len(simple_hits) + len(qualified_hits)
            for hit in affected_hits:
                occurrences.append(
                    (
                        match.start() + hit.start(),
                        match.start() + hit.end(),
                        qualified_owner + "." + field_name,
                    )
                )

        if not affected_counts:
            continue

        candidates: list[dict[str, Any]] = []
        source_arity = _source_parameter_count(match.group("params"))
        for method in profile.get("methods", []):
            if method.get("name") != match.group("name"):
                continue
            descriptor = str(method.get("descriptor", ""))
            if _descriptor_parameter_count(descriptor) != source_arity:
                continue
            parameter_match = _source_parameters_match_descriptor(
                match.group("params"),
                descriptor,
                current_package=internal_name.rpartition("/")[0],
            )
            if parameter_match is False:
                continue

            exact_counts = _hierarchy_static_field_access_counts(
                method,
                hierarchy=hierarchy,
                targets=static_targets,
            )
            if all(
                exact_counts.get(key, 0) == count
                for key, count in total_source_counts.items()
            ):
                candidates.append(method)

        if len(candidates) != 1:
            continue

        exact_method = candidates[0]
        edits.extend(occurrences)
        actions.append(
            {
                "kind": (
                    "primitive_scope_shadowed_self_static_field_owner_qualification"
                ),
                "source_path": rel,
                "method_name": match.group("name"),
                "method_descriptor": exact_method["descriptor"],
                "qualified_owner": internal_name,
                "primitive_parameter_shadow": primitive_parameter,
                "primitive_local_shadow_scope_count": len(
                    primitive_local_spans
                ),
                "field_access_counts": {
                    owner + "." + name: count
                    for (owner, name), count in sorted(
                        affected_counts.items()
                    )
                },
                "total_field_access_counts": {
                    owner + "." + name: count
                    for (owner, name), count in sorted(
                        total_source_counts.items()
                    )
                },
                "replacement_count": sum(affected_counts.values()),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_primitive_scope_shadowed_self_class_owner"
                    ),
                    "strategy": (
                        "exact_method_complete_static_field_access_qualification"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping primitive-scope self-owner edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_primitive_shadowed_instance_field_receivers(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore instance-field receivers hidden by scalar primitive values.

    Procyon can emit h.a(...) while a primitive parameter/local named h
    shadows the current object's reference field h. Rewriting to this.h is
    permitted only when one exact readable method proves both the complete
    getfield count for h and the matching invokevirtual/invokeinterface
    owner/name multiset.
    """
    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
    except KeyError:
        return []
    try:
        profile = profile_class_field_accesses(class_bytes)
    except BytecodeProfileError:
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []

    hierarchy = _read_readable_hierarchy(
        readable_zip=readable_zip,
        internal_name=current_owner,
    )
    if not hierarchy:
        return []

    visible_names = sorted(
        {
            str(field.get("name", ""))
            for owner, parsed in hierarchy
            for field in parsed.fields
            if (
                _is_java_identifier(str(field.get("name", "")))
                and _field_visible_from(
                    declaring_owner=owner,
                    current_owner=current_owner,
                    access=int(field.get("access", 0)),
                )
            )
        }
    )
    receivers: dict[str, tuple[str, str]] = {}
    for simple in visible_names:
        resolved = _nearest_visible_instance_reference_field(
            hierarchy=hierarchy,
            current_owner=current_owner,
            field_name=simple,
        )
        if resolved is not None:
            receivers[simple] = resolved
    if not receivers:
        return []

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for match in _METHOD_DECL_RE.finditer(text):
        brace_start = text.find("{", match.start(), match.end())
        if brace_start < 0:
            continue
        header_code = whole_code[match.start():brace_start]
        if re.search(r"\bstatic\b", header_code) is not None:
            continue

        body_end = _matching_brace_end(text, brace_start)
        method_text = text[match.start():body_end]
        method_code = _java_code_mask(method_text)

        for simple, (declaring_owner, receiver_owner) in sorted(
            receivers.items()
        ):
            reference_parameter, reference_local_spans = (
                _same_name_value_shadow_spans(
                    method_match=match,
                    method_code=method_code,
                    simple_name=simple,
                )
            )
            if reference_parameter:
                continue
            primitive_parameter, primitive_local_spans = (
                _primitive_same_name_value_shadow_spans(
                    method_match=match,
                    method_code=method_code,
                    simple_name=simple,
                )
            )
            if not primitive_parameter and not primitive_local_spans:
                continue

            simple_call = re.compile(
                r"(?<![A-Za-z0-9_$.])"
                + re.escape(simple)
                + r"\.(?P<method>[A-Za-z_$][A-Za-z0-9_$]*)\s*\("
            )
            simple_hits = [
                hit
                for hit in simple_call.finditer(method_code)
                if not any(
                    start <= hit.start() < end
                    for start, end in reference_local_spans
                )
            ]
            affected_hits = [
                hit
                for hit in simple_hits
                if (
                    primitive_parameter
                    or any(
                        start <= hit.start() < end
                        for start, end in primitive_local_spans
                    )
                )
            ]
            if not affected_hits:
                continue

            qualified_call = re.compile(
                r"(?<![A-Za-z0-9_$.])this\."
                + re.escape(simple)
                + r"\.(?P<method>[A-Za-z_$][A-Za-z0-9_$]*)\s*\("
            )
            qualified_hits = list(qualified_call.finditer(method_code))

            affected_counts: dict[str, int] = {}
            total_counts: dict[str, int] = {}
            for hit in affected_hits:
                name = hit.group("method")
                affected_counts[name] = affected_counts.get(name, 0) + 1
            for hit in simple_hits + qualified_hits:
                name = hit.group("method")
                total_counts[name] = total_counts.get(name, 0) + 1

            source_arity = _source_parameter_count(match.group("params"))
            candidates: list[dict[str, Any]] = []
            field_descriptor = "L" + receiver_owner + ";"
            for method in profile.get("methods", []):
                if method.get("name") != match.group("name"):
                    continue
                descriptor = str(method.get("descriptor", ""))
                if _descriptor_parameter_count(descriptor) != source_arity:
                    continue
                parameter_match = _source_parameters_match_descriptor(
                    match.group("params"),
                    descriptor,
                    current_package=current_owner.rpartition("/")[0],
                )
                if parameter_match is False:
                    continue

                field_get_count = _hierarchy_instance_field_get_count(
                    method,
                    hierarchy=hierarchy,
                    field_name=simple,
                    declaring_owner=declaring_owner,
                    descriptor=field_descriptor,
                )
                if field_get_count != sum(total_counts.values()):
                    continue

                invocation_counts: dict[str, int] = {}
                for invocation in method.get("method_invocations", []):
                    if invocation.get("operation") not in {
                        "invokevirtual",
                        "invokeinterface",
                    }:
                        continue
                    if str(invocation.get("owner", "")) != receiver_owner:
                        continue
                    name = str(invocation.get("name", ""))
                    if name not in total_counts:
                        continue
                    invocation_counts[name] = (
                        invocation_counts.get(name, 0) + 1
                    )

                if all(
                    invocation_counts.get(name, 0) == count
                    for name, count in total_counts.items()
                ):
                    candidates.append(method)

            if len(candidates) != 1:
                continue

            exact_method = candidates[0]
            for hit in affected_hits:
                edits.append(
                    (
                        match.start() + hit.start(),
                        match.start() + hit.start() + len(simple),
                        "this." + simple,
                    )
                )
            actions.append(
                {
                    "kind": (
                        "primitive_shadowed_instance_field_receiver_qualification"
                    ),
                    "source_path": rel,
                    "method_name": match.group("name"),
                    "method_descriptor": exact_method["descriptor"],
                    "receiver_field_name": simple,
                    "receiver_declaring_owner": declaring_owner,
                    "receiver_type_owner": receiver_owner,
                    "primitive_parameter_shadow": primitive_parameter,
                    "primitive_local_shadow_scope_count": len(
                        primitive_local_spans
                    ),
                    "call_counts": dict(sorted(affected_counts.items())),
                    "total_call_counts": dict(sorted(total_counts.items())),
                    "replacement_count": len(affected_hits),
                    "provenance": {
                        "kind": "source_safety",
                        "reason": (
                            "procyon_primitive_scope_shadowed_instance_field_receiver"
                        ),
                        "strategy": (
                            "exact_getfield_and_virtual_invocation_multiset_qualification"
                        ),
                    },
                }
            )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping instance-receiver qualification edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_reference_shadowed_self_static_field_owners(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Qualify self static fields hidden by a same-name reference field.

    This is the reference-valued counterpart to the primitive hierarchy rule.
    Ordinary methods and constructors are eligible; parameter/local value
    shadows remain excluded, source/exact method staticness must match, and
    exact readable bytecode must account for the complete source field-access
    multiset before any owner is qualified.
    """
    rel = path.relative_to(source_root).as_posix()
    simple_name_from_path = Path(rel).stem
    text = path.read_text(encoding="utf-8")
    code = _java_code_mask(text)
    candidate = re.compile(
        r"(?<![A-Za-z0-9_$.])"
        + re.escape(simple_name_from_path)
        + r"\.[A-Za-z_$][A-Za-z0-9_$]*\b"
    )
    if candidate.search(code) is None:
        return []

    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
    except KeyError:
        return []

    try:
        profile = profile_class_field_accesses(class_bytes)
    except BytecodeProfileError as exc:
        raise SourceNormalizationError(
            f"{rel}: exact readable class field profile failed: {exc}"
        ) from exc

    internal_name = str(profile["internal_name"])
    simple_name = internal_name.rsplit("/", 1)[-1]
    if Path(rel).stem != simple_name:
        return []

    hierarchy = _read_readable_hierarchy(
        readable_zip=readable_zip,
        internal_name=internal_name,
    )
    if not hierarchy:
        return []

    reference_shadow_owners = [
        owner
        for owner, parsed in hierarchy
        for field in parsed.fields
        if (
            str(field.get("name", "")) == simple_name
            and not (int(field.get("access", 0)) & 0x0008)
            and _is_reference_value_shadow_descriptor(
                str(field.get("descriptor", ""))
            )
            and _field_visible_from(
                declaring_owner=owner,
                current_owner=internal_name,
                access=int(field.get("access", 0)),
            )
        )
    ]
    if not reference_shadow_owners:
        return []

    static_by_name: dict[str, list[str]] = {}
    for owner, parsed in hierarchy:
        for field in parsed.fields:
            name = str(field.get("name", ""))
            if (
                int(field.get("access", 0)) & 0x0008
                and _is_java_identifier(name)
                and _field_visible_from(
                    declaring_owner=owner,
                    current_owner=internal_name,
                    access=int(field.get("access", 0)),
                )
            ):
                static_by_name.setdefault(name, []).append(owner)
    static_targets = {
        name: owners[0]
        for name, owners in static_by_name.items()
        if len(owners) == 1
    }
    if not static_targets:
        return []

    qualified_owner = internal_name.replace("/", ".")
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for match in _METHOD_DECL_RE.finditer(text):
        brace_start = text.find("{", match.start(), match.end())
        if brace_start < 0:
            continue
        header_code = code[match.start():brace_start]
        source_static = re.search(r"\bstatic\b", header_code) is not None

        body_end = _matching_brace_end(text, brace_start)
        method_text = text[match.start():body_end]
        method_code = _java_code_mask(method_text)

        parameter_shadow, local_shadow_spans = (
            _same_name_value_shadow_spans(
                method_match=match,
                method_code=method_code,
                simple_name=simple_name,
            )
        )
        if parameter_shadow:
            continue

        source_counts: dict[tuple[str, str], int] = {}
        total_source_counts: dict[tuple[str, str], int] = {}
        occurrences: list[tuple[int, int, str]] = []

        for field_name, declaring_owner in sorted(static_targets.items()):
            simple_token = re.compile(
                r"(?<![A-Za-z0-9_$.])"
                + re.escape(simple_name)
                + r"\."
                + re.escape(field_name)
                + r"\b(?!\s*\()"
            )
            simple_hits = [
                hit
                for hit in simple_token.finditer(method_code)
                if not any(
                    start <= hit.start() < end
                    for start, end in local_shadow_spans
                )
            ]
            if not simple_hits:
                continue

            qualified_token = re.compile(
                r"(?<![A-Za-z0-9_$.])"
                + re.escape(qualified_owner)
                + r"\."
                + re.escape(field_name)
                + r"\b(?!\s*\()"
            )
            qualified_hits = list(qualified_token.finditer(method_code))

            key = (declaring_owner, field_name)
            source_counts[key] = len(simple_hits)
            total_source_counts[key] = len(simple_hits) + len(qualified_hits)
            for hit in simple_hits:
                occurrences.append(
                    (
                        match.start() + hit.start(),
                        match.start() + hit.end(),
                        qualified_owner + "." + field_name,
                    )
                )

        if not source_counts:
            continue

        candidates: list[dict[str, Any]] = []
        source_arity = _source_parameter_count(match.group("params"))
        for method in profile.get("methods", []):
            if method.get("name") != match.group("name"):
                continue
            method_static = bool(
                int(method.get("access", 0)) & 0x0008
            )
            if method_static != source_static:
                continue
            descriptor = str(method.get("descriptor", ""))
            if _descriptor_parameter_count(descriptor) != source_arity:
                continue
            parameter_match = _source_parameters_match_descriptor(
                match.group("params"),
                descriptor,
                current_package=internal_name.rpartition("/")[0],
            )
            if parameter_match is False:
                continue

            exact_counts = _hierarchy_static_field_access_counts(
                method,
                hierarchy=hierarchy,
                targets=static_targets,
            )
            if all(
                exact_counts.get(key, 0) == count
                for key, count in total_source_counts.items()
            ):
                candidates.append(method)

        if len(candidates) != 1:
            continue

        exact_method = candidates[0]
        edits.extend(occurrences)
        actions.append(
            {
                "kind": (
                    "reference_shadowed_self_static_field_owner_qualification"
                ),
                "source_path": rel,
                "method_name": match.group("name"),
                "method_descriptor": exact_method["descriptor"],
                "qualified_owner": internal_name,
                "reference_shadow_owners": sorted(
                    set(reference_shadow_owners)
                ),
                "field_access_counts": {
                    owner + "." + name: count
                    for (owner, name), count in sorted(source_counts.items())
                },
                "total_field_access_counts": {
                    owner + "." + name: count
                    for (owner, name), count in sorted(
                        total_source_counts.items()
                    )
                },
                "replacement_count": sum(source_counts.values()),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_reference_value_shadowed_self_class_owner"
                    ),
                    "strategy": (
                        "exact_static_method_complete_field_access_qualification"
                        if source_static
                        else "exact_instance_method_complete_field_access_qualification"
                    ),
                },
            }
        )

    constructor_re = re.compile(
        r"(?m)^(?P<indent>[ \t]*)"
        r"(?:(?:public|private|protected)\s+)*"
        + re.escape(simple_name)
        + r"\s*\((?P<params>[^()\n]*)\)\s*"
        r"(?:throws\s+[^\{\n]+\s*)?\{"
    )
    for match in constructor_re.finditer(text):
        brace_start = text.find("{", match.start(), match.end())
        if brace_start < 0:
            continue
        body_end = _matching_brace_end(text, brace_start)
        constructor_text = text[match.start():body_end]
        constructor_code = _java_code_mask(constructor_text)

        if _block_has_same_name_local_declaration(
            constructor_code,
            simple_name=simple_name,
        ):
            continue

        source_counts: dict[tuple[str, str], int] = {}
        total_source_counts: dict[tuple[str, str], int] = {}
        occurrences: list[tuple[int, int, str]] = []

        for field_name, declaring_owner in sorted(static_targets.items()):
            simple_token = re.compile(
                r"(?<![A-Za-z0-9_$.])"
                + re.escape(simple_name)
                + r"\."
                + re.escape(field_name)
                + r"\b(?!\s*\()"
            )
            simple_hits = list(simple_token.finditer(constructor_code))
            if not simple_hits:
                continue

            qualified_token = re.compile(
                r"(?<![A-Za-z0-9_$.])"
                + re.escape(qualified_owner)
                + r"\."
                + re.escape(field_name)
                + r"\b(?!\s*\()"
            )
            qualified_hits = list(
                qualified_token.finditer(constructor_code)
            )

            key = (declaring_owner, field_name)
            source_counts[key] = len(simple_hits)
            total_source_counts[key] = (
                len(simple_hits) + len(qualified_hits)
            )
            for hit in simple_hits:
                occurrences.append(
                    (
                        match.start() + hit.start(),
                        match.start() + hit.end(),
                        qualified_owner + "." + field_name,
                    )
                )

        if not source_counts:
            continue

        candidates: list[dict[str, Any]] = []
        source_arity = _source_parameter_count(match.group("params"))
        for method in profile.get("methods", []):
            if method.get("name") != "<init>":
                continue
            descriptor = str(method.get("descriptor", ""))
            if _descriptor_parameter_count(descriptor) != source_arity:
                continue
            parameter_match = _source_parameters_match_descriptor(
                match.group("params"),
                descriptor,
                current_package=internal_name.rpartition("/")[0],
            )
            if parameter_match is False:
                continue

            exact_counts = _hierarchy_static_field_access_counts(
                method,
                hierarchy=hierarchy,
                targets=static_targets,
            )
            if all(
                exact_counts.get(key, 0) == count
                for key, count in total_source_counts.items()
            ):
                candidates.append(method)

        if len(candidates) != 1:
            continue

        exact_method = candidates[0]
        edits.extend(occurrences)
        actions.append(
            {
                "kind": (
                    "reference_shadowed_self_static_field_owner_qualification"
                ),
                "source_path": rel,
                "method_name": "<init>",
                "method_descriptor": exact_method["descriptor"],
                "qualified_owner": internal_name,
                "reference_shadow_owners": sorted(
                    set(reference_shadow_owners)
                ),
                "field_access_counts": {
                    owner + "." + name: count
                    for (owner, name), count in sorted(
                        source_counts.items()
                    )
                },
                "total_field_access_counts": {
                    owner + "." + name: count
                    for (owner, name), count in sorted(
                        total_source_counts.items()
                    )
                },
                "replacement_count": sum(source_counts.values()),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_reference_value_shadowed_self_class_owner"
                    ),
                    "strategy": (
                        "exact_constructor_complete_field_access_qualification"
                    ),
                },
            }
        )

    whole_code = _java_code_mask(text)
    static_block_re = re.compile(r"(?m)^[ \t]*static[ \t]*\{")
    exact_clinits = [
        method
        for method in profile.get("methods", [])
        if method.get("name") == "<clinit>"
        and method.get("descriptor") == "()V"
    ]
    if len(exact_clinits) == 1:
        exact_clinit = exact_clinits[0]
        for block_match in static_block_re.finditer(whole_code):
            brace_start = whole_code.find(
                "{", block_match.start(), block_match.end()
            )
            if (
                brace_start < 0
                or _brace_depth_before(whole_code, brace_start) != 1
            ):
                continue
            block_end = _matching_brace_end(whole_code, brace_start)
            block_code = whole_code[block_match.start():block_end]
            if _block_has_same_name_local_declaration(
                block_code,
                simple_name=simple_name,
            ):
                continue

            source_counts: dict[tuple[str, str], int] = {}
            total_source_counts: dict[tuple[str, str], int] = {}
            occurrences: list[tuple[int, int, str]] = []

            for field_name, declaring_owner in sorted(
                static_targets.items()
            ):
                simple_token = re.compile(
                    r"(?<![A-Za-z0-9_$.])"
                    + re.escape(simple_name)
                    + r"\."
                    + re.escape(field_name)
                    + r"\b(?!\s*\()"
                )
                simple_hits = list(simple_token.finditer(block_code))

                qualified_token = re.compile(
                    r"(?<![A-Za-z0-9_$.])"
                    + re.escape(qualified_owner)
                    + r"\."
                    + re.escape(field_name)
                    + r"\b(?!\s*\()"
                )
                qualified_hits = list(
                    qualified_token.finditer(block_code)
                )

                if not simple_hits:
                    continue

                key = (declaring_owner, field_name)
                source_counts[key] = len(simple_hits)
                total_source_counts[key] = (
                    len(simple_hits) + len(qualified_hits)
                )
                for hit in simple_hits:
                    occurrences.append(
                        (
                            block_match.start() + hit.start(),
                            block_match.start() + hit.end(),
                            qualified_owner + "." + field_name,
                        )
                    )

            if not source_counts:
                continue

            exact_counts = _hierarchy_static_field_access_counts(
                exact_clinit,
                hierarchy=hierarchy,
                targets=static_targets,
            )
            if not all(
                exact_counts.get(key, 0) == count
                for key, count in total_source_counts.items()
            ):
                continue

            edits.extend(occurrences)
            actions.append(
                {
                    "kind": (
                        "reference_shadowed_self_static_field_owner_qualification"
                    ),
                    "source_path": rel,
                    "method_name": "<clinit>",
                    "method_descriptor": "()V",
                    "qualified_owner": internal_name,
                    "reference_shadow_owners": sorted(
                        set(reference_shadow_owners)
                    ),
                    "field_access_counts": {
                        owner + "." + name: count
                        for (owner, name), count in sorted(
                            source_counts.items()
                        )
                    },
                    "total_field_access_counts": {
                        owner + "." + name: count
                        for (owner, name), count in sorted(
                            total_source_counts.items()
                        )
                    },
                    "replacement_count": sum(source_counts.values()),
                    "provenance": {
                        "kind": "source_safety",
                        "reason": (
                            "procyon_reference_value_shadowed_self_class_owner"
                        ),
                        "strategy": (
                            "exact_clinit_complete_field_access_qualification"
                        ),
                    },
                }
            )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping reference self-owner edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


_DOTTED_STATIC_FIELD_RE = re.compile(
    r"(?<![A-Za-z0-9_$])"
    r"(?P<owner>[A-Za-z_$][A-Za-z0-9_$]*"
    r"(?:\.[A-Za-z_$][A-Za-z0-9_$]*){1,})"
    r"\.(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)\b"
    r"(?!\s*\()"
)
_SIMPLE_STATIC_FIELD_RE = re.compile(
    r"(?<![A-Za-z0-9_$.])"
    r"(?P<owner>[A-Za-z_$][A-Za-z0-9_$]*)"
    r"\.(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)\b"
    r"(?!\s*\()"
)


def _java_owner_binary_candidates(owner: str) -> list[str]:
    parts = owner.split(".")
    candidates: list[str] = []
    for split in range(1, len(parts) + 1):
        package = "/".join(parts[:split])
        nested = "$".join(parts[split:])
        candidate = package + (("$" + nested) if nested else "")
        if candidate not in candidates:
            candidates.append(candidate)
    return candidates


def _nested_owner_binary_candidates(
    *,
    owner: str,
    current_owner: str,
    imported_outers: dict[str, str] | None = None,
) -> list[tuple[str, str]]:
    """Return exact binary candidates plus the Java owner used for rewriting.

    In addition to already-qualified owners, allow exactly one compact
    same-package outer+nested interpretation such as d.a -> rs/d$a when the
    current class is in package rs.
    """
    out: list[tuple[str, str]] = []
    seen: set[str] = set()

    for candidate in _java_owner_binary_candidates(owner):
        if candidate in seen:
            continue
        seen.add(candidate)
        out.append((candidate, owner))

    current_package = current_owner.rpartition("/")[0]
    parts = owner.split(".")
    if current_package and len(parts) >= 2:
        java_owner = current_package.replace("/", ".") + "." + owner

        package_candidate = (
            current_package
            + "/"
            + "/".join(parts)
        )
        if package_candidate not in seen:
            seen.add(package_candidate)
            out.append((package_candidate, java_owner))

        nested_candidate = (
            current_package
            + "/"
            + parts[0]
            + "$"
            + "$".join(parts[1:])
        )
        if nested_candidate not in seen:
            seen.add(nested_candidate)
            out.append((nested_candidate, java_owner))

    # An explicit import may name an outer class outside this package.
    # Preserve all other candidates; multiple bytecode witnesses still veto.
    if imported_outers and len(parts) >= 2:
        imported_outer = imported_outers.get(parts[0])
        if imported_outer:
            candidate = imported_outer + "$" + "$".join(parts[1:])
            java_owner = imported_outer.replace("/", ".") + "." + ".".join(parts[1:])
            if candidate not in seen:
                seen.add(candidate)
                out.append((candidate, java_owner))

    return out


def _package_relative_owner_has_visible_name_shadow(
    *,
    owner: str,
    candidate_internal: str,
    current_owner: str,
    readable_zip: zipfile.ZipFile,
) -> tuple[bool, list[str]]:
    current_package = current_owner.rpartition("/")[0]
    parts = owner.split(".")
    if not current_package or len(parts) < 2:
        return False, []

    expected = current_package + "/" + "/".join(parts)
    if candidate_internal != expected:
        return False, []

    leading = parts[0]
    if not _is_java_identifier(leading):
        return False, []

    hierarchy = _read_readable_hierarchy(
        readable_zip=readable_zip,
        internal_name=current_owner,
    )
    if not hierarchy:
        return False, []

    shadow_owners: list[str] = []
    for declaring_owner, parsed in hierarchy:
        for field in parsed.fields:
            if str(field.get("name", "")) != leading:
                continue
            if not _field_visible_from(
                declaring_owner=declaring_owner,
                current_owner=current_owner,
                access=int(field.get("access", 0)),
            ):
                continue
            shadow_owners.append(declaring_owner)

    return bool(shadow_owners), sorted(set(shadow_owners))


def _nested_owner_has_visible_name_shadow(
    *,
    nested_internal: str,
    current_owner: str,
    readable_zip: zipfile.ZipFile,
) -> tuple[bool, list[str]]:
    if "$" not in nested_internal.rsplit("/", 1)[-1]:
        return False, []

    outer_internal, nested_simple = nested_internal.rsplit("$", 1)
    if not _is_java_identifier(nested_simple):
        return False, []

    hierarchy = _read_readable_hierarchy(
        readable_zip=readable_zip,
        internal_name=outer_internal,
    )
    if not hierarchy:
        return False, []

    shadow_owners: list[str] = []
    for declaring_owner, parsed in hierarchy:
        for field in parsed.fields:
            if str(field.get("name", "")) != nested_simple:
                continue
            if not _field_visible_from(
                declaring_owner=declaring_owner,
                current_owner=current_owner,
                access=int(field.get("access", 0)),
            ):
                continue
            shadow_owners.append(declaring_owner)

    return bool(shadow_owners), sorted(set(shadow_owners))


def _resolve_shadowed_nested_static_field(
    *,
    owner: str,
    field_name: str,
    current_owner: str,
    readable_zip: zipfile.ZipFile,
    entries: set[str],
    class_cache: dict[str, Any],
    imported_outers: dict[str, str] | None = None,
) -> tuple[str, list[str], str] | None:
    matches: list[tuple[str, list[str], str]] = []

    for candidate, java_owner in _nested_owner_binary_candidates(
        owner=owner,
        current_owner=current_owner,
        imported_outers=imported_outers,
    ):
        entry = candidate + ".class"
        if entry not in entries:
            continue

        parsed = class_cache.get(candidate)
        if parsed is None:
            try:
                parsed = parse_class(readable_zip.read(entry))
            except (KeyError, ClassFormatError):
                continue
            class_cache[candidate] = parsed

        is_nested = "$" in candidate.rsplit("/", 1)[-1]
        declarations = [
            field
            for field in parsed.fields
            if (
                str(field.get("name", "")) == field_name
                and int(field.get("access", 0)) & 0x0008
                and (
                    is_nested
                    or _field_visible_from(
                        declaring_owner=candidate,
                        current_owner=current_owner,
                        access=int(field.get("access", 0)),
                    )
                )
            )
        ]
        if len(declarations) != 1:
            continue

        if is_nested:
            shadowed, shadow_owners = _nested_owner_has_visible_name_shadow(
                nested_internal=candidate,
                current_owner=current_owner,
                readable_zip=readable_zip,
            )
        else:
            shadowed, shadow_owners = (
                _package_relative_owner_has_visible_name_shadow(
                    owner=owner,
                    candidate_internal=candidate,
                    current_owner=current_owner,
                    readable_zip=readable_zip,
                )
            )
        if not shadowed:
            continue

        matches.append((candidate, shadow_owners, java_owner))

    if len(matches) != 1:
        return None
    return matches[0]


def _resolve_shadowed_simple_nested_static_field(
    *,
    owner: str,
    field_name: str,
    current_owner: str,
    readable_zip: zipfile.ZipFile,
    entries: set[str],
    class_cache: dict[str, Any],
) -> tuple[str, list[str], str] | None:
    """Resolve simple Inner.FIELD to exact Outer$Inner.FIELD.

    The candidate must be a nested class owned by the exact current class.
    Its target field must be declared static, and a visible hierarchy value
    with the same nested simple name must prove the Java name-resolution
    shadow that makes the Procyon expression illegal. Java enclosing and
    nested classes are nestmates for source-level private access, so a
    private static member of current_owner$Inner is valid from current_owner
    and must not be rejected by the generic inter-class visibility helper.
    """
    if not _is_java_identifier(owner):
        return None

    candidate = current_owner + "$" + owner
    entry = candidate + ".class"
    if entry not in entries:
        return None

    parsed = class_cache.get(candidate)
    if parsed is None:
        try:
            parsed = parse_class(readable_zip.read(entry))
        except (KeyError, ClassFormatError):
            return None
        class_cache[candidate] = parsed
    if parsed.name != candidate:
        return None

    declarations = [
        field
        for field in parsed.fields
        if (
            str(field.get("name", "")) == field_name
            and int(field.get("access", 0)) & 0x0008
        )
    ]
    if len(declarations) != 1:
        return None

    shadowed, shadow_owners = _nested_owner_has_visible_name_shadow(
        nested_internal=candidate,
        current_owner=current_owner,
        readable_zip=readable_zip,
    )
    if not shadowed:
        return None

    java_owner = current_owner.replace("/", ".") + "." + owner
    return candidate, shadow_owners, java_owner


_DOTTED_STATIC_METHOD_RE = re.compile(
    r"(?<![A-Za-z0-9_$])"
    r"(?P<owner>[A-Za-z_$][A-Za-z0-9_$]*"
    r"(?:\.[A-Za-z_$][A-Za-z0-9_$]*){1,})"
    r"\.(?P<method>[A-Za-z_$][A-Za-z0-9_$]*)\s*\("
)
_SIMPLE_STATIC_METHOD_RE = re.compile(
    r"(?<![A-Za-z0-9_$.])"
    r"(?P<owner>[A-Za-z_$][A-Za-z0-9_$]*)"
    r"\.(?P<method>[A-Za-z_$][A-Za-z0-9_$]*)\s*\("
)


def _resolve_shadowed_nested_static_method(
    *,
    owner: str,
    method_name: str,
    current_owner: str,
    readable_zip: zipfile.ZipFile,
    entries: set[str],
    class_cache: dict[str, Any],
    imported_outers: dict[str, str] | None = None,
) -> tuple[str, list[str], str] | None:
    matches: list[tuple[str, list[str], str]] = []

    for candidate, java_owner in _nested_owner_binary_candidates(
        owner=owner,
        current_owner=current_owner,
        imported_outers=imported_outers,
    ):
        entry = candidate + ".class"
        if entry not in entries:
            continue

        parsed = class_cache.get(candidate)
        if parsed is None:
            try:
                parsed = parse_class(readable_zip.read(entry))
            except (KeyError, ClassFormatError):
                continue
            class_cache[candidate] = parsed

        declarations = [
            method
            for method in parsed.methods
            if (
                str(method.get("name", "")) == method_name
                and int(method.get("access", 0)) & 0x0008
                and _field_visible_from(
                    declaring_owner=candidate,
                    current_owner=current_owner,
                    access=int(method.get("access", 0)),
                )
            )
        ]
        if not declarations:
            continue

        if "$" in candidate.rsplit("/", 1)[-1]:
            shadowed, shadow_owners = _nested_owner_has_visible_name_shadow(
                nested_internal=candidate,
                current_owner=current_owner,
                readable_zip=readable_zip,
            )
        else:
            shadowed, shadow_owners = (
                _package_relative_owner_has_visible_name_shadow(
                    owner=owner,
                    candidate_internal=candidate,
                    current_owner=current_owner,
                    readable_zip=readable_zip,
                )
            )
        if not shadowed:
            continue

        matches.append((candidate, shadow_owners, java_owner))

    if len(matches) != 1:
        return None
    return matches[0]


def _resolve_shadowed_simple_nested_static_method(
    *,
    owner: str,
    method_name: str,
    current_owner: str,
    readable_zip: zipfile.ZipFile,
    entries: set[str],
    class_cache: dict[str, Any],
) -> tuple[str, list[str], str] | None:
    if not _is_java_identifier(owner):
        return None

    candidate = current_owner + "$" + owner
    entry = candidate + ".class"
    if entry not in entries:
        return None

    parsed = class_cache.get(candidate)
    if parsed is None:
        try:
            parsed = parse_class(readable_zip.read(entry))
        except (KeyError, ClassFormatError):
            return None
        class_cache[candidate] = parsed
    if parsed.name != candidate:
        return None

    declarations = [
        method
        for method in parsed.methods
        if (
            str(method.get("name", "")) == method_name
            and int(method.get("access", 0)) & 0x0008
        )
    ]
    if not declarations:
        return None

    shadowed, shadow_owners = _nested_owner_has_visible_name_shadow(
        nested_internal=candidate,
        current_owner=current_owner,
        readable_zip=readable_zip,
    )
    if not shadowed:
        return None

    java_owner = current_owner.replace("/", ".") + "." + owner
    return candidate, shadow_owners, java_owner


def _normalize_exact_static_call_nested_type_collisions(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Force nested type context using exact invokestatic owner authority.

    Procyon can emit X.method(X.Nested.FIELD, ...) when X resolves as a type,
    but X itself also exposes a value field named Nested. Java then resolves
    X.Nested in expression context through that field instead of the nested
    type. When imports/source package are insufficient to recover the nested
    owner directly, infer the exact outer owner from the correlated
    invokestatic and require exact getstatic + hierarchy collision proof.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    imports: dict[str, str] = {}
    duplicate_imports: set[str] = set()
    for import_match in _SINGLE_TYPE_IMPORT_RE.finditer(text):
        dotted = import_match.group("name")
        simple = dotted.rsplit(".", 1)[-1]
        internal = dotted.replace(".", "/")
        previous = imports.get(simple)
        if previous is not None and previous != internal:
            duplicate_imports.add(simple)
        else:
            imports[simple] = internal
    for simple in duplicate_imports:
        imports.pop(simple, None)

    def source_return_matches(
        source_return: str,
        exact_return: str | None,
    ) -> bool:
        if exact_return is None:
            return False
        if (
            _source_parameters_match_descriptor(
                source_return + " recoveredReturn",
                "(" + exact_return + ")V",
                current_package=current_package,
            )
            is True
        ):
            return True
        if not (
            exact_return.startswith("L")
            and exact_return.endswith(";")
        ):
            return False
        source_simple = source_return.strip()
        if not re.fullmatch(
            r"[A-Za-z_$][A-Za-z0-9_$]*",
            source_simple,
        ):
            return False
        imported_owner = imports.get(source_simple)
        return imported_owner == exact_return[1:-1]

    whole_code = _java_code_mask(text)
    pair_re = re.compile(
        r"(?<![A-Za-z0-9_$.])"
        r"(?P<outer>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\.(?P<method>[A-Za-z_$][A-Za-z0-9_$]*)\s*"
        r"\(\s*"
        r"(?P<nested_expr>"
        r"(?P=outer)"
        r"\.(?P<nested>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\.(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)"
        r")\b"
    )

    class_cache: dict[str, Any] = {}
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        occurrences = [
            {
                "outer": match.group("outer"),
                "method": match.group("method"),
                "nested": match.group("nested"),
                "field": match.group("field"),
                "start": method_start + match.start("nested_expr"),
                "end": method_start + match.end("nested_expr"),
            }
            for match in pair_re.finditer(method_code)
        ]
        if not occurrences:
            continue

        source_counts: dict[tuple[str, str, str, str], int] = {}
        for row in occurrences:
            key = (
                str(row["outer"]),
                str(row["method"]),
                str(row["nested"]),
                str(row["field"]),
            )
            source_counts[key] = source_counts.get(key, 0) + 1

        field_identity_keys: dict[
            tuple[str, str, str],
            set[tuple[str, str, str, str]],
        ] = {}
        for key in source_counts:
            field_identity = (key[0], key[2], key[3])
            field_identity_keys.setdefault(field_identity, set()).add(key)
        if any(len(keys) != 1 for keys in field_identity_keys.values()):
            continue

        source_field_occurrences: dict[
            tuple[str, str, str, str],
            list[dict[str, Any]],
        ] = {}
        for key in source_counts:
            outer, _static_name, nested_simple, field_name = key
            field_re = re.compile(
                r"(?<![A-Za-z0-9_$.])"
                + re.escape(outer)
                + r"\."
                + re.escape(nested_simple)
                + r"\."
                + re.escape(field_name)
                + r"(?![A-Za-z0-9_$])"
            )
            source_field_occurrences[key] = [
                {
                    "start": method_start + match.start(),
                    "end": method_start + match.end(),
                }
                for match in field_re.finditer(method_code)
            ]
            if (
                len(source_field_occurrences[key])
                < source_counts[key]
            ):
                source_field_occurrences = {}
                break
        if not source_field_occurrences:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        exact_candidates: list[dict[str, Any]] = []

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            exact_return = _descriptor_return_descriptor(descriptor)
            source_return = method_match.group("return").strip()
            if source_return == "void":
                if exact_return != "V":
                    continue
            elif not source_return_matches(
                source_return,
                exact_return,
            ):
                continue

            groups: dict[tuple[str, str, str, str], dict[str, Any]] = {}
            exact_ok = True

            for key, source_count in sorted(source_counts.items()):
                outer, static_name, nested_simple, field_name = key
                source_field_count = len(
                    source_field_occurrences.get(key, [])
                )
                if source_field_count < source_count:
                    exact_ok = False
                    break

                invocation_rows = [
                    row
                    for row in exact_method.get("method_invocations", [])
                    if (
                        row.get("operation") == "invokestatic"
                        and row.get("name") == static_name
                        and str(row.get("owner", "")).rsplit("/", 1)[-1]
                        == outer
                    )
                ]
                owner_candidates = sorted(
                    {
                        str(row.get("owner", ""))
                        for row in invocation_rows
                        if str(row.get("owner", ""))
                    }
                )
                valid: list[dict[str, Any]] = []

                for exact_outer in owner_candidates:
                    exact_invocations = [
                        row
                        for row in invocation_rows
                        if row.get("owner") == exact_outer
                    ]
                    if len(exact_invocations) != source_count:
                        continue

                    nested_owner = exact_outer + "$" + nested_simple
                    parsed = class_cache.get(nested_owner)
                    if parsed is None:
                        try:
                            parsed = parse_class(
                                readable_zip.read(nested_owner + ".class")
                            )
                        except (KeyError, ClassFormatError):
                            continue
                        class_cache[nested_owner] = parsed
                    if parsed.name != nested_owner:
                        continue

                    declarations = [
                        field
                        for field in parsed.fields
                        if (
                            str(field.get("name", "")) == field_name
                            and int(field.get("access", 0)) & 0x0008
                            and _field_visible_from(
                                declaring_owner=nested_owner,
                                current_owner=current_owner,
                                access=int(field.get("access", 0)),
                            )
                        )
                    ]
                    if len(declarations) != 1:
                        continue
                    field_descriptor = str(
                        declarations[0].get("descriptor", "")
                    )

                    shadowed, shadow_owners = (
                        _nested_owner_has_visible_name_shadow(
                            nested_internal=nested_owner,
                            current_owner=current_owner,
                            readable_zip=readable_zip,
                        )
                    )
                    if not shadowed:
                        continue

                    field_rows = [
                        row
                        for row in exact_method.get("field_accesses", [])
                        if (
                            row.get("operation") == "getstatic"
                            and row.get("owner") == nested_owner
                            and row.get("name") == field_name
                            and str(row.get("descriptor", ""))
                            == field_descriptor
                        )
                    ]
                    if len(field_rows) != source_field_count:
                        continue

                    field_shapes = _descriptor_parameter_shapes(
                        "(" + field_descriptor + ")V"
                    )
                    if field_shapes is None or len(field_shapes) != 1:
                        continue

                    invocation_descriptors: list[str] = []
                    compatible = True
                    for invocation in exact_invocations:
                        invocation_descriptor = str(
                            invocation.get("descriptor", "")
                        )
                        invocation_shapes = _descriptor_parameter_shapes(
                            invocation_descriptor
                        )
                        if (
                            invocation_shapes is None
                            or not invocation_shapes
                            or invocation_shapes[0] != field_shapes[0]
                        ):
                            compatible = False
                            break
                        invocation_descriptors.append(
                            invocation_descriptor
                        )
                    if not compatible:
                        continue

                    valid.append(
                        {
                            "exact_outer": exact_outer,
                            "nested_owner": nested_owner,
                            "field_descriptor": field_descriptor,
                            "shadow_declaring_owners": shadow_owners,
                            "source_call_count": source_count,
                            "source_field_count": source_field_count,
                            "invocation_descriptors": sorted(
                                invocation_descriptors
                            ),
                            "invocation_offsets": [
                                int(row.get("offset", -1))
                                for row in exact_invocations
                            ],
                            "field_offsets": [
                                int(row.get("offset", -1))
                                for row in field_rows
                            ],
                        }
                    )

                if len(valid) != 1:
                    exact_ok = False
                    break
                groups[key] = valid[0]

            if not exact_ok:
                continue
            exact_candidates.append(
                {
                    "method": exact_method,
                    "groups": groups,
                }
            )

        if len(exact_candidates) != 1:
            continue

        proof = exact_candidates[0]
        replacement_count = 0
        for key, field_occurrences in sorted(
            source_field_occurrences.items()
        ):
            group = proof["groups"][key]
            java_nested = (
                str(group["nested_owner"])
                .replace("$", ".")
                .replace("/", ".")
            )
            for row in field_occurrences:
                edits.append(
                    (
                        int(row["start"]),
                        int(row["end"]),
                        "((" + java_nested + ")null)." + key[3],
                    )
                )
                replacement_count += 1

        actions.append(
            {
                "kind": (
                    "exact_static_call_nested_type_collision_reconstruction"
                ),
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "pair_count": len(occurrences),
                "replacement_count": replacement_count,
                "groups": [
                    {
                        "source_outer": key[0],
                        "static_method": key[1],
                        "nested_name": key[2],
                        "field_name": key[3],
                        "source_count": source_counts[key],
                        **group,
                    }
                    for key, group in sorted(proof["groups"].items())
                ],
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_nested_type_hidden_by_outer_static_field"
                    ),
                    "strategy": (
                        "exact_invokestatic_owner_plus_nested_getstatic_collision"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping exact nested-type collision edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



def _normalize_exact_static_call_ternary_nested_type_collisions(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Force nested type context inside ternary static-call arguments.

    This is the conditional-expression companion to the direct
    X.method(X.Nested.FIELD, ...) repair.  The source shape is admitted only
    when exact bytecode proves the two getstatic arms form one branch diamond
    that converges before the uniquely correlated outer invokestatic.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    ternary_re = re.compile(
        r"(?<![A-Za-z0-9_$.])"
        r"(?P<outer>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\.(?P<method>[A-Za-z_$][A-Za-z0-9_$]*)\s*"
        r"\(\s*"
        r"(?P<condition>[^?,\n]+?)\s*\?\s*"
        r"(?P<true_expr>"
        r"(?P=outer)"
        r"\.(?P<nested>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\.(?P<true_field>[A-Za-z_$][A-Za-z0-9_$]*)"
        r")\s*:\s*"
        r"(?P<false_expr>"
        r"(?P=outer)"
        r"\.(?P=nested)"
        r"\.(?P<false_field>[A-Za-z_$][A-Za-z0-9_$]*)"
        r")\s*,"
    )

    class_cache: dict[str, Any] = {}
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        occurrences = [
            {
                "outer": match.group("outer"),
                "method": match.group("method"),
                "nested": match.group("nested"),
                "true_field": match.group("true_field"),
                "false_field": match.group("false_field"),
                "true_start": method_start + match.start("true_expr"),
                "true_end": method_start + match.end("true_expr"),
                "false_start": method_start + match.start("false_expr"),
                "false_end": method_start + match.end("false_expr"),
            }
            for match in ternary_re.finditer(method_code)
        ]
        if not occurrences:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        exact_candidates: list[dict[str, Any]] = []

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            instructions = list(exact_method.get("instructions", []))
            by_offset = {
                int(row.get("offset", -1)): index
                for index, row in enumerate(instructions)
                if int(row.get("offset", -1)) >= 0
            }
            used_invokes: set[int] = set()
            flows: list[dict[str, Any]] = []
            exact_ok = True

            for occurrence in occurrences:
                outer = str(occurrence["outer"])
                static_name = str(occurrence["method"])
                nested_simple = str(occurrence["nested"])
                true_field = str(occurrence["true_field"])
                false_field = str(occurrence["false_field"])

                invocation_rows = [
                    row
                    for row in exact_method.get("method_invocations", [])
                    if (
                        row.get("operation") == "invokestatic"
                        and row.get("name") == static_name
                        and str(row.get("owner", "")).rsplit("/", 1)[-1]
                        == outer
                    )
                ]
                owner_candidates = sorted(
                    {
                        str(row.get("owner", ""))
                        for row in invocation_rows
                        if str(row.get("owner", ""))
                    }
                )
                valid: list[dict[str, Any]] = []

                for exact_outer in owner_candidates:
                    nested_owner = exact_outer + "$" + nested_simple
                    parsed = class_cache.get(nested_owner)
                    if parsed is None:
                        try:
                            parsed = parse_class(
                                readable_zip.read(nested_owner + ".class")
                            )
                        except (KeyError, ClassFormatError):
                            continue
                        class_cache[nested_owner] = parsed
                    if parsed.name != nested_owner:
                        continue

                    field_rows: dict[str, dict[str, Any]] = {}
                    for field_name in (true_field, false_field):
                        declarations = [
                            field
                            for field in parsed.fields
                            if (
                                str(field.get("name", "")) == field_name
                                and int(field.get("access", 0)) & 0x0008
                                and _field_visible_from(
                                    declaring_owner=nested_owner,
                                    current_owner=current_owner,
                                    access=int(field.get("access", 0)),
                                )
                            )
                        ]
                        if len(declarations) != 1:
                            field_rows = {}
                            break
                        field_rows[field_name] = declarations[0]
                    if len(field_rows) != 2:
                        continue

                    true_descriptor = str(
                        field_rows[true_field].get("descriptor", "")
                    )
                    false_descriptor = str(
                        field_rows[false_field].get("descriptor", "")
                    )
                    if (
                        not true_descriptor
                        or true_descriptor != false_descriptor
                    ):
                        continue

                    shadowed, shadow_owners = (
                        _nested_owner_has_visible_name_shadow(
                            nested_internal=nested_owner,
                            current_owner=current_owner,
                            readable_zip=readable_zip,
                        )
                    )
                    if not shadowed:
                        continue

                    field_shape = _descriptor_parameter_shapes(
                        "(" + true_descriptor + ")V"
                    )
                    if field_shape is None or len(field_shape) != 1:
                        continue

                    exact_invocations = [
                        row
                        for row in invocation_rows
                        if (
                            row.get("owner") == exact_outer
                            and int(row.get("offset", -1)) not in used_invokes
                        )
                    ]
                    matching_flows: list[dict[str, Any]] = []

                    for invocation in exact_invocations:
                        invocation_descriptor = str(
                            invocation.get("descriptor", "")
                        )
                        invocation_shapes = _descriptor_parameter_shapes(
                            invocation_descriptor
                        )
                        if (
                            invocation_shapes is None
                            or not invocation_shapes
                            or invocation_shapes[0] != field_shape[0]
                        ):
                            continue
                        invocation_offset = int(
                            invocation.get("offset", -1)
                        )
                        invocation_index = by_offset.get(invocation_offset)
                        if invocation_index is None:
                            continue

                        lower = max(0, invocation_index - 40)
                        for selector_index in range(lower, invocation_index):
                            selector = instructions[selector_index]
                            if not (
                                selector.get("opcode") == "0x99"
                                and "branch_target_offset" in selector
                            ):
                                continue

                            true_index = selector_index + 1
                            if true_index + 1 >= invocation_index:
                                continue
                            true_get = instructions[true_index]
                            goto = instructions[true_index + 1]
                            if not (
                                true_get.get("mnemonic") == "getstatic"
                                and true_get.get("owner") == nested_owner
                                and true_get.get("name") == true_field
                                and true_get.get("descriptor")
                                == true_descriptor
                                and goto.get("opcode") in {"0xa7", "0xc8"}
                                and "branch_target_offset" in goto
                            ):
                                continue

                            false_offset = int(
                                selector["branch_target_offset"]
                            )
                            false_index = by_offset.get(false_offset)
                            if false_index is None:
                                continue
                            false_get = instructions[false_index]
                            if not (
                                false_get.get("mnemonic") == "getstatic"
                                and false_get.get("owner") == nested_owner
                                and false_get.get("name") == false_field
                                and false_get.get("descriptor")
                                == true_descriptor
                            ):
                                continue

                            merge_offset = int(
                                goto["branch_target_offset"]
                            )
                            merge_index = by_offset.get(merge_offset)
                            if (
                                merge_index is None
                                or false_index + 1 != merge_index
                                or not (
                                    merge_index < invocation_index
                                )
                            ):
                                continue

                            matching_flows.append(
                                {
                                    "exact_outer": exact_outer,
                                    "nested_owner": nested_owner,
                                    "true_field": true_field,
                                    "false_field": false_field,
                                    "field_descriptor": true_descriptor,
                                    "shadow_declaring_owners": shadow_owners,
                                    "selector_offset": int(
                                        selector.get("offset", -1)
                                    ),
                                    "true_field_offset": int(
                                        true_get.get("offset", -1)
                                    ),
                                    "goto_offset": int(
                                        goto.get("offset", -1)
                                    ),
                                    "false_field_offset": int(
                                        false_get.get("offset", -1)
                                    ),
                                    "merge_offset": merge_offset,
                                    "invoke_offset": invocation_offset,
                                    "invocation_descriptor":
                                        invocation_descriptor,
                                }
                            )

                    if len(matching_flows) == 1:
                        valid.append(matching_flows[0])

                if len(valid) != 1:
                    exact_ok = False
                    break
                used_invokes.add(int(valid[0]["invoke_offset"]))
                flows.append(valid[0])

            if exact_ok and len(flows) == len(occurrences):
                exact_candidates.append(
                    {
                        "method": exact_method,
                        "flows": flows,
                    }
                )

        if len(exact_candidates) != 1:
            continue

        proof = exact_candidates[0]
        for occurrence, flow in zip(occurrences, proof["flows"]):
            java_nested = (
                str(flow["nested_owner"])
                .replace("$", ".")
                .replace("/", ".")
            )
            edits.append(
                (
                    int(occurrence["true_start"]),
                    int(occurrence["true_end"]),
                    "((" + java_nested + ")null)."
                    + str(occurrence["true_field"]),
                )
            )
            edits.append(
                (
                    int(occurrence["false_start"]),
                    int(occurrence["false_end"]),
                    "((" + java_nested + ")null)."
                    + str(occurrence["false_field"]),
                )
            )

        actions.append(
            {
                "kind": (
                    "exact_static_call_ternary_nested_type_collision_reconstruction"
                ),
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "ternary_count": len(occurrences),
                "replacement_count": len(occurrences) * 2,
                "flows": proof["flows"],
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_nested_type_hidden_in_ternary_static_call_argument"
                    ),
                    "strategy": (
                        "exact_branch_diamond_getstatic_to_invokestatic_proof"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping ternary nested-type collision edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_shadowed_nested_static_field_owners(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Force shadowed nested static-field owners into Java type context.

    Procyon can emit pkg.Outer.Inner.FIELD for a JVM getstatic/putstatic
    owned by pkg/Outer$Inner. If Outer or one of its superclasses also
    exposes a field named Inner, javac resolves Inner as that value in
    expression context and the otherwise exact source becomes illegal.

    A null cast to pkg.Outer.Inner forces the owner through a type context
    while preserving Java static-field semantics. Rewrites are made only
    when one source method and one exact readable bytecode method agree on
    every affected nested-owner static-field access.
    """
    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
    except KeyError:
        return []

    try:
        profile = profile_class_field_accesses(class_bytes)
    except BytecodeProfileError:
        # Some synthetic/unit-test workspaces intentionally use placeholder
        # class bytes. This optional normalization has no exact bytecode
        # authority in that case, so fail closed by making no source edit.
        return []

    current_owner = str(profile["internal_name"])
    text = path.read_text(encoding="utf-8")
    imported_outers: dict[str, str] = {}
    conflicting_imports: set[str] = set()
    for imported in _SINGLE_TYPE_IMPORT_RE.finditer(text):
        target = imported.group("name").replace(".", "/")
        simple = target.rsplit("/", 1)[-1]
        if simple in imported_outers and imported_outers[simple] != target:
            conflicting_imports.add(simple)
        imported_outers[simple] = target
    for simple in conflicting_imports:
        imported_outers.pop(simple, None)
    if "." not in text:
        return []

    entries = {
        info.filename
        for info in readable_zip.infolist()
        if not info.is_dir() and info.filename.endswith(".class")
    }
    class_cache: dict[str, Any] = {}

    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for match in _METHOD_DECL_RE.finditer(text):
        brace_start = text.find("{", match.start(), match.end())
        if brace_start < 0:
            continue
        body_end = _matching_brace_end(text, brace_start)
        method_text = text[match.start():body_end]
        method_code = _java_code_mask(method_text)

        source_counts: dict[tuple[str, str, str], int] = {}
        source_occurrences: dict[
            tuple[str, str, str],
            list[tuple[int, int, str]],
        ] = {}
        shadow_owners_by_key: dict[
            tuple[str, str, str],
            list[str],
        ] = {}

        tokens: list[tuple[re.Match[str], bool]] = [
            (token, False)
            for token in _DOTTED_STATIC_FIELD_RE.finditer(method_code)
        ]
        tokens.extend(
            (token, True)
            for token in _SIMPLE_STATIC_FIELD_RE.finditer(method_code)
        )
        tokens.sort(key=lambda row: row[0].start())

        for token, simple_owner in tokens:
            owner = token.group("owner")
            field_name = token.group("field")
            if simple_owner:
                simple_resolved = _resolve_shadowed_simple_nested_static_field(
                    owner=owner,
                    field_name=field_name,
                    current_owner=current_owner,
                    readable_zip=readable_zip,
                    entries=entries,
                    class_cache=class_cache,
                )
                if simple_resolved is None:
                    continue
                nested_internal, shadow_owners, java_owner = simple_resolved
            else:
                resolved = _resolve_shadowed_nested_static_field(
                    owner=owner,
                    field_name=field_name,
                    current_owner=current_owner,
                    readable_zip=readable_zip,
                    entries=entries,
                    class_cache=class_cache,
                    imported_outers=imported_outers,
                )
                if resolved is None:
                    continue
                nested_internal, shadow_owners, java_owner = resolved

            key = (nested_internal, field_name, java_owner)
            source_counts[key] = source_counts.get(key, 0) + 1
            shadow_owners_by_key[key] = shadow_owners
            source_occurrences.setdefault(key, []).append(
                (
                    match.start() + token.start(),
                    match.start() + token.end(),
                    "((" + java_owner + ")null)." + field_name,
                )
            )

        if not source_counts:
            continue

        candidates: list[dict[str, Any]] = []
        source_arity = _source_parameter_count(match.group("params"))
        for method in profile.get("methods", []):
            if method.get("name") != match.group("name"):
                continue
            descriptor = str(method.get("descriptor", ""))
            if _descriptor_parameter_count(descriptor) != source_arity:
                continue
            parameter_match = _source_parameters_match_descriptor(
                match.group("params"),
                descriptor,
                current_package=current_owner.rpartition("/")[0],
            )
            if parameter_match is False:
                continue

            byte_counts: dict[tuple[str, str, str], int] = {}
            for access in method.get("field_accesses", []):
                if access.get("operation") not in {"getstatic", "putstatic"}:
                    continue
                for key in source_counts:
                    nested_internal, field_name, _owner = key
                    if (
                        str(access.get("owner", "")) == nested_internal
                        and str(access.get("name", "")) == field_name
                    ):
                        byte_counts[key] = byte_counts.get(key, 0) + 1

            if all(
                byte_counts.get(key, 0) == count
                for key, count in source_counts.items()
            ):
                candidates.append(method)

        if len(candidates) != 1:
            continue

        exact_method = candidates[0]
        method_edits = [
            edit
            for key in source_counts
            for edit in source_occurrences[key]
        ]
        edits.extend(method_edits)

        actions.append(
            {
                "kind": (
                    "shadowed_nested_static_field_owner_type_context"
                ),
                "source_path": rel,
                "method_name": match.group("name"),
                "method_descriptor": exact_method["descriptor"],
                "nested_owners": sorted(
                    {key[0] for key in source_counts}
                ),
                "shadow_declaring_owners": sorted(
                    {
                        shadow_owner
                        for key in source_counts
                        for shadow_owner in shadow_owners_by_key[key]
                    }
                ),
                "field_access_counts": {
                    nested + "." + field: count
                    for (nested, field, _owner), count in sorted(
                        source_counts.items()
                    )
                },
                "replacement_count": sum(source_counts.values()),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_nested_type_hidden_by_enclosing_hierarchy_field"
                    ),
                    "strategy": (
                        "exact_bytecode_static_field_type_context_qualification"
                    ),
                },
            }
        )


    simple_name = current_owner.rsplit("/", 1)[-1]
    constructor_re = re.compile(
        r"(?m)^(?P<indent>[ \t]*)"
        r"(?:(?:public|private|protected)\s+)*"
        + re.escape(simple_name)
        + r"\s*\((?P<params>[^()\n]*)\)\s*"
        r"(?:throws\s+[^\{\n]+\s*)?\{"
    )
    for match in constructor_re.finditer(text):
        brace_start = text.find("{", match.start(), match.end())
        if brace_start < 0:
            continue
        body_end = _matching_brace_end(text, brace_start)
        constructor_text = text[match.start():body_end]
        constructor_code = _java_code_mask(constructor_text)

        source_counts: dict[tuple[str, str, str], int] = {}
        source_occurrences: dict[
            tuple[str, str, str],
            list[tuple[int, int, str]],
        ] = {}
        shadow_owners_by_key: dict[
            tuple[str, str, str],
            list[str],
        ] = {}

        tokens: list[tuple[re.Match[str], bool]] = [
            (token, False)
            for token in _DOTTED_STATIC_FIELD_RE.finditer(constructor_code)
        ]
        tokens.extend(
            (token, True)
            for token in _SIMPLE_STATIC_FIELD_RE.finditer(constructor_code)
        )
        tokens.sort(key=lambda row: row[0].start())

        for token, simple_owner in tokens:
            owner = token.group("owner")
            field_name = token.group("field")
            if simple_owner:
                simple_resolved = _resolve_shadowed_simple_nested_static_field(
                    owner=owner,
                    field_name=field_name,
                    current_owner=current_owner,
                    readable_zip=readable_zip,
                    entries=entries,
                    class_cache=class_cache,
                )
                if simple_resolved is None:
                    continue
                nested_internal, shadow_owners, java_owner = simple_resolved
            else:
                resolved = _resolve_shadowed_nested_static_field(
                    owner=owner,
                    field_name=field_name,
                    current_owner=current_owner,
                    readable_zip=readable_zip,
                    entries=entries,
                    class_cache=class_cache,
                    imported_outers=imported_outers,
                )
                if resolved is None:
                    continue
                nested_internal, shadow_owners, java_owner = resolved

            key = (nested_internal, field_name, java_owner)
            source_counts[key] = source_counts.get(key, 0) + 1
            shadow_owners_by_key[key] = shadow_owners
            source_occurrences.setdefault(key, []).append(
                (
                    match.start() + token.start(),
                    match.start() + token.end(),
                    "((" + java_owner + ")null)." + field_name,
                )
            )

        if not source_counts:
            continue

        candidates: list[dict[str, Any]] = []
        source_arity = _source_parameter_count(match.group("params"))
        for method in profile.get("methods", []):
            if method.get("name") != "<init>":
                continue
            descriptor = str(method.get("descriptor", ""))
            if _descriptor_parameter_count(descriptor) != source_arity:
                continue
            parameter_match = _source_parameters_match_descriptor(
                match.group("params"),
                descriptor,
                current_package=current_owner.rpartition("/")[0],
            )
            if parameter_match is False:
                continue

            byte_counts: dict[tuple[str, str, str], int] = {}
            for access in method.get("field_accesses", []):
                if access.get("operation") not in {"getstatic", "putstatic"}:
                    continue
                for key in source_counts:
                    nested_internal, field_name, _owner = key
                    if (
                        str(access.get("owner", "")) == nested_internal
                        and str(access.get("name", "")) == field_name
                    ):
                        byte_counts[key] = byte_counts.get(key, 0) + 1

            if all(
                byte_counts.get(key, 0) == count
                for key, count in source_counts.items()
            ):
                candidates.append(method)

        if len(candidates) != 1:
            continue

        exact_method = candidates[0]
        constructor_edits = [
            edit
            for key in source_counts
            for edit in source_occurrences[key]
        ]
        edits.extend(constructor_edits)

        actions.append(
            {
                "kind": (
                    "shadowed_nested_static_field_owner_type_context"
                ),
                "source_path": rel,
                "method_name": "<init>",
                "method_descriptor": exact_method["descriptor"],
                "nested_owners": sorted(
                    {key[0] for key in source_counts}
                ),
                "shadow_declaring_owners": sorted(
                    {
                        shadow_owner
                        for key in source_counts
                        for shadow_owner in shadow_owners_by_key[key]
                    }
                ),
                "field_access_counts": {
                    nested + "." + field: count
                    for (nested, field, _owner), count in sorted(
                        source_counts.items()
                    )
                },
                "replacement_count": sum(source_counts.values()),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_nested_type_hidden_by_enclosing_hierarchy_field"
                    ),
                    "strategy": (
                        "exact_constructor_descriptor_static_field_type_context_qualification"
                    ),
                },
            }
        )

    exact_clinits = [
        method
        for method in profile.get("methods", [])
        if method.get("name") == "<clinit>"
        and method.get("descriptor") == "()V"
    ]
    if len(exact_clinits) == 1:
        exact_clinit = exact_clinits[0]
        whole_code = _java_code_mask(text)
        static_block_re = re.compile(r"(?m)^[ \t]*static[ \t]*\{")

        for block_match in static_block_re.finditer(whole_code):
            brace_start = whole_code.find(
                "{", block_match.start(), block_match.end()
            )
            if (
                brace_start < 0
                or _brace_depth_before(whole_code, brace_start) != 1
            ):
                continue
            block_end = _matching_brace_end(whole_code, brace_start)
            block_code = whole_code[block_match.start():block_end]

            source_counts: dict[tuple[str, str, str], int] = {}
            source_occurrences: dict[
                tuple[str, str, str],
                list[tuple[int, int, str]],
            ] = {}
            shadow_owners_by_key: dict[
                tuple[str, str, str],
                list[str],
            ] = {}

            tokens: list[tuple[re.Match[str], bool]] = [
                (token, False)
                for token in _DOTTED_STATIC_FIELD_RE.finditer(block_code)
            ]
            tokens.extend(
                (token, True)
                for token in _SIMPLE_STATIC_FIELD_RE.finditer(block_code)
            )
            tokens.sort(key=lambda row: row[0].start())

            for token, simple_owner in tokens:
                owner = token.group("owner")
                field_name = token.group("field")
                if simple_owner:
                    simple_resolved = (
                        _resolve_shadowed_simple_nested_static_field(
                            owner=owner,
                            field_name=field_name,
                            current_owner=current_owner,
                            readable_zip=readable_zip,
                            entries=entries,
                            class_cache=class_cache,
                        )
                    )
                    if simple_resolved is None:
                        continue
                    (
                        nested_internal,
                        shadow_owners,
                        java_owner,
                    ) = simple_resolved
                else:
                    resolved = _resolve_shadowed_nested_static_field(
                        owner=owner,
                        field_name=field_name,
                        current_owner=current_owner,
                        readable_zip=readable_zip,
                        entries=entries,
                        class_cache=class_cache,
                        imported_outers=imported_outers,
                    )
                    if resolved is None:
                        continue
                    nested_internal, shadow_owners, java_owner = resolved

                key = (nested_internal, field_name, java_owner)
                source_counts[key] = source_counts.get(key, 0) + 1
                shadow_owners_by_key[key] = shadow_owners
                source_occurrences.setdefault(key, []).append(
                    (
                        block_match.start() + token.start(),
                        block_match.start() + token.end(),
                        "((" + java_owner + ")null)." + field_name,
                    )
                )

            if not source_counts:
                continue

            byte_counts: dict[tuple[str, str, str], int] = {}
            for access in exact_clinit.get("field_accesses", []):
                if access.get("operation") not in {
                    "getstatic",
                    "putstatic",
                }:
                    continue
                for key in source_counts:
                    nested_internal, field_name, _owner = key
                    if (
                        str(access.get("owner", "")) == nested_internal
                        and str(access.get("name", "")) == field_name
                    ):
                        byte_counts[key] = byte_counts.get(key, 0) + 1

            if not all(
                byte_counts.get(key, 0) == count
                for key, count in source_counts.items()
            ):
                continue

            edits.extend(
                edit
                for key in source_counts
                for edit in source_occurrences[key]
            )
            actions.append(
                {
                    "kind": (
                        "shadowed_nested_static_field_owner_type_context"
                    ),
                    "source_path": rel,
                    "method_name": "<clinit>",
                    "method_descriptor": "()V",
                    "nested_owners": sorted(
                        {key[0] for key in source_counts}
                    ),
                    "shadow_declaring_owners": sorted(
                        {
                            shadow_owner
                            for key in source_counts
                            for shadow_owner in shadow_owners_by_key[key]
                        }
                    ),
                    "field_access_counts": {
                        nested + "." + field: count
                        for (nested, field, _owner), count in sorted(
                            source_counts.items()
                        )
                    },
                    "replacement_count": sum(source_counts.values()),
                    "provenance": {
                        "kind": "source_safety",
                        "reason": (
                            "procyon_nested_type_hidden_by_enclosing_hierarchy_field"
                        ),
                        "strategy": (
                            "exact_clinit_static_field_type_context_qualification"
                        ),
                    },
                }
            )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping nested-owner type-context edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions

def _normalize_shadowed_nested_static_method_owners(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Force shadowed nested static-method owners into Java type context.

    This is the invokestatic counterpart to nested static-field recovery.
    Ordinary methods are bound to one exact readable method using source
    staticness, descriptor shape and the complete invokestatic owner/name
    multiset. Top-level class initializers retain the exact <clinit>()V path.
    """
    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
    except KeyError:
        return []

    try:
        profile = profile_class_field_accesses(class_bytes)
    except BytecodeProfileError:
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []

    text = path.read_text(encoding="utf-8")
    imported_outers: dict[str, str] = {}
    conflicting_imports: set[str] = set()
    for imported in _SINGLE_TYPE_IMPORT_RE.finditer(text):
        target = imported.group("name").replace(".", "/")
        simple = target.rsplit("/", 1)[-1]
        if simple in imported_outers and imported_outers[simple] != target:
            conflicting_imports.add(simple)
        imported_outers[simple] = target
    for simple in conflicting_imports:
        imported_outers.pop(simple, None)
    whole_code = _java_code_mask(text)
    entries = {
        info.filename
        for info in readable_zip.infolist()
        if not info.is_dir() and info.filename.endswith(".class")
    }
    class_cache: dict[str, Any] = {}
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for method_match in _METHOD_DECL_RE.finditer(text):
        brace_start = text.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        header_code = whole_code[method_match.start():brace_start]
        source_static = re.search(r"\bstatic\b", header_code) is not None
        body_end = _matching_brace_end(text, brace_start)
        method_text = text[method_match.start():body_end]
        method_code = _java_code_mask(method_text)

        source_counts: dict[tuple[str, str, str], int] = {}
        source_occurrences: dict[
            tuple[str, str, str],
            list[tuple[int, int, str]],
        ] = {}
        shadow_owners_by_key: dict[
            tuple[str, str, str],
            list[str],
        ] = {}

        tokens: list[tuple[re.Match[str], bool]] = [
            (token, False)
            for token in _DOTTED_STATIC_METHOD_RE.finditer(method_code)
        ]
        tokens.extend(
            (token, True)
            for token in _SIMPLE_STATIC_METHOD_RE.finditer(method_code)
        )
        tokens.sort(key=lambda row: row[0].start())

        for token, simple_owner in tokens:
            owner = token.group("owner")
            method_name = token.group("method")
            if simple_owner:
                simple_resolved = (
                    _resolve_shadowed_simple_nested_static_method(
                        owner=owner,
                        method_name=method_name,
                        current_owner=current_owner,
                        readable_zip=readable_zip,
                        entries=entries,
                        class_cache=class_cache,
                    )
                )
                if simple_resolved is None:
                    continue
                (
                    nested_internal,
                    shadow_owners,
                    java_owner,
                ) = simple_resolved
            else:
                resolved = _resolve_shadowed_nested_static_method(
                    owner=owner,
                    method_name=method_name,
                    current_owner=current_owner,
                    readable_zip=readable_zip,
                    entries=entries,
                    class_cache=class_cache,
                    imported_outers=imported_outers,
                )
                if resolved is None:
                    continue
                nested_internal, shadow_owners, java_owner = resolved

            key = (nested_internal, method_name, java_owner)
            source_counts[key] = source_counts.get(key, 0) + 1
            shadow_owners_by_key[key] = shadow_owners
            source_occurrences.setdefault(key, []).append(
                (
                    method_match.start() + token.start("owner"),
                    method_match.start() + token.end("owner"),
                    "((" + java_owner + ")null)",
                )
            )

        if not source_counts:
            continue

        source_arity = _source_parameter_count(
            method_match.group("params")
        )
        candidates: list[dict[str, Any]] = []
        for method in profile.get("methods", []):
            if method.get("name") != method_match.group("name"):
                continue
            method_static = bool(
                int(method.get("access", 0)) & 0x0008
            )
            if method_static != source_static:
                continue
            descriptor = str(method.get("descriptor", ""))
            if _descriptor_parameter_count(descriptor) != source_arity:
                continue
            parameter_match = _source_parameters_match_descriptor(
                method_match.group("params"),
                descriptor,
                current_package=current_owner.rpartition("/")[0],
            )
            if parameter_match is False:
                continue

            invocation_counts: dict[tuple[str, str, str], int] = {}
            for invocation in method.get("method_invocations", []):
                if invocation.get("operation") != "invokestatic":
                    continue
                for key in source_counts:
                    nested_internal, method_name, _owner = key
                    if (
                        str(invocation.get("owner", ""))
                        == nested_internal
                        and str(invocation.get("name", ""))
                        == method_name
                    ):
                        invocation_counts[key] = (
                            invocation_counts.get(key, 0) + 1
                        )

            if all(
                invocation_counts.get(key, 0) == count
                for key, count in source_counts.items()
            ):
                candidates.append(method)

        if len(candidates) != 1:
            continue

        exact_method = candidates[0]
        edits.extend(
            edit
            for key in source_counts
            for edit in source_occurrences[key]
        )
        actions.append(
            {
                "kind": (
                    "shadowed_nested_static_method_owner_type_context"
                ),
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": exact_method["descriptor"],
                "nested_owners": sorted(
                    {key[0] for key in source_counts}
                ),
                "shadow_declaring_owners": sorted(
                    {
                        shadow_owner
                        for key in source_counts
                        for shadow_owner in shadow_owners_by_key[key]
                    }
                ),
                "method_invocation_counts": {
                    nested + "." + method: count
                    for (nested, method, _owner), count in sorted(
                        source_counts.items()
                    )
                },
                "replacement_count": sum(source_counts.values()),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_nested_type_hidden_before_static_method"
                    ),
                    "strategy": (
                        "exact_method_invokestatic_owner_name_multiset_qualification"
                    ),
                },
            }
        )

    exact_clinits = [
        method
        for method in profile.get("methods", [])
        if method.get("name") == "<clinit>"
        and method.get("descriptor") == "()V"
    ]
    exact_clinit = (
        exact_clinits[0]
        if len(exact_clinits) == 1
        else None
    )
    static_block_re = re.compile(r"(?m)^[ \t]*static[ \t]*\{")

    for block_match in (
        static_block_re.finditer(whole_code)
        if exact_clinit is not None
        else []
    ):
        brace_start = whole_code.find(
            "{", block_match.start(), block_match.end()
        )
        if (
            brace_start < 0
            or _brace_depth_before(whole_code, brace_start) != 1
        ):
            continue
        block_end = _matching_brace_end(whole_code, brace_start)
        block_code = whole_code[block_match.start():block_end]

        source_counts: dict[tuple[str, str, str], int] = {}
        source_occurrences: dict[
            tuple[str, str, str],
            list[tuple[int, int, str]],
        ] = {}
        shadow_owners_by_key: dict[
            tuple[str, str, str],
            list[str],
        ] = {}

        tokens: list[tuple[re.Match[str], bool]] = [
            (token, False)
            for token in _DOTTED_STATIC_METHOD_RE.finditer(block_code)
        ]
        tokens.extend(
            (token, True)
            for token in _SIMPLE_STATIC_METHOD_RE.finditer(block_code)
        )
        tokens.sort(key=lambda row: row[0].start())

        for token, simple_owner in tokens:
            owner = token.group("owner")
            method_name = token.group("method")
            if simple_owner:
                simple_resolved = (
                    _resolve_shadowed_simple_nested_static_method(
                        owner=owner,
                        method_name=method_name,
                        current_owner=current_owner,
                        readable_zip=readable_zip,
                        entries=entries,
                        class_cache=class_cache,
                    )
                )
                if simple_resolved is None:
                    continue
                (
                    nested_internal,
                    shadow_owners,
                    java_owner,
                ) = simple_resolved
            else:
                resolved = _resolve_shadowed_nested_static_method(
                    owner=owner,
                    method_name=method_name,
                    current_owner=current_owner,
                    readable_zip=readable_zip,
                    entries=entries,
                    class_cache=class_cache,
                    imported_outers=imported_outers,
                )
                if resolved is None:
                    continue
                nested_internal, shadow_owners, java_owner = resolved

            key = (nested_internal, method_name, java_owner)
            source_counts[key] = source_counts.get(key, 0) + 1
            shadow_owners_by_key[key] = shadow_owners
            source_occurrences.setdefault(key, []).append(
                (
                    block_match.start() + token.start("owner"),
                    block_match.start() + token.end("owner"),
                    "((" + java_owner + ")null)",
                )
            )

        if not source_counts:
            continue

        invocation_counts: dict[tuple[str, str, str], int] = {}
        for invocation in exact_clinit.get("method_invocations", []):
            if invocation.get("operation") != "invokestatic":
                continue
            for key in source_counts:
                nested_internal, method_name, _owner = key
                if (
                    str(invocation.get("owner", "")) == nested_internal
                    and str(invocation.get("name", "")) == method_name
                ):
                    invocation_counts[key] = (
                        invocation_counts.get(key, 0) + 1
                    )

        if not all(
            invocation_counts.get(key, 0) == count
            for key, count in source_counts.items()
        ):
            continue

        edits.extend(
            edit
            for key in source_counts
            for edit in source_occurrences[key]
        )
        actions.append(
            {
                "kind": (
                    "shadowed_nested_static_method_owner_type_context"
                ),
                "source_path": rel,
                "method_name": "<clinit>",
                "method_descriptor": "()V",
                "nested_owners": sorted(
                    {key[0] for key in source_counts}
                ),
                "shadow_declaring_owners": sorted(
                    {
                        shadow_owner
                        for key in source_counts
                        for shadow_owner in shadow_owners_by_key[key]
                    }
                ),
                "method_invocation_counts": {
                    nested + "." + method: count
                    for (nested, method, _owner), count in sorted(
                        source_counts.items()
                    )
                },
                "replacement_count": sum(source_counts.values()),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_nested_type_hidden_before_static_method_in_clinit"
                    ),
                    "strategy": (
                        "exact_clinit_invokestatic_owner_name_multiset_qualification"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping nested static-call owner edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


_PACKAGE_DECL_RE = re.compile(
    r"(?m)^\s*package\s+"
    r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)*)"
    r"\s*;"
)
_SINGLE_TYPE_IMPORT_RE = re.compile(
    r"(?m)^\s*import\s+(?!static\s+)"
    r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)+)"
    r"\s*;"
)


def _parameter_type_spans(
    params: str,
) -> list[tuple[int, int, str]] | None:
    if not params.strip():
        return []

    bounds: list[tuple[int, int]] = []
    start = 0
    depth = 0
    for index, ch in enumerate(params):
        if ch == "<":
            depth += 1
        elif ch == ">" and depth:
            depth -= 1
        elif ch == "," and depth == 0:
            bounds.append((start, index))
            start = index + 1
    bounds.append((start, len(params)))

    out: list[tuple[int, int, str]] = []
    for left, right in bounds:
        raw = params[left:right]
        match = re.fullmatch(
            r"(?P<prefix>\s*(?:(?:final)\s+)*)"
            r"(?P<type>.+?)"
            r"(?P<gap>\s+)"
            r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)"
            r"(?P<var_arrays>(?:\[\])*)"
            r"\s*",
            raw,
        )
        if match is None:
            return None
        type_text = match.group("type").strip()
        type_left = left + match.start("type")
        type_right = left + match.end("type")
        # Exclude surrounding whitespace captured by the lazy type group.
        while type_left < type_right and params[type_left].isspace():
            type_left += 1
        while type_right > type_left and params[type_right - 1].isspace():
            type_right -= 1
        out.append((type_left, type_right, type_text))
    return out


def _source_parameter_names(params: str) -> list[str] | None:
    text = params.strip()
    if not text:
        return []
    parts: list[str] = []
    start = 0
    depth = 0
    for index, ch in enumerate(text):
        if ch == "<":
            depth += 1
        elif ch == ">" and depth:
            depth -= 1
        elif ch == "," and depth == 0:
            parts.append(text[start:index].strip())
            start = index + 1
    parts.append(text[start:].strip())

    out: list[str] = []
    for part in parts:
        value = re.sub(r"^(?:final\s+)+", "", part.strip())
        match = re.fullmatch(
            r".+?\s+"
            r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)"
            r"(?:\[\])*",
            value,
        )
        if match is None:
            return None
        out.append(match.group("name"))
    return out


def _normalize_compile_time_lombok_nonnull(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Erase Lombok NonNull syntax when exact bytecode proves metadata-only use."""
    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
    except KeyError:
        return []

    try:
        utf8 = set(profile_class_utf8_constants(class_bytes))
        references = profile_class_constant_pool_references(class_bytes)
    except BytecodeProfileError:
        return []

    if "Llombok/NonNull;" not in utf8:
        return []
    if not (
        {
            "RuntimeInvisibleAnnotations",
            "RuntimeInvisibleParameterAnnotations",
            "RuntimeInvisibleTypeAnnotations",
        }
        & utf8
    ):
        return []
    if "lombok/NonNull" in set(
        references.get("class_references", [])
    ):
        return []

    text = path.read_text(encoding="utf-8")
    import_re = re.compile(
        r"(?m)^import\s+lombok\.NonNull\s*;[ \t]*\n"
    )
    import_match = import_re.search(text)
    if import_match is None:
        return []

    code = _java_code_mask(text)
    annotation_re = re.compile(
        r"(?<![A-Za-z0-9_$.])@NonNull\b"
    )
    annotation_matches = list(annotation_re.finditer(code))
    if not annotation_matches:
        return []

    for match in reversed(annotation_matches):
        text = text[:match.start()] + text[match.end():]

    import_match = import_re.search(text)
    if import_match is None:
        return []
    text = (
        text[:import_match.start()]
        + text[import_match.end():]
    )
    path.write_text(text, encoding="utf-8")

    return [
        {
            "kind": "compile_time_lombok_nonnull_erasure",
            "source_path": rel,
            "annotation_name": "lombok.NonNull",
            "replacement_count": len(annotation_matches),
            "removed_import_count": 1,
            "provenance": {
                "kind": "source_safety",
                "reason": "compile_time_only_lombok_nonnull_dependency",
                "strategy": (
                    "exact_runtime_invisible_metadata_without_class_reference"
                ),
            },
        }
    ]



def _normalize_two_string_swing_capture_aliases(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore two String lambda captures from exact slot-use evidence.

    This family is intentionally narrow: the exact enclosing static method
    must capture local slots 0 and 1, in that order, into one two-String
    Runnable invoked through SwingUtilities.invokeLater.  A unique exact
    synthetic two-String lambda helper must then use slot 0 as the message
    passed to JOptionPane.showConfirmDialog and slot 1 as the StringSelection
    constructor argument.  Only the corresponding undeclared source aliases
    are rewritten to the enclosing source parameter names.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
    except KeyError:
        return []
    try:
        profile = profile_class_field_accesses(class_bytes)
    except BytecodeProfileError:
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    synthetic_candidates: list[dict[str, Any]] = []
    for exact_method in profile.get("methods", []):
        if (
            str(exact_method.get("descriptor", ""))
            != "(Ljava/lang/String;Ljava/lang/String;)V"
            or not (int(exact_method.get("access", 0)) & 0x1000)
            or not (int(exact_method.get("access", 0)) & 0x0008)
        ):
            continue
        instructions = list(exact_method.get("instructions", []))
        show_index = next(
            (
                index
                for index, row in enumerate(instructions)
                if row.get("mnemonic") == "invokestatic"
                and row.get("owner") == "javax/swing/JOptionPane"
                and row.get("name") == "showConfirmDialog"
                and row.get("descriptor")
                == "(Ljava/awt/Component;Ljava/lang/Object;"
                "Ljava/lang/String;I)I"
            ),
            None,
        )
        selection_index = next(
            (
                index
                for index, row in enumerate(instructions)
                if row.get("mnemonic") == "invokespecial"
                and row.get("owner")
                == "java/awt/datatransfer/StringSelection"
                and row.get("name") == "<init>"
                and row.get("descriptor")
                == "(Ljava/lang/String;)V"
            ),
            None,
        )
        if show_index is None or selection_index is None:
            continue
        if show_index < 4 or selection_index < 1:
            continue
        if not (
            instructions[show_index - 4].get("mnemonic")
            == "aconst_null"
            and instructions[show_index - 3].get("mnemonic") == "aload"
            and int(
                instructions[show_index - 3].get("local_index", -1)
            )
            == 0
            and instructions[show_index - 2].get("mnemonic")
            in {"ldc", "ldc_w"}
            and instructions[show_index - 2].get("constant")
            == "Message"
            and int(
                instructions[show_index - 1].get("int_constant", -1)
            )
            == 2
            and instructions[selection_index - 1].get("mnemonic")
            == "aload"
            and int(
                instructions[selection_index - 1].get(
                    "local_index", -1
                )
            )
            == 1
        ):
            continue
        synthetic_candidates.append(exact_method)
    if len(synthetic_candidates) != 1:
        return []

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    message_re = re.compile(
        r"JOptionPane\.showConfirmDialog\s*\(\s*null\s*,\s*"
        r"(?P<alias>[A-Za-z_$][A-Za-z0-9_$]*)\s*,"
        r"[ \t]+,\s*2\s*\)"
    )
    data_re = re.compile(
        r"new\s+StringSelection\s*\(\s*"
        r"(?P<alias>[A-Za-z_$][A-Za-z0-9_$]*)\s*\)"
    )

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        source_params = method_match.group("params")
        parameter_names = _source_parameter_names(source_params)
        if parameter_names is None or len(parameter_names) != 2:
            continue
        if (
            _source_parameters_match_descriptor(
                source_params,
                "(Ljava/lang/String;Ljava/lang/String;)V",
                current_package=current_package,
            )
            is not True
        ):
            continue

        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue
        if not re.search(
            r"\bstatic\b",
            whole_code[method_match.start():brace_start],
        ):
            continue

        exact_candidates = [
            method
            for method in profile.get("methods", [])
            if method.get("name") == method_match.group("name")
            and method.get("descriptor")
            == "(Ljava/lang/String;Ljava/lang/String;)V"
            and bool(int(method.get("access", 0)) & 0x0008)
            and not bool(int(method.get("access", 0)) & 0x1000)
        ]
        if len(exact_candidates) != 1:
            continue
        exact_method = exact_candidates[0]
        instructions = list(exact_method.get("instructions", []))
        if len(instructions) != 5:
            continue
        if not (
            instructions[0].get("mnemonic") == "aload"
            and int(instructions[0].get("local_index", -1)) == 0
            and instructions[1].get("mnemonic") == "aload"
            and int(instructions[1].get("local_index", -1)) == 1
            and instructions[2].get("mnemonic") == "invokedynamic"
            and instructions[2].get("descriptor")
            == "(Ljava/lang/String;Ljava/lang/String;)"
            "Ljava/lang/Runnable;"
            and instructions[3].get("mnemonic") == "invokestatic"
            and instructions[3].get("owner")
            == "javax/swing/SwingUtilities"
            and instructions[3].get("name") == "invokeLater"
            and instructions[3].get("descriptor")
            == "(Ljava/lang/Runnable;)V"
            and instructions[4].get("mnemonic") == "return"
        ):
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        message_matches = list(message_re.finditer(method_code))
        data_matches = list(data_re.finditer(method_code))
        if len(message_matches) != 1 or len(data_matches) != 1:
            continue

        message_alias = message_matches[0].group("alias")
        data_alias = data_matches[0].group("alias")
        if message_alias == data_alias:
            continue
        replacements = (
            (message_matches[0], message_alias, parameter_names[0]),
            (data_matches[0], data_alias, parameter_names[1]),
        )

        body_code = method_code[method_code.find("{") + 1:]
        declaration_re_template = (
            r"\b(?:final\s+)?"
            r"[A-Za-z_$][A-Za-z0-9_$.<>\[\]?]*\s+{alias}\b"
        )
        refused = False
        for _match, alias, parameter_name in replacements:
            if alias == parameter_name:
                refused = True
                break
            declaration_re = re.compile(
                declaration_re_template.format(
                    alias=re.escape(alias)
                )
            )
            if declaration_re.search(body_code):
                refused = True
                break
            if (
                len(
                    re.findall(
                        r"(?<![A-Za-z0-9_$])"
                        + re.escape(alias)
                        + r"(?![A-Za-z0-9_$])",
                        body_code,
                    )
                )
                != 1
            ):
                refused = True
                break
        if refused:
            continue

        for source_match, alias, parameter_name in replacements:
            alias_start = source_match.start("alias")
            alias_end = source_match.end("alias")
            edits.append(
                (
                    method_start + alias_start,
                    method_start + alias_end,
                    parameter_name,
                )
            )
        actions.append(
            {
                "kind": "two_string_swing_capture_alias",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": (
                    "(Ljava/lang/String;Ljava/lang/String;)V"
                ),
                "message_parameter_name": parameter_names[0],
                "data_parameter_name": parameter_names[1],
                "message_alias_name": message_alias,
                "data_alias_name": data_alias,
                "replacement_count": 2,
                "synthetic_method_name": synthetic_candidates[0].get(
                    "name"
                ),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_two_string_swing_lambda_capture_alias"
                    ),
                    "strategy": (
                        "exact_outer_capture_order_and_synthetic_slot_use"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping two-String Swing capture edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_invokedynamic_parameter_capture_aliases(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Repair Procyon lambda aliases proven by exact indy captures.

    Procyon can emit a lambda body that refers to an undeclared suffixed
    alias such as event2 even though the exact enclosing method captures its
    original event parameter directly into invokedynamic.  Rewrite only
    suffixed aliases of declared parameters, only in a uniquely correlated
    exact method, and only when exact invokedynamic parameter shapes prove
    that same source parameter is captured.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
    except KeyError:
        return []
    try:
        profile = profile_class_field_accesses(class_bytes)
    except BytecodeProfileError:
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        source_params = method_match.group("params")
        parameter_names = _source_parameter_names(source_params)
        parameter_shapes = _source_parameter_shapes(source_params)
        if (
            parameter_names is None
            or parameter_shapes is None
            or not parameter_names
            or len(parameter_names) != len(parameter_shapes)
        ):
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        exact_candidates: list[dict[str, Any]] = []
        for method in profile.get("methods", []):
            if method.get("name") != method_match.group("name"):
                continue
            descriptor = str(method.get("descriptor", ""))
            if (
                _descriptor_parameter_count(descriptor)
                != len(parameter_names)
            ):
                continue
            if bool(int(method.get("access", 0)) & 0x0008) != source_static:
                continue
            if (
                _source_parameters_match_descriptor(
                    source_params,
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            exact_candidates.append(method)
        if len(exact_candidates) != 1:
            continue

        exact_method = exact_candidates[0]
        exact_method_descriptor = str(
            exact_method.get("descriptor", "")
        )
        exact_parameter_shapes = _descriptor_parameter_shapes(
            exact_method_descriptor
        )
        if (
            exact_parameter_shapes is None
            or len(exact_parameter_shapes) != len(parameter_names)
        ):
            continue

        indy_calls = [
            invocation
            for invocation in exact_method.get(
                "method_invocations", []
            )
            if invocation.get("operation") == "invokedynamic"
        ]
        if not indy_calls:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        pending: list[dict[str, Any]] = []

        for index, parameter_name in enumerate(parameter_names):
            target_shape = exact_parameter_shapes[index]
            matching_calls = []
            for invocation in indy_calls:
                indy_descriptor = str(
                    invocation.get("descriptor", "")
                )
                indy_shapes = _descriptor_parameter_shapes(
                    indy_descriptor
                )
                if indy_shapes is None:
                    continue
                if target_shape not in indy_shapes:
                    continue
                matching_calls.append(
                    {
                        "descriptor": indy_descriptor,
                        "offset": int(
                            invocation.get("offset", -1)
                        ),
                        "bootstrap_method_attr_index": int(
                            invocation.get(
                                "bootstrap_method_attr_index",
                                -1,
                            )
                        ),
                    }
                )
            if not matching_calls:
                continue

            alias_re = re.compile(
                r"(?<![A-Za-z0-9_$])"
                + re.escape(parameter_name)
                + r"(?P<suffix>[0-9]+)"
                r"(?![A-Za-z0-9_$])"
            )
            alias_matches = list(alias_re.finditer(method_code))
            if not alias_matches:
                continue
            alias_names = {
                match.group(0) for match in alias_matches
            }
            if len(alias_names) != 1:
                continue
            alias_name = next(iter(alias_names))

            declaration_re = re.compile(
                r"\b(?:final\s+)?"
                r"[A-Za-z_$][A-Za-z0-9_$.<>\[\]?]*\s+"
                + re.escape(alias_name)
                + r"\b"
            )
            if declaration_re.search(method_code):
                continue

            pending.append(
                {
                    "parameter_name": parameter_name,
                    "alias_name": alias_name,
                    "matches": alias_matches,
                    "matching_calls": matching_calls,
                }
            )

        for item in pending:
            alias_matches = item["matches"]
            for alias_match in alias_matches:
                start = method_start + alias_match.start()
                end = method_start + alias_match.end()
                edits.append(
                    (
                        start,
                        end,
                        str(item["parameter_name"]),
                    )
                )
            actions.append(
                {
                    "kind": (
                        "invokedynamic_parameter_capture_alias"
                    ),
                    "source_path": rel,
                    "method_name": method_match.group("name"),
                    "method_descriptor": exact_method_descriptor,
                    "parameter_name": item["parameter_name"],
                    "alias_name": item["alias_name"],
                    "replacement_count": len(alias_matches),
                    "invokedynamic_callsites": item[
                        "matching_calls"
                    ],
                    "provenance": {
                        "kind": "source_safety",
                        "reason": (
                            "procyon_invokedynamic_parameter_capture_alias"
                        ),
                        "strategy": (
                            "source_parameter_to_exact_invokedynamic_capture"
                        ),
                    },
                }
            )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping invokedynamic capture-alias edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



def _normalize_invokedynamic_captured_class_local_aliases(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore lost aliases for captured Class locals in Field mappers.

    Procyon can preserve the source Class local used to open declared fields
    while inventing an undeclared alias for that same captured value inside
    a block lambda. Repair only the narrow reflection shape where source and
    exact bytecode independently agree on one declared-field stream, one
    captured Class slot, and one LambdaMetafactory helper whose Class/Field
    parameter use proves Field.get(capturedClass), Class.getSimpleName(), and
    Field.getName().
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    bootstrap_methods = list(profile.get("bootstrap_methods", []))
    if not bootstrap_methods:
        return []

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    stream_re = re.compile(
        r"(?:(?:java\.util\.)?Arrays)\s*\.\s*stream\s*\(\s*"
        r"(?P<capture>[A-Za-z_$][A-Za-z0-9_$]*)\s*\.\s*"
        r"getDeclaredFields\s*\(\s*\)\s*\)"
    )
    block_map_re = re.compile(
        r"\.\s*map\s*\(\s*"
        r"(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)\s*->\s*\{"
    )

    expected_bootstrap_descriptors = {
        "metafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodHandle;"
            "Ljava/lang/invoke/MethodType;)"
            "Ljava/lang/invoke/CallSite;"
        ),
        "altMetafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "[Ljava/lang/Object;)"
            "Ljava/lang/invoke/CallSite;"
        ),
    }

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        stream_matches = list(stream_re.finditer(method_code))
        block_maps = list(block_map_re.finditer(method_code))
        if len(stream_matches) != 1 or len(block_maps) != 1:
            continue

        stream_match = stream_matches[0]
        block_map = block_maps[0]
        if block_map.start() <= stream_match.start():
            continue

        capture_name = stream_match.group("capture")
        field_name = block_map.group("field")

        capture_decl_re = re.compile(
            r"\b(?:(?:java\.lang\.)?Class)"
            r"(?:\s*<[^;=(){}]+>)?\s+"
            + re.escape(capture_name)
            + r"\b"
        )
        capture_decls = [
            match
            for match in capture_decl_re.finditer(method_code)
            if match.start() < stream_match.start()
        ]
        if len(capture_decls) != 1:
            continue

        field_get_re = re.compile(
            r"(?<![A-Za-z0-9_$])"
            + re.escape(field_name)
            + r"\s*\.\s*get\s*\(\s*"
            r"(?P<alias>[A-Za-z_$][A-Za-z0-9_$]*)\s*\)"
        )
        field_gets = list(field_get_re.finditer(method_code))
        if len(field_gets) != 1:
            continue
        alias_name = field_gets[0].group("alias")
        if alias_name == capture_name:
            continue

        simple_name_re = re.compile(
            r"(?<![A-Za-z0-9_$])"
            + re.escape(alias_name)
            + r"\s*\.\s*getSimpleName\s*\(\s*\)"
        )
        simple_name_hits = list(simple_name_re.finditer(method_code))
        field_name_re = re.compile(
            r"(?<![A-Za-z0-9_$])"
            + re.escape(field_name)
            + r"\s*\.\s*getName\s*\(\s*\)"
        )
        field_name_hits = list(field_name_re.finditer(method_code))
        if len(simple_name_hits) != 1 or len(field_name_hits) != 1:
            continue

        alias_hits = list(
            re.finditer(
                r"(?<![A-Za-z0-9_$])"
                + re.escape(alias_name)
                + r"(?![A-Za-z0-9_$])",
                method_code,
            )
        )
        if len(alias_hits) != 2:
            continue
        expected_alias_starts = {
            field_gets[0].start("alias"),
            simple_name_hits[0].start(),
        }
        if {hit.start() for hit in alias_hits} != expected_alias_starts:
            continue

        declaration_re = re.compile(
            r"\b(?:final\s+)?"
            r"[A-Za-z_$][A-Za-z0-9_$.<>\[\]?]*\s+"
            + re.escape(alias_name)
            + r"\b"
        )
        if declaration_re.search(method_code):
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        exact_candidates = [
            exact_method
            for exact_method in profile.get("methods", [])
            if exact_method.get("name") == method_match.group("name")
            and _source_parameters_match_descriptor(
                method_match.group("params"),
                str(exact_method.get("descriptor", "")),
                current_package=current_package,
            )
            is True
            and (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                == source_static
            )
        ]
        if len(exact_candidates) != 1:
            continue
        exact_method = exact_candidates[0]
        exact_instructions = list(exact_method.get("instructions", []))
        instruction_index_by_offset = {
            int(instruction.get("offset", -1)): index
            for index, instruction in enumerate(exact_instructions)
            if int(instruction.get("offset", -1)) >= 0
        }

        declared_field_sites: list[tuple[int, int]] = []
        for index, instruction in enumerate(exact_instructions):
            if not (
                instruction.get("mnemonic") == "invokevirtual"
                and instruction.get("owner") == "java/lang/Class"
                and instruction.get("name") == "getDeclaredFields"
                and instruction.get("descriptor")
                == "()[Ljava/lang/reflect/Field;"
                and index > 0
            ):
                continue
            receiver = exact_instructions[index - 1]
            if receiver.get("mnemonic") != "aload":
                continue
            local_index = int(receiver.get("local_index", -1))
            if local_index < 0:
                continue
            declared_field_sites.append((index, local_index))
        if len(declared_field_sites) != 1:
            continue
        declared_field_index, capture_slot = declared_field_sites[0]

        matching_indy: list[dict[str, Any]] = []
        for invocation in exact_method.get("method_invocations", []):
            if not (
                invocation.get("operation") == "invokedynamic"
                and invocation.get("name") == "apply"
                and invocation.get("descriptor")
                == "(Ljava/lang/Class;)Ljava/util/function/Function;"
            ):
                continue
            invocation_offset = int(invocation.get("offset", -1))
            instruction_index = instruction_index_by_offset.get(
                invocation_offset
            )
            if (
                instruction_index is None
                or instruction_index <= declared_field_index
                or instruction_index <= 0
            ):
                continue
            capture_load = exact_instructions[instruction_index - 1]
            if not (
                capture_load.get("mnemonic") == "aload"
                and int(capture_load.get("local_index", -1))
                == capture_slot
            ):
                continue

            bootstrap_index = int(
                invocation.get("bootstrap_method_attr_index", -1)
            )
            if not (0 <= bootstrap_index < len(bootstrap_methods)):
                continue
            bootstrap = bootstrap_methods[bootstrap_index]
            bootstrap_method = bootstrap.get("bootstrap_method", {})
            bootstrap_name = str(bootstrap_method.get("name", ""))
            if not (
                bootstrap_method.get("owner")
                == "java/lang/invoke/LambdaMetafactory"
                and bootstrap_name in expected_bootstrap_descriptors
                and bootstrap_method.get("descriptor")
                == expected_bootstrap_descriptors[bootstrap_name]
                and bootstrap_method.get("target_kind") == "method"
                and int(bootstrap_method.get("reference_kind", -1)) == 6
            ):
                continue

            implementation_handles = [
                argument.get("method_handle", {})
                for argument in bootstrap.get("arguments", [])
                if argument.get("kind") == "method_handle"
                and argument.get("method_handle", {}).get("owner")
                == current_owner
            ]
            if len(implementation_handles) != 1:
                continue
            implementation = implementation_handles[0]
            helper_descriptor = str(
                implementation.get("descriptor", "")
            )
            helper_shapes = _descriptor_parameter_shapes(
                helper_descriptor
            )
            helper_return = _descriptor_return_descriptor(
                helper_descriptor
            )
            if not (
                implementation.get("target_kind") == "method"
                and int(implementation.get("reference_kind", -1)) == 6
                and helper_shapes
                == [
                    (0, "ref", "java/lang/Class"),
                    (0, "ref", "java/lang/reflect/Field"),
                ]
                and helper_return is not None
                and helper_return.startswith("L")
                and helper_return.endswith(";")
            ):
                continue

            expected_instantiated = (
                "(Ljava/lang/reflect/Field;)"
                + helper_return
            )
            instantiated_types = {
                str(argument.get("descriptor", ""))
                for argument in bootstrap.get("arguments", [])
                if argument.get("kind") == "method_type"
            }
            if expected_instantiated not in instantiated_types:
                continue

            helpers = [
                helper
                for helper in profile.get("methods", [])
                if helper.get("name") == implementation.get("name")
                and helper.get("descriptor") == helper_descriptor
                and int(helper.get("access", 0)) & 0x0008
                and int(helper.get("access", 0)) & 0x1000
            ]
            if len(helpers) != 1:
                continue
            helper_instructions = list(
                helpers[0].get("instructions", [])
            )

            field_get_sites = [
                index
                for index in range(2, len(helper_instructions))
                if helper_instructions[index].get("mnemonic")
                == "invokevirtual"
                and helper_instructions[index].get("owner")
                == "java/lang/reflect/Field"
                and helper_instructions[index].get("name") == "get"
                and helper_instructions[index].get("descriptor")
                == "(Ljava/lang/Object;)Ljava/lang/Object;"
                and helper_instructions[index - 2].get("mnemonic")
                == "aload"
                and int(
                    helper_instructions[index - 2].get(
                        "local_index", -1
                    )
                )
                == 1
                and helper_instructions[index - 1].get("mnemonic")
                == "aload"
                and int(
                    helper_instructions[index - 1].get(
                        "local_index", -1
                    )
                )
                == 0
            ]
            class_name_sites = [
                index
                for index in range(1, len(helper_instructions))
                if helper_instructions[index].get("mnemonic")
                == "invokevirtual"
                and helper_instructions[index].get("owner")
                == "java/lang/Class"
                and helper_instructions[index].get("name")
                == "getSimpleName"
                and helper_instructions[index].get("descriptor")
                == "()Ljava/lang/String;"
                and helper_instructions[index - 1].get("mnemonic")
                == "aload"
                and int(
                    helper_instructions[index - 1].get(
                        "local_index", -1
                    )
                )
                == 0
            ]
            field_name_sites = [
                index
                for index in range(1, len(helper_instructions))
                if helper_instructions[index].get("mnemonic")
                == "invokevirtual"
                and helper_instructions[index].get("owner")
                == "java/lang/reflect/Field"
                and helper_instructions[index].get("name") == "getName"
                and helper_instructions[index].get("descriptor")
                == "()Ljava/lang/String;"
                and helper_instructions[index - 1].get("mnemonic")
                == "aload"
                and int(
                    helper_instructions[index - 1].get(
                        "local_index", -1
                    )
                )
                == 1
            ]
            if not (
                len(field_get_sites) == 1
                and len(class_name_sites) == 1
                and len(field_name_sites) == 1
            ):
                continue

            matching_indy.append(
                {
                    "descriptor": str(
                        invocation.get("descriptor", "")
                    ),
                    "offset": invocation_offset,
                    "bootstrap_method_attr_index": bootstrap_index,
                    "helper_name": str(
                        implementation.get("name", "")
                    ),
                    "helper_descriptor": helper_descriptor,
                    "capture_slot": capture_slot,
                }
            )

        if len(matching_indy) != 1:
            continue

        for alias_hit in alias_hits:
            edits.append(
                (
                    method_start + alias_hit.start(),
                    method_start + alias_hit.end(),
                    capture_name,
                )
            )
        actions.append(
            {
                "kind": "invokedynamic_captured_class_local_alias",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": exact_method.get("descriptor"),
                "capture_source_name": capture_name,
                "undeclared_capture_alias": alias_name,
                "field_lambda_parameter_name": field_name,
                "invokedynamic": matching_indy[0],
                "replacement_count": len(alias_hits),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_invokedynamic_captured_class_local_alias"
                    ),
                    "strategy": (
                        "unique_declared_field_stream_plus_exact_class_capture_helper"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping captured-Class alias edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



def _normalize_invokedynamic_callback_reference_capture_aliases(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore lost reference captures in a four-int callback lambda.

    Procyon can reconstruct an instance LambdaMetafactory callback body with
    undeclared aliases for outer reference locals even when the outer source
    locals are still present.  Repair only the narrow shape where source and
    exact bytecode independently prove the captured Set, Map.Entry, and Map
    values. Primitive captures are deliberately left to separate rules.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    bootstrap_methods = list(profile.get("bootstrap_methods", []))
    if not bootstrap_methods:
        return []
    class_field_names = {
        str(field.get("name", ""))
        for field in profile.get("fields", [])
        if _is_java_identifier(str(field.get("name", "")))
    }

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []
    identifier = r"[A-Za-z_$][A-Za-z0-9_$]*"

    entry_loop_re = re.compile(
        r"for\s*\(\s*"
        r"(?:(?:java\.util\.)?Map\s*\.\s*)?Entry"
        r"(?:\s*<[^;(){}]+>)?\s+"
        r"(?P<entry>" + identifier + r")\s*:\s*"
        r"(?P<input>" + identifier + r")\s*\.\s*entrySet"
        r"\s*\(\s*\)\s*\)"
    )
    map_value_re_template = (
        r"\b(?:final\s+)?(?:java\.util\.)?Map"
        r"(?:\s*<[^;=(){}]+>)?\s+"
        r"(?P<map>" + identifier + r")\s*=\s*"
        r"(?:\(\s*(?:java\.util\.)?Map"
        r"(?:\s*<[^;=(){}]+>)?\s*\)\s*)?"
        r"{entry}\s*\.\s*getValue\s*\(\s*\)"
    )
    set_decl_re = re.compile(
        r"\b(?:final\s+)?(?:java\.util\.)?"
        r"(?:Set|HashSet|LinkedHashSet)"
        r"(?:\s*<[^;=(){}]+>)?\s+"
        r"(?P<set>" + identifier + r")\s*=\s*new\s+"
        r"(?:java\.util\.)?(?:HashSet|LinkedHashSet)"
        r"(?:\s*<[^;=(){}]*>)?\s*\("
    )
    callback_re = re.compile(
        r"\(\s*(?P<p1>" + identifier + r")\s*,\s*"
        r"(?P<p2>" + identifier + r")\s*,\s*"
        r"(?P<p3>" + identifier + r")\s*,\s*"
        r"(?P<p4>" + identifier + r")\s*\)\s*->\s*\{"
    )

    expected_bootstrap_descriptors = {
        "metafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodHandle;"
            "Ljava/lang/invoke/MethodType;)"
            "Ljava/lang/invoke/CallSite;"
        ),
        "altMetafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "[Ljava/lang/Object;)"
            "Ljava/lang/invoke/CallSite;"
        ),
    }

    expected_capture_shapes = [
        (0, "ref", current_owner),
        (0, "primitive", "I"),
        (0, "ref", "java/util/Set"),
        (0, "ref", "java/util/Map$Entry"),
        (0, "primitive", "I"),
        (0, "ref", "java/util/Map"),
    ]
    expected_helper_shapes = [
        (0, "primitive", "I"),
        (0, "ref", "java/util/Set"),
        (0, "ref", "java/util/Map$Entry"),
        (0, "primitive", "I"),
        (0, "ref", "java/util/Map"),
        (0, "primitive", "I"),
        (0, "primitive", "I"),
        (0, "primitive", "I"),
        (0, "primitive", "I"),
    ]

    def _declared_in_method(
        method_code: str,
        name: str,
        parameter_names: list[str],
        lambda_names: set[str],
    ) -> bool:
        if (
            name in parameter_names
            or name in lambda_names
            or name in class_field_names
        ):
            return True
        declaration_re = re.compile(
            r"\b(?:final\s+)?"
            r"[A-Za-z_$][A-Za-z0-9_$.<>\[\]?]*\s+"
            + re.escape(name)
            + r"\b"
        )
        return declaration_re.search(method_code) is not None

    def _unique_undeclared_alias(
        lambda_code: str,
        method_code: str,
        pattern: re.Pattern[str],
        *,
        outer_name: str,
        parameter_names: list[str],
        lambda_names: set[str],
    ) -> tuple[str, list[re.Match[str]]] | None:
        matches = list(pattern.finditer(lambda_code))
        aliases = {
            match.group("alias")
            for match in matches
            if match.group("alias") != outer_name
            and not _declared_in_method(
                method_code,
                match.group("alias"),
                parameter_names,
                lambda_names,
            )
        }
        if len(aliases) != 1:
            return None
        alias = next(iter(aliases))
        alias_matches = [
            match for match in matches if match.group("alias") == alias
        ]
        token_hits = list(
            re.finditer(
                r"(?<![A-Za-z0-9_$])"
                + re.escape(alias)
                + r"(?![A-Za-z0-9_$])",
                lambda_code,
            )
        )
        if (
            len(alias_matches) != 1
            or len(token_hits) != 1
            or token_hits[0].start() != alias_matches[0].start("alias")
        ):
            return None
        return alias, alias_matches

    def _helper_uses_capture(
        instructions: list[dict[str, Any]],
        *,
        slot: int,
        owner: str,
        name: str,
        descriptor: str,
        lookback: int = 3,
    ) -> bool:
        sites = []
        for index, instruction in enumerate(instructions):
            if not (
                instruction.get("mnemonic")
                in {"invokeinterface", "invokevirtual"}
                and instruction.get("owner") == owner
                and instruction.get("name") == name
                and instruction.get("descriptor") == descriptor
            ):
                continue
            start = max(0, index - lookback)
            window = instructions[start:index]
            if any(
                row.get("mnemonic") == "aload"
                and int(row.get("local_index", -1)) == slot
                for row in window
            ):
                sites.append(index)
        return len(sites) == 1

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        source_params = method_match.group("params")
        parameter_names = _source_parameter_names(source_params)
        if parameter_names is None:
            continue

        entry_loops = list(entry_loop_re.finditer(method_code))
        callbacks = list(callback_re.finditer(method_code))
        set_decls = list(set_decl_re.finditer(method_code))
        if (
            len(entry_loops) != 1
            or len(callbacks) != 1
            or len(set_decls) != 1
        ):
            continue
        entry_loop = entry_loops[0]
        callback = callbacks[0]
        set_decl = set_decls[0]
        if not (
            entry_loop.start() < set_decl.start() < callback.start()
        ):
            continue

        entry_name = entry_loop.group("entry")
        map_value_re = re.compile(
            map_value_re_template.replace("{entry}", re.escape(entry_name))
        )
        map_values = list(map_value_re.finditer(method_code))
        if len(map_values) != 1:
            continue
        map_value = map_values[0]
        if not (
            entry_loop.start() < map_value.start() < callback.start()
        ):
            continue

        map_name = map_value.group("map")
        set_name = set_decl.group("set")
        callback_brace = method_code.find(
            "{", callback.start(), callback.end()
        )
        if callback_brace < 0:
            continue
        try:
            callback_end = _matching_brace_end(
                method_code, callback_brace
            )
        except SourceNormalizationError:
            continue
        callback_code = method_code[callback_brace:callback_end]
        lambda_names = {
            callback.group("p1"),
            callback.group("p2"),
            callback.group("p3"),
            callback.group("p4"),
        }

        set_alias = _unique_undeclared_alias(
            callback_code,
            method_code,
            re.compile(
                r"(?<![A-Za-z0-9_$.])"
                r"(?P<alias>" + identifier + r")\s*\.\s*add\s*\("
            ),
            outer_name=set_name,
            parameter_names=parameter_names,
            lambda_names=lambda_names,
        )
        entry_alias = _unique_undeclared_alias(
            callback_code,
            method_code,
            re.compile(
                r"(?<![A-Za-z0-9_$.])"
                r"(?P<alias>" + identifier + r")\s*\.\s*getKey"
                r"\s*\(\s*\)"
            ),
            outer_name=entry_name,
            parameter_names=parameter_names,
            lambda_names=lambda_names,
        )
        map_alias = _unique_undeclared_alias(
            callback_code,
            method_code,
            re.compile(
                r"(?<![A-Za-z0-9_$.])"
                r"(?P<alias>" + identifier + r")\s*\.\s*getOrDefault"
                r"\s*\("
            ),
            outer_name=map_name,
            parameter_names=parameter_names,
            lambda_names=lambda_names,
        )
        if set_alias is None or entry_alias is None or map_alias is None:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        if source_static:
            continue
        exact_candidates = [
            exact_method
            for exact_method in profile.get("methods", [])
            if exact_method.get("name") == method_match.group("name")
            and _source_parameters_match_descriptor(
                source_params,
                str(exact_method.get("descriptor", "")),
                current_package=current_package,
            )
            is True
            and not (int(exact_method.get("access", 0)) & 0x0008)
        ]
        if len(exact_candidates) != 1:
            continue
        exact_method = exact_candidates[0]

        matching_indy: list[dict[str, Any]] = []
        for invocation in exact_method.get("method_invocations", []):
            if invocation.get("operation") != "invokedynamic":
                continue
            descriptor = str(invocation.get("descriptor", ""))
            captured_shapes = _descriptor_parameter_shapes(descriptor)
            return_descriptor = _descriptor_return_descriptor(descriptor)
            if not (
                captured_shapes == expected_capture_shapes
                and return_descriptor is not None
                and return_descriptor.startswith("L")
                and return_descriptor.endswith(";")
            ):
                continue

            bootstrap_index = int(
                invocation.get("bootstrap_method_attr_index", -1)
            )
            if not (0 <= bootstrap_index < len(bootstrap_methods)):
                continue
            bootstrap = bootstrap_methods[bootstrap_index]
            bootstrap_method = bootstrap.get("bootstrap_method", {})
            bootstrap_name = str(bootstrap_method.get("name", ""))
            if not (
                bootstrap_method.get("owner")
                == "java/lang/invoke/LambdaMetafactory"
                and bootstrap_name in expected_bootstrap_descriptors
                and bootstrap_method.get("descriptor")
                == expected_bootstrap_descriptors[bootstrap_name]
                and bootstrap_method.get("target_kind") == "method"
            ):
                continue

            implementation_handles = [
                argument.get("method_handle", {})
                for argument in bootstrap.get("arguments", [])
                if argument.get("kind") == "method_handle"
                and argument.get("method_handle", {}).get("owner")
                == current_owner
            ]
            if len(implementation_handles) != 1:
                continue
            implementation = implementation_handles[0]
            helper_descriptor = str(
                implementation.get("descriptor", "")
            )
            helper_shapes = _descriptor_parameter_shapes(
                helper_descriptor
            )
            if not (
                implementation.get("target_kind") == "method"
                and int(implementation.get("reference_kind", -1)) == 7
                and helper_shapes == expected_helper_shapes
                and _descriptor_return_descriptor(helper_descriptor) == "V"
            ):
                continue

            instantiated_types = {
                str(argument.get("descriptor", ""))
                for argument in bootstrap.get("arguments", [])
                if argument.get("kind") == "method_type"
            }
            if "(IIII)V" not in instantiated_types:
                continue

            helpers = [
                helper
                for helper in profile.get("methods", [])
                if helper.get("name") == implementation.get("name")
                and helper.get("descriptor") == helper_descriptor
                and not (int(helper.get("access", 0)) & 0x0008)
                and (int(helper.get("access", 0)) & 0x1000)
            ]
            if len(helpers) != 1:
                continue
            helper_instructions = list(
                helpers[0].get("instructions", [])
            )
            if not (
                _helper_uses_capture(
                    helper_instructions,
                    slot=2,
                    owner="java/util/Set",
                    name="add",
                    descriptor="(Ljava/lang/Object;)Z",
                )
                and _helper_uses_capture(
                    helper_instructions,
                    slot=3,
                    owner="java/util/Map$Entry",
                    name="getKey",
                    descriptor="()Ljava/lang/Object;",
                    lookback=2,
                )
                and _helper_uses_capture(
                    helper_instructions,
                    slot=5,
                    owner="java/util/Map",
                    name="getOrDefault",
                    descriptor=(
                        "(Ljava/lang/Object;Ljava/lang/Object;)"
                        "Ljava/lang/Object;"
                    ),
                )
            ):
                continue

            matching_indy.append(
                {
                    "descriptor": descriptor,
                    "offset": int(invocation.get("offset", -1)),
                    "bootstrap_method_attr_index": bootstrap_index,
                    "helper_name": str(
                        implementation.get("name", "")
                    ),
                    "helper_descriptor": helper_descriptor,
                }
            )

        if len(matching_indy) != 1:
            continue

        replacements = [
            (set_alias[0], set_alias[1][0], set_name, "set"),
            (entry_alias[0], entry_alias[1][0], entry_name, "entry"),
            (map_alias[0], map_alias[1][0], map_name, "map"),
        ]
        for alias_name, match, replacement, _role in replacements:
            start = (
                method_start
                + callback_brace
                + match.start("alias")
            )
            end = (
                method_start
                + callback_brace
                + match.end("alias")
            )
            edits.append((start, end, replacement))

        actions.append(
            {
                "kind": (
                    "invokedynamic_callback_reference_capture_alias"
                ),
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": exact_method.get("descriptor"),
                "capture_source_names": {
                    "set": set_name,
                    "entry": entry_name,
                    "map": map_name,
                },
                "undeclared_capture_aliases": {
                    "set": set_alias[0],
                    "entry": entry_alias[0],
                    "map": map_alias[0],
                },
                "invokedynamic": matching_indy[0],
                "replacement_count": 3,
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_invokedynamic_callback_reference_capture_alias"
                    ),
                    "strategy": (
                        "source_outer_reference_roles_plus_exact_instance_lambda_helper"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping callback capture-alias edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



def _normalize_invokedynamic_callback_copied_int_capture(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Reconstruct one copied effectively-final int callback capture.

    This handles the narrow Procyon shape where source preserves a mutable
    outer int local but loses the compiler-required effectively-final copy
    captured by a four-int callback lambda. Exact bytecode must prove the
    original -1-initialized local is copied to a fresh slot immediately before
    the established six-value LambdaMetafactory capture sequence.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    bootstrap_methods = list(profile.get("bootstrap_methods", []))
    if not bootstrap_methods:
        return []
    integer_set_fields = {
        str(field.get("name", ""))
        for field in profile.get("fields", [])
        if not (int(field.get("access", 0)) & 0x0008)
        and field.get("descriptor") == "Ljava/util/Set;"
        and field.get("signature")
        == "Ljava/util/Set<Ljava/lang/Integer;>;"
        and _is_java_identifier(str(field.get("name", "")))
    }
    if not integer_set_fields:
        return []

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []
    identifier = r"[A-Za-z_$][A-Za-z0-9_$]*"

    region_decl_re = re.compile(
        r"\bint\s+(?P<region>" + identifier + r")\s*=\s*-1\s*;"
    )
    callback_re = re.compile(
        r"\(\s*(?P<p1>" + identifier + r")\s*,\s*"
        r"(?P<p2>" + identifier + r")\s*,\s*"
        r"(?P<p3>" + identifier + r")\s*,\s*"
        r"(?P<p4>" + identifier + r")\s*\)\s*->\s*\{"
    )

    expected_capture_shapes = [
        (0, "ref", current_owner),
        (0, "primitive", "I"),
        (0, "ref", "java/util/Set"),
        (0, "ref", "java/util/Map$Entry"),
        (0, "primitive", "I"),
        (0, "ref", "java/util/Map"),
    ]
    expected_helper_shapes = [
        (0, "primitive", "I"),
        (0, "ref", "java/util/Set"),
        (0, "ref", "java/util/Map$Entry"),
        (0, "primitive", "I"),
        (0, "ref", "java/util/Map"),
        (0, "primitive", "I"),
        (0, "primitive", "I"),
        (0, "primitive", "I"),
        (0, "primitive", "I"),
    ]
    expected_bootstrap_descriptors = {
        "metafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodHandle;"
            "Ljava/lang/invoke/MethodType;)"
            "Ljava/lang/invoke/CallSite;"
        ),
        "altMetafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "[Ljava/lang/Object;)"
            "Ljava/lang/invoke/CallSite;"
        ),
    }

    def _instruction_int_constant(
        row: dict[str, Any],
    ) -> int | None:
        value = row.get("int_constant")
        if isinstance(value, int):
            return value
        mnemonic = str(row.get("mnemonic", ""))
        constants = {
            "iconst_m1": -1,
            "iconst_0": 0,
            "iconst_1": 1,
            "iconst_2": 2,
            "iconst_3": 3,
            "iconst_4": 4,
            "iconst_5": 5,
        }
        return constants.get(mnemonic)

    def _has_helper_region_proof(
        instructions: list[dict[str, Any]],
        *,
        field_name: str,
    ) -> bool:
        boxed_add = False
        signed_shift = False
        low_mask = False
        slot_one_loads = [
            index
            for index, row in enumerate(instructions)
            if row.get("mnemonic") == "iload"
            and int(row.get("local_index", -1)) == 1
        ]
        if len(slot_one_loads) != 4:
            return False
        for index, row in enumerate(instructions):
            if (
                row.get("mnemonic") == "iload"
                and int(row.get("local_index", -1)) == 1
            ):
                if index >= 2 and index + 2 < len(instructions):
                    receiver = instructions[index - 2]
                    field = instructions[index - 1]
                    box = instructions[index + 1]
                    add = instructions[index + 2]
                    if (
                        receiver.get("mnemonic") == "aload"
                        and int(receiver.get("local_index", -1)) == 0
                        and field.get("mnemonic") == "getfield"
                        and field.get("owner") == current_owner
                        and field.get("name") == field_name
                        and field.get("descriptor") == "Ljava/util/Set;"
                        and box.get("mnemonic") == "invokestatic"
                        and box.get("owner") == "java/lang/Integer"
                        and box.get("name") == "valueOf"
                        and box.get("descriptor")
                        == "(I)Ljava/lang/Integer;"
                        and add.get("mnemonic") == "invokeinterface"
                        and add.get("owner") == "java/util/Set"
                        and add.get("name") == "add"
                        and add.get("descriptor")
                        == "(Ljava/lang/Object;)Z"
                    ):
                        boxed_add = True
                if index + 2 < len(instructions):
                    constant = _instruction_int_constant(
                        instructions[index + 1]
                    )
                    operation = instructions[index + 2]
                    if (
                        constant == 8
                        and operation.get("mnemonic") == "ishr"
                    ):
                        signed_shift = True
                    if (
                        constant == 255
                        and operation.get("mnemonic") == "iand"
                    ):
                        low_mask = True
        return boxed_add and signed_shift and low_mask

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        region_decls = list(region_decl_re.finditer(method_code))
        callbacks = list(callback_re.finditer(method_code))
        if len(region_decls) != 1 or len(callbacks) != 1:
            continue
        region_decl = region_decls[0]
        callback = callbacks[0]
        region_name = region_decl.group("region")
        if region_decl.start() >= callback.start():
            continue

        region_assign_re = re.compile(
            r"(?<![A-Za-z0-9_$])"
            + re.escape(region_name)
            + r"\s*=\s*(?P<rhs>[^;{}]+)\s*;"
        )
        region_assignments = [
            match
            for match in region_assign_re.finditer(method_code)
            if region_decl.end() <= match.start() < callback.start()
        ]
        if len(region_assignments) != 1:
            continue
        region_assignment = region_assignments[0]
        if "(" not in region_assignment.group("rhs"):
            continue

        callback_brace = method_code.find(
            "{", callback.start(), callback.end()
        )
        if callback_brace < 0:
            continue
        try:
            callback_end = _matching_brace_end(
                method_code, callback_brace
            )
        except SourceNormalizationError:
            continue
        callback_code = method_code[callback_brace:callback_end]
        lambda_names = {
            callback.group("p1"),
            callback.group("p2"),
            callback.group("p3"),
            callback.group("p4"),
        }

        add_field_aliases = {
            (match.group("field"), match.group("alias"))
            for match in re.finditer(
                r"(?<![A-Za-z0-9_$])"
                r"(?:this\s*\.\s*)?"
                r"(?P<field>" + identifier + r")"
                r"\s*\.\s*add\s*\(\s*(?P<alias>"
                + identifier
                + r")\s*\)",
                callback_code,
            )
            if match.group("field") in integer_set_fields
            and match.group("alias") not in lambda_names
        }
        add_aliases = {alias for _field, alias in add_field_aliases}
        shift_aliases = {
            match.group("alias")
            for match in re.finditer(
                r"(?<![A-Za-z0-9_$])(?P<alias>"
                + identifier
                + r")\s*>>\s*8",
                callback_code,
            )
        }
        mask_aliases = {
            match.group("alias")
            for match in re.finditer(
                r"(?<![A-Za-z0-9_$])(?P<alias>"
                + identifier
                + r")\s*&\s*(?:0[xX]0*[fF]{2}|255)",
                callback_code,
            )
        }
        alias_candidates = (
            add_aliases & shift_aliases & mask_aliases
        )
        alias_candidates.discard(region_name)
        alias_candidates.difference_update(lambda_names)
        if len(alias_candidates) != 1:
            continue
        alias_name = next(iter(alias_candidates))
        matching_source_fields = {
            field
            for field, alias in add_field_aliases
            if alias == alias_name
        }
        if len(matching_source_fields) != 1:
            continue
        region_field_name = next(iter(matching_source_fields))

        alias_hits = list(
            re.finditer(
                r"(?<![A-Za-z0-9_$])"
                + re.escape(alias_name)
                + r"(?![A-Za-z0-9_$])",
                callback_code,
            )
        )
        if len(alias_hits) != 4:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        if source_static:
            continue
        source_params = method_match.group("params")
        exact_candidates = [
            exact_method
            for exact_method in profile.get("methods", [])
            if exact_method.get("name") == method_match.group("name")
            and _source_parameters_match_descriptor(
                source_params,
                str(exact_method.get("descriptor", "")),
                current_package=current_package,
            )
            is True
            and not (int(exact_method.get("access", 0)) & 0x0008)
        ]
        if len(exact_candidates) != 1:
            continue
        exact_method = exact_candidates[0]
        exact_instructions = list(
            exact_method.get("instructions", [])
        )
        instruction_index_by_offset = {
            int(row.get("offset", -1)): index
            for index, row in enumerate(exact_instructions)
            if int(row.get("offset", -1)) >= 0
        }

        parameter_slots = _descriptor_parameter_local_slots(
            str(exact_method.get("descriptor", "")),
            is_static=False,
        )
        if parameter_slots is None:
            continue
        parameter_slot_set = set(parameter_slots)

        minus_one_slots = {
            int(exact_instructions[index + 1].get("local_index", -1))
            for index in range(len(exact_instructions) - 1)
            if _instruction_int_constant(exact_instructions[index]) == -1
            and exact_instructions[index + 1].get("mnemonic") == "istore"
            and int(
                exact_instructions[index + 1].get("local_index", -1)
            )
            >= 0
        }
        if len(minus_one_slots) != 1:
            continue
        original_slot = next(iter(minus_one_slots))
        if original_slot in parameter_slot_set:
            continue

        matching_indy: list[dict[str, Any]] = []
        for invocation in exact_method.get("method_invocations", []):
            if invocation.get("operation") != "invokedynamic":
                continue
            descriptor = str(invocation.get("descriptor", ""))
            if (
                _descriptor_parameter_shapes(descriptor)
                != expected_capture_shapes
            ):
                continue
            invocation_offset = int(invocation.get("offset", -1))
            instruction_index = instruction_index_by_offset.get(
                invocation_offset
            )
            if instruction_index is None or instruction_index < 6:
                continue
            capture_rows = exact_instructions[
                instruction_index - 6:instruction_index
            ]
            if not (
                capture_rows[0].get("mnemonic") == "aload"
                and int(capture_rows[0].get("local_index", -1)) == 0
                and capture_rows[1].get("mnemonic") == "iload"
                and capture_rows[2].get("mnemonic") == "aload"
                and capture_rows[3].get("mnemonic") == "aload"
                and capture_rows[4].get("mnemonic") == "iload"
                and capture_rows[5].get("mnemonic") == "aload"
            ):
                continue
            capture_slot = int(
                capture_rows[1].get("local_index", -1)
            )
            if (
                capture_slot < 0
                or capture_slot == original_slot
                or capture_slot in parameter_slot_set
            ):
                continue

            copy_sites = [
                index
                for index in range(instruction_index - 1)
                if (
                    exact_instructions[index].get("mnemonic") == "iload"
                    and int(
                        exact_instructions[index].get(
                            "local_index", -1
                        )
                    )
                    == original_slot
                    and exact_instructions[index + 1].get("mnemonic")
                    == "istore"
                    and int(
                        exact_instructions[index + 1].get(
                            "local_index", -1
                        )
                    )
                    == capture_slot
                )
            ]
            if len(copy_sites) != 1:
                continue
            copy_index = copy_sites[0]
            original_value_sites = [
                index
                for index in range(copy_index)
                if (
                    exact_instructions[index].get("mnemonic")
                    in {
                        "invokestatic",
                        "invokevirtual",
                        "invokeinterface",
                        "invokespecial",
                    }
                    and _descriptor_return_descriptor(
                        str(
                            exact_instructions[index].get(
                                "descriptor", ""
                            )
                        )
                    )
                    == "I"
                    and index + 1 < len(exact_instructions)
                    and exact_instructions[index + 1].get("mnemonic")
                    == "istore"
                    and int(
                        exact_instructions[index + 1].get(
                            "local_index", -1
                        )
                    )
                    == original_slot
                )
            ]
            if len(original_value_sites) != 1:
                continue
            original_value_index = original_value_sites[0]
            overwritten = any(
                row.get("mnemonic") == "istore"
                and int(row.get("local_index", -1)) == capture_slot
                for row in exact_instructions[
                    copy_index + 2:instruction_index
                ]
            )
            if overwritten:
                continue

            bootstrap_index = int(
                invocation.get("bootstrap_method_attr_index", -1)
            )
            if not (0 <= bootstrap_index < len(bootstrap_methods)):
                continue
            bootstrap = bootstrap_methods[bootstrap_index]
            bootstrap_method = bootstrap.get("bootstrap_method", {})
            bootstrap_name = str(bootstrap_method.get("name", ""))
            if not (
                bootstrap_method.get("owner")
                == "java/lang/invoke/LambdaMetafactory"
                and bootstrap_name in expected_bootstrap_descriptors
                and bootstrap_method.get("descriptor")
                == expected_bootstrap_descriptors[bootstrap_name]
            ):
                continue

            implementation_handles = [
                argument.get("method_handle", {})
                for argument in bootstrap.get("arguments", [])
                if argument.get("kind") == "method_handle"
                and argument.get("method_handle", {}).get("owner")
                == current_owner
            ]
            if len(implementation_handles) != 1:
                continue
            implementation = implementation_handles[0]
            helper_descriptor = str(
                implementation.get("descriptor", "")
            )
            if not (
                int(implementation.get("reference_kind", -1)) == 7
                and _descriptor_parameter_shapes(helper_descriptor)
                == expected_helper_shapes
                and _descriptor_return_descriptor(helper_descriptor) == "V"
            ):
                continue

            helpers = [
                helper
                for helper in profile.get("methods", [])
                if helper.get("name") == implementation.get("name")
                and helper.get("descriptor") == helper_descriptor
                and not (int(helper.get("access", 0)) & 0x0008)
                and (int(helper.get("access", 0)) & 0x1000)
            ]
            if len(helpers) != 1:
                continue
            if not _has_helper_region_proof(
                list(helpers[0].get("instructions", [])),
                field_name=region_field_name,
            ):
                continue

            matching_indy.append(
                {
                    "descriptor": descriptor,
                    "offset": invocation_offset,
                    "bootstrap_method_attr_index": bootstrap_index,
                    "helper_name": str(
                        implementation.get("name", "")
                    ),
                    "helper_descriptor": helper_descriptor,
                    "original_slot": original_slot,
                    "capture_slot": capture_slot,
                    "original_value_offset": int(
                        exact_instructions[original_value_index].get(
                            "offset", -1
                        )
                    ),
                    "copy_offset": int(
                        exact_instructions[copy_index].get(
                            "offset", -1
                        )
                    ),
                }
            )

        if len(matching_indy) != 1:
            continue

        statement_boundary = max(
            method_code.rfind(";", 0, callback.start()),
            method_code.rfind("{", 0, callback.start()),
            method_code.rfind("}", 0, callback.start()),
        ) + 1
        statement_start = statement_boundary
        while (
            statement_start < callback.start()
            and method_code[statement_start].isspace()
        ):
            statement_start += 1
        if statement_start >= callback.start():
            continue

        absolute_statement_start = method_start + statement_start
        line_start = text.rfind(
            "\n", 0, absolute_statement_start
        ) + 1
        indentation = text[line_start:absolute_statement_start]
        if indentation.strip():
            continue

        digest = hashlib.sha256(
            (
                rel
                + "\0"
                + method_match.group("name")
                + "\0"
                + str(exact_method.get("descriptor", ""))
                + "\0"
                + region_name
            ).encode("utf-8")
        ).hexdigest()[:12]
        recovered_name = "recoveredCallbackCapture_" + digest
        if re.search(
            r"(?<![A-Za-z0-9_$])"
            + re.escape(recovered_name)
            + r"(?![A-Za-z0-9_$])",
            method_code,
        ):
            continue

        declaration = (
            indentation
            + "final int "
            + recovered_name
            + " = "
            + region_name
            + ";\n"
        )
        edits.append((line_start, line_start, declaration))
        for alias_hit in alias_hits:
            edits.append(
                (
                    method_start
                    + callback_brace
                    + alias_hit.start(),
                    method_start
                    + callback_brace
                    + alias_hit.end(),
                    recovered_name,
                )
            )

        actions.append(
            {
                "kind": "invokedynamic_callback_copied_int_capture",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": exact_method.get("descriptor"),
                "source_original_name": region_name,
                "corrupted_capture_alias": alias_name,
                "affected_region_field_name": region_field_name,
                "recovered_capture_name": recovered_name,
                "replacement_count": len(alias_hits),
                "invokedynamic": matching_indy[0],
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_lost_effectively_final_callback_int_copy"
                    ),
                    "strategy": (
                        "unique_minus_one_source_local_plus_exact_jvm_slot_copy"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: (row[0], row[1]))
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping copied-int callback edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



def _normalize_invokedynamic_callback_direct_int_capture_alias(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore one directly captured int alias in the callback report."""

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    bootstrap_methods = list(profile.get("bootstrap_methods", []))
    if not bootstrap_methods:
        return []

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []
    identifier = r"[A-Za-z_$][A-Za-z0-9_$]*"

    callback_re = re.compile(
        r"\(\s*(?P<p1>" + identifier + r")\s*,\s*"
        r"(?P<p2>" + identifier + r")\s*,\s*"
        r"(?P<p3>" + identifier + r")\s*,\s*"
        r"(?P<p4>" + identifier + r")\s*\)\s*->\s*\{"
    )
    int_decl_re = re.compile(
        r"\bint\s+(?P<name>" + identifier + r")\s*=\s*"
        r"(?P<rhs>[^;{}]+)\s*;"
    )

    expected_capture_shapes = [
        (0, "ref", current_owner),
        (0, "primitive", "I"),
        (0, "ref", "java/util/Set"),
        (0, "ref", "java/util/Map$Entry"),
        (0, "primitive", "I"),
        (0, "ref", "java/util/Map"),
    ]
    expected_helper_shapes = [
        (0, "primitive", "I"),
        (0, "ref", "java/util/Set"),
        (0, "ref", "java/util/Map$Entry"),
        (0, "primitive", "I"),
        (0, "ref", "java/util/Map"),
        (0, "primitive", "I"),
        (0, "primitive", "I"),
        (0, "primitive", "I"),
        (0, "primitive", "I"),
    ]
    expected_bootstrap_descriptors = {
        "metafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodHandle;"
            "Ljava/lang/invoke/MethodType;)"
            "Ljava/lang/invoke/CallSite;"
        ),
        "altMetafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "[Ljava/lang/Object;)"
            "Ljava/lang/invoke/CallSite;"
        ),
    }

    def _helper_uses_land_slot(
        instructions: list[dict[str, Any]],
    ) -> bool:
        sites = 0
        for index in range(len(instructions) - 1):
            load = instructions[index]
            call = instructions[index + 1]
            if not (
                load.get("mnemonic") == "iload"
                and int(load.get("local_index", -1)) == 4
                and call.get("mnemonic") == "invokevirtual"
                and call.get("owner") == "java/lang/StringBuilder"
                and call.get("name") == "append"
                and call.get("descriptor")
                == "(I)Ljava/lang/StringBuilder;"
            ):
                continue
            sites += 1
        return sites == 1

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        callbacks = list(callback_re.finditer(method_code))
        if len(callbacks) != 1:
            continue
        callback = callbacks[0]
        callback_brace = method_code.find(
            "{", callback.start(), callback.end()
        )
        if callback_brace < 0:
            continue
        try:
            callback_end = _matching_brace_end(
                method_code, callback_brace
            )
        except SourceNormalizationError:
            continue

        local_candidates = [
            match
            for match in int_decl_re.finditer(method_code)
            if match.end() < callback.start()
            and "(" in match.group("rhs")
            and not match.group("rhs").strip().startswith("-")
        ]
        if not local_candidates:
            continue

        raw_callback = text[
            method_start + callback_brace:
            method_start + callback_end
        ]
        land_alias_match = re.search(
            r"\"(?:\\.|[^\"\\])*land\s*=\s*\""
            r"\s*\+\s*(?P<alias>" + identifier + r")",
            raw_callback,
        )
        if land_alias_match is None:
            continue
        alias_name = land_alias_match.group("alias")
        lambda_names = {
            callback.group("p1"),
            callback.group("p2"),
            callback.group("p3"),
            callback.group("p4"),
        }
        if alias_name in lambda_names:
            continue
        alias_hits = list(
            re.finditer(
                r"(?<![A-Za-z0-9_$])"
                + re.escape(alias_name)
                + r"(?![A-Za-z0-9_$])",
                raw_callback,
            )
        )
        if len(alias_hits) != 1:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        if source_static:
            continue
        exact_candidates = [
            exact_method
            for exact_method in profile.get("methods", [])
            if exact_method.get("name") == method_match.group("name")
            and _source_parameters_match_descriptor(
                method_match.group("params"),
                str(exact_method.get("descriptor", "")),
                current_package=current_package,
            )
            is True
            and not (int(exact_method.get("access", 0)) & 0x0008)
        ]
        if len(exact_candidates) != 1:
            continue
        exact_method = exact_candidates[0]
        instructions = list(exact_method.get("instructions", []))
        by_offset = {
            int(row.get("offset", -1)): index
            for index, row in enumerate(instructions)
            if int(row.get("offset", -1)) >= 0
        }

        matching_indy: list[dict[str, Any]] = []
        for invocation in exact_method.get("method_invocations", []):
            if (
                invocation.get("operation") != "invokedynamic"
                or _descriptor_parameter_shapes(
                    str(invocation.get("descriptor", ""))
                )
                != expected_capture_shapes
            ):
                continue
            idx = by_offset.get(int(invocation.get("offset", -1)))
            if idx is None or idx < 6:
                continue
            capture_rows = instructions[idx - 6:idx]
            if not (
                capture_rows[4].get("mnemonic") == "iload"
            ):
                continue
            land_slot = int(
                capture_rows[4].get("local_index", -1)
            )
            if land_slot < 0:
                continue

            direct_stores = []
            for ins_idx in range(1, idx):
                store = instructions[ins_idx]
                prev = instructions[ins_idx - 1]
                if not (
                    store.get("mnemonic") == "istore"
                    and int(store.get("local_index", -1)) == land_slot
                ):
                    continue
                if prev.get("mnemonic") not in {
                    "invokestatic",
                    "invokevirtual",
                    "invokeinterface",
                }:
                    continue
                descriptor = str(prev.get("descriptor", ""))
                if _descriptor_return_descriptor(descriptor) != "I":
                    continue
                direct_stores.append(ins_idx)
            if len(direct_stores) != 1:
                continue
            store_idx = direct_stores[0]
            if any(
                row.get("mnemonic") == "istore"
                and int(row.get("local_index", -1)) == land_slot
                for row in instructions[store_idx + 1:idx]
            ):
                continue

            bootstrap_index = int(
                invocation.get("bootstrap_method_attr_index", -1)
            )
            if not (0 <= bootstrap_index < len(bootstrap_methods)):
                continue
            bootstrap = bootstrap_methods[bootstrap_index]
            bootstrap_method = bootstrap.get("bootstrap_method", {})
            bootstrap_name = str(bootstrap_method.get("name", ""))
            if not (
                bootstrap_method.get("owner")
                == "java/lang/invoke/LambdaMetafactory"
                and bootstrap_name in expected_bootstrap_descriptors
                and bootstrap_method.get("descriptor")
                == expected_bootstrap_descriptors[bootstrap_name]
                and bootstrap_method.get("target_kind") == "method"
            ):
                continue
            implementation_handles = [
                argument.get("method_handle", {})
                for argument in bootstrap.get("arguments", [])
                if argument.get("kind") == "method_handle"
                and argument.get("method_handle", {}).get("owner")
                == current_owner
            ]
            if len(implementation_handles) != 1:
                continue
            implementation = implementation_handles[0]
            helper_descriptor = str(
                implementation.get("descriptor", "")
            )
            if not (
                implementation.get("target_kind") == "method"
                and int(implementation.get("reference_kind", -1)) == 7
                and _descriptor_parameter_shapes(helper_descriptor)
                == expected_helper_shapes
                and _descriptor_return_descriptor(helper_descriptor) == "V"
            ):
                continue
            instantiated_types = {
                str(argument.get("descriptor", ""))
                for argument in bootstrap.get("arguments", [])
                if argument.get("kind") == "method_type"
            }
            if "(IIII)V" not in instantiated_types:
                continue
            helpers = [
                helper
                for helper in profile.get("methods", [])
                if helper.get("name") == implementation.get("name")
                and helper.get("descriptor") == helper_descriptor
                and not (int(helper.get("access", 0)) & 0x0008)
                and (int(helper.get("access", 0)) & 0x1000)
            ]
            if len(helpers) != 1:
                continue
            if not _helper_uses_land_slot(
                list(helpers[0].get("instructions", []))
            ):
                continue

            matching_indy.append(
                {
                    "land_slot": land_slot,
                    "descriptor": str(
                        invocation.get("descriptor", "")
                    ),
                    "offset": int(invocation.get("offset", -1)),
                    "helper_name": str(
                        implementation.get("name", "")
                    ),
                    "helper_descriptor": helper_descriptor,
                }
            )

        if len(matching_indy) != 1:
            continue

        source_candidates = []
        for local in local_candidates:
            source_name = local.group("name")
            if source_name == alias_name:
                continue
            raw_after = text[
                method_start + local.end():
                method_start + callback.start()
            ]
            if re.search(
                r"(?<![A-Za-z0-9_$])"
                + re.escape(source_name)
                + r"\s*=",
                raw_after,
            ):
                continue
            source_candidates.append(local)
        if len(source_candidates) != 1:
            continue
        source_name = source_candidates[0].group("name")

        absolute_start = (
            method_start
            + callback_brace
            + land_alias_match.start("alias")
        )
        absolute_end = (
            method_start
            + callback_brace
            + land_alias_match.end("alias")
        )
        edits.append((absolute_start, absolute_end, source_name))
        actions.append(
            {
                "kind": "invokedynamic_callback_direct_int_capture_alias",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": exact_method.get("descriptor"),
                "source_capture_name": source_name,
                "undeclared_capture_alias": alias_name,
                "replacement_count": 1,
                "invokedynamic": matching_indy[0],
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_invokedynamic_direct_int_capture_alias"
                    ),
                    "strategy": (
                        "unique_source_int_assignment_plus_exact_direct_capture_slot"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping direct-int callback edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_intpredicate_parameter_capture_aliases(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore undeclared IntPredicate aliases from exact parameter captures.

    Procyon can emit an anyMatch lambda whose comparison operand names an
    undeclared alias even though LambdaMetafactory captures an int method
    parameter directly. Bind that operand back to the source parameter only
    when source anyMatch order and exact invokedynamic/IntStream.anyMatch
    order agree one-for-one and the bootstrap helper proves stream element
    equals captured parameter.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    bootstrap_methods = list(profile.get("bootstrap_methods", []))
    if not bootstrap_methods:
        return []

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    identifier = r"[A-Za-z_$][A-Za-z0-9_$]*"
    source_predicate_re = re.compile(
        r"\.\s*anyMatch\s*\(\s*"
        r"(?P<lambda>" + identifier + r")\s*->\s*"
        r"(?P<left>" + identifier + r")\s*==\s*"
        r"(?P<right>" + identifier + r")\s*\)"
    )
    expected_bootstrap_descriptors = {
        "metafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodHandle;"
            "Ljava/lang/invoke/MethodType;)"
            "Ljava/lang/invoke/CallSite;"
        ),
        "altMetafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "[Ljava/lang/Object;)"
            "Ljava/lang/invoke/CallSite;"
        ),
    }

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        source_matches = list(source_predicate_re.finditer(method_code))
        if not source_matches:
            continue

        source_params = method_match.group("params")
        parameter_names = _source_parameter_names(source_params)
        parameter_shapes = _source_parameter_shapes(source_params)
        if (
            parameter_names is None
            or parameter_shapes is None
            or len(parameter_names) != len(parameter_shapes)
        ):
            continue
        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )

        exact_candidates: list[dict[str, Any]] = []
        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    source_params,
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            exact_shapes = _descriptor_parameter_shapes(descriptor)
            parameter_slots = _descriptor_parameter_local_slots(
                descriptor,
                is_static=source_static,
            )
            if (
                exact_shapes is None
                or parameter_slots is None
                or len(exact_shapes) != len(parameter_names)
                or len(parameter_slots) != len(parameter_names)
            ):
                continue

            int_parameter_by_slot = {
                slot: parameter_names[index]
                for index, (shape, slot) in enumerate(
                    zip(exact_shapes, parameter_slots)
                )
                if shape == (0, "primitive", "I")
            }
            if not int_parameter_by_slot:
                continue

            instructions = list(exact_method.get("instructions", []))
            exact_predicates: list[dict[str, Any]] = []
            for index in range(1, len(instructions) - 1):
                instruction = instructions[index]
                if not (
                    instruction.get("mnemonic") == "invokedynamic"
                    and instruction.get("name") == "test"
                    and instruction.get("descriptor")
                    == "(I)Ljava/util/function/IntPredicate;"
                ):
                    continue
                capture_load = instructions[index - 1]
                any_match = instructions[index + 1]
                if not (
                    capture_load.get("mnemonic") == "iload"
                    and any_match.get("mnemonic") == "invokeinterface"
                    and any_match.get("owner")
                    == "java/util/stream/IntStream"
                    and any_match.get("name") == "anyMatch"
                    and any_match.get("descriptor")
                    == "(Ljava/util/function/IntPredicate;)Z"
                ):
                    continue
                capture_slot = int(
                    capture_load.get("local_index", -1)
                )
                bootstrap_index = int(
                    instruction.get(
                        "bootstrap_method_attr_index",
                        -1,
                    )
                )
                if not (
                    0 <= bootstrap_index < len(bootstrap_methods)
                ):
                    continue
                bootstrap = bootstrap_methods[bootstrap_index]
                handle = bootstrap.get("bootstrap_method", {})
                bootstrap_name = str(handle.get("name", ""))
                if not (
                    handle.get("owner")
                    == "java/lang/invoke/LambdaMetafactory"
                    and bootstrap_name
                    in expected_bootstrap_descriptors
                    and handle.get("descriptor")
                    == expected_bootstrap_descriptors[bootstrap_name]
                    and handle.get("target_kind") == "method"
                    and int(handle.get("reference_kind", -1)) == 6
                ):
                    continue

                implementation_handles = [
                    argument.get("method_handle", {})
                    for argument in bootstrap.get("arguments", [])
                    if argument.get("kind") == "method_handle"
                    and argument.get("method_handle", {}).get("owner")
                    == current_owner
                ]
                if len(implementation_handles) != 1:
                    continue
                implementation = implementation_handles[0]
                if not (
                    implementation.get("target_kind") == "method"
                    and int(
                        implementation.get("reference_kind", -1)
                    )
                    == 6
                    and implementation.get("descriptor") == "(II)Z"
                ):
                    continue
                instantiated_types = [
                    str(argument.get("descriptor", ""))
                    for argument in bootstrap.get("arguments", [])
                    if argument.get("kind") == "method_type"
                ]
                if instantiated_types.count("(I)Z") != 2:
                    continue

                helpers = [
                    helper
                    for helper in profile.get("methods", [])
                    if helper.get("name") == implementation.get("name")
                    and helper.get("descriptor") == "(II)Z"
                    and int(helper.get("access", 0)) & 0x0008
                    and int(helper.get("access", 0)) & 0x1000
                ]
                if len(helpers) != 1:
                    continue
                helper_instructions = list(
                    helpers[0].get("instructions", [])
                )
                if len(helper_instructions) < 5:
                    continue
                if not (
                    helper_instructions[0].get("mnemonic") == "iload"
                    and int(
                        helper_instructions[0].get(
                            "local_index", -1
                        )
                    )
                    == 1
                    and helper_instructions[1].get("mnemonic")
                    == "iload"
                    and int(
                        helper_instructions[1].get(
                            "local_index", -1
                        )
                    )
                    == 0
                    and helper_instructions[2].get("opcode")
                    in {"0x9f", "0xa0"}
                    and helper_instructions[-1].get("mnemonic")
                    == "ireturn"
                ):
                    continue

                exact_predicates.append(
                    {
                        "offset": int(
                            instruction.get("offset", -1)
                        ),
                        "bootstrap_method_attr_index": (
                            bootstrap_index
                        ),
                        "helper_name": str(
                            implementation.get("name", "")
                        ),
                        "capture_slot": capture_slot,
                        "parameter_name": (
                            int_parameter_by_slot.get(capture_slot)
                        ),
                    }
                )

            if len(exact_predicates) != len(source_matches):
                continue
            exact_candidates.append(
                {
                    "method": exact_method,
                    "predicates": exact_predicates,
                }
            )

        if len(exact_candidates) != 1:
            continue
        proof = exact_candidates[0]

        for source_match, exact_predicate in zip(
            source_matches,
            proof["predicates"],
        ):
            parameter_name = exact_predicate.get("parameter_name")
            if not parameter_name:
                continue

            lambda_name = source_match.group("lambda")
            left_name = source_match.group("left")
            right_name = source_match.group("right")
            if left_name == lambda_name and right_name != lambda_name:
                alias_group = "right"
                alias_name = right_name
            elif right_name == lambda_name and left_name != lambda_name:
                alias_group = "left"
                alias_name = left_name
            else:
                continue

            if alias_name in parameter_names:
                continue
            if alias_name == parameter_name:
                continue
            if _block_has_same_name_local_declaration(
                method_code,
                simple_name=alias_name,
            ):
                continue

            alias_hits = list(
                re.finditer(
                    r"(?<![A-Za-z0-9_$])"
                    + re.escape(alias_name)
                    + r"(?![A-Za-z0-9_$])",
                    method_code,
                )
            )
            if len(alias_hits) != 1:
                continue
            if alias_hits[0].start() != source_match.start(alias_group):
                continue

            edits.append(
                (
                    method_start + source_match.start(alias_group),
                    method_start + source_match.end(alias_group),
                    str(parameter_name),
                )
            )
            actions.append(
                {
                    "kind": "intpredicate_parameter_capture_alias",
                    "source_path": rel,
                    "method_name": method_match.group("name"),
                    "method_descriptor": proof["method"].get(
                        "descriptor"
                    ),
                    "lambda_parameter_name": lambda_name,
                    "undeclared_capture_alias": alias_name,
                    "captured_parameter_name": parameter_name,
                    "capture_slot": exact_predicate["capture_slot"],
                    "invokedynamic_offset": exact_predicate["offset"],
                    "bootstrap_method_attr_index": exact_predicate[
                        "bootstrap_method_attr_index"
                    ],
                    "helper_name": exact_predicate["helper_name"],
                    "replacement_count": 1,
                    "provenance": {
                        "kind": "source_safety",
                        "reason": (
                            "procyon_intpredicate_parameter_capture_alias"
                        ),
                        "strategy": (
                            "ordered_anymatch_plus_exact_parameter_slot_and_equality_helper"
                        ),
                    },
                }
            )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping IntPredicate parameter-capture edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



def _normalize_intpredicate_derived_local_capture_aliases(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore an IntPredicate local capture from an exact loop-derived value.

    This is deliberately separate from parameter-capture recovery. It handles
    one source shape where a primitive enhanced-for element is proven by exact
    bytecode and the captured int is derived directly as element >>> 16 before
    LambdaMetafactory captures it. The missing local name is never guessed;
    the undeclared alias is replaced by that exact source expression.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    bootstrap_methods = list(profile.get("bootstrap_methods", []))
    if not bootstrap_methods:
        return []

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    identifier = r"[A-Za-z_$][A-Za-z0-9_$]*"
    raw_set_decl_re = re.compile(
        r"(?m)(?:^|[;{}]\s*)"
        r"(?:(?:final)\s+)?"
        r"(?P<type>(?:java\.util\.)?(?:Set|LinkedHashSet))\s+"
        r"(?P<name>" + identifier + r")\s*"
        r"(?:=|;)"
    )
    enhanced_for_re = re.compile(
        r"for\s*\(\s*int\s+"
        r"(?P<element>" + identifier + r")\s*:\s*"
        r"(?P<iterable>" + identifier + r")\s*\)\s*\{"
    )
    predicate_re = re.compile(
        r"\.\s*anyMatch\s*\(\s*"
        r"(?P<lambda>" + identifier + r")\s*->\s*"
        r"(?P<left>" + identifier + r")\s*==\s*"
        r"(?P<right>" + identifier + r")\s*\)"
    )
    expected_bootstrap_descriptors = {
        "metafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodHandle;"
            "Ljava/lang/invoke/MethodType;)"
            "Ljava/lang/invoke/CallSite;"
        ),
        "altMetafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "[Ljava/lang/Object;)"
            "Ljava/lang/invoke/CallSite;"
        ),
    }

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        source_params = method_match.group("params")
        parameter_names = _source_parameter_names(source_params)
        if parameter_names is None:
            continue
        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )

        raw_sets = {
            match.group("name")
            for match in raw_set_decl_re.finditer(method_code)
        }
        if not raw_sets:
            continue

        source_candidates: list[dict[str, Any]] = []
        for loop_match in enhanced_for_re.finditer(method_code):
            iterable_name = loop_match.group("iterable")
            if iterable_name not in raw_sets:
                continue
            loop_brace = method_code.find(
                "{", loop_match.start(), loop_match.end()
            )
            if loop_brace < 0:
                continue
            try:
                loop_end = _matching_brace_end(
                    method_code,
                    loop_brace,
                )
            except SourceNormalizationError:
                continue
            loop_code = method_code[loop_brace:loop_end]
            element_name = loop_match.group("element")

            for predicate in predicate_re.finditer(loop_code):
                lambda_name = predicate.group("lambda")
                left_name = predicate.group("left")
                right_name = predicate.group("right")
                if (
                    left_name == lambda_name
                    and right_name != lambda_name
                ):
                    alias_group = "right"
                    alias_name = right_name
                elif (
                    right_name == lambda_name
                    and left_name != lambda_name
                ):
                    alias_group = "left"
                    alias_name = left_name
                else:
                    continue

                if alias_name in parameter_names:
                    continue
                if alias_name in {element_name, iterable_name}:
                    continue
                if _block_has_same_name_local_declaration(
                    method_code,
                    simple_name=alias_name,
                ):
                    continue

                alias_hits = list(
                    re.finditer(
                        r"(?<![A-Za-z0-9_$])"
                        + re.escape(alias_name)
                        + r"(?![A-Za-z0-9_$])",
                        method_code,
                    )
                )
                alias_start_in_method = (
                    loop_brace + predicate.start(alias_group)
                )
                if (
                    len(alias_hits) != 1
                    or alias_hits[0].start() != alias_start_in_method
                ):
                    continue

                source_candidates.append(
                    {
                        "element_name": element_name,
                        "iterable_name": iterable_name,
                        "lambda_name": lambda_name,
                        "alias_name": alias_name,
                        "alias_start": (
                            method_start + alias_start_in_method
                        ),
                        "alias_end": (
                            method_start
                            + loop_brace
                            + predicate.end(alias_group)
                        ),
                    }
                )

        if len(source_candidates) != 1:
            continue
        source_candidate = source_candidates[0]

        exact_candidates: list[dict[str, Any]] = []
        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    source_params,
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            parameter_slots = _descriptor_parameter_local_slots(
                descriptor,
                is_static=source_static,
            )
            if parameter_slots is None:
                continue
            parameter_slot_set = set(parameter_slots)

            instructions = list(exact_method.get("instructions", []))
            set_iterator_calls = [
                row
                for row in instructions
                if (
                    row.get("mnemonic") == "invokeinterface"
                    and row.get("owner") == "java/util/Set"
                    and row.get("name") == "iterator"
                    and row.get("descriptor")
                    == "()Ljava/util/Iterator;"
                )
            ]
            if len(set_iterator_calls) != 1:
                continue

            derived_flows: list[dict[str, Any]] = []
            for index in range(0, len(instructions) - 7):
                rows = instructions[index:index + 8]
                if not (
                    rows[0].get("mnemonic") == "invokeinterface"
                    and rows[0].get("owner")
                    == "java/util/Iterator"
                    and rows[0].get("name") == "next"
                    and rows[0].get("descriptor")
                    == "()Ljava/lang/Object;"
                    and rows[1].get("mnemonic") == "checkcast"
                    and rows[1].get("type")
                    == "java/lang/Integer"
                    and rows[2].get("mnemonic")
                    in {"invokevirtual", "invokeinterface"}
                    and rows[2].get("owner")
                    == "java/lang/Integer"
                    and rows[2].get("name") == "intValue"
                    and rows[2].get("descriptor") == "()I"
                    and rows[3].get("mnemonic") == "istore"
                    and rows[4].get("mnemonic") == "iload"
                    and rows[4].get("local_index")
                    == rows[3].get("local_index")
                    and rows[5].get("mnemonic") == "bipush"
                    and rows[5].get("int_constant") == 16
                    and rows[6].get("mnemonic") == "iushr"
                    and rows[7].get("mnemonic") == "istore"
                ):
                    continue

                element_slot = int(rows[3].get("local_index", -1))
                capture_slot = int(rows[7].get("local_index", -1))
                if (
                    element_slot < 0
                    or capture_slot < 0
                    or capture_slot == element_slot
                    or capture_slot in parameter_slot_set
                ):
                    continue
                derived_flows.append(
                    {
                        "element_slot": element_slot,
                        "capture_slot": capture_slot,
                        "iterator_next_offset": int(
                            rows[0].get("offset", -1)
                        ),
                        "derivation_start_offset": int(
                            rows[4].get("offset", -1)
                        ),
                        "derivation_store_offset": int(
                            rows[7].get("offset", -1)
                        ),
                    }
                )

            if len(derived_flows) != 1:
                continue
            derived_flow = derived_flows[0]
            capture_slot = derived_flow["capture_slot"]

            exact_predicates: list[dict[str, Any]] = []
            for index in range(0, len(instructions) - 2):
                capture_load = instructions[index]
                instruction = instructions[index + 1]
                any_match = instructions[index + 2]
                if not (
                    capture_load.get("mnemonic") == "iload"
                    and int(
                        capture_load.get("local_index", -1)
                    )
                    == capture_slot
                    and instruction.get("mnemonic")
                    == "invokedynamic"
                    and instruction.get("name") == "test"
                    and instruction.get("descriptor")
                    == "(I)Ljava/util/function/IntPredicate;"
                    and any_match.get("mnemonic")
                    == "invokeinterface"
                    and any_match.get("owner")
                    == "java/util/stream/IntStream"
                    and any_match.get("name") == "anyMatch"
                    and any_match.get("descriptor")
                    == "(Ljava/util/function/IntPredicate;)Z"
                    and int(
                        capture_load.get("offset", -1)
                    )
                    > derived_flow["derivation_store_offset"]
                ):
                    continue

                overwritten = any(
                    row.get("mnemonic") == "istore"
                    and int(row.get("local_index", -1))
                    == capture_slot
                    and derived_flow["derivation_store_offset"]
                    < int(row.get("offset", -1))
                    < int(capture_load.get("offset", -1))
                    for row in instructions
                )
                if overwritten:
                    continue

                bootstrap_index = int(
                    instruction.get(
                        "bootstrap_method_attr_index",
                        -1,
                    )
                )
                if not (
                    0 <= bootstrap_index < len(bootstrap_methods)
                ):
                    continue
                bootstrap = bootstrap_methods[bootstrap_index]
                handle = bootstrap.get("bootstrap_method", {})
                bootstrap_name = str(handle.get("name", ""))
                if not (
                    handle.get("owner")
                    == "java/lang/invoke/LambdaMetafactory"
                    and bootstrap_name
                    in expected_bootstrap_descriptors
                    and handle.get("descriptor")
                    == expected_bootstrap_descriptors[bootstrap_name]
                    and handle.get("target_kind") == "method"
                    and int(handle.get("reference_kind", -1)) == 6
                ):
                    continue

                implementation_handles = [
                    argument.get("method_handle", {})
                    for argument in bootstrap.get("arguments", [])
                    if (
                        argument.get("kind") == "method_handle"
                        and argument.get(
                            "method_handle", {}
                        ).get("owner") == current_owner
                    )
                ]
                if len(implementation_handles) != 1:
                    continue
                implementation = implementation_handles[0]
                if not (
                    implementation.get("target_kind") == "method"
                    and int(
                        implementation.get("reference_kind", -1)
                    )
                    == 6
                    and implementation.get("descriptor") == "(II)Z"
                ):
                    continue

                method_types = [
                    str(argument.get("descriptor", ""))
                    for argument in bootstrap.get("arguments", [])
                    if argument.get("kind") == "method_type"
                ]
                if method_types.count("(I)Z") != 2:
                    continue

                helpers = [
                    helper
                    for helper in profile.get("methods", [])
                    if (
                        helper.get("name")
                        == implementation.get("name")
                        and helper.get("descriptor") == "(II)Z"
                        and int(helper.get("access", 0)) & 0x0008
                        and int(helper.get("access", 0)) & 0x1000
                    )
                ]
                if len(helpers) != 1:
                    continue
                helper_instructions = list(
                    helpers[0].get("instructions", [])
                )
                if len(helper_instructions) < 5:
                    continue
                if not (
                    helper_instructions[0].get("mnemonic") == "iload"
                    and int(
                        helper_instructions[0].get(
                            "local_index", -1
                        )
                    )
                    == 1
                    and helper_instructions[1].get("mnemonic")
                    == "iload"
                    and int(
                        helper_instructions[1].get(
                            "local_index", -1
                        )
                    )
                    == 0
                    and helper_instructions[2].get("opcode")
                    in {"0x9f", "0xa0"}
                    and helper_instructions[-1].get("mnemonic")
                    == "ireturn"
                ):
                    continue

                exact_predicates.append(
                    {
                        "capture_load_offset": int(
                            capture_load.get("offset", -1)
                        ),
                        "invokedynamic_offset": int(
                            instruction.get("offset", -1)
                        ),
                        "bootstrap_method_attr_index": (
                            bootstrap_index
                        ),
                        "helper_name": str(
                            implementation.get("name", "")
                        ),
                    }
                )

            if len(exact_predicates) != 1:
                continue

            exact_candidates.append(
                {
                    "method": exact_method,
                    "flow": derived_flow,
                    "predicate": exact_predicates[0],
                }
            )

        if len(exact_candidates) != 1:
            continue
        proof = exact_candidates[0]

        replacement = (
            "("
            + source_candidate["element_name"]
            + " >>> 16)"
        )
        edits.append(
            (
                int(source_candidate["alias_start"]),
                int(source_candidate["alias_end"]),
                replacement,
            )
        )
        actions.append(
            {
                "kind": (
                    "intpredicate_derived_local_capture_alias"
                ),
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"].get(
                    "descriptor"
                ),
                "lambda_parameter_name": source_candidate[
                    "lambda_name"
                ],
                "undeclared_capture_alias": source_candidate[
                    "alias_name"
                ],
                "loop_element_name": source_candidate[
                    "element_name"
                ],
                "loop_iterable_name": source_candidate[
                    "iterable_name"
                ],
                "element_slot": proof["flow"]["element_slot"],
                "capture_slot": proof["flow"]["capture_slot"],
                "iterator_next_offset": proof["flow"][
                    "iterator_next_offset"
                ],
                "derivation_start_offset": proof["flow"][
                    "derivation_start_offset"
                ],
                "derivation_store_offset": proof["flow"][
                    "derivation_store_offset"
                ],
                "invokedynamic_offset": proof["predicate"][
                    "invokedynamic_offset"
                ],
                "bootstrap_method_attr_index": proof["predicate"][
                    "bootstrap_method_attr_index"
                ],
                "helper_name": proof["predicate"]["helper_name"],
                "derived_expression": replacement,
                "replacement_count": 1,
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_intpredicate_derived_local_capture_alias"
                    ),
                    "strategy": (
                        "unique_raw_set_enhanced_for_plus_exact_integer_"
                        "iterator_unbox_plus_unsigned_shift16_capture_plus_"
                        "lambda_metafactory_equality_helper"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping derived IntPredicate edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_invokedynamic_lambda_outer_capture_collisions(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Repair lambda-parameter collisions with exact captured outer params.

    Procyon can reuse an outer method parameter as the source lambda
    parameter while inventing a separate undeclared name for the captured
    value.  Repair both names atomically only when the exact invokedynamic
    bootstrap resolves to a same-class static helper whose instruction order
    proves lambda-argument receiver -> captured-argument boolean invocation.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    bootstrap_methods = list(
        profile.get("bootstrap_methods", [])
    )
    if not bootstrap_methods:
        return []

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(
                whole_code,
                brace_start,
            )
        except SourceNormalizationError:
            continue

        source_params = method_match.group("params")
        parameter_names = _source_parameter_names(source_params)
        parameter_shapes = _source_parameter_shapes(source_params)
        if (
            parameter_names is None
            or parameter_shapes is None
            or not parameter_names
            or len(parameter_names) != len(parameter_shapes)
        ):
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        exact_candidates: list[dict[str, Any]] = []
        for exact_method in profile.get("methods", []):
            if (
                exact_method.get("name")
                != method_match.group("name")
            ):
                continue
            descriptor = str(
                exact_method.get("descriptor", "")
            )
            if (
                _source_parameters_match_descriptor(
                    source_params,
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue
            exact_candidates.append(exact_method)
        if len(exact_candidates) != 1:
            continue
        exact_method = exact_candidates[0]
        exact_shapes = _descriptor_parameter_shapes(
            str(exact_method.get("descriptor", ""))
        )
        if (
            exact_shapes is None
            or len(exact_shapes) != len(parameter_names)
        ):
            continue
        exact_parameter_slots = _descriptor_parameter_local_slots(
            str(exact_method.get("descriptor", "")),
            is_static=source_static,
        )
        if (
            exact_parameter_slots is None
            or len(exact_parameter_slots) != len(parameter_names)
        ):
            continue
        exact_instructions = list(
            exact_method.get("instructions", [])
        )
        instruction_index_by_offset = {
            int(instruction.get("offset", -1)): index
            for index, instruction in enumerate(exact_instructions)
            if int(instruction.get("offset", -1)) >= 0
        }

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        method_text = text[method_start:body_end]
        method_edits: list[tuple[int, int, str]] = []
        method_actions: list[dict[str, Any]] = []

        for param_index, outer_name in enumerate(
            parameter_names
        ):
            outer_shape = exact_shapes[param_index]
            if not (
                outer_shape[0] == 0
                and outer_shape[1] == "ref"
            ):
                continue
            outer_owner = outer_shape[2]
            outer_slot = exact_parameter_slots[param_index]

            lambda_re = re.compile(
                r"(?P<lambda_paren>\(\s*)?"
                r"(?P<lambda>"
                + re.escape(outer_name)
                + r")"
                r"(?(lambda_paren)\s*\))"
                r"\s*->\s*"
                r"(?P<receiver>"
                + re.escape(outer_name)
                + r")\s*\.\s*"
                r"(?P<member>[A-Za-z_$][A-Za-z0-9_$]*)"
                r"\s*\(\s*"
                r"(?P<alias>[A-Za-z_$][A-Za-z0-9_$]*)"
                r"\s*\)"
            )
            lambda_matches = list(
                lambda_re.finditer(method_code)
            )
            if len(lambda_matches) != 1:
                continue
            source_match = lambda_matches[0]
            alias_name = source_match.group("alias")
            member_name = source_match.group("member")
            if alias_name == outer_name:
                continue

            alias_hits = list(
                re.finditer(
                    r"(?<![A-Za-z0-9_$])"
                    + re.escape(alias_name)
                    + r"(?![A-Za-z0-9_$])",
                    method_code,
                )
            )
            if len(alias_hits) != 1:
                continue
            if not (
                alias_hits[0].start()
                == source_match.start("alias")
            ):
                continue
            declaration_re = re.compile(
                r"\b(?:final\s+)?"
                r"[A-Za-z_$][A-Za-z0-9_$.<>\[\]?]*\s+"
                + re.escape(alias_name)
                + r"\b"
            )
            if declaration_re.search(method_code):
                continue

            matching_indy = []
            for invocation in exact_method.get(
                "method_invocations", []
            ):
                if invocation.get("operation") != "invokedynamic":
                    continue
                indy_descriptor = str(
                    invocation.get("descriptor", "")
                )
                indy_shapes = _descriptor_parameter_shapes(
                    indy_descriptor
                )
                return_descriptor = _descriptor_return_descriptor(
                    indy_descriptor
                )
                if not (
                    indy_shapes is not None
                    and len(indy_shapes) == 1
                    and indy_shapes[0] == outer_shape
                    and return_descriptor is not None
                    and return_descriptor.startswith("L")
                    and return_descriptor.endswith(";")
                ):
                    continue
                invocation_offset = int(
                    invocation.get("offset", -1)
                )
                instruction_index = instruction_index_by_offset.get(
                    invocation_offset
                )
                if (
                    instruction_index is None
                    or instruction_index <= 0
                ):
                    continue
                capture_load = exact_instructions[
                    instruction_index - 1
                ]
                if not (
                    capture_load.get("mnemonic") == "aload"
                    and int(
                        capture_load.get("local_index", -1)
                    )
                    == outer_slot
                ):
                    continue
                bootstrap_index = int(
                    invocation.get(
                        "bootstrap_method_attr_index",
                        -1,
                    )
                )
                if not (
                    0 <= bootstrap_index < len(bootstrap_methods)
                ):
                    continue
                bootstrap = bootstrap_methods[bootstrap_index]
                bootstrap_method = bootstrap.get(
                    "bootstrap_method", {}
                )
                bootstrap_name = str(
                    bootstrap_method.get("name", "")
                )
                bootstrap_descriptor = str(
                    bootstrap_method.get("descriptor", "")
                )
                expected_bootstrap_descriptors = {
                    "metafactory": (
                        "(Ljava/lang/invoke/MethodHandles$Lookup;"
                        "Ljava/lang/String;"
                        "Ljava/lang/invoke/MethodType;"
                        "Ljava/lang/invoke/MethodType;"
                        "Ljava/lang/invoke/MethodHandle;"
                        "Ljava/lang/invoke/MethodType;)"
                        "Ljava/lang/invoke/CallSite;"
                    ),
                    "altMetafactory": (
                        "(Ljava/lang/invoke/MethodHandles$Lookup;"
                        "Ljava/lang/String;"
                        "Ljava/lang/invoke/MethodType;"
                        "[Ljava/lang/Object;)"
                        "Ljava/lang/invoke/CallSite;"
                    ),
                }
                if not (
                    bootstrap_method.get("owner")
                    == "java/lang/invoke/LambdaMetafactory"
                    and bootstrap_name in expected_bootstrap_descriptors
                    and bootstrap_descriptor
                    == expected_bootstrap_descriptors[bootstrap_name]
                    and bootstrap_method.get("target_kind") == "method"
                    and int(
                        bootstrap_method.get("reference_kind", -1)
                    )
                    == 6
                ):
                    continue

                implementation_handles = [
                    arg.get("method_handle", {})
                    for arg in bootstrap.get("arguments", [])
                    if arg.get("kind") == "method_handle"
                    and arg.get("method_handle", {}).get("owner")
                    == current_owner
                ]
                if len(implementation_handles) != 1:
                    continue
                implementation = implementation_handles[0]
                helper_descriptor = str(
                    implementation.get("descriptor", "")
                )
                helper_shapes = _descriptor_parameter_shapes(
                    helper_descriptor
                )
                if not (
                    implementation.get("target_kind")
                    == "method"
                    and int(
                        implementation.get(
                            "reference_kind", -1
                        )
                    )
                    == 6
                    and helper_shapes is not None
                    and helper_shapes
                    == [outer_shape, outer_shape]
                    and _descriptor_return_descriptor(
                        helper_descriptor
                    )
                    == "Z"
                ):
                    continue

                instantiated_types = {
                    str(arg.get("descriptor", ""))
                    for arg in bootstrap.get(
                        "arguments", []
                    )
                    if arg.get("kind") == "method_type"
                }
                instantiated_descriptor = (
                    "(L" + outer_owner + ";)Z"
                )
                if instantiated_descriptor not in instantiated_types:
                    continue

                helpers = [
                    helper
                    for helper in profile.get("methods", [])
                    if (
                        helper.get("name")
                        == implementation.get("name")
                        and helper.get("descriptor")
                        == helper_descriptor
                        and int(helper.get("access", 0)) & 0x0008
                    )
                ]
                if len(helpers) != 1:
                    continue
                helper = helpers[0]
                instructions = list(
                    helper.get("instructions", [])
                )
                if len(instructions) != 4:
                    continue
                if not (
                    instructions[0].get("mnemonic") == "aload"
                    and int(
                        instructions[0].get(
                            "local_index", -1
                        )
                    )
                    == 1
                    and instructions[1].get("mnemonic") == "aload"
                    and int(
                        instructions[1].get(
                            "local_index", -1
                        )
                    )
                    == 0
                    and instructions[2].get("mnemonic")
                    in {"invokevirtual", "invokeinterface"}
                    and instructions[2].get("owner")
                    == outer_owner
                    and instructions[2].get("name")
                    == member_name
                    and instructions[2].get("descriptor")
                    == "(L" + outer_owner + ";)Z"
                    and instructions[3].get("mnemonic")
                    == "ireturn"
                ):
                    continue

                matching_indy.append(
                    {
                        "descriptor": indy_descriptor,
                        "offset": int(
                            invocation.get("offset", -1)
                        ),
                        "bootstrap_method_attr_index": (
                            bootstrap_index
                        ),
                        "helper_name": str(
                            implementation.get("name", "")
                        ),
                        "helper_descriptor": helper_descriptor,
                    }
                )

            if len(matching_indy) != 1:
                continue

            seed = (
                rel
                + "\0"
                + str(exact_method.get("descriptor", ""))
                + "\0"
                + outer_name
                + "\0"
                + method_text[
                    source_match.start():source_match.end()
                ]
            )
            fallback_name = (
                "recoveredLambdaArg_"
                + hashlib.sha256(
                    seed.encode("utf-8")
                ).hexdigest()[:12]
            )
            if re.search(
                r"(?<![A-Za-z0-9_$])"
                + re.escape(fallback_name)
                + r"(?![A-Za-z0-9_$])",
                method_code,
            ):
                continue

            method_edits.append(
                (
                    method_start
                    + source_match.start("lambda"),
                    method_start
                    + source_match.end("lambda"),
                    fallback_name,
                )
            )
            method_edits.append(
                (
                    method_start
                    + source_match.start("receiver"),
                    method_start
                    + source_match.end("receiver"),
                    fallback_name,
                )
            )
            method_edits.append(
                (
                    method_start
                    + source_match.start("alias"),
                    method_start
                    + source_match.end("alias"),
                    outer_name,
                )
            )
            method_actions.append(
                {
                    "kind": (
                        "invokedynamic_lambda_outer_capture_collision"
                    ),
                    "source_path": rel,
                    "method_name": method_match.group("name"),
                    "method_descriptor": exact_method.get(
                        "descriptor"
                    ),
                    "outer_parameter_name": outer_name,
                    "outer_parameter_slot": outer_slot,
                    "undeclared_capture_alias": alias_name,
                    "source_lambda_parameter_name": outer_name,
                    "replacement_lambda_parameter_name": (
                        fallback_name
                    ),
                    "member_name": member_name,
                    "invokedynamic": matching_indy[0],
                    "replacement_count": 3,
                    "provenance": {
                        "kind": "source_safety",
                        "reason": (
                            "procyon_lambda_parameter_collides_with_captured_outer_parameter"
                        ),
                        "strategy": (
                            "exact_bootstrap_helper_receiver_capture_order"
                        ),
                    },
                }
            )

        if not method_edits:
            continue
        method_edits.sort(key=lambda row: row[0])
        if any(
            left[1] > right[0]
            for left, right in zip(
                method_edits,
                method_edits[1:],
            )
        ):
            continue
        edits.extend(method_edits)
        actions.extend(method_actions)

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping lambda capture-collision edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _signature_list_return_element_owner(
    signature: str,
) -> str | None:
    match = re.search(
        r"\)Ljava/util/List<L(?P<owner>[^;<>]+);>;$",
        signature,
    )
    if match is None:
        return None
    owner = match.group("owner")
    if not owner or not all(
        _is_java_identifier(part) for part in owner.split("/")
    ):
        return None
    return owner


def _normalize_raw_iterable_map_entry_lambda_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Remove raw Iterable casts that erase exact Map.Entry lambda typing.

    The repair is deliberately source-shape and bytecode constrained.  A raw
    cast is removed only when the exact receiver field is parameterized, its
    zero-argument getter returns a container of Map.Entry<K,V> from the same
    type variables, the enclosing static filter call is itself generic over
    Iterable<T>, and the exact LambdaMetafactory helper receives the same
    erased Map.Entry element after all captured parameters.  Source method
    correlation tolerates marker parameter annotations because they are not
    part of a JVM method descriptor; every exact receiver/filter/lambda
    multiplicity gate remains unchanged.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        profile = profile_class_field_accesses(
            readable_zip.read(class_entry)
        )
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    bootstrap_methods = list(profile.get("bootstrap_methods", []))
    if not bootstrap_methods:
        return []

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    call_re = re.compile(
        r"(?P<filter_owner>[A-Za-z_$][A-Za-z0-9_$.]*)"
        r"\s*\.\s*"
        r"(?P<filter_method>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\(\s*"
        r"(?P<cast>\(\s*(?:java\.lang\.)?Iterable\s*\)\s*)"
        r"(?P<receiver>(?:this\s*\.\s*)?"
        r"(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)\s*\.\s*"
        r"(?P<getter>[A-Za-z_$][A-Za-z0-9_$]*)\s*\(\s*\))"
        r"\s*,\s*"
        r"(?P<lambda>[A-Za-z_$][A-Za-z0-9_$]*)\s*->"
    )

    owner_cache: dict[str, dict[str, Any]] = {
        current_owner: profile,
    }

    def owner_profile(owner: str) -> dict[str, Any] | None:
        cached = owner_cache.get(owner)
        if cached is not None:
            return cached
        try:
            parsed = profile_class_field_accesses(
                readable_zip.read(owner + ".class")
            )
        except (KeyError, BytecodeProfileError):
            return None
        if str(parsed.get("internal_name", "")) != owner:
            return None
        owner_cache[owner] = parsed
        return parsed

    def generic_entry_getter(
        *,
        field_name: str,
        getter_name: str,
    ) -> dict[str, Any] | None:
        fields = [
            field
            for field in profile.get("fields", [])
            if (
                str(field.get("name", "")) == field_name
                and str(field.get("descriptor", "")).startswith("L")
                and str(field.get("descriptor", "")).endswith(";")
                and isinstance(field.get("signature"), str)
            )
        ]
        if len(fields) != 1:
            return None
        field = fields[0]
        descriptor = str(field["descriptor"])
        receiver_owner = descriptor[1:-1]
        field_signature = str(field.get("signature") or "")
        if not (
            field_signature.startswith("L" + receiver_owner + "<")
            and field_signature.endswith(">;")
        ):
            return None

        receiver_profile = owner_profile(receiver_owner)
        if receiver_profile is None:
            return None
        getters = [
            method
            for method in receiver_profile.get("methods", [])
            if (
                str(method.get("name", "")) == getter_name
                and _descriptor_parameter_count(
                    str(method.get("descriptor", ""))
                )
                == 0
                and isinstance(method.get("signature"), str)
            )
        ]
        if len(getters) != 1:
            return None
        getter = getters[0]
        getter_descriptor = str(getter.get("descriptor", ""))
        getter_return = _descriptor_return_descriptor(getter_descriptor)
        if not (
            getter_return
            and getter_return.startswith("L")
            and getter_return.endswith(";")
        ):
            return None

        getter_signature = str(getter.get("signature") or "")
        signature_match = re.fullmatch(
            r"\(\)L(?P<container>[^;<]+)"
            r"<Ljava/util/Map\$Entry<"
            r"T(?P<key>[A-Za-z_$][A-Za-z0-9_$]*);"
            r"T(?P<value>[A-Za-z_$][A-Za-z0-9_$]*);"
            r">;>;",
            getter_signature,
        )
        if signature_match is None:
            return None
        if signature_match.group("key") == signature_match.group("value"):
            return None

        container_owner = getter_return[1:-1]
        if signature_match.group("container") != container_owner:
            return None

        return {
            "field_name": field_name,
            "field_descriptor": descriptor,
            "field_signature": field_signature,
            "receiver_owner": receiver_owner,
            "getter_name": getter_name,
            "getter_descriptor": getter_descriptor,
            "getter_signature": getter_signature,
            "container_owner": container_owner,
            "entry_key_type_variable": signature_match.group("key"),
            "entry_value_type_variable": signature_match.group("value"),
        }

    def source_parameters_match_descriptor(
        params: str,
        descriptor: str,
    ) -> bool | None:
        direct = _source_parameters_match_descriptor(
            params,
            descriptor,
            current_package=current_package,
        )
        if direct is True:
            return True

        marker_annotation = re.compile(
            r"(?<![A-Za-z0-9_$])@"
            r"(?:[A-Za-z_$][A-Za-z0-9_$]*\.)*"
            r"[A-Za-z_$][A-Za-z0-9_$]*\s*"
        )
        stripped = marker_annotation.sub("", params)
        if stripped == params:
            return direct
        return _source_parameters_match_descriptor(
            stripped,
            descriptor,
            current_package=current_package,
        )

    def source_owner_matches(
        source_owner: str,
        exact_owner: str,
    ) -> bool:
        if "." in source_owner:
            return source_owner.replace(".", "/") == exact_owner
        return exact_owner.rsplit("/", 1)[-1] == source_owner

    def generic_filter_method(
        *,
        owner: str,
        name: str,
        descriptor: str,
    ) -> dict[str, Any] | None:
        shapes = _descriptor_parameter_shapes(descriptor)
        if not (
            shapes is not None
            and len(shapes) == 2
            and shapes[0] == (0, "ref", "java/lang/Iterable")
            and shapes[1][0] == 0
            and shapes[1][1] == "ref"
            and _descriptor_return_descriptor(descriptor)
            == "Ljava/lang/Iterable;"
        ):
            return None

        parsed = owner_profile(owner)
        if parsed is None:
            return None
        methods = [
            method
            for method in parsed.get("methods", [])
            if (
                method.get("name") == name
                and method.get("descriptor") == descriptor
                and int(method.get("access", 0)) & 0x0008
                and isinstance(method.get("signature"), str)
            )
        ]
        if len(methods) != 1:
            return None

        signature = str(methods[0].get("signature") or "")
        type_variable = re.match(
            r"^<(?P<name>[A-Za-z_$][A-Za-z0-9_$]*):",
            signature,
        )
        if type_variable is None:
            return None
        token = "T" + type_variable.group("name") + ";"
        iterable_token = "Ljava/lang/Iterable<" + token + ">;"
        if signature.count(iterable_token) != 2:
            return None
        if signature.count(token) < 3:
            return None

        return {
            "owner": owner,
            "name": name,
            "descriptor": descriptor,
            "signature": signature,
            "functional_owner": str(shapes[1][2]),
            "type_variable": type_variable.group("name"),
        }

    def entry_lambda_bootstraps(
        exact_method: dict[str, Any],
        *,
        functional_owner: str,
    ) -> list[dict[str, Any]]:
        out: list[dict[str, Any]] = []
        expected_functional_return = "L" + functional_owner + ";"
        for invocation in exact_method.get("method_invocations", []):
            if invocation.get("operation") != "invokedynamic":
                continue
            invocation_descriptor = str(
                invocation.get("descriptor", "")
            )
            if (
                _descriptor_return_descriptor(invocation_descriptor)
                != expected_functional_return
            ):
                continue
            captured_shapes = _descriptor_parameter_shapes(
                invocation_descriptor
            )
            if captured_shapes is None:
                continue

            bootstrap_index = int(
                invocation.get("bootstrap_method_attr_index", -1)
            )
            if not (0 <= bootstrap_index < len(bootstrap_methods)):
                continue
            bootstrap = bootstrap_methods[bootstrap_index]
            bootstrap_method = bootstrap.get("bootstrap_method", {})
            if not (
                bootstrap_method.get("owner")
                == "java/lang/invoke/LambdaMetafactory"
                and bootstrap_method.get("name")
                in {"metafactory", "altMetafactory"}
            ):
                continue

            method_types = [
                str(argument.get("descriptor", ""))
                for argument in bootstrap.get("arguments", [])
                if argument.get("kind") == "method_type"
            ]
            if (
                method_types.count("(Ljava/lang/Object;)Z") != 1
                or method_types.count("(Ljava/util/Map$Entry;)Z") != 1
            ):
                continue

            implementations = [
                argument.get("method_handle", {})
                for argument in bootstrap.get("arguments", [])
                if (
                    argument.get("kind") == "method_handle"
                    and argument.get("method_handle", {}).get("owner")
                    == current_owner
                    and argument.get("method_handle", {}).get("target_kind")
                    == "method"
                    and int(
                        argument.get("method_handle", {}).get(
                            "reference_kind", -1
                        )
                    )
                    == 6
                )
            ]
            if len(implementations) != 1:
                continue
            implementation = implementations[0]
            helper_descriptor = str(
                implementation.get("descriptor", "")
            )
            helper_shapes = _descriptor_parameter_shapes(
                helper_descriptor
            )
            if not (
                helper_shapes is not None
                and len(helper_shapes) == len(captured_shapes) + 1
                and helper_shapes[:-1] == captured_shapes
                and helper_shapes[-1]
                == (0, "ref", "java/util/Map$Entry")
                and _descriptor_return_descriptor(
                    helper_descriptor
                )
                == "Z"
            ):
                continue

            helpers = [
                helper
                for helper in profile.get("methods", [])
                if (
                    helper.get("name")
                    == implementation.get("name")
                    and helper.get("descriptor")
                    == helper_descriptor
                    and int(helper.get("access", 0)) & 0x0008
                    and int(helper.get("access", 0)) & 0x1000
                )
            ]
            if len(helpers) != 1:
                continue
            helper = helpers[0]
            get_value_calls = [
                row
                for row in helper.get("method_invocations", [])
                if (
                    row.get("operation")
                    in {"invokeinterface", "invokevirtual"}
                    and row.get("owner") == "java/util/Map$Entry"
                    and row.get("name") == "getValue"
                    and row.get("descriptor")
                    == "()Ljava/lang/Object;"
                )
            ]
            if len(get_value_calls) != 1:
                continue

            out.append(
                {
                    "offset": int(invocation.get("offset", -1)),
                    "descriptor": invocation_descriptor,
                    "captured_parameter_shapes": captured_shapes,
                    "bootstrap_method_attr_index": bootstrap_index,
                    "helper_name": str(
                        implementation.get("name", "")
                    ),
                    "helper_descriptor": helper_descriptor,
                    "map_entry_getvalue_count": 1,
                }
            )
        return out

    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(
                whole_code,
                brace_start,
            )
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        structural_calls = list(call_re.finditer(method_code))
        if not structural_calls:
            continue

        source_rows: list[dict[str, Any]] = []
        receiver_proofs: dict[
            tuple[str, str],
            dict[str, Any],
        ] = {}
        receiver_counts: dict[tuple[str, str], int] = {}
        filter_counts: dict[tuple[str, str], int] = {}
        source_ok = True

        for source_call in structural_calls:
            statement_end = method_code.find(";", source_call.end())
            if statement_end < 0:
                source_ok = False
                break
            alias = source_call.group("lambda")
            get_value_re = re.compile(
                r"(?<![A-Za-z0-9_$])"
                + re.escape(alias)
                + r"\s*\.\s*getValue\s*\("
            )
            lambda_body = method_code[
                source_call.end():statement_end
            ]
            if len(get_value_re.findall(lambda_body)) != 1:
                source_ok = False
                break

            receiver_key = (
                source_call.group("field"),
                source_call.group("getter"),
            )
            receiver_proof = receiver_proofs.get(receiver_key)
            if receiver_proof is None:
                receiver_proof = generic_entry_getter(
                    field_name=receiver_key[0],
                    getter_name=receiver_key[1],
                )
                if receiver_proof is None:
                    source_ok = False
                    break
                receiver_proofs[receiver_key] = receiver_proof
            receiver_counts[receiver_key] = (
                receiver_counts.get(receiver_key, 0) + 1
            )

            filter_key = (
                source_call.group("filter_owner"),
                source_call.group("filter_method"),
            )
            filter_counts[filter_key] = (
                filter_counts.get(filter_key, 0) + 1
            )

            source_rows.append(
                {
                    "receiver_key": receiver_key,
                    "filter_key": filter_key,
                    "lambda_parameter": alias,
                    "cast_start": (
                        method_start + source_call.start("cast")
                    ),
                    "cast_end": (
                        method_start + source_call.end("cast")
                    ),
                }
            )

        if not source_ok or not source_rows:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[
                    method_match.start():brace_start
                ],
            )
        )
        exact_candidates: list[dict[str, Any]] = []

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            exact_descriptor = str(
                exact_method.get("descriptor", "")
            )
            if (
                source_parameters_match_descriptor(
                    method_match.group("params"),
                    exact_descriptor,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            exact_return = _descriptor_return_descriptor(
                exact_descriptor
            )
            source_return = method_match.group("return").strip()
            if source_return == "void":
                if exact_return != "V":
                    continue
            elif exact_return is None or (
                _source_parameters_match_descriptor(
                    source_return + " recoveredReturn",
                    "(" + exact_return + ")V",
                    current_package=current_package,
                )
                is not True
            ):
                continue

            instructions = list(
                exact_method.get("instructions", [])
            )
            flow_counts: dict[tuple[str, str], int] = {
                key: 0 for key in receiver_counts
            }
            flow_offsets: dict[
                tuple[str, str],
                list[dict[str, int]],
            ] = {
                key: [] for key in receiver_counts
            }
            for index in range(len(instructions) - 1):
                field_access = instructions[index]
                getter_call = instructions[index + 1]
                for key, receiver_proof in receiver_proofs.items():
                    if not (
                        field_access.get("mnemonic")
                        in {"getfield", "getstatic"}
                        and field_access.get("owner")
                        == current_owner
                        and field_access.get("name")
                        == receiver_proof["field_name"]
                        and field_access.get("descriptor")
                        == receiver_proof["field_descriptor"]
                        and getter_call.get("mnemonic")
                        in {"invokevirtual", "invokeinterface"}
                        and getter_call.get("owner")
                        == receiver_proof["receiver_owner"]
                        and getter_call.get("name")
                        == receiver_proof["getter_name"]
                        and getter_call.get("descriptor")
                        == receiver_proof["getter_descriptor"]
                    ):
                        continue
                    flow_counts[key] += 1
                    flow_offsets[key].append(
                        {
                            "field_offset": int(
                                field_access.get("offset", -1)
                            ),
                            "getter_offset": int(
                                getter_call.get("offset", -1)
                            ),
                        }
                    )

            if any(
                flow_counts.get(key, 0) != count
                for key, count in receiver_counts.items()
            ):
                continue

            filter_proofs: dict[
                tuple[str, str],
                list[dict[str, Any]],
            ] = {}
            filter_ok = True
            for filter_key, source_count in filter_counts.items():
                source_owner, source_name = filter_key
                matching: list[dict[str, Any]] = []
                for invocation in exact_method.get(
                    "method_invocations", []
                ):
                    if not (
                        invocation.get("operation") == "invokestatic"
                        and invocation.get("name") == source_name
                        and source_owner_matches(
                            source_owner,
                            str(invocation.get("owner", "")),
                        )
                    ):
                        continue
                    proof = generic_filter_method(
                        owner=str(invocation.get("owner", "")),
                        name=source_name,
                        descriptor=str(
                            invocation.get("descriptor", "")
                        ),
                    )
                    if proof is not None:
                        matching.append(
                            {
                                **proof,
                                "offset": int(
                                    invocation.get("offset", -1)
                                ),
                            }
                        )
                if len(matching) != source_count:
                    filter_ok = False
                    break
                filter_proofs[filter_key] = matching
            if not filter_ok:
                continue

            functional_owners = {
                proof["functional_owner"]
                for proofs in filter_proofs.values()
                for proof in proofs
            }
            if len(functional_owners) != 1:
                continue
            functional_owner = next(iter(functional_owners))

            lambda_bootstraps = entry_lambda_bootstraps(
                exact_method,
                functional_owner=functional_owner,
            )
            if len(lambda_bootstraps) != len(source_rows):
                continue
            if sum(
                int(row["map_entry_getvalue_count"])
                for row in lambda_bootstraps
            ) != len(source_rows):
                continue

            exact_candidates.append(
                {
                    "method": exact_method,
                    "flow_offsets": flow_offsets,
                    "filter_proofs": filter_proofs,
                    "functional_owner": functional_owner,
                    "lambda_bootstraps": lambda_bootstraps,
                }
            )

        if len(exact_candidates) != 1:
            continue

        exact_proof = exact_candidates[0]
        for row in source_rows:
            edits.append(
                (
                    int(row["cast_start"]),
                    int(row["cast_end"]),
                    "",
                )
            )

        actions.append(
            {
                "kind": (
                    "raw_iterable_map_entry_lambda_cast_removal"
                ),
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": exact_proof["method"]["descriptor"],
                "raw_iterable_cast_count": len(source_rows),
                "lambda_parameter_names": [
                    row["lambda_parameter"]
                    for row in source_rows
                ],
                "receiver_proofs": [
                    {
                        **receiver_proof,
                        "source_count": receiver_counts[key],
                        "exact_flow_offsets": exact_proof[
                            "flow_offsets"
                        ][key],
                    }
                    for key, receiver_proof in sorted(
                        receiver_proofs.items()
                    )
                ],
                "filter_proofs": [
                    proof
                    for key in sorted(exact_proof["filter_proofs"])
                    for proof in exact_proof["filter_proofs"][key]
                ],
                "functional_owner": exact_proof[
                    "functional_owner"
                ],
                "lambda_bootstraps": exact_proof[
                    "lambda_bootstraps"
                ],
                "replacement_count": len(source_rows),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_raw_iterable_cast_erases_map_entry_lambda_type"
                    ),
                    "strategy": (
                        "exact_parameterized_field_plus_entry_getter_signature_"
                        "plus_generic_filter_signature_plus_"
                        "lambda_metafactory_map_entry_helper"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping raw Iterable lambda-cast edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions

def _normalize_impossible_collectors_tolist_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Remove a Procyon collector cast contradicted by exact generic authority."""

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        profile = profile_class_field_accesses(
            readable_zip.read(class_entry)
        )
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    bootstrap_methods = list(profile.get("bootstrap_methods", []))
    if not bootstrap_methods:
        return []

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        candidates = []
        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue
            signature = str(exact_method.get("signature") or "")
            element_owner = _signature_list_return_element_owner(signature)
            if element_owner is None:
                continue

            invocations = list(exact_method.get("method_invocations", []))
            to_list = [
                row for row in invocations
                if row.get("operation") == "invokestatic"
                and row.get("owner") == "java/util/stream/Collectors"
                and row.get("name") == "toList"
                and row.get("descriptor") == "()Ljava/util/stream/Collector;"
            ]
            collect = [
                row for row in invocations
                if row.get("operation") in {"invokeinterface", "invokevirtual"}
                and row.get("owner") == "java/util/stream/Stream"
                and row.get("name") == "collect"
                and row.get("descriptor")
                == "(Ljava/util/stream/Collector;)Ljava/lang/Object;"
            ]
            if len(to_list) != 1 or len(collect) != 1:
                continue

            predicate_matches = []
            expected_instantiated = "(L" + element_owner + ";)Z"
            for invocation in invocations:
                if invocation.get("operation") != "invokedynamic":
                    continue
                indy_descriptor = str(invocation.get("descriptor", ""))
                if not indy_descriptor.endswith(
                    ")Ljava/util/function/Predicate;"
                ):
                    continue
                bootstrap_index = int(
                    invocation.get("bootstrap_method_attr_index", -1)
                )
                if not (0 <= bootstrap_index < len(bootstrap_methods)):
                    continue
                bootstrap = bootstrap_methods[bootstrap_index]
                bm = bootstrap.get("bootstrap_method", {})
                if not (
                    bm.get("owner") == "java/lang/invoke/LambdaMetafactory"
                    and bm.get("name") in {"metafactory", "altMetafactory"}
                ):
                    continue
                method_types = {
                    str(arg.get("descriptor", ""))
                    for arg in bootstrap.get("arguments", [])
                    if arg.get("kind") == "method_type"
                }
                if expected_instantiated not in method_types:
                    continue
                predicate_matches.append(
                    {
                        "offset": int(invocation.get("offset", -1)),
                        "descriptor": indy_descriptor,
                        "bootstrap_method_attr_index": bootstrap_index,
                    }
                )
            if len(predicate_matches) != 1:
                continue

            candidates.append(
                {
                    "method": exact_method,
                    "element_owner": element_owner,
                    "predicate": predicate_matches[0],
                }
            )
        if len(candidates) != 1:
            continue

        proof = candidates[0]
        element_simple = (
            str(proof["element_owner"])
            .rsplit("/", 1)[-1]
            .rsplit("$", 1)[-1]
        )
        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        cast_re = re.compile(
            r"(?P<cast>\(\s*(?:java\.util\.stream\.)?Collector\s*<\s*"
            r"\?\s+super\s+Object\s*,\s*\?\s*,\s*"
            r"(?:java\.util\.)?List\s*<\s*"
            r"(?P<element>[A-Za-z_$][A-Za-z0-9_$.]*)\s*>\s*>\s*\)\s*)"
            r"(?P<call>(?:java\.util\.stream\.)?Collectors\s*\.\s*toList\s*\(\s*\))"
        )
        matches = list(cast_re.finditer(method_code))
        filtered_matches = []
        for match in matches:
            source_element = match.group("element")
            if "." in source_element:
                if source_element.replace(".", "/") != proof["element_owner"]:
                    continue
            elif source_element != element_simple:
                continue
            filtered_matches.append(match)
        matches = filtered_matches
        if len(matches) != 1:
            continue
        match = matches[0]

        start = method_start + match.start("cast")
        end = method_start + match.end("cast")
        edits.append((start, end, ""))
        actions.append(
            {
                "kind": "impossible_collectors_tolist_cast_removal",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"].get("descriptor"),
                "method_signature": proof["method"].get("signature"),
                "element_owner": proof["element_owner"],
                "predicate_invokedynamic": proof["predicate"],
                "replacement_count": 1,
                "provenance": {
                    "kind": "source_safety",
                    "reason": "procyon_impossible_collectors_tolist_generic_cast",
                    "strategy": (
                        "exact_method_signature_plus_predicate_bootstrap_plus_erased_collect_calls"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping Collectors.toList cast edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_collectors_to_list_wildcard_sink_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Remove wildcard List<Object> collector casts with exact typed sinks.

    Procyon can force a stream collect to List<Object> with an explicit
    Collector<? super Object, ?, List<? super Object>> cast, then cast the
    resulting value to Collection<E>. Java rejects that conversion even when
    exact lambda bootstraps and the downstream constructor Signature prove E.
    Remove only the inner Collector casts when all of those authorities agree.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    bootstrap_methods = list(profile.get("bootstrap_methods", []))
    if not bootstrap_methods:
        return []

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    outer_stream_re = re.compile(
        r"\(\s*(?:java\.util\.)?Collection\s*<\s*"
        r"(?P<element>[A-Za-z_$][A-Za-z0-9_$.]*)\s*>\s*\)\s*"
        r"(?:(?:java\.util\.)?Arrays)\s*\.\s*stream\s*\(\s*"
        r"(?P<receiver>[A-Za-z_$][A-Za-z0-9_$]*)\s*\.\s*"
        r"(?P<member>getDeclaredFields|getMethods)\s*\(\s*\)\s*\)"
    )
    inner_cast_re = re.compile(
        r"(?P<cast>"
        r"\(\s*(?:java\.util\.stream\.)?Collector\s*<\s*"
        r"\?\s+super\s+Object\s*,\s*"
        r"\?\s*,\s*"
        r"(?:java\.util\.)?List\s*<\s*"
        r"\?\s+super\s+Object\s*>\s*>\s*\)\s*"
        r")"
        r"(?P<call>"
        r"(?:java\.util\.stream\.)?Collectors"
        r"\s*\.\s*toList\s*\(\s*\)"
        r")"
    )
    any_to_list_re = re.compile(
        r"(?<![A-Za-z0-9_$.])"
        r"(?:java\.util\.stream\.)?Collectors"
        r"\s*\.\s*toList\s*\(\s*\)"
    )

    expected_bootstrap_descriptors = {
        "metafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodType;"
            "Ljava/lang/invoke/MethodHandle;"
            "Ljava/lang/invoke/MethodType;)"
            "Ljava/lang/invoke/CallSite;"
        ),
        "altMetafactory": (
            "(Ljava/lang/invoke/MethodHandles$Lookup;"
            "Ljava/lang/String;"
            "Ljava/lang/invoke/MethodType;"
            "[Ljava/lang/Object;)"
            "Ljava/lang/invoke/CallSite;"
        ),
    }

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        outer_streams = list(outer_stream_re.finditer(method_code))
        inner_casts = list(inner_cast_re.finditer(method_code))
        all_to_list = list(any_to_list_re.finditer(method_code))
        if not (
            len(outer_streams) == 2
            and len(inner_casts) == 2
            and len(all_to_list) == 2
        ):
            continue
        if [
            match.group("member") for match in outer_streams
        ] != ["getDeclaredFields", "getMethods"]:
            continue
        if len({
            match.group("receiver") for match in outer_streams
        }) != 1:
            continue
        if not (
            outer_streams[0].start()
            < inner_casts[0].start()
            < outer_streams[1].start()
            < inner_casts[1].start()
        ):
            continue

        element_sources = [
            match.group("element") for match in outer_streams
        ]
        if len(set(element_sources)) != 2:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        exact_candidates: list[dict[str, Any]] = []

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            instructions = list(exact_method.get("instructions", []))
            reflection_members = [
                item.get("name")
                for item in instructions
                if item.get("mnemonic") == "invokevirtual"
                and item.get("owner") == "java/lang/Class"
                and item.get("name")
                in {"getDeclaredFields", "getMethods"}
            ]
            if reflection_members.count("getDeclaredFields") != 1:
                continue
            if reflection_members.count("getMethods") != 1:
                continue

            collect_triplets: list[dict[str, int]] = []
            for index in range(len(instructions) - 2):
                first = instructions[index]
                second = instructions[index + 1]
                third = instructions[index + 2]
                if not (
                    first.get("mnemonic") == "invokestatic"
                    and first.get("owner")
                    == "java/util/stream/Collectors"
                    and first.get("name") == "toList"
                    and first.get("descriptor")
                    == "()Ljava/util/stream/Collector;"
                    and second.get("mnemonic") == "invokeinterface"
                    and second.get("owner")
                    == "java/util/stream/Stream"
                    and second.get("name") == "collect"
                    and second.get("descriptor")
                    == "(Ljava/util/stream/Collector;)Ljava/lang/Object;"
                    and third.get("mnemonic") == "checkcast"
                    and third.get("type") == "java/util/List"
                ):
                    continue
                collect_triplets.append(
                    {
                        "to_list_offset": int(first.get("offset", -1)),
                        "collect_offset": int(second.get("offset", -1)),
                        "checkcast_offset": int(third.get("offset", -1)),
                        "instruction_index": index,
                    }
                )
            if len(collect_triplets) != 2:
                continue

            sink_calls = []
            for index, item in enumerate(instructions):
                if not (
                    item.get("mnemonic") == "invokespecial"
                    and item.get("name") == "<init>"
                    and item.get("descriptor", "").endswith(
                        "Ljava/util/Collection;"
                        "Ljava/util/Collection;)V"
                    )
                ):
                    continue
                sink_calls.append((index, item))
            if len(sink_calls) != 1:
                continue
            sink_index, sink_call = sink_calls[0]
            if max(
                row["instruction_index"] for row in collect_triplets
            ) >= sink_index:
                continue

            sink_owner = str(sink_call.get("owner", ""))
            sink_descriptor = str(
                sink_call.get("descriptor", "")
            )
            if not sink_owner or sink_owner == current_owner:
                continue
            try:
                sink_bytes = readable_zip.read(sink_owner + ".class")
                sink_profile = profile_class_field_accesses(sink_bytes)
            except (KeyError, BytecodeProfileError):
                continue
            sink_constructors = [
                row
                for row in sink_profile.get("methods", [])
                if row.get("name") == "<init>"
                and row.get("descriptor") == sink_descriptor
            ]
            if len(sink_constructors) != 1:
                continue
            sink_signature = sink_constructors[0].get("signature")
            signature_match = re.fullmatch(
                r"\(L[^;]+;"
                r"Ljava/util/Collection<L(?P<first>[^;]+);>;"
                r"Ljava/util/Collection<L(?P<second>[^;]+);>;"
                r"\)V",
                str(sink_signature or ""),
            )
            if signature_match is None:
                continue
            element_owners = [
                signature_match.group("first"),
                signature_match.group("second"),
            ]

            source_owner_matches = []
            for source_element, owner in zip(
                element_sources,
                element_owners,
            ):
                source_owner_matches.append(
                    _source_parameters_match_descriptor(
                        source_element + " recoveredCollectorElement",
                        "(L" + owner + ";)V",
                        current_package=current_package,
                    )
                    is True
                )
            if source_owner_matches != [True, True]:
                continue

            expected_function_types = [
                "(Ljava/lang/reflect/Field;)L"
                + element_owners[0]
                + ";",
                "(Ljava/lang/reflect/Method;)L"
                + element_owners[1]
                + ";",
            ]
            function_proofs: list[dict[str, Any]] = []
            for expected_instantiated in expected_function_types:
                matching = []
                for invocation in exact_method.get(
                    "method_invocations", []
                ):
                    if (
                        invocation.get("operation") != "invokedynamic"
                        or _descriptor_return_descriptor(
                            str(invocation.get("descriptor", ""))
                        )
                        != "Ljava/util/function/Function;"
                    ):
                        continue
                    bootstrap_index = int(
                        invocation.get(
                            "bootstrap_method_attr_index",
                            -1,
                        )
                    )
                    if not (
                        0 <= bootstrap_index < len(bootstrap_methods)
                    ):
                        continue
                    bootstrap = bootstrap_methods[bootstrap_index]
                    handle = bootstrap.get("bootstrap_method", {})
                    bootstrap_name = str(handle.get("name", ""))
                    if not (
                        handle.get("owner")
                        == "java/lang/invoke/LambdaMetafactory"
                        and bootstrap_name
                        in expected_bootstrap_descriptors
                        and handle.get("descriptor")
                        == expected_bootstrap_descriptors[
                            bootstrap_name
                        ]
                        and handle.get("target_kind") == "method"
                        and int(handle.get("reference_kind", -1)) == 6
                    ):
                        continue
                    method_types = [
                        str(argument.get("descriptor", ""))
                        for argument in bootstrap.get(
                            "arguments", []
                        )
                        if argument.get("kind") == "method_type"
                    ]
                    if method_types.count(expected_instantiated) != 1:
                        continue
                    matching.append(
                        {
                            "offset": int(
                                invocation.get("offset", -1)
                            ),
                            "descriptor": str(
                                invocation.get("descriptor", "")
                            ),
                            "bootstrap_method_attr_index": (
                                bootstrap_index
                            ),
                            "instantiated_method_type": (
                                expected_instantiated
                            ),
                        }
                    )
                if len(matching) != 1:
                    function_proofs = []
                    break
                function_proofs.append(matching[0])
            if len(function_proofs) != 2:
                continue

            exact_candidates.append(
                {
                    "method": exact_method,
                    "sink_owner": sink_owner,
                    "sink_descriptor": sink_descriptor,
                    "sink_signature": sink_signature,
                    "element_owners": element_owners,
                    "collect_triplets": collect_triplets,
                    "functions": function_proofs,
                }
            )

        if len(exact_candidates) != 1:
            continue
        proof = exact_candidates[0]

        for source_match in inner_casts:
            edits.append(
                (
                    method_start + source_match.start("cast"),
                    method_start + source_match.end("cast"),
                    "",
                )
            )
        actions.append(
            {
                "kind": (
                    "collectors_to_list_wildcard_sink_cast_removal"
                ),
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "sink_owner": proof["sink_owner"],
                "sink_descriptor": proof["sink_descriptor"],
                "sink_signature": proof["sink_signature"],
                "source_element_types": element_sources,
                "exact_element_owners": proof["element_owners"],
                "collector_pairs": proof["collect_triplets"],
                "function_bootstraps": proof["functions"],
                "replacement_count": len(inner_casts),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_collectors_to_list_wildcard_forces_object"
                    ),
                    "strategy": (
                        "exact_constructor_signature_plus_function_element_types"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping wildcard collector-cast edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_generic_key_object_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Remove impossible Object casts from exact generic key arguments.

    The exact field Signature binds concrete source types to the raw generic
    class parameters. Remove only a first-argument Object cast when the target
    method consumes that first class type variable and exact caller flow proves
    the key local already has the substituted concrete reference type.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    current_simple = _source_simple_type_name(current_owner)
    current_dotted = current_owner.replace("/", ".")

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)

    imports: dict[str, str] = {}
    duplicate_imports: set[str] = set()
    for import_match in _SINGLE_TYPE_IMPORT_RE.finditer(text):
        dotted = import_match.group("name")
        simple = dotted.rsplit(".", 1)[-1]
        internal = dotted.replace(".", "/")
        previous = imports.get(simple)
        if previous is not None and previous != internal:
            duplicate_imports.add(simple)
        else:
            imports[simple] = internal
    for simple in duplicate_imports:
        imports.pop(simple, None)

    owner_cache: dict[str, dict[str, Any]] = {
        current_owner: profile,
    }

    def owner_profile(owner: str) -> dict[str, Any] | None:
        cached = owner_cache.get(owner)
        if cached is not None:
            return cached
        try:
            parsed = profile_class_field_accesses(
                readable_zip.read(owner + ".class")
            )
        except (KeyError, BytecodeProfileError):
            return None
        if str(parsed.get("internal_name", "")) != owner:
            return None
        owner_cache[owner] = parsed
        return parsed

    def class_exists(internal: str) -> bool:
        try:
            readable_zip.getinfo(internal + ".class")
            return True
        except KeyError:
            return False

    def reference_type_known(internal: str) -> bool:
        return internal.startswith("java/") or class_exists(internal)

    def resolve_source_type(type_text: str) -> str | None:
        value = type_text.strip()
        value = re.sub(r"<.*>$", "", value).strip()
        while value.endswith("[]"):
            value = value[:-2].strip()
        if not re.fullmatch(
            r"[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)*",
            value,
        ):
            return None
        if value == current_simple or value == current_dotted:
            return current_owner
        if value in imports:
            return imports[value]
        if "." in value:
            candidate = value.replace(".", "/")
            return candidate if reference_type_known(candidate) else None
        same_package = (
            current_package + "/" + value
            if current_package
            else value
        )
        if class_exists(same_package):
            return same_package
        java_lang = "java/lang/" + value
        if reference_type_known(java_lang):
            return java_lang
        return None

    def class_type_parameters(signature: str) -> list[str] | None:
        if not signature.startswith("<"):
            return None

        def skip_field_type(index: int) -> int | None:
            if index >= len(signature):
                return None
            token = signature[index]
            if token == "T":
                end = signature.find(";", index + 1)
                return None if end < 0 else end + 1
            if token == "[":
                index += 1
                if index >= len(signature):
                    return None
                if signature[index] in "ZBCSIJFD":
                    return index + 1
                return skip_field_type(index)
            if token != "L":
                return None
            depth = 0
            index += 1
            while index < len(signature):
                ch = signature[index]
                if ch == "<":
                    depth += 1
                elif ch == ">":
                    if depth == 0:
                        return None
                    depth -= 1
                elif ch == ";" and depth == 0:
                    return index + 1
                index += 1
            return None

        out: list[str] = []
        index = 1
        while index < len(signature) and signature[index] != ">":
            start = index
            while (
                index < len(signature)
                and (
                    signature[index].isalnum()
                    or signature[index] in "_$"
                )
            ):
                index += 1
            if start == index or index >= len(signature):
                return None
            name = signature[start:index]
            if signature[index] != ":":
                return None
            out.append(name)

            while index < len(signature) and signature[index] == ":":
                index += 1
                if index >= len(signature):
                    return None
                if signature[index] == ":":
                    continue
                next_index = skip_field_type(index)
                if next_index is None:
                    return None
                index = next_index

        if index >= len(signature) or signature[index] != ">":
            return None
        return out

    field_signature_re = re.compile(
        r"^L(?P<owner>[^;<]+)<"
        r"L(?P<key>[^;<>]+);"
        r"L(?P<value>[^;<>]+);"
        r">;$"
    )

    def field_binding(
        field_name: str,
        member_name: str,
    ) -> dict[str, Any] | None:
        fields = [
            field
            for field in profile.get("fields", [])
            if (
                field.get("name") == field_name
                and not (int(field.get("access", 0)) & 0x0008)
            )
        ]
        if len(fields) != 1:
            return None
        field = fields[0]
        descriptor = str(field.get("descriptor", ""))
        if not (
            descriptor.startswith("L")
            and descriptor.endswith(";")
        ):
            return None
        raw_owner = descriptor[1:-1]
        signature = str(field.get("signature") or "")
        match = field_signature_re.fullmatch(signature)
        if match is None or match.group("owner") != raw_owner:
            return None
        key_owner = match.group("key")
        value_owner = match.group("value")
        if not (
            reference_type_known(key_owner)
            and reference_type_known(value_owner)
        ):
            return None

        parsed = owner_profile(raw_owner)
        if parsed is None:
            return None
        class_signature = str(parsed.get("signature") or "")
        type_parameters = class_type_parameters(class_signature)
        if type_parameters is None or len(type_parameters) != 2:
            return None
        key_variable, value_variable = type_parameters
        if key_variable == value_variable:
            return None

        methods = [
            method
            for method in parsed.get("methods", [])
            if (
                method.get("name") == member_name
                and method.get("descriptor")
                == "(Ljava/lang/Object;Ljava/lang/Object;)V"
                and method.get("signature")
                == f"(T{key_variable};T{value_variable};)V"
            )
        ]
        if len(methods) != 1:
            return None

        return {
            "field_name": field_name,
            "field_descriptor": descriptor,
            "field_signature": signature,
            "raw_owner": raw_owner,
            "raw_class_signature": class_signature,
            "key_variable": key_variable,
            "value_variable": value_variable,
            "key_owner": key_owner,
            "value_owner": value_owner,
            "member_name": member_name,
            "member_descriptor": str(methods[0]["descriptor"]),
            "member_signature": str(methods[0]["signature"]),
        }

    def identifier_source_type(
        *,
        method_match: re.Match[str],
        method_text: str,
        before: int,
        identifier: str,
    ) -> str | None:
        candidates: list[str] = []

        parameter_names = _source_parameter_names(
            method_match.group("params")
        )
        parameter_spans = _parameter_type_spans(
            method_match.group("params")
        )
        if (
            parameter_names is not None
            and parameter_spans is not None
            and len(parameter_names) == len(parameter_spans)
        ):
            for name, (_left, _right, type_text) in zip(
                parameter_names,
                parameter_spans,
            ):
                if name != identifier:
                    continue
                resolved = resolve_source_type(type_text)
                if resolved is not None:
                    candidates.append(resolved)

        prefix = method_text[:before]
        local_re = re.compile(
            r"(?m)(?:^|[;{}]\s*)[ \t]*"
            r"(?:(?:final)\s+)?"
            r"(?P<type>[A-Za-z_$][A-Za-z0-9_$.]*)\s+"
            + re.escape(identifier)
            + r"\b\s*(?:=|;)"
        )
        for local in local_re.finditer(prefix):
            resolved = resolve_source_type(local.group("type"))
            if resolved is not None:
                candidates.append(resolved)

        enhanced_for_re = re.compile(
            r"\bfor\s*\(\s*"
            r"(?:(?:final)\s+)?"
            r"(?P<type>[A-Za-z_$][A-Za-z0-9_$.]*)\s+"
            + re.escape(identifier)
            + r"\s*:"
        )
        for loop_var in enhanced_for_re.finditer(prefix):
            resolved = resolve_source_type(loop_var.group("type"))
            if resolved is not None:
                candidates.append(resolved)

        unique = sorted(set(candidates))
        return unique[0] if len(unique) == 1 else None

    call_re = re.compile(
        r"this\.(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\.\s*(?P<member>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\(\s*"
        r"(?P<cast>\(\s*Object\s*\)\s*)"
        r"(?P<identifier>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*,"
    )

    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_text = text[method_start:body_end]
        method_code = whole_code[method_start:body_end]
        calls: list[dict[str, Any]] = []

        for call in call_re.finditer(method_text):
            if (
                call.start() >= len(method_code)
                or method_code[call.start()].isspace()
            ):
                continue
            binding = field_binding(
                call.group("field"),
                call.group("member"),
            )
            if binding is None:
                continue
            source_key_type = identifier_source_type(
                method_match=method_match,
                method_text=method_text,
                before=call.start(),
                identifier=call.group("identifier"),
            )
            if source_key_type != binding["key_owner"]:
                continue
            calls.append(
                {
                    "match": call,
                    "identifier": call.group("identifier"),
                    **binding,
                }
            )

        if not calls:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        if source_static:
            continue

        exact_candidates: list[dict[str, Any]] = []
        source_proofs = [
            (
                call["field_name"],
                call["raw_owner"],
                call["member_name"],
                call["member_descriptor"],
                call["key_owner"],
            )
            for call in calls
        ]

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if int(exact_method.get("access", 0)) & 0x0008:
                continue

            parameter_shapes = _descriptor_parameter_shapes(descriptor)
            parameter_slots = _descriptor_parameter_local_slots(
                descriptor,
                is_static=False,
            )
            if (
                parameter_shapes is None
                or parameter_slots is None
                or len(parameter_shapes) != len(parameter_slots)
            ):
                continue

            exact_parameter_types = {
                slot: shape[2]
                for shape, slot in zip(
                    parameter_shapes,
                    parameter_slots,
                )
                if shape[0] == 0 and shape[1] == "ref"
            }

            instructions = list(exact_method.get("instructions", []))
            flows: list[dict[str, Any]] = []

            for index, field_access in enumerate(instructions):
                matching_calls = [
                    call
                    for call in calls
                    if (
                        field_access.get("mnemonic") == "getfield"
                        and field_access.get("owner") == current_owner
                        and field_access.get("name") == call["field_name"]
                        and field_access.get("descriptor")
                        == call["field_descriptor"]
                    )
                ]
                if not matching_calls:
                    continue
                matching_proofs = {
                    (
                        call["field_name"],
                        call["field_descriptor"],
                        call["raw_owner"],
                        call["member_name"],
                        call["member_descriptor"],
                        call["key_owner"],
                    )
                    for call in matching_calls
                }
                if len(matching_proofs) != 1:
                    continue
                call = matching_calls[0]
                if index == 0:
                    continue
                receiver_load = instructions[index - 1]
                if not (
                    receiver_load.get("mnemonic") == "aload"
                    and int(receiver_load.get("local_index", -1)) == 0
                ):
                    continue
                if index + 1 >= len(instructions):
                    continue
                key_load = instructions[index + 1]
                if key_load.get("mnemonic") != "aload":
                    continue
                key_slot = int(key_load.get("local_index", -1))
                if key_slot < 0:
                    continue

                key_slot_proven = (
                    exact_parameter_types.get(key_slot)
                    == call["key_owner"]
                )
                key_store_offset: int | None = None
                if not key_slot_proven:
                    latest_store: int | None = None
                    for probe in range(index - 1, -1, -1):
                        item = instructions[probe]
                        if (
                            item.get("mnemonic") == "astore"
                            and int(item.get("local_index", -1))
                            == key_slot
                        ):
                            latest_store = probe
                            break
                    if (
                        latest_store is not None
                        and latest_store > 0
                        and instructions[
                            latest_store - 1
                        ].get("mnemonic") == "checkcast"
                        and instructions[
                            latest_store - 1
                        ].get("type") == call["key_owner"]
                    ):
                        key_slot_proven = True
                        key_store_offset = int(
                            instructions[latest_store].get(
                                "offset", -1
                            )
                        )
                if not key_slot_proven:
                    continue

                target_index: int | None = None
                for probe in range(
                    index + 2,
                    min(len(instructions), index + 18),
                ):
                    item = instructions[probe]
                    if (
                        item.get("mnemonic")
                        in {"invokevirtual", "invokeinterface"}
                        and item.get("owner") == call["raw_owner"]
                        and item.get("name") == call["member_name"]
                        and item.get("descriptor")
                        == call["member_descriptor"]
                    ):
                        target_index = probe
                        break
                if target_index is None:
                    continue
                if any(
                    item.get("mnemonic") == "checkcast"
                    and item.get("type") == call["key_owner"]
                    for item in instructions[index + 2:target_index]
                ):
                    continue

                flows.append(
                    {
                        "field_name": call["field_name"],
                        "raw_owner": call["raw_owner"],
                        "member_name": call["member_name"],
                        "member_descriptor": call["member_descriptor"],
                        "key_owner": call["key_owner"],
                        "key_local_index": key_slot,
                        "key_store_offset": key_store_offset,
                        "field_offset": int(
                            field_access.get("offset", -1)
                        ),
                        "key_load_offset": int(
                            key_load.get("offset", -1)
                        ),
                        "invoke_offset": int(
                            instructions[target_index].get(
                                "offset", -1
                            )
                        ),
                    }
                )

            exact_proofs = [
                (
                    flow["field_name"],
                    flow["raw_owner"],
                    flow["member_name"],
                    flow["member_descriptor"],
                    flow["key_owner"],
                )
                for flow in flows
            ]
            if exact_proofs != source_proofs:
                continue

            exact_candidates.append(
                {
                    "method": exact_method,
                    "flows": flows,
                }
            )

        if len(exact_candidates) != 1:
            continue

        proof = exact_candidates[0]
        for call in calls:
            match = call["match"]
            edits.append(
                (
                    method_start + match.start("cast"),
                    method_start + match.end("cast"),
                    "",
                )
            )

        actions.append(
            {
                "kind": "generic_key_object_cast_removal",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "fields": [call["field_name"] for call in calls],
                "raw_owners": [call["raw_owner"] for call in calls],
                "field_signatures": [
                    call["field_signature"] for call in calls
                ],
                "raw_class_signatures": [
                    call["raw_class_signature"] for call in calls
                ],
                "member_signatures": [
                    call["member_signature"] for call in calls
                ],
                "generic_key_types": [
                    call["key_owner"] for call in calls
                ],
                "flows": proof["flows"],
                "replacement_count": len(calls),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_erased_generic_key_object_cast"
                    ),
                    "strategy": (
                        "exact_field_and_class_signatures_plus_direct_key_slot_flow"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping generic-key Object-cast edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



def _normalize_generic_key_getclass_object_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Remove Object casts around getClass() used as exact generic keys.

    This is a narrow companion to generic_key_object_cast_removal.  It handles
    one-argument generic lookups where Procyon writes
    member((Object)value.getClass()) even though exact field/class/member
    Signatures bind K to Class<?> and bytecode proves the flow
    getfield -> Object.getClass -> erased generic lookup -> checkcast V.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)

    imports: dict[str, str] = {}
    duplicate_imports: set[str] = set()
    for import_match in _SINGLE_TYPE_IMPORT_RE.finditer(text):
        dotted = import_match.group("name")
        simple = dotted.rsplit(".", 1)[-1]
        internal = dotted.replace(".", "/")
        previous = imports.get(simple)
        if previous is not None and previous != internal:
            duplicate_imports.add(simple)
        else:
            imports[simple] = internal
    for simple in duplicate_imports:
        imports.pop(simple, None)

    owner_cache: dict[str, dict[str, Any]] = {
        current_owner: profile,
    }

    def owner_profile(owner: str) -> dict[str, Any] | None:
        cached = owner_cache.get(owner)
        if cached is not None:
            return cached
        try:
            parsed = profile_class_field_accesses(
                readable_zip.read(owner + ".class")
            )
        except (KeyError, BytecodeProfileError):
            return None
        if str(parsed.get("internal_name", "")) != owner:
            return None
        owner_cache[owner] = parsed
        return parsed

    def class_exists(owner: str) -> bool:
        if owner.startswith("java/"):
            return True
        try:
            readable_zip.getinfo(owner + ".class")
            return True
        except KeyError:
            return False

    def resolve_source_ref(type_text: str) -> str | None:
        value = re.sub(r"\s+", "", type_text)
        if "<" in value:
            value = value.split("<", 1)[0]
        while value.endswith("[]"):
            value = value[:-2]
        if not re.fullmatch(
            r"[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)*",
            value,
        ):
            return None
        if value in imports:
            return imports[value]
        if "." in value:
            candidate = value.replace(".", "/")
            return candidate if class_exists(candidate) else None
        nested = current_owner + "$" + value
        if class_exists(nested):
            return nested
        same_package = (
            current_package + "/" + value
            if current_package
            else value
        )
        if class_exists(same_package):
            return same_package
        java_lang = "java/lang/" + value
        if class_exists(java_lang):
            return java_lang
        return None

    def consume_signature_type(
        signature: str,
        start: int,
    ) -> int | None:
        if start >= len(signature):
            return None
        token = signature[start]
        if token in "+-":
            return consume_signature_type(signature, start + 1)
        if token == "*":
            return start + 1
        if token == "T":
            end = signature.find(";", start + 1)
            return None if end < 0 else end + 1
        if token == "[":
            return consume_signature_type(signature, start + 1)
        if token != "L":
            return None
        depth = 0
        index = start + 1
        while index < len(signature):
            ch = signature[index]
            if ch == "<":
                depth += 1
            elif ch == ">":
                if depth == 0:
                    return None
                depth -= 1
            elif ch == ";" and depth == 0:
                return index + 1
            index += 1
        return None

    def field_signature_arguments(
        signature: str,
        raw_owner: str,
    ) -> list[str] | None:
        prefix = "L" + raw_owner + "<"
        if not (signature.startswith(prefix) and signature.endswith(">;")):
            return None
        body = signature[len(prefix):-2]
        out: list[str] = []
        index = 0
        while index < len(body):
            end = consume_signature_type(body, index)
            if end is None or end <= index:
                return None
            out.append(body[index:end])
            index = end
        return out if len(out) == 2 else None

    def signature_erasure_owner(signature: str) -> str | None:
        value = signature
        while value and value[0] in "+-":
            value = value[1:]
        if not value.startswith("L") or not value.endswith(";"):
            return None
        body = value[1:-1]
        generic = body.find("<")
        owner = body if generic < 0 else body[:generic]
        return owner if owner and class_exists(owner) else None

    def source_field_arguments(
        *,
        field_name: str,
        raw_owner: str,
        exact_argument_owners: list[str],
    ) -> bool:
        start_re = re.compile(
            r"(?m)^[ \t]*"
            r"(?:(?:public|private|protected|static|final|transient|volatile)"
            r"\s+)*"
            r"(?P<raw>[A-Za-z_$][A-Za-z0-9_$.]*)\s*"
            r"(?P<angle><)"
        )
        matches = 0
        for match in start_re.finditer(whole_code):
            if resolve_source_ref(match.group("raw")) != raw_owner:
                continue
            angle_start = match.start("angle")
            angle_end = _matching_generic_angle_end(
                whole_code,
                angle_start,
            )
            if angle_end is None:
                continue
            tail = whole_code[angle_end + 1:]
            field_match = re.match(
                r"\s+"
                + re.escape(field_name)
                + r"\b\s*(?:=|;)",
                tail,
            )
            if field_match is None:
                continue
            args_text = text[angle_start + 1:angle_end]
            spans = _top_level_generic_argument_spans(args_text)
            if spans is None or len(spans) != 2:
                continue
            source_owners = [
                resolve_source_ref(args_text[left:right].strip())
                for left, right in spans
            ]
            if source_owners != exact_argument_owners:
                continue
            matches += 1
        return matches == 1

    def field_binding(
        field_name: str,
        member_name: str,
    ) -> dict[str, Any] | None:
        fields = [
            field
            for field in profile.get("fields", [])
            if (
                field.get("name") == field_name
                and not (int(field.get("access", 0)) & 0x0008)
                and isinstance(field.get("signature"), str)
            )
        ]
        if len(fields) != 1:
            return None
        field = fields[0]
        descriptor = str(field.get("descriptor", ""))
        if not (
            descriptor.startswith("L")
            and descriptor.endswith(";")
        ):
            return None
        raw_owner = descriptor[1:-1]
        signature = str(field.get("signature") or "")
        exact_args = field_signature_arguments(signature, raw_owner)
        if exact_args is None:
            return None
        exact_argument_owners = [
            signature_erasure_owner(argument)
            for argument in exact_args
        ]
        if any(owner is None for owner in exact_argument_owners):
            return None
        key_owner, value_owner = exact_argument_owners
        if key_owner != "java/lang/Class":
            return None
        if not source_field_arguments(
            field_name=field_name,
            raw_owner=raw_owner,
            exact_argument_owners=exact_argument_owners,
        ):
            return None

        parsed = owner_profile(raw_owner)
        if parsed is None:
            return None
        class_signature = str(parsed.get("signature") or "")
        class_match = re.match(
            r"^<(?P<key>[A-Za-z_$][A-Za-z0-9_$]*):"
            r"Ljava/lang/Object;"
            r"(?P<value>[A-Za-z_$][A-Za-z0-9_$]*):"
            r"Ljava/lang/Object;>",
            class_signature,
        )
        if class_match is None:
            return None
        key_variable = class_match.group("key")
        value_variable = class_match.group("value")
        if key_variable == value_variable:
            return None

        methods = [
            method
            for method in parsed.get("methods", [])
            if (
                method.get("name") == member_name
                and method.get("descriptor")
                == "(Ljava/lang/Object;)Ljava/lang/Object;"
                and method.get("signature")
                == f"(T{key_variable};)T{value_variable};"
            )
        ]
        if len(methods) != 1:
            return None

        return {
            "field_name": field_name,
            "field_descriptor": descriptor,
            "field_signature": signature,
            "raw_owner": raw_owner,
            "raw_class_signature": class_signature,
            "key_owner": key_owner,
            "value_owner": value_owner,
            "member_name": member_name,
            "member_descriptor": str(methods[0]["descriptor"]),
            "member_signature": str(methods[0]["signature"]),
        }

    call_re = re.compile(
        r"this\s*\.\s*(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\.\s*(?P<member>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\(\s*"
        r"(?P<cast>\(\s*(?:java\.lang\.)?Object\s*\)\s*)"
        r"(?P<identifier>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\.\s*getClass\s*\(\s*\)\s*\)"
    )

    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        calls: list[dict[str, Any]] = []

        for match in call_re.finditer(method_code):
            binding = field_binding(
                match.group("field"),
                match.group("member"),
            )
            if binding is None:
                continue
            calls.append(
                {
                    "match": match,
                    "identifier": match.group("identifier"),
                    **binding,
                }
            )

        if not calls:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        if source_static:
            continue

        exact_candidates: list[dict[str, Any]] = []
        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if int(exact_method.get("access", 0)) & 0x0008:
                continue

            instructions = list(exact_method.get("instructions", []))
            flows: list[dict[str, Any]] = []

            for call in calls:
                matching: list[dict[str, Any]] = []
                for index in range(1, len(instructions) - 4):
                    receiver_load = instructions[index - 1]
                    field_get = instructions[index]
                    key_load = instructions[index + 1]
                    get_class = instructions[index + 2]
                    lookup = instructions[index + 3]
                    value_cast = instructions[index + 4]

                    if not (
                        receiver_load.get("mnemonic") == "aload"
                        and int(receiver_load.get("local_index", -1)) == 0
                        and field_get.get("mnemonic") == "getfield"
                        and field_get.get("owner") == current_owner
                        and field_get.get("name") == call["field_name"]
                        and field_get.get("descriptor")
                        == call["field_descriptor"]
                        and key_load.get("mnemonic") == "aload"
                        and int(key_load.get("local_index", -1)) > 0
                        and get_class.get("mnemonic") == "invokevirtual"
                        and get_class.get("owner") == "java/lang/Object"
                        and get_class.get("name") == "getClass"
                        and get_class.get("descriptor")
                        == "()Ljava/lang/Class;"
                        and lookup.get("mnemonic")
                        in {"invokevirtual", "invokeinterface"}
                        and lookup.get("owner") == call["raw_owner"]
                        and lookup.get("name") == call["member_name"]
                        and lookup.get("descriptor")
                        == call["member_descriptor"]
                        and value_cast.get("mnemonic") == "checkcast"
                        and value_cast.get("type") == call["value_owner"]
                    ):
                        continue

                    matching.append(
                        {
                            "field_offset": int(
                                field_get.get("offset", -1)
                            ),
                            "key_load_offset": int(
                                key_load.get("offset", -1)
                            ),
                            "key_local_index": int(
                                key_load.get("local_index", -1)
                            ),
                            "getclass_offset": int(
                                get_class.get("offset", -1)
                            ),
                            "lookup_offset": int(
                                lookup.get("offset", -1)
                            ),
                            "value_checkcast_offset": int(
                                value_cast.get("offset", -1)
                            ),
                        }
                    )

                if len(matching) != 1:
                    flows = []
                    break
                flows.append(matching[0])

            if len(flows) == len(calls):
                exact_candidates.append(
                    {
                        "method": exact_method,
                        "flows": flows,
                    }
                )

        if len(exact_candidates) != 1:
            continue

        proof = exact_candidates[0]
        for call in calls:
            match = call["match"]
            edits.append(
                (
                    method_start + match.start("cast"),
                    method_start + match.end("cast"),
                    "",
                )
            )

        actions.append(
            {
                "kind": "generic_key_object_cast_removal",
                "mode": "getclass_expression",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "fields": [call["field_name"] for call in calls],
                "raw_owners": [call["raw_owner"] for call in calls],
                "field_signatures": [
                    call["field_signature"] for call in calls
                ],
                "raw_class_signatures": [
                    call["raw_class_signature"] for call in calls
                ],
                "member_signatures": [
                    call["member_signature"] for call in calls
                ],
                "generic_key_types": [
                    call["key_owner"] for call in calls
                ],
                "generic_value_types": [
                    call["value_owner"] for call in calls
                ],
                "flows": proof["flows"],
                "replacement_count": len(calls),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_erased_generic_getclass_key_object_cast"
                    ),
                    "strategy": (
                        "exact_field_and_class_signatures_plus_getclass_"
                        "lookup_checkcast_flow"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping generic getClass key edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_inherited_cc_generic_value_object_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Remove Object casts from inherited cc<T> calls with exact substitution.

    This handles only current-instance fields inherited through a readable
    superclass chain. Every generic superclass hop must resolve uniquely to
    concrete reference types, and a source this.method(...) value must be
    matched to an exact invocation returning the substituted field type.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
        cc_profile = profile_class_field_accesses(
            readable_zip.read("gnu/trove/f/b/cc.class")
        )
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    cc_methods = [
        method
        for method in cc_profile.get("methods", [])
        if (
            method.get("name") == "a"
            and method.get("descriptor")
            == "(ILjava/lang/Object;)Ljava/lang/Object;"
            and method.get("signature") == "(ITV;)TV;"
        )
    ]
    if len(cc_methods) != 1:
        return []

    profile_cache: dict[str, dict[str, Any] | None] = {
        current_owner: profile,
        "gnu/trove/f/b/cc": cc_profile,
    }
    class_cache: dict[str, Any | None] = {}

    def owner_profile(owner: str) -> dict[str, Any] | None:
        if owner in profile_cache:
            return profile_cache[owner]
        try:
            parsed = profile_class_field_accesses(
                readable_zip.read(owner + ".class")
            )
        except (KeyError, BytecodeProfileError):
            profile_cache[owner] = None
            return None
        if str(parsed.get("internal_name", "")) != owner:
            profile_cache[owner] = None
            return None
        profile_cache[owner] = parsed
        return parsed

    def owner_class(owner: str) -> Any | None:
        if owner in class_cache:
            return class_cache[owner]
        try:
            parsed = parse_class(
                readable_zip.read(owner + ".class")
            )
        except (KeyError, ClassFormatError):
            class_cache[owner] = None
            return None
        if parsed.name != owner:
            class_cache[owner] = None
            return None
        class_cache[owner] = parsed
        return parsed

    def class_type_parameters(
        signature: str,
    ) -> tuple[list[str], int] | None:
        if not signature.startswith("<"):
            return [], 0

        def skip_field_type(index: int) -> int | None:
            if index >= len(signature):
                return None
            token = signature[index]
            if token == "T":
                end = signature.find(";", index + 1)
                return None if end < 0 else end + 1
            if token == "[":
                index += 1
                if index >= len(signature):
                    return None
                if signature[index] in "ZBCSIJFD":
                    return index + 1
                return skip_field_type(index)
            if token != "L":
                return None
            depth = 0
            index += 1
            while index < len(signature):
                ch = signature[index]
                if ch == "<":
                    depth += 1
                elif ch == ">":
                    if depth == 0:
                        return None
                    depth -= 1
                elif ch == ";" and depth == 0:
                    return index + 1
                index += 1
            return None

        names: list[str] = []
        index = 1
        while index < len(signature) and signature[index] != ">":
            start = index
            while (
                index < len(signature)
                and (
                    signature[index].isalnum()
                    or signature[index] in "_$"
                )
            ):
                index += 1
            if start == index or index >= len(signature):
                return None
            name = signature[start:index]
            if signature[index] != ":":
                return None
            names.append(name)

            while index < len(signature) and signature[index] == ":":
                index += 1
                if index >= len(signature):
                    return None
                if signature[index] == ":":
                    continue
                next_index = skip_field_type(index)
                if next_index is None:
                    return None
                index = next_index

        if index >= len(signature) or signature[index] != ">":
            return None
        return names, index + 1

    def direct_super_bindings(
        *,
        owner: str,
        bindings: dict[str, str],
        super_owner: str,
    ) -> dict[str, str] | None:
        current_profile = owner_profile(owner)
        super_profile = owner_profile(super_owner)
        if current_profile is None or super_profile is None:
            return None

        super_signature = str(
            super_profile.get("signature") or ""
        )
        formal_result = class_type_parameters(
            super_signature
        )
        if formal_result is None:
            return None
        super_formals = formal_result[0]
        if not super_formals:
            return {}

        signature = str(
            current_profile.get("signature") or ""
        )
        if not signature:
            return None
        current_formals = class_type_parameters(signature)
        if current_formals is None:
            return None
        index = current_formals[1]

        prefix = "L" + super_owner
        if not signature.startswith(prefix, index):
            return None
        index += len(prefix)
        if index >= len(signature) or signature[index] != "<":
            return None
        index += 1

        actuals: list[str] = []
        while index < len(signature) and signature[index] != ">":
            token = signature[index]
            if token == "L":
                end = signature.find(";", index + 1)
                if end < 0:
                    return None
                raw = signature[index + 1:end]
                if "<" in raw or ">" in raw:
                    return None
                actuals.append(raw)
                index = end + 1
                continue
            if token == "T":
                end = signature.find(";", index + 1)
                if end < 0:
                    return None
                variable = signature[index + 1:end]
                resolved = bindings.get(variable)
                if resolved is None:
                    return None
                actuals.append(resolved)
                index = end + 1
                continue
            return None

        if (
            index >= len(signature)
            or signature[index] != ">"
            or index + 1 >= len(signature)
            or signature[index + 1] != ";"
            or len(actuals) != len(super_formals)
        ):
            return None
        return dict(zip(super_formals, actuals))

    variable_field_re = re.compile(
        r"^Lgnu/trove/f/b/cc<T(?P<variable>"
        r"[A-Za-z_$][A-Za-z0-9_$]*)"
        r";>;$"
    )
    concrete_field_re = re.compile(
        r"^Lgnu/trove/f/b/cc<L(?P<value>[^;<>]+);>;$"
    )

    def resolve_inherited_field(
        field_name: str,
    ) -> dict[str, Any] | None:
        owner = current_owner
        bindings: dict[str, str] = {}
        hierarchy_path: list[str] = []
        seen: set[str] = set()

        while owner and owner not in seen and len(seen) < 64:
            seen.add(owner)
            hierarchy_path.append(owner)
            parsed_profile = owner_profile(owner)
            parsed_class = owner_class(owner)
            if parsed_profile is None or parsed_class is None:
                return None

            named_fields = [
                field
                for field in parsed_profile.get("fields", [])
                if field.get("name") == field_name
            ]
            if named_fields:
                if owner == current_owner or len(named_fields) != 1:
                    return None
                field = named_fields[0]
                if (
                    field.get("descriptor")
                    != "Lgnu/trove/f/b/cc;"
                    or (int(field.get("access", 0)) & 0x0008)
                    or not _field_visible_from(
                        declaring_owner=owner,
                        current_owner=current_owner,
                        access=int(field.get("access", 0)),
                    )
                ):
                    return None
                signature = str(field.get("signature") or "")
                generic_value: str | None = None
                concrete = concrete_field_re.fullmatch(signature)
                if concrete is not None:
                    generic_value = concrete.group("value")
                else:
                    variable = variable_field_re.fullmatch(signature)
                    if variable is None:
                        return None
                    generic_value = bindings.get(
                        variable.group("variable")
                    )
                if generic_value is None:
                    return None
                try:
                    readable_zip.getinfo(
                        generic_value + ".class"
                    )
                except KeyError:
                    if not generic_value.startswith("java/"):
                        return None
                return {
                    "declaring_owner": owner,
                    "field_name": field_name,
                    "field_descriptor": str(
                        field.get("descriptor", "")
                    ),
                    "field_signature": signature,
                    "generic_value": generic_value,
                    "allowed_field_owners": tuple(
                        hierarchy_path
                    ),
                    "hierarchy_path": tuple(hierarchy_path),
                    "substitutions": dict(bindings),
                }

            super_owner = parsed_class.super_name
            if not super_owner or super_owner == "java/lang/Object":
                return None
            next_bindings = direct_super_bindings(
                owner=owner,
                bindings=bindings,
                super_owner=super_owner,
            )
            if next_bindings is None:
                return None
            owner = super_owner
            bindings = next_bindings

        return None

    full_hierarchy: list[str] = []
    owner = current_owner
    seen: set[str] = set()
    while owner and owner not in seen and len(seen) < 64:
        seen.add(owner)
        full_hierarchy.append(owner)
        parsed = owner_class(owner)
        if parsed is None:
            return []
        owner = parsed.super_name
        if owner == "java/lang/Object":
            full_hierarchy.append(owner)
            break
    full_hierarchy_set = set(full_hierarchy)

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    call_re = re.compile(
        r"this\.(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\.\s*a\s*\(\s*"
        r"(?P<first>[^,\n]+?)\s*,\s*"
        r"(?P<cast>\(\s*Object\s*\)\s*)"
        r"this\.(?P<value_method>"
        r"[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\(\s*(?P<value_args>[^()\n]*)\s*\)"
    )

    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(
                whole_code,
                brace_start,
            )
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_text = text[method_start:body_end]
        calls: list[dict[str, Any]] = []

        for call in call_re.finditer(method_text):
            field = resolve_inherited_field(
                call.group("field")
            )
            if field is None:
                continue
            value_args = call.group("value_args")
            calls.append(
                {
                    "match": call,
                    **field,
                    "value_method": call.group(
                        "value_method"
                    ),
                    "value_arg_count": (
                        0
                        if not value_args.strip()
                        else _source_parameter_count(
                            value_args
                        )
                    ),
                }
            )

        if not calls:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[
                    method_match.start():brace_start
                ],
            )
        )
        if source_static:
            continue

        exact_candidates: list[dict[str, Any]] = []
        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(
                exact_method.get("descriptor", "")
            )
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
                or (int(exact_method.get("access", 0)) & 0x0008)
            ):
                continue

            instructions = list(
                exact_method.get("instructions", [])
            )
            flows: list[dict[str, Any]] = []

            for index, field_access in enumerate(instructions):
                if not (
                    field_access.get("mnemonic") == "getfield"
                    and field_access.get("descriptor")
                    == "Lgnu/trove/f/b/cc;"
                ):
                    continue

                possible_calls = [
                    call
                    for call in calls
                    if (
                        field_access.get("name")
                        == call["field_name"]
                        and field_access.get("owner")
                        in call["allowed_field_owners"]
                    )
                ]
                if not possible_calls or index == 0:
                    continue
                receiver_load = instructions[index - 1]
                if not (
                    receiver_load.get("mnemonic") == "aload"
                    and int(
                        receiver_load.get("local_index", -1)
                    ) == 0
                ):
                    continue

                target_index: int | None = None
                for probe in range(
                    index + 1,
                    min(len(instructions), index + 48),
                ):
                    item = instructions[probe]
                    if (
                        item.get("mnemonic")
                        in {"invokevirtual", "invokeinterface"}
                        and item.get("owner")
                        == "gnu/trove/f/b/cc"
                        and item.get("name") == "a"
                        and item.get("descriptor")
                        == "(ILjava/lang/Object;)Ljava/lang/Object;"
                    ):
                        target_index = probe
                        break
                if target_index is None:
                    continue

                segment = instructions[
                    index + 1:target_index
                ]
                proven_calls: list[
                    tuple[dict[str, Any], dict[str, Any]]
                ] = []
                for call in possible_calls:
                    method_invocations = [
                        item
                        for item in segment
                        if (
                            item.get("mnemonic")
                            == "invokevirtual"
                            and item.get("owner")
                            in full_hierarchy_set
                            and item.get("name")
                            == call["value_method"]
                            and _descriptor_parameter_count(
                                str(
                                    item.get(
                                        "descriptor",
                                        "",
                                    )
                                )
                            )
                            == call["value_arg_count"]
                            and _descriptor_return_descriptor(
                                str(
                                    item.get(
                                        "descriptor",
                                        "",
                                    )
                                )
                            )
                            == (
                                "L"
                                + call["generic_value"]
                                + ";"
                            )
                        )
                    ]
                    if len(method_invocations) != 1:
                        continue
                    invocation = method_invocations[0]
                    invocation_index = segment.index(
                        invocation
                    )
                    if not any(
                        item.get("mnemonic") == "aload"
                        and int(
                            item.get("local_index", -1)
                        ) == 0
                        for item in segment[
                            :invocation_index
                        ]
                    ):
                        continue
                    if any(
                        item.get("mnemonic") == "checkcast"
                        and item.get("type")
                        == call["generic_value"]
                        for item in segment[
                            invocation_index + 1:
                        ]
                    ):
                        continue
                    proven_calls.append(
                        (call, invocation)
                    )

                if len(proven_calls) != 1:
                    continue
                call, invocation = proven_calls[0]
                flows.append(
                    {
                        "field_owner": str(
                            field_access.get("owner", "")
                        ),
                        "field_name": call["field_name"],
                        "field_declaring_owner": call[
                            "declaring_owner"
                        ],
                        "field_signature": call[
                            "field_signature"
                        ],
                        "generic_value": call[
                            "generic_value"
                        ],
                        "hierarchy_path": list(
                            call["hierarchy_path"]
                        ),
                        "substitutions": call[
                            "substitutions"
                        ],
                        "value_method": call[
                            "value_method"
                        ],
                        "value_arg_count": call[
                            "value_arg_count"
                        ],
                        "value_invoke_owner": str(
                            invocation.get("owner", "")
                        ),
                        "value_invoke_descriptor": str(
                            invocation.get(
                                "descriptor", ""
                            )
                        ),
                        "field_offset": int(
                            field_access.get(
                                "offset", -1
                            )
                        ),
                        "value_invoke_offset": int(
                            invocation.get(
                                "offset", -1
                            )
                        ),
                        "cc_invoke_offset": int(
                            instructions[target_index].get(
                                "offset", -1
                            )
                        ),
                    }
                )

            source_proofs = [
                (
                    call["declaring_owner"],
                    call["field_name"],
                    call["generic_value"],
                    call["value_method"],
                    call["value_arg_count"],
                )
                for call in calls
            ]
            exact_proofs = [
                (
                    flow["field_declaring_owner"],
                    flow["field_name"],
                    flow["generic_value"],
                    flow["value_method"],
                    flow["value_arg_count"],
                )
                for flow in flows
            ]
            if exact_proofs != source_proofs:
                continue

            exact_candidates.append(
                {
                    "method": exact_method,
                    "flows": flows,
                }
            )

        if len(exact_candidates) != 1:
            continue

        proof = exact_candidates[0]
        for call in calls:
            match = call["match"]
            edits.append(
                (
                    method_start + match.start("cast"),
                    method_start + match.end("cast"),
                    "",
                )
            )

        actions.append(
            {
                "kind": "cc_generic_value_object_cast_removal",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof[
                    "method"
                ]["descriptor"],
                "fields": [
                    "this." + call["field_name"]
                    for call in calls
                ],
                "generic_value_types": [
                    call["generic_value"]
                    for call in calls
                ],
                "value_kinds": [
                    "method_call" for _ in calls
                ],
                "receiver_authority": (
                    "inherited_generic_hierarchy"
                ),
                "flows": proof["flows"],
                "replacement_count": len(calls),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_erased_inherited_cc_generic_value_object_cast"
                    ),
                    "strategy": (
                        "exact_super_signature_substitution_plus_method_return"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping inherited cc<T> Object-cast edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



def _normalize_direct_generic_factory_target_inference_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Remove parameterized casts that defeat direct generic factory inference.

    The repair is intentionally narrow.  Source must assign a zero-argument
    static generic factory directly into a parameterized instance field while
    wrapping the factory result in the same parameterized raw type.  Exact
    field Signature authority must prove both concrete type arguments, the
    factory Signature must be exactly a two-variable Object-bounded generic
    factory returning that raw type, and caller bytecode must prove one direct
    invokestatic -> putfield flow per edited source occurrence.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)

    imports: dict[str, str] = {}
    duplicate_imports: set[str] = set()
    for import_match in _SINGLE_TYPE_IMPORT_RE.finditer(text):
        dotted = import_match.group("name")
        simple = dotted.rsplit(".", 1)[-1]
        internal = dotted.replace(".", "/")
        previous = imports.get(simple)
        if previous is not None and previous != internal:
            duplicate_imports.add(simple)
        else:
            imports[simple] = internal
    for simple in duplicate_imports:
        imports.pop(simple, None)

    owner_cache: dict[str, dict[str, Any]] = {
        current_owner: profile,
    }

    def owner_profile(owner: str) -> dict[str, Any] | None:
        cached = owner_cache.get(owner)
        if cached is not None:
            return cached
        try:
            parsed = profile_class_field_accesses(
                readable_zip.read(owner + ".class")
            )
        except (KeyError, BytecodeProfileError):
            return None
        if str(parsed.get("internal_name", "")) != owner:
            return None
        owner_cache[owner] = parsed
        return parsed

    def class_exists(owner: str) -> bool:
        if owner.startswith("java/"):
            return True
        try:
            readable_zip.getinfo(owner + ".class")
            return True
        except KeyError:
            return False

    def resolve_source_ref(type_text: str) -> str | None:
        value = re.sub(r"\s+", "", type_text)
        if "<" in value:
            value = value.split("<", 1)[0]
        while value.endswith("[]"):
            value = value[:-2]
        if not re.fullmatch(
            r"[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)*",
            value,
        ):
            return None
        if value in imports:
            return imports[value]
        if "." in value:
            candidate = value.replace(".", "/")
            return candidate if class_exists(candidate) else None
        nested = current_owner + "$" + value
        if class_exists(nested):
            return nested
        same_package = (
            current_package + "/" + value
            if current_package
            else value
        )
        if class_exists(same_package):
            return same_package
        java_lang = "java/lang/" + value
        if class_exists(java_lang):
            return java_lang
        return None

    def consume_signature_type(
        signature: str,
        start: int,
    ) -> int | None:
        if start >= len(signature):
            return None
        token = signature[start]
        if token in "+-":
            return consume_signature_type(signature, start + 1)
        if token == "*":
            return start + 1
        if token == "T":
            end = signature.find(";", start + 1)
            return None if end < 0 else end + 1
        if token == "[":
            return consume_signature_type(signature, start + 1)
        if token != "L":
            return None
        depth = 0
        index = start + 1
        while index < len(signature):
            ch = signature[index]
            if ch == "<":
                depth += 1
            elif ch == ">":
                if depth == 0:
                    return None
                depth -= 1
            elif ch == ";" and depth == 0:
                return index + 1
            index += 1
        return None

    def field_signature_arguments(
        signature: str,
        raw_owner: str,
    ) -> list[str] | None:
        prefix = "L" + raw_owner + "<"
        if not (signature.startswith(prefix) and signature.endswith(">;")):
            return None
        body = signature[len(prefix):-2]
        arguments: list[str] = []
        index = 0
        while index < len(body):
            end = consume_signature_type(body, index)
            if end is None or end <= index:
                return None
            arguments.append(body[index:end])
            index = end
        return arguments if len(arguments) == 2 else None

    def signature_erasure_owner(signature: str) -> str | None:
        value = signature
        while value and value[0] in "+-":
            value = value[1:]
        if not value.startswith("L") or not value.endswith(";"):
            return None
        body = value[1:-1]
        generic = body.find("<")
        owner = body if generic < 0 else body[:generic]
        return owner if owner and class_exists(owner) else None

    def field_proof(
        *,
        field_name: str,
        source_raw: str,
        source_args: list[str],
    ) -> dict[str, Any] | None:
        fields = [
            field
            for field in profile.get("fields", [])
            if (
                field.get("name") == field_name
                and not (int(field.get("access", 0)) & 0x0008)
                and isinstance(field.get("signature"), str)
            )
        ]
        if len(fields) != 1:
            return None
        field = fields[0]
        descriptor = str(field.get("descriptor", ""))
        if not (
            descriptor.startswith("L")
            and descriptor.endswith(";")
        ):
            return None
        raw_owner = descriptor[1:-1]
        if resolve_source_ref(source_raw) != raw_owner:
            return None

        signature = str(field.get("signature") or "")
        exact_args = field_signature_arguments(signature, raw_owner)
        if exact_args is None or len(source_args) != 2:
            return None
        exact_arg_owners = [
            signature_erasure_owner(argument)
            for argument in exact_args
        ]
        source_arg_owners = [
            resolve_source_ref(argument)
            for argument in source_args
        ]
        if (
            any(owner is None for owner in exact_arg_owners)
            or source_arg_owners != exact_arg_owners
        ):
            return None

        return {
            "field_name": field_name,
            "descriptor": descriptor,
            "signature": signature,
            "raw_owner": raw_owner,
            "exact_argument_signatures": exact_args,
            "exact_argument_owners": exact_arg_owners,
        }

    def factory_proof(
        *,
        raw_owner: str,
        factory_name: str,
    ) -> dict[str, Any] | None:
        parsed = owner_profile(raw_owner)
        if parsed is None:
            return None
        rows = [
            method
            for method in parsed.get("methods", [])
            if (
                method.get("name") == factory_name
                and method.get("descriptor") == "()L" + raw_owner + ";"
                and int(method.get("access", 0)) & 0x0008
                and isinstance(method.get("signature"), str)
            )
        ]
        if len(rows) != 1:
            return None
        signature = str(rows[0].get("signature") or "")
        match = re.fullmatch(
            r"<(?P<t1>[A-Za-z_$][A-Za-z0-9_$]*):"
            r"Ljava/lang/Object;"
            r"(?P<t2>[A-Za-z_$][A-Za-z0-9_$]*):"
            r"Ljava/lang/Object;>"
            r"\(\)L"
            + re.escape(raw_owner)
            + r"<T(?P=t1);T(?P=t2);>;",
            signature,
        )
        if match is None or match.group("t1") == match.group("t2"):
            return None
        return {
            "owner": raw_owner,
            "name": factory_name,
            "descriptor": "()L" + raw_owner + ";",
            "signature": signature,
            "type_variables": [
                match.group("t1"),
                match.group("t2"),
            ],
        }

    start_re = re.compile(
        r"this\s*\.\s*(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*=\s*"
        r"(?P<cast_open>\(\s*)"
        r"(?P<raw>[A-Za-z_$][A-Za-z0-9_$.]*)\s*"
        r"(?P<angle><)"
    )
    tail_re = re.compile(
        r"(?P<cast_close>\s*\))\s*"
        r"(?P<factory_owner>[A-Za-z_$][A-Za-z0-9_$.]*)"
        r"\s*\.\s*"
        r"(?P<factory>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\(\s*\)\s*;"
    )

    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    # Procyon also emits this impossible cast in Java constructors.
    # Method-only scanning cannot reach <init> even when the exact readable
    # class proves an aload_0 -> generic invokestatic -> putfield flow.
    # Restrict constructor matches to the current top-level class: never
    # infer a nested class constructor from its surrounding source file.
    constructor_simple = current_owner.rsplit("/", 1)[-1].rsplit("$", 1)[-1]
    constructor_re = re.compile(
        r"(?m)^[ \\t]*(?:(?:public|private|protected)\\s+)?"
        + re.escape(constructor_simple)
        + r"\\s*\\((?P<params>[^()\\n]*)\\)\\s*"
        r"(?:throws\\s+[^\\{\\n]+\\s*)?\\{"
    )
    constructors = [
        match
        for match in constructor_re.finditer(whole_code)
        if _brace_depth_before(whole_code, match.start()) == 1
    ]
    source_declarations = [
        (match, match.group("name"))
        for match in _METHOD_DECL_RE.finditer(whole_code)
        if not any(
            match.start() == ctor.start() and match.end() == ctor.end()
            for ctor in constructors
        )
    ]
    source_declarations.extend((match, "<init>") for match in constructors)
    source_declarations.sort(key=lambda pair: pair[0].start())

    for method_match, source_method_name in source_declarations:
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        method_text = text[method_start:body_end]
        occurrences: list[dict[str, Any]] = []

        for match in start_re.finditer(method_code):
            angle_start = match.start("angle")
            angle_end = _matching_generic_angle_end(
                method_code,
                angle_start,
            )
            if angle_end is None:
                continue

            args_text = method_text[angle_start + 1:angle_end]
            spans = _top_level_generic_argument_spans(args_text)
            if spans is None or len(spans) != 2:
                continue
            source_args = [
                args_text[left:right].strip()
                for left, right in spans
            ]

            tail = method_code[angle_end + 1:]
            tail_match = tail_re.match(tail)
            if tail_match is None:
                continue

            field = field_proof(
                field_name=match.group("field"),
                source_raw=match.group("raw"),
                source_args=source_args,
            )
            if field is None:
                continue
            factory_owner = resolve_source_ref(
                tail_match.group("factory_owner")
            )
            if factory_owner != field["raw_owner"]:
                continue
            factory = factory_proof(
                raw_owner=field["raw_owner"],
                factory_name=tail_match.group("factory"),
            )
            if factory is None:
                continue

            occurrences.append(
                {
                    "field": field,
                    "factory": factory,
                    "cast_start": (
                        method_start + match.start("cast_open")
                    ),
                    "cast_end": (
                        method_start
                        + angle_end
                        + 1
                        + tail_match.end("cast_close")
                    ),
                }
            )

        if not occurrences:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        if source_static:
            continue

        exact_candidates: list[dict[str, Any]] = []
        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != source_method_name:
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if int(exact_method.get("access", 0)) & 0x0008:
                continue

            instructions = list(exact_method.get("instructions", []))
            flows: list[dict[str, Any]] = []
            used_store_offsets: set[int] = set()

            for occurrence in occurrences:
                field = occurrence["field"]
                factory = occurrence["factory"]
                matches: list[dict[str, Any]] = []
                for index in range(1, len(instructions) - 1):
                    receiver = instructions[index - 1]
                    call = instructions[index]
                    store = instructions[index + 1]
                    if not (
                        receiver.get("mnemonic") == "aload"
                        and int(receiver.get("local_index", -1)) == 0
                        and call.get("mnemonic") == "invokestatic"
                        and call.get("owner") == factory["owner"]
                        and call.get("name") == factory["name"]
                        and call.get("descriptor")
                        == factory["descriptor"]
                        and store.get("mnemonic") == "putfield"
                        and store.get("owner") == current_owner
                        and store.get("name") == field["field_name"]
                        and store.get("descriptor")
                        == field["descriptor"]
                    ):
                        continue
                    matches.append(
                        {
                            "factory_offset": int(
                                call.get("offset", -1)
                            ),
                            "store_offset": int(
                                store.get("offset", -1)
                            ),
                            "field_name": field["field_name"],
                            "factory_owner": factory["owner"],
                            "factory_name": factory["name"],
                            "factory_descriptor": factory["descriptor"],
                            "factory_signature": factory["signature"],
                        }
                    )

                if len(matches) != 1:
                    flows = []
                    break
                if matches[0]["store_offset"] in used_store_offsets:
                    flows = []
                    break
                used_store_offsets.add(matches[0]["store_offset"])
                flows.append(matches[0])

            if len(flows) == len(occurrences):
                exact_candidates.append(
                    {
                        "method": exact_method,
                        "flows": flows,
                    }
                )

        if len(exact_candidates) != 1:
            continue

        proof = exact_candidates[0]
        for occurrence in occurrences:
            edits.append(
                (
                    int(occurrence["cast_start"]),
                    int(occurrence["cast_end"]),
                    "",
                )
            )

        actions.append(
            {
                "kind": "generic_builder_target_inference_cast_removal",
                "mode": "direct_static_factory",
                "source_path": rel,
                "method_name": source_method_name,
                "method_descriptor": proof["method"]["descriptor"],
                "field_names": [
                    occurrence["field"]["field_name"]
                    for occurrence in occurrences
                ],
                "field_signatures": [
                    occurrence["field"]["signature"]
                    for occurrence in occurrences
                ],
                "factory_signatures": [
                    occurrence["factory"]["signature"]
                    for occurrence in occurrences
                ],
                "exact_flows": proof["flows"],
                "replacement_count": len(occurrences),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_parameterized_cast_blocks_direct_generic_"
                        "factory_target_inference"
                    ),
                    "strategy": (
                        "exact_field_signature_plus_generic_factory_signature_"
                        "plus_invokestatic_putfield_flow"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping direct generic factory edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_generic_builder_target_inference_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Remove source-only parameterized casts that block target inference.

    Some decompiler output wraps a generic terminal builder invocation in an
    explicit parameterized cast.  That cast removes assignment-context target
    typing, causing javac to infer the terminal method at its broad receiver
    bounds and then reject the cast.  Remove only the outer cast when exact
    field Signature authority and exact invoke->putfield bytecode prove the
    assignment target, while the builder chain proves Object/Object receiver
    bounds flowing through a preserving method into a two-variable generic
    terminal method.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    current_simple = current_owner.rsplit("/", 1)[-1]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)

    imports: dict[str, str] = {}
    duplicate_imports: set[str] = set()
    for import_match in _SINGLE_TYPE_IMPORT_RE.finditer(text):
        dotted = import_match.group("name")
        simple = dotted.rsplit(".", 1)[-1]
        internal = dotted.replace(".", "/")
        previous = imports.get(simple)
        if previous is not None and previous != internal:
            duplicate_imports.add(simple)
        else:
            imports[simple] = internal
    for simple in duplicate_imports:
        imports.pop(simple, None)

    def class_exists(internal: str) -> bool:
        if internal.startswith("java/"):
            return True
        try:
            readable_zip.getinfo(internal + ".class")
            return True
        except KeyError:
            return False

    def resolve_source_ref(value: str) -> str | None:
        name = value.strip()
        if not re.fullmatch(
            r"[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)*",
            name,
        ):
            return None
        if name == "Object":
            return "java/lang/Object"
        if name in imports:
            return imports[name]
        if "." in name:
            internal = name.replace(".", "/")
            return internal if class_exists(internal) else None
        same_package = current_package + "/" + name if current_package else name
        if class_exists(same_package):
            return same_package
        java_lang = "java/lang/" + name
        if class_exists(java_lang):
            return java_lang
        return None

    field_proofs: dict[str, dict[str, Any]] = {}
    field_sig_re = re.compile(
        r"^L(?P<raw>[^;<]+)<"
        r"L(?P<arg1>[^;<]+);"
        r"L(?P<arg2>[^;<]+);"
        r">;$"
    )
    for field in profile.get("fields", []):
        if int(field.get("access", 0)) & 0x0008:
            continue
        signature = field.get("signature")
        descriptor = str(field.get("descriptor", ""))
        if not isinstance(signature, str):
            continue
        match = field_sig_re.fullmatch(signature)
        if match is None:
            continue
        raw = match.group("raw")
        if descriptor != "L" + raw + ";":
            continue
        if not all(
            class_exists(owner)
            for owner in (raw, match.group("arg1"), match.group("arg2"))
        ):
            continue
        field_proofs[str(field.get("name", ""))] = {
            "raw": raw,
            "arg1": match.group("arg1"),
            "arg2": match.group("arg2"),
            "descriptor": descriptor,
            "signature": signature,
        }
    if not field_proofs:
        return []

    owner_profiles: dict[str, dict[str, Any]] = {}

    def owner_profile(owner: str) -> dict[str, Any] | None:
        cached = owner_profiles.get(owner)
        if cached is not None:
            return cached
        try:
            parsed = profile_class_field_accesses(
                readable_zip.read(owner + ".class")
            )
        except (KeyError, BytecodeProfileError):
            return None
        if str(parsed.get("internal_name", "")) != owner:
            return None
        owner_profiles[owner] = parsed
        return parsed

    def exact_method_row(
        owner: str,
        name: str,
        descriptor: str,
    ) -> dict[str, Any] | None:
        parsed = owner_profile(owner)
        if parsed is None:
            return None
        rows = [
            row
            for row in parsed.get("methods", [])
            if (
                row.get("name") == name
                and row.get("descriptor") == descriptor
            )
        ]
        return rows[0] if len(rows) == 1 else None

    assignment_re = re.compile(
        r"this\s*\.\s*(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*=\s*"
        r"(?P<cast>\(\s*"
        r"(?P<raw>[A-Za-z_$][A-Za-z0-9_$.]*)\s*<\s*"
        r"(?P<arg1>[A-Za-z_$][A-Za-z0-9_$.]*)\s*,\s*"
        r"(?P<arg2>[A-Za-z_$][A-Za-z0-9_$.]*)\s*>\s*\))"
        r"\s*(?P<chain>"
        r"(?P<factory_owner>[A-Za-z_$][A-Za-z0-9_$.]*)"
        r"\s*\.\s*(?P<factory_name>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\(\s*\)"
        r"[^;\n]*?"
        r"\.\s*(?P<terminal>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\(\s*\)"
        r")\s*;"
    )

    constructor_re = re.compile(
        r"(?m)^(?P<indent>[ \t]*)"
        r"(?:(?:public|private|protected)\s+)*"
        + re.escape(current_simple)
        + r"\s*\((?P<params>[^()\n]*)\)\s*"
        r"(?:throws\s+[^\{\n]+\s*)?\{"
    )
    source_blocks: list[tuple[re.Match[str], str]] = [
        (match, match.group("name"))
        for match in _METHOD_DECL_RE.finditer(whole_code)
    ]
    source_blocks.extend(
        (match, "<init>")
        for match in constructor_re.finditer(whole_code)
    )
    source_blocks.sort(key=lambda row: row[0].start())

    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for block_match, exact_name in source_blocks:
        brace_start = whole_code.find(
            "{", block_match.start(), block_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        block_start = block_match.start()
        method_text = text[block_start:body_end]
        method_code = whole_code[block_start:body_end]
        occurrences: list[dict[str, Any]] = []

        for match in assignment_re.finditer(method_code):
            field_name = match.group("field")
            field = field_proofs.get(field_name)
            if field is None:
                continue
            raw = resolve_source_ref(match.group("raw"))
            arg1 = resolve_source_ref(match.group("arg1"))
            arg2 = resolve_source_ref(match.group("arg2"))
            factory_owner = resolve_source_ref(match.group("factory_owner"))
            if (
                raw != field["raw"]
                or arg1 != field["arg1"]
                or arg2 != field["arg2"]
                or factory_owner is None
            ):
                continue

            chain = method_text[match.start("chain"):match.end("chain")]
            source_method_names = re.findall(
                r"\.\s*([A-Za-z_$][A-Za-z0-9_$]*)\s*\(",
                chain,
            )
            if len(source_method_names) < 2:
                continue
            occurrences.append(
                {
                    "field_name": field_name,
                    "field": field,
                    "factory_owner": factory_owner,
                    "factory_name": match.group("factory_name"),
                    "terminal_name": match.group("terminal"),
                    "source_method_names": source_method_names,
                    "cast_start": block_start + match.start("cast"),
                    "cast_end": block_start + match.end("cast"),
                }
            )

        if not occurrences:
            continue

        source_static = (
            exact_name != "<init>"
            and bool(
                re.search(
                    r"\bstatic\b",
                    whole_code[block_match.start():brace_start],
                )
            )
        )
        exact_candidates: list[dict[str, Any]] = []

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != exact_name:
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    block_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if exact_name != "<init>" and (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            instructions = list(exact_method.get("instructions", []))
            flows: list[dict[str, Any]] = []
            used_store_offsets: set[int] = set()

            for occurrence in occurrences:
                field = occurrence["field"]
                matches: list[dict[str, Any]] = []

                for store_index, store in enumerate(instructions):
                    if not (
                        store.get("mnemonic") == "putfield"
                        and store.get("owner") == current_owner
                        and store.get("name") == occurrence["field_name"]
                        and store.get("descriptor") == field["descriptor"]
                        and store_index > 0
                    ):
                        continue
                    terminal_index = store_index - 1
                    terminal = instructions[terminal_index]
                    if not (
                        terminal.get("mnemonic")
                        in {"invokevirtual", "invokeinterface"}
                        and terminal.get("name")
                        == occurrence["terminal_name"]
                        and terminal.get("descriptor")
                        == "()" + field["descriptor"]
                    ):
                        continue
                    terminal_owner = str(terminal.get("owner", ""))
                    terminal_method = exact_method_row(
                        terminal_owner,
                        occurrence["terminal_name"],
                        "()" + field["descriptor"],
                    )
                    if terminal_method is None:
                        continue
                    terminal_signature = str(
                        terminal_method.get("signature") or ""
                    )
                    generic_match = re.fullmatch(
                        r"<(?P<t1>[A-Za-z_$][A-Za-z0-9_$]*):"
                        r"T(?P<b1>[A-Za-z_$][A-Za-z0-9_$]*);"
                        r"(?P<t2>[A-Za-z_$][A-Za-z0-9_$]*):"
                        r"T(?P<b2>[A-Za-z_$][A-Za-z0-9_$]*);>"
                        r"\(\)L"
                        + re.escape(field["raw"])
                        + r"<T(?P=t1);T(?P=t2);>;",
                        terminal_signature,
                    )
                    if generic_match is None:
                        continue

                    preserve_index: int | None = None
                    for probe in range(terminal_index - 1, -1, -1):
                        item = instructions[probe]
                        if (
                            item.get("mnemonic")
                            in {"invokevirtual", "invokeinterface"}
                            and item.get("owner") == terminal_owner
                            and str(item.get("descriptor", "")).endswith(
                                "L" + terminal_owner + ";"
                            )
                        ):
                            preserve_index = probe
                            break
                    if preserve_index is None:
                        continue
                    preserve = instructions[preserve_index]
                    preserve_method = exact_method_row(
                        terminal_owner,
                        str(preserve.get("name", "")),
                        str(preserve.get("descriptor", "")),
                    )
                    if preserve_method is None:
                        continue
                    preserve_signature = str(
                        preserve_method.get("signature") or ""
                    )
                    expected_preserve_return = (
                        "L"
                        + terminal_owner
                        + "<T"
                        + generic_match.group("b1")
                        + ";T"
                        + generic_match.group("b2")
                        + ";>;"
                    )
                    if not preserve_signature.endswith(
                        ")" + expected_preserve_return
                    ):
                        continue

                    factory_index: int | None = None
                    for probe in range(preserve_index - 1, -1, -1):
                        item = instructions[probe]
                        if (
                            item.get("mnemonic") == "invokestatic"
                            and item.get("owner") == terminal_owner
                            and str(item.get("descriptor", "")).endswith(
                                "L" + terminal_owner + ";"
                            )
                        ):
                            factory_index = probe
                            break
                    if factory_index is None:
                        continue
                    factory = instructions[factory_index]
                    if (
                        terminal_owner != occurrence["factory_owner"]
                        or str(factory.get("name", ""))
                        != occurrence["factory_name"]
                    ):
                        continue
                    factory_method = exact_method_row(
                        terminal_owner,
                        str(factory.get("name", "")),
                        str(factory.get("descriptor", "")),
                    )
                    if factory_method is None:
                        continue
                    factory_signature = str(
                        factory_method.get("signature") or ""
                    )
                    expected_factory_return = (
                        "L"
                        + terminal_owner
                        + "<Ljava/lang/Object;Ljava/lang/Object;>;"
                    )
                    if not factory_signature.endswith(
                        ")" + expected_factory_return
                    ):
                        continue

                    exact_names = [
                        str(factory.get("name", "")),
                        str(preserve.get("name", "")),
                        str(terminal.get("name", "")),
                    ]
                    if occurrence["source_method_names"][-3:] != exact_names:
                        continue

                    matches.append(
                        {
                            "store_offset": int(store.get("offset", -1)),
                            "factory_owner": terminal_owner,
                            "factory_name": exact_names[0],
                            "factory_descriptor": factory.get("descriptor"),
                            "factory_signature": factory_signature,
                            "preserve_name": exact_names[1],
                            "preserve_descriptor": preserve.get("descriptor"),
                            "preserve_signature": preserve_signature,
                            "terminal_name": exact_names[2],
                            "terminal_descriptor": terminal.get("descriptor"),
                            "terminal_signature": terminal_signature,
                        }
                    )

                if len(matches) != 1:
                    flows = []
                    break
                if matches[0]["store_offset"] in used_store_offsets:
                    flows = []
                    break
                used_store_offsets.add(matches[0]["store_offset"])
                flows.append(matches[0])

            if len(flows) == len(occurrences):
                exact_candidates.append(
                    {
                        "method": exact_method,
                        "flows": flows,
                    }
                )

        if len(exact_candidates) != 1:
            continue

        proof = exact_candidates[0]
        for occurrence in occurrences:
            edits.append(
                (
                    int(occurrence["cast_start"]),
                    int(occurrence["cast_end"]),
                    "",
                )
            )

        actions.append(
            {
                "kind": "generic_builder_target_inference_cast_removal",
                "source_path": rel,
                "method_name": exact_name,
                "method_descriptor": proof["method"]["descriptor"],
                "field_names": sorted(
                    {str(row["field_name"]) for row in occurrences}
                ),
                "field_signatures": sorted(
                    {str(row["field"]["signature"]) for row in occurrences}
                ),
                "exact_flows": proof["flows"],
                "replacement_count": len(occurrences),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_parameterized_cast_blocks_generic_target_inference"
                    ),
                    "strategy": (
                        "exact_generic_field_signature_plus_builder_invoke_store_flow"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping generic builder target-inference edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



def _normalize_cc_generic_value_object_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Remove impossible Object casts from cc<T>.a(int, T) calls.

    The JVM descriptor erases cc<V>.a(int,V) to Object, but source generic
    substitution still requires the concrete field type argument. Repair only
    when exact field Signature authority binds T and the value expression is
    independently proven to have that exact source type.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
        cc_profile = profile_class_field_accesses(
            readable_zip.read("gnu/trove/f/b/cc.class")
        )
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    current_simple = _source_simple_type_name(current_owner)
    current_dotted = current_owner.replace("/", ".")

    cc_methods = [
        method
        for method in cc_profile.get("methods", [])
        if (
            method.get("name") == "a"
            and method.get("descriptor")
            == "(ILjava/lang/Object;)Ljava/lang/Object;"
            and method.get("signature") == "(ITV;)TV;"
        )
    ]
    if len(cc_methods) != 1:
        return []

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)

    imports: dict[str, str] = {}
    duplicate_imports: set[str] = set()
    for import_match in _SINGLE_TYPE_IMPORT_RE.finditer(text):
        dotted = import_match.group("name")
        simple = dotted.rsplit(".", 1)[-1]
        internal = dotted.replace(".", "/")
        previous = imports.get(simple)
        if previous is not None and previous != internal:
            duplicate_imports.add(simple)
        else:
            imports[simple] = internal
    for simple in duplicate_imports:
        imports.pop(simple, None)

    def class_exists(internal: str) -> bool:
        try:
            readable_zip.getinfo(internal + ".class")
            return True
        except KeyError:
            return False

    def reference_type_known(internal: str) -> bool:
        return internal.startswith("java/") or class_exists(internal)

    def resolve_source_type(type_text: str) -> str | None:
        value = type_text.strip()
        value = re.sub(r"<.*>$", "", value).strip()
        while value.endswith("[]"):
            value = value[:-2].strip()
        if not re.fullmatch(
            r"[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)*",
            value,
        ):
            return None
        if value == current_simple or value == current_dotted:
            return current_owner
        if value in imports:
            return imports[value]
        if "." in value:
            candidate = value.replace(".", "/")
            return candidate if class_exists(candidate) else None
        same_package = (
            current_package + "/" + value
            if current_package
            else value
        )
        if class_exists(same_package):
            return same_package
        java_lang = "java/lang/" + value
        if reference_type_known(java_lang):
            return java_lang
        return None

    owner_cache: dict[str, dict[str, Any]] = {
        current_owner: profile,
        "gnu/trove/f/b/cc": cc_profile,
    }

    def owner_profile(owner: str) -> dict[str, Any] | None:
        cached = owner_cache.get(owner)
        if cached is not None:
            return cached
        try:
            parsed = profile_class_field_accesses(
                readable_zip.read(owner + ".class")
            )
        except (KeyError, BytecodeProfileError):
            return None
        if str(parsed.get("internal_name", "")) != owner:
            return None
        owner_cache[owner] = parsed
        return parsed

    field_signature_re = re.compile(
        r"^Lgnu/trove/f/b/cc<L(?P<value>[^;<>]+);>;$"
    )

    def resolve_receiver(
        receiver: str,
    ) -> tuple[str, str, str, bool] | None:
        owner_text, dot, field_name = receiver.rpartition(".")
        if not dot or not owner_text or not field_name:
            return None

        source_instance = owner_text == "this"
        if source_instance:
            owner = current_owner
        elif owner_text in {current_simple, current_dotted}:
            owner = current_owner
        elif owner_text in imports:
            owner = imports[owner_text]
        elif "." in owner_text:
            owner = owner_text.replace(".", "/")
        else:
            candidate = (
                current_package + "/" + owner_text
                if current_package
                else owner_text
            )
            if not class_exists(candidate):
                return None
            owner = candidate

        parsed = owner_profile(owner)
        if parsed is None:
            return None
        fields = [
            field
            for field in parsed.get("fields", [])
            if (
                field.get("name") == field_name
                and field.get("descriptor") == "Lgnu/trove/f/b/cc;"
                and bool(int(field.get("access", 0)) & 0x0008)
                == (not source_instance)
            )
        ]
        if len(fields) != 1:
            return None
        signature = fields[0].get("signature")
        if not isinstance(signature, str):
            return None
        match = field_signature_re.fullmatch(signature)
        if match is None:
            return None
        value_owner = match.group("value")
        if not reference_type_known(value_owner):
            return None
        return owner, field_name, value_owner, (not source_instance)

    def identifier_source_type(
        *,
        method_match: re.Match[str],
        method_text: str,
        before: int,
        identifier: str,
    ) -> str | None:
        candidates: list[str] = []

        parameter_names = _source_parameter_names(
            method_match.group("params")
        )
        parameter_spans = _parameter_type_spans(
            method_match.group("params")
        )
        if (
            parameter_names is not None
            and parameter_spans is not None
            and len(parameter_names) == len(parameter_spans)
        ):
            for name, (_left, _right, type_text) in zip(
                parameter_names, parameter_spans
            ):
                if name != identifier:
                    continue
                resolved = resolve_source_type(type_text)
                if resolved is not None:
                    candidates.append(resolved)

        prefix = method_text[:before]
        local_re = re.compile(
            r"(?m)(?:^|[;{}]\s*)[ \t]*"
            r"(?:(?:final)\s+)?"
            r"(?P<type>[A-Za-z_$][A-Za-z0-9_$.]*)\s+"
            + re.escape(identifier)
            + r"\b\s*(?:=|;)"
        )
        for local in local_re.finditer(prefix):
            resolved = resolve_source_type(local.group("type"))
            if resolved is not None:
                candidates.append(resolved)

        unique = sorted(set(candidates))
        return unique[0] if len(unique) == 1 else None

    call_re = re.compile(
        r"(?P<receiver>"
        r"(?:[A-Za-z_$][A-Za-z0-9_$]*\.)+"
        r"[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\.\s*a\s*\(\s*"
        r"(?P<first>[^\n]+)\s*,\s*"
        r"(?P<cast>\(\s*Object\s*\)\s*)"
        r"(?:"
        r"(?P<boolean>true|false)\b"
        r"|new\s+(?P<new_type>"
        r"[A-Za-z_$][A-Za-z0-9_$.]*)\s*\("
        r"|(?P<identifier>[A-Za-z_$][A-Za-z0-9_$]*)\b"
        r")"
    )

    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_text = text[method_start:body_end]
        method_code = whole_code[method_start:body_end]
        calls: list[dict[str, Any]] = []

        for call in call_re.finditer(method_text):
            if (
                call.start() >= len(method_code)
                or method_code[call.start()].isspace()
            ):
                continue

            resolved_receiver = resolve_receiver(
                call.group("receiver")
            )
            if resolved_receiver is None:
                continue
            (
                field_owner,
                field_name,
                generic_value,
                field_is_static,
            ) = resolved_receiver

            value_kind: str
            if call.group("boolean") is not None:
                if generic_value != "java/lang/Boolean":
                    continue
                value_kind = "boolean"
            elif call.group("new_type") is not None:
                resolved_new = resolve_source_type(
                    call.group("new_type")
                )
                if resolved_new != generic_value:
                    continue
                value_kind = "new"
            else:
                identifier = call.group("identifier")
                if identifier is None:
                    continue
                resolved_identifier = identifier_source_type(
                    method_match=method_match,
                    method_text=method_text,
                    before=call.start(),
                    identifier=identifier,
                )
                if resolved_identifier != generic_value:
                    continue
                value_kind = "identifier"

            calls.append(
                {
                    "match": call,
                    "field_owner": field_owner,
                    "field_name": field_name,
                    "generic_value": generic_value,
                    "field_is_static": field_is_static,
                    "value_kind": value_kind,
                }
            )

        if not calls:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        exact_candidates: list[dict[str, Any]] = []

        target_fields = {
            (
                call["field_owner"],
                call["field_name"],
                call["generic_value"],
                call["field_is_static"],
            )
            for call in calls
        }

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            instructions = list(exact_method.get("instructions", []))
            flows: list[dict[str, Any]] = []

            for index, field_access in enumerate(instructions):
                key = (
                    str(field_access.get("owner", "")),
                    str(field_access.get("name", "")),
                )
                matching = [
                    row
                    for row in target_fields
                    if row[0] == key[0] and row[1] == key[1]
                ]
                if not matching:
                    continue
                if len(matching) != 1:
                    continue
                generic_value = matching[0][2]
                field_is_static = bool(matching[0][3])
                expected_field_mnemonic = (
                    "getstatic" if field_is_static else "getfield"
                )
                if not (
                    field_access.get("mnemonic")
                    == expected_field_mnemonic
                    and field_access.get("descriptor")
                    == "Lgnu/trove/f/b/cc;"
                ):
                    continue
                if not field_is_static:
                    if index == 0:
                        continue
                    receiver_load = instructions[index - 1]
                    if not (
                        receiver_load.get("mnemonic") == "aload"
                        and int(receiver_load.get("local_index", -1)) == 0
                    ):
                        continue

                target_index: int | None = None
                for probe in range(
                    index + 1,
                    min(len(instructions), index + 33),
                ):
                    item = instructions[probe]
                    if (
                        item.get("mnemonic")
                        in {"invokevirtual", "invokeinterface"}
                        and item.get("owner") == "gnu/trove/f/b/cc"
                        and item.get("name") == "a"
                        and item.get("descriptor")
                        == "(ILjava/lang/Object;)Ljava/lang/Object;"
                    ):
                        target_index = probe
                        break
                if target_index is None:
                    continue

                segment = instructions[index + 1:target_index]
                value_kind: str | None = None

                if (
                    generic_value == "java/lang/Boolean"
                    and any(
                        item.get("mnemonic") == "invokestatic"
                        and item.get("owner") == "java/lang/Boolean"
                        and item.get("name") == "valueOf"
                        and item.get("descriptor")
                        == "(Z)Ljava/lang/Boolean;"
                        for item in segment
                    )
                ):
                    value_kind = "boolean"
                else:
                    new_indices = [
                        offset
                        for offset, item in enumerate(segment)
                        if (
                            item.get("mnemonic") == "new"
                            and item.get("type") == generic_value
                        )
                    ]
                    if len(new_indices) == 1:
                        new_index = new_indices[0]
                        if any(
                            item.get("mnemonic") == "invokespecial"
                            and item.get("owner") == generic_value
                            and item.get("name") == "<init>"
                            for item in segment[new_index + 1:]
                        ):
                            value_kind = "new"

                identifier_slot: int | None = None
                if value_kind is None:
                    aloads = [
                        item
                        for item in segment
                        if item.get("mnemonic") == "aload"
                    ]
                    if len(aloads) == 1:
                        value_kind = "identifier"
                        identifier_slot = int(
                            aloads[0].get("local_index", -1)
                        )
                    elif segment and segment[-1].get("mnemonic") == "aload":
                        candidate_slot = int(
                            segment[-1].get("local_index", -1)
                        )
                        if candidate_slot >= 0:
                            latest_store: int | None = None
                            for probe in range(index - 1, -1, -1):
                                item = instructions[probe]
                                if (
                                    item.get("mnemonic") == "astore"
                                    and int(
                                        item.get("local_index", -1)
                                    ) == candidate_slot
                                ):
                                    latest_store = probe
                                    break
                            if (
                                latest_store is not None
                                and latest_store > 0
                                and instructions[
                                    latest_store - 1
                                ].get("mnemonic") == "checkcast"
                                and instructions[
                                    latest_store - 1
                                ].get("type") == generic_value
                            ):
                                value_kind = "identifier"
                                identifier_slot = candidate_slot

                if value_kind is None:
                    continue

                flows.append(
                    {
                        "field_owner": key[0],
                        "field_name": key[1],
                        "generic_value": generic_value,
                        "field_is_static": field_is_static,
                        "value_kind": value_kind,
                        "identifier_slot": identifier_slot,
                        "field_offset": int(
                            field_access.get("offset", -1)
                        ),
                        "invoke_offset": int(
                            instructions[target_index].get(
                                "offset", -1
                            )
                        ),
                    }
                )

            source_proofs = [
                (
                    call["field_owner"],
                    call["field_name"],
                    call["generic_value"],
                    call["field_is_static"],
                    call["value_kind"],
                )
                for call in calls
            ]
            exact_proofs = [
                (
                    flow["field_owner"],
                    flow["field_name"],
                    flow["generic_value"],
                    flow["field_is_static"],
                    flow["value_kind"],
                )
                for flow in flows
            ]
            if exact_proofs != source_proofs:
                continue

            exact_candidates.append(
                {
                    "method": exact_method,
                    "flows": flows,
                }
            )

        if len(exact_candidates) != 1:
            continue

        proof = exact_candidates[0]
        for call in calls:
            match = call["match"]
            edits.append(
                (
                    method_start + match.start("cast"),
                    method_start + match.end("cast"),
                    "",
                )
            )

        actions.append(
            {
                "kind": "cc_generic_value_object_cast_removal",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "fields": [
                    call["field_owner"] + "." + call["field_name"]
                    for call in calls
                ],
                "generic_value_types": [
                    call["generic_value"] for call in calls
                ],
                "value_kinds": [
                    call["value_kind"] for call in calls
                ],
                "flows": proof["flows"],
                "replacement_count": len(calls),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_erased_cc_generic_value_object_cast"
                    ),
                    "strategy": (
                        "exact_field_signature_plus_method_signature_and_value_type"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping cc<T> Object-cast edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_erased_generic_constructor_argument_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Remove Procyon Object casts that break a proven generic key call.

    The JVM call is erased to Object, but source-level generic typing can make
    Procyon's explicit Object cast around new Key(...) illegal. Remove only
    that cast when the source field proves concrete key/value types and one
    exact readable method proves the same field access, constructor allocation,
    erased Object-to-Object call, and reference return type.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
    except KeyError:
        return []
    try:
        profile = profile_class_field_accesses(class_bytes)
    except BytecodeProfileError:
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]
    exact_fields = {
        str(field.get("name", "")): str(field.get("descriptor", ""))
        for field in profile.get("fields", [])
    }

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    field_re = re.compile(
        r"(?m)^[ \t]*(?:(?:public|private|protected|static|final)\s+)*"
        r"(?P<raw>[A-Za-z_$][A-Za-z0-9_$.]*)\s*<\s*"
        r"(?P<key>[A-Za-z_$][A-Za-z0-9_$]*)\s*,\s*"
        r"(?P<value>[A-Za-z_$][A-Za-z0-9_$]*)\s*>\s+"
        r"(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)\s*(?:=[^;\n]+)?;"
    )
    generic_fields: dict[str, tuple[str, str, str]] = {}
    for match in field_re.finditer(whole_code):
        field_name = match.group("field")
        field_descriptor = exact_fields.get(field_name)
        if not (
            field_descriptor is not None
            and field_descriptor.startswith("L")
            and field_descriptor.endswith(";")
        ):
            continue
        field_owner = field_descriptor[1:-1]
        raw_source_type = match.group("raw").rsplit(".", 1)[-1]
        if _source_simple_type_name(field_owner) != raw_source_type:
            continue
        generic_fields[field_name] = (
            match.group("key"),
            match.group("value"),
            field_owner,
        )
    if not generic_fields:
        return []

    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        call_re = re.compile(
            r"this\.(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)"
            r"\.(?P<member>[A-Za-z_$][A-Za-z0-9_$]*)\s*\(\s*"
            r"(?P<cast>\(\s*Object\s*\)\s*)"
            r"new\s+(?P<key>[A-Za-z_$][A-Za-z0-9_$]*)\s*\("
        )
        calls = [
            match
            for match in call_re.finditer(method_code)
            if match.group("field") in generic_fields
            and generic_fields[match.group("field")][0]
            == match.group("key")
        ]
        if not calls:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        candidates: list[dict[str, Any]] = []
        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            instructions = list(exact_method.get("instructions", []))
            exact_ok = True
            for call in calls:
                field_name = call.group("field")
                member = call.group("member")
                key_type, value_type, _field_owner = generic_fields[field_name]
                field_seen = any(
                    item.get("mnemonic") == "getfield"
                    and item.get("owner") == current_owner
                    and item.get("name") == field_name
                    for item in instructions
                )
                new_seen = any(
                    item.get("mnemonic") == "new"
                    and str(item.get("type", "")).rsplit("/", 1)[-1]
                    .rsplit("$", 1)[-1] == key_type
                    for item in instructions
                )
                erased_call_seen = any(
                    invocation.get("name") == member
                    and invocation.get("descriptor")
                    == "(Ljava/lang/Object;)Ljava/lang/Object;"
                    for invocation in exact_method.get(
                        "method_invocations", []
                    )
                )
                return_descriptor = _descriptor_return_descriptor(
                    descriptor
                )
                return_simple = ""
                if (
                    return_descriptor is not None
                    and return_descriptor.startswith("L")
                    and return_descriptor.endswith(";")
                ):
                    return_simple = (
                        return_descriptor[1:-1]
                        .rsplit("/", 1)[-1]
                        .rsplit("$", 1)[-1]
                    )
                if not (
                    field_seen
                    and new_seen
                    and erased_call_seen
                    and return_simple == value_type
                ):
                    exact_ok = False
                    break
            if exact_ok:
                candidates.append(exact_method)

        if len(candidates) != 1:
            continue

        exact_method = candidates[0]
        for call in calls:
            cast_start = method_start + call.start("cast")
            cast_end = method_start + call.end("cast")
            edits.append((cast_start, cast_end, ""))
            actions.append(
                {
                    "kind": (
                        "erased_generic_constructor_argument_cast_removal"
                    ),
                    "source_path": rel,
                    "method_name": method_match.group("name"),
                    "method_descriptor": exact_method["descriptor"],
                    "field_name": call.group("field"),
                    "member_name": call.group("member"),
                    "key_source_type": call.group("key"),
                    "value_source_type": generic_fields[
                        call.group("field")
                    ][1],
                    "field_owner": generic_fields[
                        call.group("field")
                    ][2],
                    "replacement_count": 1,
                    "provenance": {
                        "kind": "source_safety",
                        "reason": (
                            "procyon_erased_generic_constructor_argument_cast"
                        ),
                        "strategy": (
                            "source_generic_field_plus_exact_erased_call"
                        ),
                    },
                }
            )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping erased generic argument-cast edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



def _normalize_enum_valueof_object_class_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Replace impossible Class<Object> Enum.valueOf casts with raw Class.

    Procyon can emit Enum.valueOf((Class<Object>) type, value), which is
    source-illegal because Enum.valueOf requires Class<T> where
    T extends Enum<T>. The exact JVM call is erased to raw Class. Rewrite
    only the Class<Object> type token when one uniquely correlated method
    proves the same source parameters and the exact bytecode flow:
    instanceof Class -> Class.isEnum -> checkcast Class ->
    Enum.valueOf(Class,String).
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    call_re = re.compile(
        r"(?:(?:java\.lang\.)?Enum)\s*\.\s*valueOf\s*\(\s*"
        r"\(\s*(?P<class_type>(?:java\.lang\.)?Class\s*<\s*"
        r"(?:java\.lang\.)?Object\s*>)\s*\)\s*"
        r"(?P<class_arg>[A-Za-z_$][A-Za-z0-9_$]*)\s*,\s*"
        r"(?P<string_arg>[A-Za-z_$][A-Za-z0-9_$]*)\s*\)"
    )

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        params = method_match.group("params")
        source_shapes = _source_parameter_shapes(params)
        if source_shapes is None:
            continue

        parts: list[str] = []
        start = 0
        depth = 0
        for index, ch in enumerate(params):
            if ch == "<":
                depth += 1
            elif ch == ">" and depth:
                depth -= 1
            elif ch == "," and depth == 0:
                parts.append(params[start:index].strip())
                start = index + 1
        if params.strip():
            parts.append(params[start:].strip())
        if len(parts) != len(source_shapes):
            continue

        param_names: list[str] = []
        for part in parts:
            name_match = re.search(
                r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)"
                r"\s*(?:\[\]\s*)*$",
                part,
            )
            if name_match is None:
                param_names = []
                break
            param_names.append(name_match.group("name"))
        if len(param_names) != len(source_shapes):
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        source_calls = list(call_re.finditer(method_code))
        if len(source_calls) != 1:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        proven: list[
            tuple[dict[str, Any], re.Match[str], int, int]
        ] = []

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    params,
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue
            if (
                _descriptor_return_descriptor(descriptor)
                != "Ljava/lang/Object;"
            ):
                continue

            descriptor_shapes = _descriptor_parameter_shapes(descriptor)
            slots = _descriptor_parameter_local_slots(
                descriptor,
                is_static=source_static,
            )
            if (
                descriptor_shapes is None
                or slots is None
                or len(descriptor_shapes) != len(param_names)
                or len(slots) != len(param_names)
            ):
                continue

            string_positions = [
                index
                for index, (arrays, kind, name) in enumerate(
                    descriptor_shapes
                )
                if arrays == 0
                and kind == "ref"
                and name == "java/lang/String"
            ]
            type_positions = [
                index
                for index, (arrays, kind, name) in enumerate(
                    descriptor_shapes
                )
                if arrays == 0
                and kind == "ref"
                and name == "java/lang/reflect/Type"
            ]
            if len(string_positions) != 1 or len(type_positions) != 1:
                continue

            string_position = string_positions[0]
            type_position = type_positions[0]
            string_name = param_names[string_position]
            type_name = param_names[type_position]
            matching_source_calls = [
                call
                for call in source_calls
                if call.group("class_arg") == type_name
                and call.group("string_arg") == string_name
            ]
            if len(matching_source_calls) != 1:
                continue

            string_slot = slots[string_position]
            type_slot = slots[type_position]
            instructions = list(exact_method.get("instructions", []))

            enum_calls = [
                index
                for index, item in enumerate(instructions)
                if item.get("mnemonic") == "invokestatic"
                and item.get("owner") == "java/lang/Enum"
                and item.get("name") == "valueOf"
                and item.get("descriptor")
                == "(Ljava/lang/Class;Ljava/lang/String;)"
                "Ljava/lang/Enum;"
            ]
            if len(enum_calls) != 1:
                continue
            enum_index = enum_calls[0]
            if enum_index < 3:
                continue
            if not (
                instructions[enum_index - 3].get("mnemonic") == "aload"
                and int(
                    instructions[enum_index - 3].get("local_index", -1)
                )
                == type_slot
                and instructions[enum_index - 2].get("mnemonic")
                == "checkcast"
                and instructions[enum_index - 2].get("type")
                == "java/lang/Class"
                and instructions[enum_index - 1].get("mnemonic") == "aload"
                and int(
                    instructions[enum_index - 1].get("local_index", -1)
                )
                == string_slot
            ):
                continue

            instanceof_sites = [
                index
                for index in range(1, len(instructions))
                if instructions[index].get("mnemonic") == "instanceof"
                and instructions[index].get("type") == "java/lang/Class"
                and instructions[index - 1].get("mnemonic") == "aload"
                and int(
                    instructions[index - 1].get("local_index", -1)
                )
                == type_slot
            ]
            is_enum_sites = [
                index
                for index in range(2, len(instructions))
                if instructions[index].get("mnemonic") == "invokevirtual"
                and instructions[index].get("owner") == "java/lang/Class"
                and instructions[index].get("name") == "isEnum"
                and instructions[index].get("descriptor") == "()Z"
                and instructions[index - 1].get("mnemonic") == "checkcast"
                and instructions[index - 1].get("type")
                == "java/lang/Class"
                and instructions[index - 2].get("mnemonic") == "aload"
                and int(
                    instructions[index - 2].get("local_index", -1)
                )
                == type_slot
            ]
            if (
                len(instanceof_sites) != 1
                or len(is_enum_sites) != 1
                or not (
                    instanceof_sites[0]
                    < is_enum_sites[0]
                    < enum_index
                )
            ):
                continue

            proven.append(
                (
                    exact_method,
                    matching_source_calls[0],
                    type_slot,
                    string_slot,
                )
            )

        if len(proven) != 1:
            continue

        exact_method, call, type_slot, string_slot = proven[0]
        raw_class = call.group("class_type").split("<", 1)[0].strip()
        edit_start = method_start + call.start("class_type")
        edit_end = method_start + call.end("class_type")
        edits.append((edit_start, edit_end, raw_class))
        actions.append(
            {
                "kind": "enum_valueof_raw_class_cast_reconstruction",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": exact_method.get("descriptor"),
                "class_argument_name": call.group("class_arg"),
                "string_argument_name": call.group("string_arg"),
                "class_argument_slot": type_slot,
                "string_argument_slot": string_slot,
                "replacement_count": 1,
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_enum_valueof_impossible_class_object_cast"
                    ),
                    "strategy": (
                        "exact_class_is_enum_and_erased_enum_valueof_flow"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping Enum.valueOf cast edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_erased_hashmap_get_array_returns(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore array casts lost from HashMap<K,Object>.get return sites.

    Procyon can emit an uncast HashMap.get return in an array-returning method
    even though the erased get() result is Object and exact bytecode
    immediately checkcasts it to the method's array return type. Restore only
    that cast when the source field is explicitly HashMap<...,Object>, the
    source/exact method correlation is unique, and every edited return maps
    one-for-one to an exact field-get -> HashMap.get -> checkcast -> areturn
    flow for the same field and exact array descriptor.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    field_re = re.compile(
        r"(?:(?:java\.util\.)?HashMap)\s*<\s*"
        r"[^,<>]+\s*,\s*(?:java\.lang\.)?Object\s*>\s+"
        r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\s*"
        r"(?:=\s*[^;{}]+)?;"
    )
    object_hashmap_fields = {
        match.group("name") for match in field_re.finditer(whole_code)
    }
    if not object_hashmap_fields:
        return []

    return_re = re.compile(
        r"\breturn\s+"
        r"(?P<expr>(?:(?:this)\s*\.\s*)?"
        r"(?P<field>[A-Za-z_$][A-Za-z0-9_$]*)\s*\.\s*get\s*"
        r"\(\s*(?P<key>[A-Za-z_$][A-Za-z0-9_$]*)\s*\))"
        r"\s*;"
    )

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        returns = [
            match
            for match in return_re.finditer(method_code)
            if match.group("field") in object_hashmap_fields
        ]
        if not returns:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        if source_static:
            continue

        candidates: list[dict[str, Any]] = []
        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if bool(int(exact_method.get("access", 0)) & 0x0008):
                continue

            return_descriptor = _descriptor_return_descriptor(descriptor)
            if (
                return_descriptor is None
                or not return_descriptor.startswith("[")
            ):
                continue
            return_probe = (
                method_match.group("return").strip()
                + " recoveredArrayReturn"
            )
            if (
                _source_parameters_match_descriptor(
                    return_probe,
                    "(" + return_descriptor + ")V",
                    current_package=current_package,
                )
                is not True
            ):
                continue

            instructions = list(exact_method.get("instructions", []))
            flows: list[dict[str, Any]] = []
            for index in range(len(instructions) - 4):
                field_get = instructions[index]
                key_load = instructions[index + 1]
                get_call = instructions[index + 2]
                cast = instructions[index + 3]
                ret = instructions[index + 4]
                if not (
                    field_get.get("mnemonic") == "getfield"
                    and field_get.get("owner") == current_owner
                    and field_get.get("name") in object_hashmap_fields
                    and field_get.get("descriptor")
                    == "Ljava/util/HashMap;"
                    and key_load.get("mnemonic") == "aload"
                    and get_call.get("mnemonic") == "invokevirtual"
                    and get_call.get("owner") == "java/util/HashMap"
                    and get_call.get("name") == "get"
                    and get_call.get("descriptor")
                    == "(Ljava/lang/Object;)Ljava/lang/Object;"
                    and cast.get("mnemonic") == "checkcast"
                    and cast.get("type") == return_descriptor
                    and ret.get("mnemonic") == "areturn"
                ):
                    continue
                flows.append(
                    {
                        "field_name": str(field_get.get("name", "")),
                        "return_descriptor": return_descriptor,
                        "checkcast_offset": int(cast.get("offset", -1)),
                    }
                )

            source_fields = [row.group("field") for row in returns]
            exact_fields = [row["field_name"] for row in flows]
            if sorted(source_fields) != sorted(exact_fields):
                continue
            if len(flows) != len(returns):
                continue
            candidates.append(
                {
                    "method": exact_method,
                    "flows": flows,
                    "return_descriptor": return_descriptor,
                }
            )

        if len(candidates) != 1:
            continue

        proof = candidates[0]
        source_return = method_match.group("return").strip()
        for match in returns:
            expression = text[
                method_start + match.start("expr"):
                method_start + match.end("expr")
            ]
            edits.append(
                (
                    method_start + match.start("expr"),
                    method_start + match.end("expr"),
                    "(" + source_return + ")" + expression,
                )
            )

        actions.append(
            {
                "kind": "erased_hashmap_get_array_return_cast_reconstruction",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "field_names": sorted(
                    {match.group("field") for match in returns}
                ),
                "array_return_descriptor": proof["return_descriptor"],
                "exact_flows": proof["flows"],
                "replacement_count": len(returns),
                "provenance": {
                    "kind": "source_safety",
                    "reason": "procyon_erased_hashmap_get_array_return_cast",
                    "strategy": (
                        "source_hashmap_object_value_plus_exact_get_checkcast_return"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping HashMap array-return cast edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_methodhandle_invokeexact_result_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore source casts for signature-polymorphic invokeExact results."""

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    imports: dict[str, str] = {}
    duplicate_imports: set[str] = set()
    for import_match in _SINGLE_TYPE_IMPORT_RE.finditer(whole_code):
        dotted = import_match.group("name")
        simple = dotted.rsplit(".", 1)[-1]
        internal = dotted.replace(".", "/")
        previous = imports.get(simple)
        if previous is not None and previous != internal:
            duplicate_imports.add(simple)
        else:
            imports[simple] = internal
    for simple in duplicate_imports:
        imports.pop(simple, None)

    def invokeexact_target_type_matches(
        source_type: str,
        return_descriptor: str,
    ) -> bool:
        source_shapes = _source_parameter_shapes(
            source_type + " recoveredInvokeExactResult"
        )
        target_shapes = _descriptor_parameter_shapes(
            "(" + return_descriptor + ")V"
        )
        if (
            source_shapes is None
            or target_shapes is None
            or len(source_shapes) != 1
            or len(target_shapes) != 1
        ):
            return False

        source_arrays, source_kind, source_name = source_shapes[0]
        target_arrays, target_kind, target_name = target_shapes[0]
        if source_arrays != target_arrays:
            return False
        if target_arrays == 0 and target_kind != "ref":
            return False
        if target_arrays > 0 and target_kind == "primitive":
            return (
                source_kind == "primitive"
                and source_name == target_name
            )
        if source_kind == "primitive":
            return False

        if source_kind == "qualified_ref":
            return (
                _source_parameters_match_descriptor(
                    source_type + " recoveredInvokeExactResult",
                    "(" + return_descriptor + ")V",
                    current_package=current_package,
                )
                is True
            )

        imported = imports.get(source_name)
        if imported is not None:
            return imported == target_name

        if target_name == "java/lang/" + source_name:
            return True
        if (
            current_package
            and target_name == current_package + "/" + source_name
        ):
            try:
                readable_zip.getinfo(target_name + ".class")
            except KeyError:
                return False
            return True
        return False

    type_pattern = (
        r"[A-Za-z_$][A-Za-z0-9_$.]*"
        r"(?:\s*<[^;{}=]+>)?(?:\s*\[\])*"
    )
    declaration_assignment_re = re.compile(
        r"\b(?:(?:final)\s+)?"
        r"(?P<type>" + type_pattern + r")\s+"
        r"(?P<value>[A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*"
        r"(?P<expr>[^;{}]*?\.\s*invokeExact\s*\([^;{}]*\))"
        r"\s*;"
    )
    plain_assignment_re = re.compile(
        r"(?<![A-Za-z0-9_$.])"
        r"(?P<value>[A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*"
        r"(?P<expr>[^;{}]*?\.\s*invokeExact\s*\([^;{}]*\))"
        r"\s*;"
    )

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        source_rows: list[dict[str, Any]] = []

        declaration_matches = list(
            declaration_assignment_re.finditer(method_code)
        )
        covered = [
            (match.start(), match.end())
            for match in declaration_matches
        ]
        for match in declaration_matches:
            source_rows.append(
                {
                    "start": match.start(),
                    "type": match.group("type").strip(),
                    "value": match.group("value"),
                    "expr_start": match.start("expr"),
                    "expr_end": match.end("expr"),
                }
            )

        for match in plain_assignment_re.finditer(method_code):
            if any(
                left <= match.start() < right
                for left, right in covered
            ):
                continue
            value_name = match.group("value")
            declaration_re = re.compile(
                r"\b(?:(?:final)\s+)?"
                r"(?P<type>" + type_pattern + r")\s+"
                + re.escape(value_name)
                + r"\s*(?:;|=)"
            )
            prior = list(
                declaration_re.finditer(
                    method_code[:match.start()]
                )
            )
            if len(prior) != 1:
                continue
            source_rows.append(
                {
                    "start": match.start(),
                    "type": prior[0].group("type").strip(),
                    "value": value_name,
                    "expr_start": match.start("expr"),
                    "expr_end": match.end("expr"),
                }
            )

        source_rows.sort(key=lambda row: int(row["start"]))

        # Object is the declared signature-polymorphic return type itself.
        # Such assignments need no reconstructed source cast and their exact
        # invokeExact descriptor is intentionally excluded below.  Do the
        # same exclusion on the source side before enforcing multiplicity so
        # a harmless Object-target call cannot hide a separate typed call in
        # the same method.
        ignored_object_target_count = sum(
            1
            for row in source_rows
            if re.sub(r"\\s+", "", str(row["type"]))
            in {"Object", "java.lang.Object"}
        )
        source_rows = [
            row
            for row in source_rows
            if re.sub(r"\\s+", "", str(row["type"]))
            not in {"Object", "java.lang.Object"}
        ]
        if not source_rows:
            continue

        params = method_match.group("params")
        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        exact_candidates: list[dict[str, Any]] = []

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    params,
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            instructions = list(exact_method.get("instructions", []))
            flows: list[dict[str, Any]] = []
            for index, item in enumerate(instructions[:-1]):
                if not (
                    item.get("mnemonic")
                    in {"invokevirtual", "invokeinterface"}
                    and item.get("owner")
                    == "java/lang/invoke/MethodHandle"
                    and item.get("name") == "invokeExact"
                ):
                    continue
                call_descriptor = str(item.get("descriptor", ""))
                return_descriptor = _descriptor_return_descriptor(
                    call_descriptor
                )
                if (
                    return_descriptor is None
                    or return_descriptor in {"V", "Ljava/lang/Object;"}
                    or (
                        not return_descriptor.startswith("L")
                        and not return_descriptor.startswith("[")
                    )
                ):
                    continue
                store = instructions[index + 1]
                if store.get("mnemonic") != "astore":
                    continue
                flows.append(
                    {
                        "invoke_offset": int(item.get("offset", -1)),
                        "store_offset": int(store.get("offset", -1)),
                        "store_slot": int(store.get("local_index", -1)),
                        "call_descriptor": call_descriptor,
                        "return_descriptor": return_descriptor,
                    }
                )

            if len(flows) != len(source_rows):
                continue

            proven = True
            for source_row, flow in zip(source_rows, flows):
                source_type = str(source_row["type"])
                if not invokeexact_target_type_matches(
                    source_type,
                    str(flow["return_descriptor"]),
                ):
                    proven = False
                    break
            if not proven:
                continue

            exact_candidates.append(
                {
                    "method": exact_method,
                    "flows": flows,
                }
            )

        if len(exact_candidates) != 1:
            continue

        proof = exact_candidates[0]
        for source_row in source_rows:
            expr_start = int(source_row["expr_start"])
            expr_end = int(source_row["expr_end"])
            expression = text[
                method_start + expr_start:
                method_start + expr_end
            ]
            source_type = str(source_row["type"])
            edits.append(
                (
                    method_start + expr_start,
                    method_start + expr_end,
                    "(" + source_type + ")(" + expression + ")",
                )
            )

        actions.append(
            {
                "kind": (
                    "methodhandle_invokeexact_result_cast_reconstruction"
                ),
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "local_names": [
                    str(row["value"]) for row in source_rows
                ],
                "target_types": [
                    str(row["type"]) for row in source_rows
                ],
                "flows": proof["flows"],
                "replacement_count": len(source_rows),
                "ignored_object_target_count": (
                    ignored_object_target_count
                ),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "signature_polymorphic_invokeexact_result_type_erasure"
                    ),
                    "strategy": (
                        "exact_invokeexact_descriptor_return_plus_immediate_store"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping invokeExact result-cast edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_erased_map_mixed_object_locals(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore Object locals for mixed-type Map.get result lifetimes.

    Procyon can assign one branch-specific cast type to a Map<String,Object>
    result even though exact bytecode stores the raw Object and refines the
    same local through multiple later checkcast targets. Change only the
    declaration type when one exact local lifetime proves that mixed flow.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    map_param_re = re.compile(
        r"(?:java\.util\.)?Map\s*<\s*[^,<>]+\s*,\s*"
        r"(?:java\.lang\.)?Object\s*>\s+"
        r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\b"
    )
    assignment_re = re.compile(
        r"\b(?:(?:final)\s+)?"
        r"(?P<type>[A-Za-z_$][A-Za-z0-9_$.]*)\s+"
        r"(?P<value>[A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*"
        r"(?P<map>[A-Za-z_$][A-Za-z0-9_$]*)\s*\.\s*get\s*\(\s*"
        r"(?P<key>[A-Za-z_$][A-Za-z0-9_$]*)\s*\)\s*;"
    )

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        params = method_match.group("params")
        parameter_names = _source_parameter_names(params)
        if parameter_names is None:
            continue
        map_params = {
            match.group("name")
            for match in map_param_re.finditer(params)
        }
        if not map_params:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        source_matches = [
            match
            for match in assignment_re.finditer(method_code)
            if match.group("map") in map_params
            and match.group("type") not in {
                "Object",
                "java.lang.Object",
            }
        ]
        if not source_matches:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        exact_candidates: list[dict[str, Any]] = []

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    params,
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            shapes = _descriptor_parameter_shapes(descriptor)
            slots = _descriptor_parameter_local_slots(
                descriptor,
                is_static=source_static,
            )
            if (
                shapes is None
                or slots is None
                or len(shapes) != len(parameter_names)
            ):
                continue

            map_slots: dict[str, int] = {}
            for name, shape, slot in zip(parameter_names, shapes, slots):
                if (
                    name in map_params
                    and shape[0] == 0
                    and shape[1] == "ref"
                    and shape[2] in {
                        "java/util/Map",
                        "java/util/HashMap",
                        "java/util/LinkedHashMap",
                        "java/util/TreeMap",
                    }
                ):
                    map_slots[name] = slot
            if any(
                match.group("map") not in map_slots
                for match in source_matches
            ):
                continue

            instructions = list(exact_method.get("instructions", []))
            flows: list[dict[str, Any]] = []

            for index, item in enumerate(instructions[:-1]):
                if not (
                    item.get("mnemonic")
                    in {"invokeinterface", "invokevirtual"}
                    and item.get("owner")
                    in {
                        "java/util/Map",
                        "java/util/HashMap",
                        "java/util/LinkedHashMap",
                        "java/util/TreeMap",
                    }
                    and item.get("name") == "get"
                    and item.get("descriptor")
                    == "(Ljava/lang/Object;)Ljava/lang/Object;"
                ):
                    continue
                store = instructions[index + 1]
                if store.get("mnemonic") != "astore":
                    continue
                local_slot = int(store.get("local_index", -1))
                if local_slot < 0:
                    continue

                receiver_slot: int | None = None
                for probe in range(max(0, index - 4), index):
                    prior = instructions[probe]
                    if prior.get("mnemonic") != "aload":
                        continue
                    candidate_slot = int(
                        prior.get("local_index", -1)
                    )
                    if candidate_slot in set(map_slots.values()):
                        receiver_slot = candidate_slot
                if receiver_slot is None:
                    continue

                next_store = len(instructions)
                for tail in range(index + 2, len(instructions)):
                    candidate = instructions[tail]
                    if (
                        candidate.get("mnemonic") == "astore"
                        and int(candidate.get("local_index", -1))
                        == local_slot
                    ):
                        next_store = tail
                        break

                checkcasts: list[dict[str, Any]] = []
                for tail in range(index + 2, next_store - 1):
                    load = instructions[tail]
                    cast = instructions[tail + 1]
                    if not (
                        load.get("mnemonic") == "aload"
                        and int(load.get("local_index", -1))
                        == local_slot
                        and cast.get("mnemonic") == "checkcast"
                    ):
                        continue
                    cast_type = str(cast.get("type", ""))
                    if not cast_type or cast_type.startswith("["):
                        continue
                    checkcasts.append(
                        {
                            "type": cast_type,
                            "load_offset": int(
                                load.get("offset", -1)
                            ),
                            "checkcast_offset": int(
                                cast.get("offset", -1)
                            ),
                        }
                    )

                cast_types = sorted(
                    {row["type"] for row in checkcasts}
                )
                if len(cast_types) < 2:
                    continue

                flows.append(
                    {
                        "map_slot": receiver_slot,
                        "object_local_slot": local_slot,
                        "get_offset": int(item.get("offset", -1)),
                        "store_offset": int(store.get("offset", -1)),
                        "checkcast_types": cast_types,
                        "checkcasts": checkcasts,
                    }
                )

            if len(flows) != len(source_matches):
                continue

            source_proofs: list[tuple[int, str]] = []
            valid_source = True
            for match in source_matches:
                source_type = match.group("type")
                matching_types = [
                    cast_type
                    for cast_type in next(
                        flow["checkcast_types"]
                        for flow in flows
                        if flow["map_slot"]
                        == map_slots[match.group("map")]
                    )
                    if (
                        _source_parameters_match_descriptor(
                            source_type + " recoveredMixedLocal",
                            "(L" + cast_type + ";)V",
                            current_package=current_package,
                        )
                        is True
                    )
                ]
                if len(matching_types) != 1:
                    valid_source = False
                    break
                source_proofs.append(
                    (
                        map_slots[match.group("map")],
                        matching_types[0],
                    )
                )
            if not valid_source:
                continue

            exact_proofs = [
                (
                    flow["map_slot"],
                    next(
                        cast_type
                        for cast_type in flow["checkcast_types"]
                        if any(
                            proof[0] == flow["map_slot"]
                            and proof[1] == cast_type
                            for proof in source_proofs
                        )
                    ),
                )
                for flow in flows
                if any(
                    proof[0] == flow["map_slot"]
                    for proof in source_proofs
                )
            ]
            if exact_proofs != source_proofs:
                continue

            exact_candidates.append(
                {
                    "method": exact_method,
                    "flows": flows,
                }
            )

        if len(exact_candidates) != 1:
            continue

        proof = exact_candidates[0]
        for match in source_matches:
            edits.append(
                (
                    method_start + match.start("type"),
                    method_start + match.end("type"),
                    "Object",
                )
            )

        actions.append(
            {
                "kind": "erased_map_mixed_object_local_reconstruction",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "map_parameters": sorted(
                    {match.group("map") for match in source_matches}
                ),
                "local_names": [
                    match.group("value") for match in source_matches
                ],
                "flows": proof["flows"],
                "replacement_count": len(source_matches),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_branch_specific_type_for_mixed_map_object_local"
                    ),
                    "strategy": (
                        "exact_map_get_object_store_plus_multi_checkcast_lifetime"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping mixed Map Object-local edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_erased_mixed_object_integer_sinks(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore Integer unboxing at primitive sinks of mixed Object locals.

    A mixed Map<String,Object>.get result must remain source-typed Object.
    Procyon can nevertheless elide branch-local Integer casts/unboxing after
    assigning the raw result to that Object local. Restore only primitive-int
    sinks whose exact local lifetime proves aload -> checkcast Integer ->
    Integer.intValue(), with the exact sink family and multiplicity preserved.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    map_param_re = re.compile(
        r"(?:java\.util\.)?Map\s*<\s*[^,<>]+\s*,\s*"
        r"(?:java\.lang\.)?Object\s*>\s+"
        r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\b"
    )
    object_assignment_re = re.compile(
        r"\b(?:(?:final)\s+)?(?:java\.lang\.)?Object\s+"
        r"(?P<value>[A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*"
        r"(?P<map>[A-Za-z_$][A-Za-z0-9_$]*)\s*\.\s*get\s*\(\s*"
        r"(?P<key>[A-Za-z_$][A-Za-z0-9_$]*)\s*\)\s*;"
    )

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        params = method_match.group("params")
        parameter_names = _source_parameter_names(params)
        if parameter_names is None:
            continue
        map_params = {
            match.group("name")
            for match in map_param_re.finditer(params)
        }
        if not map_params:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        assignments = [
            match
            for match in object_assignment_re.finditer(method_code)
            if match.group("map") in map_params
        ]
        if len(assignments) != 1:
            continue
        assignment = assignments[0]
        value_name = assignment.group("value")

        array_sink_re = re.compile(
            r"(?P<expr>"
            r"(?P<array>[A-Za-z_$][A-Za-z0-9_$]*)"
            r"\s*\[\s*(?P<index>[A-Za-z_$][A-Za-z0-9_$]*)\s*\]"
            r"\s*=\s*"
            r"(?P<value>\b" + re.escape(value_name) + r"\b)"
            r"\s*;)"
        )
        int_local_sink_re = re.compile(
            r"(?P<expr>\b(?:(?:final)\s+)?int\s+"
            r"(?P<local>[A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*"
            r"(?P<value>\b" + re.escape(value_name) + r"\b)"
            r"\s*;)"
        )
        array_sinks = [
            match
            for match in array_sink_re.finditer(method_code)
            if match.start() > assignment.end()
        ]
        local_sinks = [
            match
            for match in int_local_sink_re.finditer(method_code)
            if match.start() > assignment.end()
        ]
        if not array_sinks and not local_sinks:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        exact_candidates: list[dict[str, Any]] = []

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    params,
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            shapes = _descriptor_parameter_shapes(descriptor)
            slots = _descriptor_parameter_local_slots(
                descriptor,
                is_static=source_static,
            )
            if (
                shapes is None
                or slots is None
                or len(shapes) != len(parameter_names)
            ):
                continue

            map_slots: dict[str, int] = {}
            for name, shape, slot in zip(parameter_names, shapes, slots):
                if (
                    name in map_params
                    and shape[0] == 0
                    and shape[1] == "ref"
                    and shape[2] in {
                        "java/util/Map",
                        "java/util/HashMap",
                        "java/util/LinkedHashMap",
                        "java/util/TreeMap",
                    }
                ):
                    map_slots[name] = slot
            map_slot = map_slots.get(assignment.group("map"))
            if map_slot is None:
                continue

            instructions = list(exact_method.get("instructions", []))
            object_flows: list[dict[str, Any]] = []

            for index, item in enumerate(instructions[:-1]):
                if not (
                    item.get("mnemonic")
                    in {"invokeinterface", "invokevirtual"}
                    and item.get("owner")
                    in {
                        "java/util/Map",
                        "java/util/HashMap",
                        "java/util/LinkedHashMap",
                        "java/util/TreeMap",
                    }
                    and item.get("name") == "get"
                    and item.get("descriptor")
                    == "(Ljava/lang/Object;)Ljava/lang/Object;"
                ):
                    continue
                store = instructions[index + 1]
                if store.get("mnemonic") != "astore":
                    continue

                receiver_matches = False
                for probe in range(max(0, index - 5), index):
                    prior = instructions[probe]
                    if (
                        prior.get("mnemonic") == "aload"
                        and int(prior.get("local_index", -1)) == map_slot
                    ):
                        receiver_matches = True
                if not receiver_matches:
                    continue

                local_slot = int(store.get("local_index", -1))
                if local_slot < 0:
                    continue
                object_flows.append(
                    {
                        "local_slot": local_slot,
                        "get_offset": int(item.get("offset", -1)),
                        "store_offset": int(store.get("offset", -1)),
                        "store_instruction_index": index + 1,
                    }
                )

            if len(object_flows) != 1:
                continue
            object_flow = object_flows[0]
            local_slot = object_flow["local_slot"]
            store_index = object_flow["store_instruction_index"]

            lifetime_end = len(instructions)
            for tail in range(store_index + 1, len(instructions)):
                candidate = instructions[tail]
                if (
                    candidate.get("mnemonic") == "astore"
                    and int(candidate.get("local_index", -1)) == local_slot
                ):
                    lifetime_end = tail
                    break

            exact_sinks: list[dict[str, Any]] = []
            for index in range(store_index + 1, lifetime_end - 3):
                load = instructions[index]
                cast = instructions[index + 1]
                unbox = instructions[index + 2]
                sink = instructions[index + 3]
                if not (
                    load.get("mnemonic") == "aload"
                    and int(load.get("local_index", -1)) == local_slot
                    and cast.get("mnemonic") == "checkcast"
                    and cast.get("type") == "java/lang/Integer"
                    and unbox.get("mnemonic")
                    in {"invokevirtual", "invokeinterface"}
                    and unbox.get("owner") == "java/lang/Integer"
                    and unbox.get("name") == "intValue"
                    and unbox.get("descriptor") == "()I"
                ):
                    continue

                sink_mnemonic = str(sink.get("mnemonic", ""))
                if sink_mnemonic == "iastore":
                    sink_kind = "array"
                elif sink_mnemonic == "istore":
                    sink_kind = "local"
                else:
                    continue
                exact_sinks.append(
                    {
                        "kind": sink_kind,
                        "load_offset": int(load.get("offset", -1)),
                        "checkcast_offset": int(cast.get("offset", -1)),
                        "unbox_offset": int(unbox.get("offset", -1)),
                        "sink_offset": int(sink.get("offset", -1)),
                        "sink_local_index": (
                            int(sink.get("local_index", -1))
                            if sink_kind == "local"
                            else None
                        ),
                    }
                )

            exact_array_count = sum(
                row["kind"] == "array" for row in exact_sinks
            )
            exact_local_count = sum(
                row["kind"] == "local" for row in exact_sinks
            )
            if (
                exact_array_count != len(array_sinks)
                or exact_local_count != len(local_sinks)
            ):
                continue

            exact_candidates.append(
                {
                    "method": exact_method,
                    "object_flow": object_flow,
                    "sinks": exact_sinks,
                }
            )

        if len(exact_candidates) != 1:
            continue

        proof = exact_candidates[0]
        replacement = "((Integer)" + value_name + ").intValue()"
        source_sinks = sorted(
            [
                (match.start("value"), match.end("value"), "array")
                for match in array_sinks
            ]
            + [
                (match.start("value"), match.end("value"), "local")
                for match in local_sinks
            ]
        )
        for start, end, _kind in source_sinks:
            edits.append(
                (
                    method_start + start,
                    method_start + end,
                    replacement,
                )
            )

        actions.append(
            {
                "kind": (
                    "erased_mixed_object_integer_sink_unbox_reconstruction"
                ),
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "map_parameter": assignment.group("map"),
                "value_local": value_name,
                "exact_object_flow": proof["object_flow"],
                "exact_integer_sinks": proof["sinks"],
                "array_sink_count": len(array_sinks),
                "local_sink_count": len(local_sinks),
                "replacement_count": len(source_sinks),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_lost_branch_integer_unbox_for_mixed_object_local"
                    ),
                    "strategy": (
                        "exact_object_slot_integer_checkcast_intvalue_sink"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping mixed Object Integer-sink edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_erased_map_number_assignments(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore Object locals for erased Map<String,Object>.get flows.

    Procyon can incorrectly collapse an exact JVM Object local plus a later
    instanceof/checkcast Number sequence into an illegal source declaration
    such as Number value = map.get(key). Procyon may also elide the later
    source cast and emit value.intValue() because it already mis-typed the
    local as Number. Restore the Object declaration and, only for that plain
    terminal form, restore the Number receiver cast already proven by exact
    bytecode. The source parameters and one exact readable JVM method must
    prove the complete get -> astore -> instanceof Number -> checkcast Number
    -> intValue flow.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    map_param_re = re.compile(
        r"(?:java\.util\.)?Map\s*<\s*String\s*,\s*Object\s*>\s+"
        r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\b"
    )
    string_param_re = re.compile(
        r"(?:java\.lang\.)?String\s+"
        r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\b"
    )

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        params = method_match.group("params")
        map_params = {
            match.group("name") for match in map_param_re.finditer(params)
        }
        string_params = {
            match.group("name") for match in string_param_re.finditer(params)
        }
        if not map_params or not string_params:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        assignment_re = re.compile(
            r"\b(?:(?:final)\s+)?(?P<type>Number)\s+"
            r"(?P<value>[A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*"
            r"(?P<map>[A-Za-z_$][A-Za-z0-9_$]*)\s*\.\s*get\s*\(\s*"
            r"(?P<key>[A-Za-z_$][A-Za-z0-9_$]*)\s*\)\s*;"
        )
        assignments = [
            match
            for match in assignment_re.finditer(method_code)
            if match.group("map") in map_params
            and match.group("key") in string_params
        ]
        if not assignments:
            continue

        proven_assignments: list[
            tuple[re.Match[str], re.Match[str] | None]
        ] = []
        for assignment in assignments:
            value_name = assignment.group("value")
            after = method_code[assignment.end():]
            if not re.search(
                r"\b" + re.escape(value_name)
                + r"\s+instanceof\s+Number\b",
                after,
            ):
                continue

            explicit_terminal_re = re.compile(
                r"\(\s*\(\s*Number\s*\)\s*"
                + re.escape(value_name)
                + r"\s*\)\s*\.\s*intValue\s*\(\s*\)"
            )
            plain_terminal_re = re.compile(
                r"(?P<receiver>\b"
                + re.escape(value_name)
                + r"\b)\s*\.\s*intValue\s*\(\s*\)"
            )
            explicit_hits = list(explicit_terminal_re.finditer(after))
            plain_hits = list(plain_terminal_re.finditer(after))
            if len(explicit_hits) + len(plain_hits) != 1:
                continue
            plain_terminal = plain_hits[0] if plain_hits else None
            proven_assignments.append((assignment, plain_terminal))
        if not proven_assignments:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        candidates: list[dict[str, Any]] = []
        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    params,
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue
            if _descriptor_return_descriptor(descriptor) != "I":
                continue

            instructions = list(exact_method.get("instructions", []))
            flows: list[int] = []
            for index, item in enumerate(instructions[:-1]):
                if not (
                    item.get("mnemonic") in {"invokeinterface", "invokevirtual"}
                    and item.get("owner") == "java/util/Map"
                    and item.get("name") == "get"
                    and item.get("descriptor")
                    == "(Ljava/lang/Object;)Ljava/lang/Object;"
                ):
                    continue
                store = instructions[index + 1]
                if store.get("mnemonic") != "astore":
                    continue
                local_index = int(store.get("local_index", -1))
                if local_index < 0:
                    continue

                instanceof_seen = False
                checkcast_intvalue_seen = False
                for tail_index in range(index + 2, len(instructions)):
                    if (
                        tail_index + 1 < len(instructions)
                        and instructions[tail_index].get("mnemonic") == "aload"
                        and int(
                            instructions[tail_index].get("local_index", -1)
                        ) == local_index
                        and instructions[tail_index + 1].get("mnemonic")
                        == "instanceof"
                        and instructions[tail_index + 1].get("type")
                        == "java/lang/Number"
                    ):
                        instanceof_seen = True
                    if (
                        tail_index + 2 < len(instructions)
                        and instructions[tail_index].get("mnemonic") == "aload"
                        and int(
                            instructions[tail_index].get("local_index", -1)
                        ) == local_index
                        and instructions[tail_index + 1].get("mnemonic")
                        == "checkcast"
                        and instructions[tail_index + 1].get("type")
                        == "java/lang/Number"
                        and instructions[tail_index + 2].get("mnemonic")
                        in {"invokevirtual", "invokeinterface"}
                        and instructions[tail_index + 2].get("owner")
                        == "java/lang/Number"
                        and instructions[tail_index + 2].get("name")
                        == "intValue"
                        and instructions[tail_index + 2].get("descriptor")
                        == "()I"
                    ):
                        checkcast_intvalue_seen = True
                if instanceof_seen and checkcast_intvalue_seen:
                    flows.append(local_index)

            if len(flows) == len(proven_assignments):
                candidates.append(
                    {
                        "method": exact_method,
                        "local_slots": flows,
                    }
                )

        if len(candidates) != 1:
            continue

        exact_method = candidates[0]["method"]
        terminal_cast_replacement_count = 0
        for assignment, plain_terminal in proven_assignments:
            edits.append(
                (
                    method_start + assignment.start("type"),
                    method_start + assignment.end("type"),
                    "Object",
                )
            )
            if plain_terminal is not None:
                receiver_start = (
                    assignment.end()
                    + plain_terminal.start("receiver")
                )
                receiver_end = (
                    assignment.end()
                    + plain_terminal.end("receiver")
                )
                edits.append(
                    (
                        method_start + receiver_start,
                        method_start + receiver_end,
                        "((Number)" + assignment.group("value") + ")",
                    )
                )
                terminal_cast_replacement_count += 1

        actions.append(
            {
                "kind": "erased_map_number_assignment_reconstruction",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": exact_method["descriptor"],
                "map_parameters": sorted(map_params),
                "string_parameters": sorted(string_params),
                "exact_object_local_slots": candidates[0]["local_slots"],
                "replacement_count": len(proven_assignments),
                "terminal_cast_replacement_count": (
                    terminal_cast_replacement_count
                ),
                "provenance": {
                    "kind": "source_safety",
                    "reason": "procyon_erased_map_get_number_local",
                    "strategy": (
                        "source_map_string_object_plus_exact_object_number_flow"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping erased Map Number-local edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_erased_raw_collection_get_assignment_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore exact casts lost from raw Map/List get() local assignments.

    Procyon can emit a raw Map/List receiver and assign get() directly to a
    concrete reference local even though the erased JVM return is Object.
    Restore only the source cast already proven by one exact readable method:
    every edited raw get() assignment must correspond one-for-one to an exact
    get -> checkcast target -> astore flow of the same collection family.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    raw_decl_re = re.compile(
        r"\b(?P<type>(?:java\.util\.)?"
        r"(?:Map|HashMap|LinkedHashMap|TreeMap|"
        r"List|ArrayList|LinkedList))\s+"
        r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\b"
    )
    assignment_re = re.compile(
        r"(?P<prefix>\b(?:(?:final)\s+)?)"
        r"(?P<type>[A-Za-z_$][A-Za-z0-9_$.]*(?:\[\])*)\s+"
        r"(?P<var>[A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*"
        r"(?P<expr>"
        r"(?P<receiver>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\.\s*get\s*\(\s*"
        r"(?P<key>[A-Za-z_$][A-Za-z0-9_$]*)\s*\)"
        r")\s*;"
    )

    map_source_types = {
        "Map", "HashMap", "LinkedHashMap", "TreeMap",
    }
    list_source_types = {"List", "ArrayList", "LinkedList"}
    map_exact_owners = {
        "java/util/Map",
        "java/util/HashMap",
        "java/util/LinkedHashMap",
        "java/util/TreeMap",
    }
    list_exact_owners = {
        "java/util/List",
        "java/util/ArrayList",
        "java/util/LinkedList",
    }

    def source_family(raw_type: str) -> str | None:
        simple = raw_type.rsplit(".", 1)[-1]
        if simple in map_source_types:
            return "map"
        if simple in list_source_types:
            return "list"
        return None

    def exact_family(call: dict[str, Any]) -> str | None:
        owner = str(call.get("owner", ""))
        descriptor = str(call.get("descriptor", ""))
        if (
            owner in map_exact_owners
            and descriptor
            == "(Ljava/lang/Object;)Ljava/lang/Object;"
        ):
            return "map"
        if (
            owner in list_exact_owners
            and descriptor == "(I)Ljava/lang/Object;"
        ):
            return "list"
        return None

    def cast_matches_source(source_type: str, cast_type: str) -> bool:
        if not cast_type:
            return False
        cast_descriptor = (
            cast_type if cast_type.startswith("[")
            else "L" + cast_type + ";"
        )
        return (
            _source_parameters_match_descriptor(
                source_type + " recoveredValue",
                "(" + cast_descriptor + ")V",
                current_package=current_package,
            )
            is True
        )

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        scope_code = (
            method_match.group("params")
            + "\n"
            + whole_code[brace_start + 1:body_end]
        )
        raw_declarations = {
            match.group("name"): match.group("type")
            for match in raw_decl_re.finditer(scope_code)
        }
        if not raw_declarations:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        assignments = [
            match
            for match in assignment_re.finditer(method_code)
            if match.group("receiver") in raw_declarations
            and match.group("type") != "Object"
            and source_family(
                raw_declarations[match.group("receiver")]
            )
            is not None
        ]
        if not assignments:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        candidates: list[dict[str, Any]] = []

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            exact_return = _descriptor_return_descriptor(descriptor)
            source_return = method_match.group("return").strip()
            if source_return == "void":
                if exact_return != "V":
                    continue
            elif exact_return is None or (
                _source_parameters_match_descriptor(
                    source_return + " recoveredReturn",
                    "(" + exact_return + ")V",
                    current_package=current_package,
                )
                is not True
            ):
                continue

            instructions = list(exact_method.get("instructions", []))
            flows: list[dict[str, Any]] = []
            for index in range(len(instructions) - 2):
                call = instructions[index]
                cast = instructions[index + 1]
                store = instructions[index + 2]
                family = exact_family(call)
                if family is None:
                    continue
                if not (
                    call.get("mnemonic")
                    in {"invokeinterface", "invokevirtual"}
                    and call.get("name") == "get"
                    and cast.get("mnemonic") == "checkcast"
                    and store.get("mnemonic") == "astore"
                ):
                    continue
                flows.append(
                    {
                        "family": family,
                        "checkcast_type": str(cast.get("type", "")),
                        "checkcast_offset": int(cast.get("offset", -1)),
                        "store_slot": int(store.get("local_index", -1)),
                    }
                )

            if len(flows) != len(assignments):
                continue

            remaining = list(flows)
            matched: list[dict[str, Any]] = []
            exact_ok = True
            for assignment in assignments:
                family = source_family(
                    raw_declarations[assignment.group("receiver")]
                )
                source_type = assignment.group("type")
                match_index = next(
                    (
                        index
                        for index, flow in enumerate(remaining)
                        if flow["family"] == family
                        and cast_matches_source(
                            source_type,
                            flow["checkcast_type"],
                        )
                    ),
                    None,
                )
                if match_index is None:
                    exact_ok = False
                    break
                matched.append(remaining.pop(match_index))

            if not exact_ok or remaining:
                continue
            candidates.append(
                {
                    "method": exact_method,
                    "flows": matched,
                }
            )

        if len(candidates) != 1:
            continue

        proof = candidates[0]
        for assignment in assignments:
            expression = text[
                method_start + assignment.start("expr"):
                method_start + assignment.end("expr")
            ]
            edits.append(
                (
                    method_start + assignment.start("expr"),
                    method_start + assignment.end("expr"),
                    "(" + assignment.group("type") + ")" + expression,
                )
            )

        actions.append(
            {
                "kind": (
                    "erased_raw_collection_get_assignment_cast_reconstruction"
                ),
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "receiver_names": sorted(
                    {match.group("receiver") for match in assignments}
                ),
                "receiver_types": {
                    name: raw_declarations[name]
                    for name in sorted(
                        {match.group("receiver") for match in assignments}
                    )
                },
                "exact_checkcast_types": [
                    flow["checkcast_type"] for flow in proof["flows"]
                ],
                "exact_store_slots": [
                    flow["store_slot"] for flow in proof["flows"]
                ],
                "replacement_count": len(assignments),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_erased_raw_collection_get_assignment_cast"
                    ),
                    "strategy": (
                        "raw_collection_source_plus_exact_get_checkcast_store"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping raw collection get assignment edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



def _normalize_erased_map_get_integer_ternaries(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore Integer casts erased from one arm of Map.get ternaries.

    The source candidate must assign an int from a containsKey-selected
    ternary where one Map.get arm is raw and the other already has an int
    cast. Exact bytecode must prove the same Map parameter slot, String keys,
    two Integer unbox flows, selector branch, and common int-store merge.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    key_token = r'[A-Za-z0-9_.:-]+'
    source_re = re.compile(
        r"\b(?:(?:final)\s+)?int\s+"
        r"(?P<target>[A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*"
        r"(?P<map>[A-Za-z_$][A-Za-z0-9_$]*)\s*\.\s*"
        r"containsKey\s*\(\s*\"(?P<key1>" + key_token + r")\"\s*\)"
        r"\s*\?\s*"
        r"(?P<raw>(?P=map)\s*\.\s*get\s*\(\s*\"(?P=key1)\""
        r"\s*\))\s*:\s*"
        r"\(\s*\(\s*int\s*\)\s*(?P=map)\s*\.\s*get\s*"
        r"\(\s*\"(?P<key2>" + key_token + r")\"\s*\)\s*\)"
        r"\s*;"
    )

    def is_map_call(
        row: dict[str, Any],
        *,
        name: str,
        descriptor: str,
    ) -> bool:
        return (
            row.get("mnemonic") in {"invokeinterface", "invokevirtual"}
            and row.get("owner") == "java/util/Map"
            and row.get("name") == name
            and row.get("descriptor") == descriptor
        )

    def integer_unbox(
        rows: list[dict[str, Any]],
        start: int,
        *,
        slot: int,
        key: str,
    ) -> bool:
        if start + 4 >= len(rows):
            return False
        load, key_row, get_call, cast, unbox = rows[start:start + 5]
        return (
            load.get("mnemonic") == "aload"
            and int(load.get("local_index", -1)) == slot
            and key_row.get("mnemonic") in {"ldc", "ldc_w"}
            and key_row.get("constant") == key
            and is_map_call(
                get_call,
                name="get",
                descriptor="(Ljava/lang/Object;)Ljava/lang/Object;",
            )
            and cast.get("mnemonic") == "checkcast"
            and cast.get("type") == "java/lang/Integer"
            and unbox.get("mnemonic") == "invokevirtual"
            and unbox.get("owner") == "java/lang/Integer"
            and unbox.get("name") == "intValue"
            and unbox.get("descriptor") == "()I"
        )

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        method_text = text[method_start:body_end]
        source_matches = [
            match
            for match in source_re.finditer(method_text)
            if (
                match.start() < len(method_code)
                and not method_code[match.start()].isspace()
            )
        ]
        if not source_matches:
            continue

        params = method_match.group("params")
        parameter_names = _source_parameter_names(params)
        if parameter_names is None:
            continue
        source_map_names = [row.group("map") for row in source_matches]
        if any(name not in parameter_names for name in source_map_names):
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        exact_candidates: list[dict[str, Any]] = []

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    params,
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            shapes = _descriptor_parameter_shapes(descriptor)
            slots = _descriptor_parameter_local_slots(
                descriptor,
                is_static=source_static,
            )
            if (
                shapes is None
                or slots is None
                or len(shapes) != len(parameter_names)
            ):
                continue
            slot_by_name: dict[str, int] = {}
            for name, shape, slot in zip(parameter_names, shapes, slots):
                if shape == (0, "ref", "java/util/Map"):
                    slot_by_name[name] = slot
            if any(name not in slot_by_name for name in source_map_names):
                continue

            instructions = list(exact_method.get("instructions", []))
            by_offset = {
                int(row.get("offset", -1)): index
                for index, row in enumerate(instructions)
            }
            flows: list[dict[str, Any]] = []

            for index in range(len(instructions) - 9):
                load, key_row, contains, selector = instructions[
                    index:index + 4
                ]
                if not (
                    load.get("mnemonic") == "aload"
                    and key_row.get("mnemonic") in {"ldc", "ldc_w"}
                    and isinstance(key_row.get("constant"), str)
                    and is_map_call(
                        contains,
                        name="containsKey",
                        descriptor="(Ljava/lang/Object;)Z",
                    )
                    and selector.get("opcode") == "0x99"
                    and "branch_target_offset" in selector
                ):
                    continue
                map_slot = int(load.get("local_index", -1))
                if map_slot < 0:
                    continue
                key1 = str(key_row["constant"])

                first_start = index + 4
                if not integer_unbox(
                    instructions,
                    first_start,
                    slot=map_slot,
                    key=key1,
                ):
                    continue
                goto_index = first_start + 5
                if goto_index >= len(instructions):
                    continue
                goto = instructions[goto_index]
                if (
                    goto.get("opcode") not in {"0xa7", "0xc8"}
                    or "branch_target_offset" not in goto
                ):
                    continue

                second_offset = int(selector["branch_target_offset"])
                second_start = by_offset.get(second_offset)
                if second_start is None:
                    continue
                if not integer_unbox(
                    instructions,
                    second_start,
                    slot=map_slot,
                    key=str(
                        instructions[second_start + 1].get("constant", "")
                    ),
                ):
                    continue
                key2 = str(
                    instructions[second_start + 1].get("constant", "")
                )

                merge_offset = int(goto["branch_target_offset"])
                merge_index = by_offset.get(merge_offset)
                if (
                    merge_index is None
                    or second_start + 5 != merge_index
                    or instructions[merge_index].get("mnemonic")
                    != "istore"
                ):
                    continue

                flows.append(
                    {
                        "map_slot": map_slot,
                        "key1": key1,
                        "key2": key2,
                        "selector_offset": int(selector["offset"]),
                        "second_arm_offset": second_offset,
                        "goto_offset": int(goto["offset"]),
                        "merge_offset": merge_offset,
                        "store_slot": int(
                            instructions[merge_index].get(
                                "local_index", -1
                            )
                        ),
                    }
                )

            source_proofs = [
                (
                    slot_by_name[row.group("map")],
                    row.group("key1"),
                    row.group("key2"),
                )
                for row in source_matches
            ]
            exact_proofs = [
                (
                    row["map_slot"],
                    row["key1"],
                    row["key2"],
                )
                for row in flows
            ]
            if exact_proofs != source_proofs:
                continue

            exact_candidates.append(
                {
                    "method": exact_method,
                    "flows": flows,
                }
            )

        if len(exact_candidates) != 1:
            continue

        proof = exact_candidates[0]
        for source_match in source_matches:
            expression = text[
                method_start + source_match.start("raw"):
                method_start + source_match.end("raw")
            ]
            edits.append(
                (
                    method_start + source_match.start("raw"),
                    method_start + source_match.end("raw"),
                    "((int)" + expression + ")",
                )
            )

        actions.append(
            {
                "kind": (
                    "erased_map_get_integer_ternary_cast_reconstruction"
                ),
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "map_parameters": sorted(set(source_map_names)),
                "flows": proof["flows"],
                "replacement_count": len(source_matches),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_erased_map_get_integer_ternary_cast"
                    ),
                    "strategy": (
                        "exact_containskey_two_arm_integer_unbox_diamond"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping Map.get Integer ternary edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions


def _normalize_erased_map_get_direct_argument_casts(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore Map casts lost from direct current-class call arguments.

    Procyon can erase Map.get() to Object when that result is passed directly
    into another method whose JVM descriptor requires Map. Restore only the
    exact cast proven by a contiguous get -> checkcast Map -> invocation flow.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    source_re = re.compile(
        r"\bthis\s*\.\s*(?P<target>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\(\s*"
        r"(?P<first>[A-Za-z_$][A-Za-z0-9_$]*)\s*,\s*"
        r"(?P<expr>"
        r"(?P<receiver>(?:(?:this)\s*\.\s*)?"
        r"[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\.\s*get\s*\(\s*"
        r"(?P<key>[A-Za-z_$][A-Za-z0-9_$]*)\s*\)"
        r")\s*\)"
    )
    map_get_owners = {
        "java/util/Map",
        "java/util/HashMap",
        "java/util/LinkedHashMap",
        "java/util/TreeMap",
    }

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        source_matches = list(source_re.finditer(method_code))
        if not source_matches:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        if source_static:
            continue

        exact_candidates: list[dict[str, Any]] = []
        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if bool(int(exact_method.get("access", 0)) & 0x0008):
                continue

            exact_return = _descriptor_return_descriptor(descriptor)
            source_return = method_match.group("return").strip()
            if source_return == "void":
                if exact_return != "V":
                    continue
            elif exact_return is None or (
                _source_parameters_match_descriptor(
                    source_return + " recoveredReturn",
                    "(" + exact_return + ")V",
                    current_package=current_package,
                )
                is not True
            ):
                continue

            instructions = list(exact_method.get("instructions", []))
            flows: list[dict[str, Any]] = []
            for index in range(len(instructions) - 2):
                get_call = instructions[index]
                cast = instructions[index + 1]
                invocation = instructions[index + 2]
                if not (
                    get_call.get("mnemonic")
                    in {"invokeinterface", "invokevirtual"}
                    and get_call.get("owner") in map_get_owners
                    and get_call.get("name") == "get"
                    and get_call.get("descriptor")
                    == "(Ljava/lang/Object;)Ljava/lang/Object;"
                    and cast.get("mnemonic") == "checkcast"
                    and cast.get("type") == "java/util/Map"
                    and invocation.get("mnemonic")
                    in {"invokevirtual", "invokespecial"}
                    and invocation.get("owner") == current_owner
                ):
                    continue
                invocation_descriptor = str(
                    invocation.get("descriptor", "")
                )
                invocation_shapes = _descriptor_parameter_shapes(
                    invocation_descriptor
                )
                if (
                    invocation_shapes is None
                    or len(invocation_shapes) != 2
                    or invocation_shapes[1]
                    != (0, "ref", "java/util/Map")
                ):
                    continue
                flows.append(
                    {
                        "target_method": str(
                            invocation.get("name", "")
                        ),
                        "target_descriptor": invocation_descriptor,
                        "get_offset": int(get_call.get("offset", -1)),
                        "checkcast_offset": int(cast.get("offset", -1)),
                        "invoke_offset": int(
                            invocation.get("offset", -1)
                        ),
                    }
                )

            if len(flows) != len(source_matches):
                continue
            if [
                flow["target_method"] for flow in flows
            ] != [
                match.group("target") for match in source_matches
            ]:
                continue

            exact_candidates.append(
                {
                    "method": exact_method,
                    "flows": flows,
                }
            )

        if len(exact_candidates) != 1:
            continue

        proof = exact_candidates[0]
        for source_match in source_matches:
            expression = text[
                method_start + source_match.start("expr"):
                method_start + source_match.end("expr")
            ]
            edits.append(
                (
                    method_start + source_match.start("expr"),
                    method_start + source_match.end("expr"),
                    "(java.util.Map)" + expression,
                )
            )

        actions.append(
            {
                "kind": (
                    "erased_map_get_direct_argument_cast_reconstruction"
                ),
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "target_methods": [
                    match.group("target") for match in source_matches
                ],
                "receiver_names": [
                    match.group("receiver") for match in source_matches
                ],
                "flows": proof["flows"],
                "replacement_count": len(source_matches),
                "provenance": {
                    "kind": "source_safety",
                    "reason": (
                        "procyon_erased_map_get_direct_argument_cast"
                    ),
                    "strategy": (
                        "exact_map_get_checkcast_direct_call_argument"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping direct Map.get argument edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions

def _normalize_erased_raw_list_toarray_returns(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore exact array casts lost from raw List.toArray return sites.

    A raw List makes source-level toArray(T[]) erase to Object[], even when
    exact bytecode immediately checkcasts that result to the method's array
    return type. Restore only that outer cast when source return/component
    types agree and one exact readable method proves the complete
    List.toArray -> checkcast array -> areturn flow one-for-one.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    return_re = re.compile(
        r"\breturn\s+"
        r"(?P<expr>"
        r"\(\s*\(\s*(?:java\.util\.)?List\s*\)\s*"
        r"(?P<receiver>[A-Za-z_$][A-Za-z0-9_$]*)\s*\)"
        r"\s*\.\s*toArray\s*\(\s*new\s+"
        r"(?P<component>[A-Za-z_$][A-Za-z0-9_$.]*)\s*"
        r"\[\s*[^;\n]+?\s*\]\s*\)"
        r")\s*;"
    )

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        source_return = method_match.group("return").strip()
        if not source_return.endswith("[]"):
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        returns = list(return_re.finditer(method_code))
        if not returns:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        candidates: list[dict[str, Any]] = []
        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            exact_return = _descriptor_return_descriptor(descriptor)
            if (
                exact_return is None
                or not exact_return.startswith("[")
                or (
                    _source_parameters_match_descriptor(
                        source_return + " recoveredReturn",
                        "(" + exact_return + ")V",
                        current_package=current_package,
                    )
                    is not True
                )
            ):
                continue

            component_ok = all(
                _source_parameters_match_descriptor(
                    match.group("component") + "[] recoveredArray",
                    "(" + exact_return + ")V",
                    current_package=current_package,
                )
                is True
                for match in returns
            )
            if not component_ok:
                continue

            instructions = list(exact_method.get("instructions", []))
            flows: list[dict[str, Any]] = []
            for index in range(len(instructions) - 2):
                call = instructions[index]
                cast = instructions[index + 1]
                ret = instructions[index + 2]
                if not (
                    call.get("mnemonic")
                    in {"invokeinterface", "invokevirtual"}
                    and call.get("owner") == "java/util/List"
                    and call.get("name") == "toArray"
                    and call.get("descriptor")
                    == "([Ljava/lang/Object;)[Ljava/lang/Object;"
                    and cast.get("mnemonic") == "checkcast"
                    and cast.get("type") == exact_return
                    and ret.get("mnemonic") == "areturn"
                ):
                    continue
                flows.append(
                    {
                        "checkcast_type": str(cast.get("type", "")),
                        "checkcast_offset": int(cast.get("offset", -1)),
                    }
                )

            if len(flows) != len(returns):
                continue
            candidates.append(
                {
                    "method": exact_method,
                    "return_descriptor": exact_return,
                    "flows": flows,
                }
            )

        if len(candidates) != 1:
            continue

        proof = candidates[0]
        for match in returns:
            expression = text[
                method_start + match.start("expr"):
                method_start + match.end("expr")
            ]
            edits.append(
                (
                    method_start + match.start("expr"),
                    method_start + match.end("expr"),
                    "(" + source_return + ")" + expression,
                )
            )

        actions.append(
            {
                "kind": "erased_raw_list_toarray_return_cast_reconstruction",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "array_return_descriptor": proof["return_descriptor"],
                "receiver_names": sorted(
                    {match.group("receiver") for match in returns}
                ),
                "component_types": sorted(
                    {match.group("component") for match in returns}
                ),
                "exact_checkcast_offsets": [
                    flow["checkcast_offset"] for flow in proof["flows"]
                ],
                "replacement_count": len(returns),
                "provenance": {
                    "kind": "source_safety",
                    "reason": "procyon_erased_raw_list_toarray_return_cast",
                    "strategy": (
                        "raw_list_toarray_source_plus_exact_array_checkcast_return"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping raw List.toArray return edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



def _normalize_erased_nested_list_receivers(
    *,
    source_root: Path,
    path: Path,
    readable_zip: zipfile.ZipFile,
) -> list[dict[str, Any]]:
    """Restore List casts lost before nested raw-List dereferences.

    Procyon can emit rawList.get(i).size()/get(j) even though exact bytecode
    checkcasts the outer get() result to java/util/List before the nested call.
    Restore only that receiver cast when one exact readable method proves the
    same List.get -> checkcast List -> nested List member flow one-for-one.
    """

    rel = path.relative_to(source_root).as_posix()
    class_entry = Path(rel).with_suffix(".class").as_posix()
    try:
        class_bytes = readable_zip.read(class_entry)
        profile = profile_class_field_accesses(class_bytes)
    except (KeyError, BytecodeProfileError):
        return []

    current_owner = str(profile.get("internal_name", ""))
    if current_owner != class_entry[:-6]:
        return []
    current_package = current_owner.rpartition("/")[0]

    text = path.read_text(encoding="utf-8")
    whole_code = _java_code_mask(text)
    edits: list[tuple[int, int, str]] = []
    actions: list[dict[str, Any]] = []

    raw_list_decl_re = re.compile(
        r"\b(?P<type>(?:java\.util\.)?List)\s+"
        r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)\b"
    )
    nested_re = re.compile(
        r"(?P<expr>"
        r"(?P<receiver>[A-Za-z_$][A-Za-z0-9_$]*)"
        r"\s*\.\s*get\s*\(\s*"
        r"(?P<index>[A-Za-z_$][A-Za-z0-9_$]*)\s*\)"
        r")\s*\.\s*(?P<member>size|get)\s*\("
    )

    for method_match in _METHOD_DECL_RE.finditer(whole_code):
        brace_start = whole_code.find(
            "{", method_match.start(), method_match.end()
        )
        if brace_start < 0:
            continue
        try:
            body_end = _matching_brace_end(whole_code, brace_start)
        except SourceNormalizationError:
            continue

        scope_code = (
            method_match.group("params")
            + "\n"
            + whole_code[brace_start + 1:body_end]
        )
        raw_lists = {
            match.group("name"): match.group("type")
            for match in raw_list_decl_re.finditer(scope_code)
        }
        if not raw_lists:
            continue

        method_start = method_match.start()
        method_code = whole_code[method_start:body_end]
        occurrences = [
            match
            for match in nested_re.finditer(method_code)
            if match.group("receiver") in raw_lists
        ]
        if not occurrences:
            continue

        source_static = bool(
            re.search(
                r"\bstatic\b",
                whole_code[method_match.start():brace_start],
            )
        )
        candidates: list[dict[str, Any]] = []

        for exact_method in profile.get("methods", []):
            if exact_method.get("name") != method_match.group("name"):
                continue
            descriptor = str(exact_method.get("descriptor", ""))
            if (
                _source_parameters_match_descriptor(
                    method_match.group("params"),
                    descriptor,
                    current_package=current_package,
                )
                is not True
            ):
                continue
            if (
                bool(int(exact_method.get("access", 0)) & 0x0008)
                != source_static
            ):
                continue

            exact_return = _descriptor_return_descriptor(descriptor)
            source_return = method_match.group("return").strip()
            if source_return == "void":
                if exact_return != "V":
                    continue
            elif exact_return is None or (
                _source_parameters_match_descriptor(
                    source_return + " recoveredReturn",
                    "(" + exact_return + ")V",
                    current_package=current_package,
                )
                is not True
            ):
                continue

            instructions = list(exact_method.get("instructions", []))
            flows: list[dict[str, Any]] = []
            for index in range(len(instructions) - 2):
                outer_get = instructions[index]
                cast = instructions[index + 1]
                if not (
                    outer_get.get("mnemonic")
                    in {"invokeinterface", "invokevirtual"}
                    and outer_get.get("owner") == "java/util/List"
                    and outer_get.get("name") == "get"
                    and outer_get.get("descriptor")
                    == "(I)Ljava/lang/Object;"
                    and cast.get("mnemonic") == "checkcast"
                    and cast.get("type") == "java/util/List"
                ):
                    continue

                next_item = instructions[index + 2]
                if (
                    next_item.get("mnemonic")
                    in {"invokeinterface", "invokevirtual"}
                    and next_item.get("owner") == "java/util/List"
                    and next_item.get("name") == "size"
                    and next_item.get("descriptor") == "()I"
                ):
                    flows.append(
                        {
                            "member": "size",
                            "checkcast_offset": int(
                                cast.get("offset", -1)
                            ),
                        }
                    )
                    continue

                if index + 3 >= len(instructions):
                    continue
                nested_call = instructions[index + 3]
                if not (
                    next_item.get("mnemonic") == "iload"
                    and nested_call.get("mnemonic")
                    in {"invokeinterface", "invokevirtual"}
                    and nested_call.get("owner") == "java/util/List"
                    and nested_call.get("name") == "get"
                    and nested_call.get("descriptor")
                    == "(I)Ljava/lang/Object;"
                ):
                    continue
                flows.append(
                    {
                        "member": "get",
                        "checkcast_offset": int(cast.get("offset", -1)),
                    }
                )

            source_counts = {
                member: sum(
                    match.group("member") == member
                    for match in occurrences
                )
                for member in {"size", "get"}
            }
            exact_counts = {
                member: sum(
                    flow["member"] == member for flow in flows
                )
                for member in {"size", "get"}
            }
            if source_counts != exact_counts:
                continue

            candidates.append(
                {
                    "method": exact_method,
                    "flows": flows,
                    "member_counts": source_counts,
                }
            )

        if len(candidates) != 1:
            continue

        proof = candidates[0]
        for match in occurrences:
            expression = text[
                method_start + match.start("expr"):
                method_start + match.end("expr")
            ]
            receiver_type = raw_lists[match.group("receiver")]
            edits.append(
                (
                    method_start + match.start("expr"),
                    method_start + match.end("expr"),
                    "((" + receiver_type + ")" + expression + ")",
                )
            )

        actions.append(
            {
                "kind": "erased_nested_list_receiver_cast_reconstruction",
                "source_path": rel,
                "method_name": method_match.group("name"),
                "method_descriptor": proof["method"]["descriptor"],
                "receiver_names": sorted(
                    {match.group("receiver") for match in occurrences}
                ),
                "member_counts": proof["member_counts"],
                "exact_checkcast_offsets": [
                    flow["checkcast_offset"] for flow in proof["flows"]
                ],
                "replacement_count": len(occurrences),
                "provenance": {
                    "kind": "source_safety",
                    "reason": "procyon_erased_nested_list_receiver_cast",
                    "strategy": (
                        "raw_list_source_plus_exact_nested_list_checkcast_flow"
                    ),
                },
            }
        )

    if not edits:
        return []

    edits.sort(key=lambda row: row[0])
    for left, right in zip(edits, edits[1:]):
        if left[1] > right[0]:
            raise SourceNormalizationError(
                f"{rel}: overlapping nested List receiver edits"
            )
    for start, end, replacement in reversed(edits):
        text = text[:start] + replacement + text[end:]
    path.write_text(text, encoding="utf-8")
    return actions



